--
-- Name: acknowledge_request_folder_completion_v2(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.acknowledge_request_folder_completion_v2(p_event_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  event_row public.ph_request_delivery_outbox;
begin
  if not private.is_service_role_request() then
    raise exception using errcode = '42501', message = 'DELIVERY_WORKER_FORBIDDEN';
  end if;
  select * into event_row from public.ph_request_delivery_outbox
  where event_id = p_event_id and status = 'delivered'
    and payload->>'contractVersion' = 'request-folder-completion-v2';
  if event_row.event_id is null then return; end if;
  update private.ph_request_folder_delivery_state set
    last_delivered_version = (event_row.payload->>'membershipVersion')::bigint,
    last_delivered_signature = event_row.payload->>'membershipSignature',
    updated_at = now()
  where request_folder = event_row.request_folder;
end
$$;


ALTER FUNCTION public.acknowledge_request_folder_completion_v2(p_event_id uuid) OWNER TO postgres;

--
-- Name: activate_eval_item_low_stock_import_v1(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.activate_eval_item_low_stock_import_v1(p_run_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET statement_timeout TO '55s'
    AS $$
declare
  current_state private.ph_eval_item_low_stock_import_state%rowtype;
  run_status text;
  expected_count integer;
  linked_count integer;
  pending_count integer;
begin
  select * into current_state
  from private.ph_eval_item_low_stock_import_state
  where singleton
  for update;
  select status into run_status
  from private.ph_eval_item_low_stock_import_runs
  where run_id = p_run_id
  for update;
  if run_status is null then raise exception using errcode = 'P0002', message = 'LOW_STOCK_IMPORT_RUN_NOT_FOUND'; end if;
  if run_status = 'active' and current_state.active_run_id = p_run_id then
    return jsonb_build_object('status', 'active', 'run_id', p_run_id);
  end if;
  if run_status <> 'building' or current_state.pending_run_id is distinct from p_run_id then
    raise exception using errcode = '55000', message = 'LOW_STOCK_IMPORT_RUN_SUPERSEDED';
  end if;

  select jsonb_array_length(expected_manifest) into expected_count
  from private.ph_eval_item_low_stock_import_runs where run_id = p_run_id;
  select count(*)::integer into linked_count
  from private.ph_eval_item_low_stock_run_files r
  join private.ph_eval_item_low_stock_file_versions v on v.file_version_id = r.file_version_id
  where r.run_id = p_run_id and v.status = 'finalized'
    and r.drive_file_id = v.drive_file_id and r.source_revision = v.source_revision;
  select count(*)::integer into pending_count
  from private.ph_eval_item_low_stock_run_files r
  left join private.ph_eval_item_low_stock_file_versions v on v.file_version_id = r.file_version_id
  where r.run_id = p_run_id and (r.file_version_id is null or v.status <> 'finalized'
    or r.drive_file_id <> v.drive_file_id or r.source_revision <> v.source_revision);
  if linked_count <> expected_count or pending_count > 0 then
    raise exception using errcode = '55000', message = 'LOW_STOCK_IMPORT_COVERAGE_INCOMPLETE';
  end if;
  -- Compute the expensive full-history group/day reduction exactly once for this
  -- immutable manifest. Public reads and Eval #2 then join this compact cache.
  delete from private.ph_eval_item_low_stock_target_stats where run_id = p_run_id;
  insert into private.ph_eval_item_low_stock_target_stats(
    run_id, itemcode_normalized, qualifying_line_count, qualifying_day_count,
    source_file_count, mean_quantity, p75_quantity, suggested_qty,
    history_from_date, history_through_date, calculated_at
  )
  with active_rows as materialized (
    select
      v.file_version_id, v.drive_file_id, v.source_report_date, v.snapshot_at, v.source_created_at,
      r.group_key, r.itemcode_normalized, r.quantity_ordered
    from private.ph_eval_item_low_stock_run_files rf
    join private.ph_eval_item_low_stock_file_versions v on v.file_version_id = rf.file_version_id
    join private.ph_eval_item_low_stock_order_rows r on r.file_version_id = v.file_version_id
    where rf.run_id = p_run_id and v.status = 'finalized' and v.disposition = 'eligible'
  ), group_files as (
    select distinct source_report_date, group_key, file_version_id, drive_file_id, snapshot_at, source_created_at
    from active_rows
  ), ranked_groups as (
    select source_report_date, group_key, file_version_id,
      snapshot_at, source_created_at, drive_file_id,
      row_number() over (
        partition by source_report_date, group_key
        order by snapshot_at desc, source_created_at desc nulls last, drive_file_id collate "C" desc, file_version_id desc
      ) as file_rank
    from group_files
  ), selected_daily_bags as (
    select a.*
    from active_rows a
    join ranked_groups g using (source_report_date, group_key, file_version_id)
    where g.file_rank = 1
  )
  select
    p_run_id,
    itemcode_normalized,
    count(*)::integer,
    count(distinct source_report_date)::integer,
    count(distinct file_version_id)::integer,
    avg(quantity_ordered)::numeric,
    percentile_disc(0.75) within group (order by quantity_ordered)::numeric,
    ceil(avg(quantity_ordered) + greatest(avg(quantity_ordered), percentile_disc(0.75) within group (order by quantity_ordered)))::integer,
    min(source_report_date),
    max(source_report_date),
    now()
  from selected_daily_bags
  group by itemcode_normalized;
  update private.ph_eval_item_low_stock_import_runs
  set status = 'superseded'
  where run_id = current_state.active_run_id and status = 'active';
  update private.ph_eval_item_low_stock_import_runs
  set status = 'active', activated_at = now()
  where run_id = p_run_id;
  update private.ph_eval_item_low_stock_import_state
  set active_run_id = p_run_id, pending_run_id = null, updated_at = now()
  where singleton;
  return jsonb_build_object('status', 'active', 'run_id', p_run_id);
end
$$;


ALTER FUNCTION public.activate_eval_item_low_stock_import_v1(p_run_id uuid) OWNER TO postgres;

--
-- Name: add_codex_ops_message_v1(uuid, integer, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.add_codex_ops_message_v1(p_task_id uuid, p_expected_revision integer, p_body text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  profile public.profiles%rowtype;
  task private.codex_ops_tasks%rowtype;
  message private.codex_ops_messages%rowtype;
  clean_body text := btrim(coalesce(p_body, ''));
begin
  profile := private.require_codex_ops_dylan_v1();
  if not private.codex_ops_flag_enabled_v1('codex_ops_enabled') then
    raise exception using errcode = '42501', message = 'CODEX_OPS_SUBMISSION_DISABLED';
  end if;
  if char_length(clean_body) not between 1 and 12000 then
    raise exception using errcode = '22023', message = 'CODEX_OPS_MESSAGE_INVALID';
  end if;
  select * into task from private.codex_ops_tasks t where t.id = p_task_id and t.created_by = profile.id for update;
  if task.id is null then raise exception using errcode = 'P0002', message = 'CODEX_OPS_TASK_NOT_FOUND'; end if;
  select * into message from private.codex_ops_messages m
  where m.task_id = task.id and m.client_idempotency_key = p_idempotency_key;
  if message.id is not null then
    return jsonb_build_object('id', message.id, 'taskId', task.id, 'revision', task.revision, 'recovered', true);
  end if;
  if task.revision <> p_expected_revision then
    raise exception using errcode = '40001', message = 'CODEX_OPS_REVISION_CONFLICT';
  end if;
  if task.status in ('diagnosing', 'fixing', 'testing', 'deploying', 'live', 'reverted', 'cancelled') then
    raise exception using errcode = '55000', message = 'CODEX_OPS_TASK_BUSY_OR_TERMINAL';
  end if;
  insert into private.codex_ops_messages (task_id, actor_type, actor_username, body, client_idempotency_key)
  values (task.id, 'user', 'dylan_collyge', clean_body, p_idempotency_key)
  returning * into message;
  update private.codex_ops_tasks
  set revision = revision + 1,
      status = case when status in ('needs_input', 'blocked', 'failed', 'needs_escalation', 'ready_for_approval') then 'queued' else status end,
      approved_sha = null,
      branch_name = case when status = 'ready_for_approval' then null else branch_name end,
      pull_request_number = case when status = 'ready_for_approval' then null else pull_request_number end,
      pull_request_url = case when status = 'ready_for_approval' then null else pull_request_url end,
      head_sha = case when status = 'ready_for_approval' then null else head_sha end,
      path_policy_passed = case when status = 'ready_for_approval' then false else path_policy_passed end,
      required_checks_passed = case when status = 'ready_for_approval' then false else required_checks_passed end,
      terminal_at = null,
      updated_at = now()
  where id = task.id returning * into task;
  insert into private.codex_ops_events (task_id, revision, event_type, sanitized_payload)
  values (task.id, task.revision, 'message.added', '{}'::jsonb);
  return jsonb_build_object('id', message.id, 'taskId', task.id, 'revision', task.revision, 'recovered', false);
end;
$$;


ALTER FUNCTION public.add_codex_ops_message_v1(p_task_id uuid, p_expected_revision integer, p_body text, p_idempotency_key uuid) OWNER TO postgres;

--
-- Name: add_default_walkie_channels_for_user(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.add_default_walkie_channels_for_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
    if to_regclass('public.ph_walkie_channels') is null
       or to_regclass('public.ph_walkie_channel_members') is null then
        return new;
    end if;

    insert into public.ph_walkie_channel_members (channel_id, username, display_name, is_archived)
    select
        channels.id,
        lower(new.username),
        coalesce(new.username, lower(new.username)),
        false
    from public.ph_walkie_channels channels
    where lower(coalesce(channels.title, '')) in ('shipping', 'quality control', 'sales')
      and coalesce(new.username, '') <> ''
    on conflict (channel_id, username) do update set
        is_archived = false,
        display_name = coalesce(excluded.display_name, public.ph_walkie_channel_members.display_name);

    return new;
end;
$$;


ALTER FUNCTION public.add_default_walkie_channels_for_user() OWNER TO postgres;

--
-- Name: append_manager_order_source_rows_v1(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.append_manager_order_source_rows_v1(p_batch_id uuid, p_rows jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  target public.ph_pikes_order_batches%rowtype;
  input_count integer;
  accepted_count integer := 0;
  total_count integer := 0;
begin
  if p_batch_id is null
     or jsonb_typeof(p_rows) <> 'array'
     or jsonb_array_length(p_rows) < 1
     or jsonb_array_length(p_rows) > 200 then
    raise exception 'MANAGER_ORDER_SOURCE_ROWS_INVALID';
  end if;

  select * into target
  from public.ph_pikes_order_batches b
  where b.batch_id = p_batch_id
  for update;

  if not found then raise exception 'MANAGER_ORDER_IMPORT_MANIFEST_MISSING'; end if;
  if target.source_key not in ('pikes', 'stine_lumber') then raise exception 'MANAGER_ORDER_SOURCE_INVALID'; end if;
  if target.status <> 'importing' then raise exception 'MANAGER_ORDER_IMPORT_INVALID_STATE'; end if;

  input_count := jsonb_array_length(p_rows);

  if exists (
    select 1
    from jsonb_to_recordset(p_rows) as x(
      "sourceRowNumber" integer,
      itemcode text,
      "itemcodeNormalized" text,
      "orderTot" text,
      "pickNotes" text
    )
    where x."sourceRowNumber" is null
       or x."sourceRowNumber" < 1
       or nullif(btrim(x.itemcode), '') is null
       or nullif(btrim(x."itemcodeNormalized"), '') is null
       or upper(btrim(x."itemcodeNormalized")) <> upper(btrim(x.itemcode))
  ) then
    raise exception 'MANAGER_ORDER_SOURCE_ROWS_INVALID';
  end if;

  if (
    select count(distinct x."sourceRowNumber")
    from jsonb_to_recordset(p_rows) as x("sourceRowNumber" integer)
  ) <> input_count then
    raise exception 'MANAGER_ORDER_SOURCE_ROWS_DUPLICATE';
  end if;

  insert into public.ph_pikes_order_source_rows (
    batch_id, source_row_number, itemcode, itemcode_normalized,
    order_tot, pick_notes, matched
  )
  select
    p_batch_id,
    x."sourceRowNumber",
    btrim(x.itemcode),
    upper(btrim(x."itemcodeNormalized")),
    nullif(btrim(coalesce(x."orderTot", '')), ''),
    nullif(btrim(coalesce(x."pickNotes", '')), ''),
    false
  from jsonb_to_recordset(p_rows) as x(
    "sourceRowNumber" integer,
    itemcode text,
    "itemcodeNormalized" text,
    "orderTot" text,
    "pickNotes" text
  )
  on conflict (batch_id, source_row_number) do update
  set itemcode = excluded.itemcode,
      itemcode_normalized = excluded.itemcode_normalized,
      order_tot = excluded.order_tot,
      pick_notes = excluded.pick_notes,
      matched = false;

  get diagnostics accepted_count = row_count;
  if accepted_count <> input_count then
    raise exception 'MANAGER_ORDER_SOURCE_ROW_COUNT_MISMATCH';
  end if;

  select count(*)::integer into total_count
  from public.ph_pikes_order_source_rows r
  where r.batch_id = p_batch_id;

  return jsonb_build_object(
    'status', 'accepted',
    'batchId', p_batch_id,
    'acceptedCount', accepted_count,
    'totalCount', total_count
  );
end;
$$;


ALTER FUNCTION public.append_manager_order_source_rows_v1(p_batch_id uuid, p_rows jsonb) OWNER TO postgres;

--
-- Name: append_request_options_v1(uuid, text, text, text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.append_request_options_v1(p_client_batch_id uuid, p_request_folder text, p_source_request_id text, p_inventory_row_ids text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor public.profiles%rowtype;
  actor_email text;
  source_request public.ph_active_request%rowtype;
  source_master public.ph_master_inventory%rowtype;
  candidate public.ph_master_inventory%rowtype;
  thread_row public.ph_request_email_threads%rowtype;
  existing_event public.ph_request_delivery_outbox%rowtype;
  selected_ids text[];
  inserted_ids text[] := '{}'::text[];
  snapshots jsonb := '[]'::jsonb;
  folder_value text := btrim(coalesce(p_request_folder, ''));
  source_id_value text := btrim(coalesce(p_source_request_id, ''));
  candidate_id text;
  request_id text;
  rep_name text;
  customer_name text;
  selected_rep_username text;
  selected_rep_display text;
  selected_rep_email text;
  rep_context_count integer := 0;
  customer_context_count integer := 0;
  active_count integer := 0;
  completed_count integer := 0;
  inserted_count integer := 0;
  skipped_duplicate_count integer := 0;
  source_itemcode_key text;
  source_commonname_key text;
  source_contsize_key text;
  candidate_itemcode_key text;
  candidate_commonname_key text;
  candidate_contsize_key text;
begin
  actor := private.current_active_profile();
  if actor.id is null then
    raise exception using errcode = '42501', message = 'REQUEST_PROFILE_REQUIRED';
  end if;
  if not private.can_create_general_requests() then
    raise exception using errcode = '42501', message = 'REQUEST_OPTION_APPEND_FORBIDDEN';
  end if;
  if p_client_batch_id is null then
    raise exception using errcode = '22023', message = 'REQUEST_OPTION_BATCH_ID_REQUIRED';
  end if;
  if folder_value = '' or source_id_value = '' then
    raise exception using errcode = '22023', message = 'REQUEST_OPTION_SOURCE_REQUIRED';
  end if;

  select coalesce(array_agg(distinct btrim(value) order by btrim(value)), '{}'::text[])
    into selected_ids
  from unnest(coalesce(p_inventory_row_ids, '{}'::text[])) value
  where btrim(coalesce(value, '')) <> '';

  if cardinality(selected_ids) < 1 or cardinality(selected_ids) > 100 then
    raise exception using errcode = '22023', message = 'REQUEST_OPTION_SELECTION_INVALID';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('request-option-append:' || folder_value, 0));

  select * into existing_event
  from public.ph_request_delivery_outbox event
  where event.event_key = 'request-options-appended:' || p_client_batch_id::text
  limit 1;

  if existing_event.event_id is not null then
    if existing_event.request_folder is distinct from folder_value
       or coalesce(existing_event.payload->>'sourceRequestId', '') is distinct from source_id_value then
      raise exception using errcode = '23505', message = 'REQUEST_OPTION_BATCH_CONFLICT';
    end if;
    select coalesce(jsonb_agg(private.canonical_request_json(request.unique_id) order by request.created_at, request.unique_id), '[]'::jsonb)
      into snapshots
    from public.ph_active_request request
    where request.client_batch_id = p_client_batch_id
      and btrim(coalesce(request.request_folder, '')) = folder_value;
    return jsonb_build_object(
      'status', 'options_added',
      'request_folder', folder_value,
      'inserted_count', coalesce(nullif(existing_event.payload->>'insertedCount', '')::integer, jsonb_array_length(snapshots)),
      'skipped_duplicate_count', coalesce(nullif(existing_event.payload->>'skippedDuplicateCount', '')::integer, 0),
      'rows', snapshots,
      'delivery_state', 'silent_until_completion',
      'idempotent_replay', true
    );
  end if;

  perform 1
  from public.ph_active_request request
  where btrim(coalesce(request.request_folder, '')) = folder_value
  order by request.unique_id
  for update;

  select * into source_request
  from public.ph_active_request request
  where request.unique_id = source_id_value
    and btrim(coalesce(request.request_folder, '')) = folder_value
    and coalesce(request.req_archived, false) = false
    and lower(btrim(coalesce(request.req_status, 'pending'))) not in ('archived', 'cancelled', 'canceled')
  for update;

  if source_request.unique_id is null then
    raise exception using errcode = 'P0002', message = 'REQUEST_OPTION_SOURCE_NOT_FOUND';
  end if;

  select count(*), count(*) filter (
    where lower(btrim(coalesce(request.req_status, ''))) in ('complete', 'completed', 'done')
       or nullif(btrim(coalesce(request.date_completed, '')), '') is not null
  )
    into active_count, completed_count
  from public.ph_active_request request
  where btrim(coalesce(request.request_folder, '')) = folder_value
    and coalesce(request.req_archived, false) = false
    and lower(btrim(coalesce(request.req_status, 'pending'))) not in ('archived', 'cancelled', 'canceled');

  if active_count < 1 then
    raise exception using errcode = 'P0002', message = 'REQUEST_FOLDER_NOT_FOUND';
  end if;
  if completed_count = active_count then
    raise exception using errcode = '55000', message = 'REQUEST_FOLDER_ALREADY_COMPLETED';
  end if;

  select count(distinct context.rep_key) filter (where context.rep_key is not null),
         count(distinct context.customer_key) filter (where context.customer_key is not null)
    into rep_context_count, customer_context_count
  from (
    select
      nullif(regexp_replace(lower(coalesce(
        nullif(btrim(request.requested_by), ''),
        nullif(btrim(request.request_selected_rep_display), ''),
        nullif(btrim(request.request_selected_rep_username), '')
      )), '[^a-z0-9]+', '', 'g'), '') as rep_key,
      nullif(regexp_replace(lower(coalesce(nullif(btrim(request.req_customer), ''), '')), '[^a-z0-9]+', '', 'g'), '') as customer_key
    from public.ph_active_request request
    where btrim(coalesce(request.request_folder, '')) = folder_value
      and coalesce(request.req_archived, false) = false
      and lower(btrim(coalesce(request.req_status, 'pending'))) not in ('archived', 'cancelled', 'canceled')
  ) context;

  if rep_context_count > 1 or customer_context_count > 1 then
    raise exception using errcode = '40001', message = 'REQUEST_FOLDER_CONTEXT_CONFLICT';
  end if;

  select * into thread_row
  from public.ph_request_email_threads thread
  where btrim(coalesce(thread.request_folder, '')) = folder_value
  limit 1;

  select * into source_master
  from public.ph_master_inventory master
  where master.unique_id = source_request.master_id
  limit 1;

  select
    coalesce(
      nullif(btrim(source_request.requested_by), ''),
      nullif(btrim(source_request.request_selected_rep_display), ''),
      nullif(btrim(source_request.request_selected_rep_username), ''),
      (
        select coalesce(
          nullif(btrim(request.requested_by), ''),
          nullif(btrim(request.request_selected_rep_display), ''),
          nullif(btrim(request.request_selected_rep_username), '')
        )
        from public.ph_active_request request
        where btrim(coalesce(request.request_folder, '')) = folder_value
        order by request.created_at, request.unique_id
        limit 1
      ),
      nullif(btrim(thread_row.sales_rep_name), '')
    ),
    coalesce(
      nullif(btrim(source_request.req_customer), ''),
      (
        select nullif(btrim(request.req_customer), '')
        from public.ph_active_request request
        where btrim(coalesce(request.request_folder, '')) = folder_value
          and nullif(btrim(coalesce(request.req_customer, '')), '') is not null
        order by request.created_at, request.unique_id
        limit 1
      ),
      nullif(btrim(thread_row.request_customer), '')
    ),
    coalesce(
      nullif(btrim(source_request.request_selected_rep_username), ''),
      (
        select nullif(btrim(request.request_selected_rep_username), '')
        from public.ph_active_request request
        where btrim(coalesce(request.request_folder, '')) = folder_value
          and nullif(btrim(coalesce(request.request_selected_rep_username, '')), '') is not null
        order by request.created_at, request.unique_id
        limit 1
      )
    ),
    coalesce(
      nullif(btrim(source_request.request_selected_rep_display), ''),
      nullif(btrim(source_request.requested_by), ''),
      nullif(btrim(thread_row.sales_rep_name), '')
    ),
    coalesce(
      nullif(btrim(source_request.request_selected_rep_email), ''),
      (
        select nullif(btrim(request.request_selected_rep_email), '')
        from public.ph_active_request request
        where btrim(coalesce(request.request_folder, '')) = folder_value
          and nullif(btrim(coalesce(request.request_selected_rep_email, '')), '') is not null
        order by request.created_at, request.unique_id
        limit 1
      ),
      nullif(btrim(thread_row.sales_rep_email), '')
    )
  into rep_name, customer_name, selected_rep_username, selected_rep_display, selected_rep_email;

  if nullif(btrim(coalesce(rep_name, '')), '') is null then
    raise exception using errcode = '40001', message = 'REQUEST_FOLDER_REP_MISSING';
  end if;
  if nullif(btrim(coalesce(customer_name, '')), '') is null then
    raise exception using errcode = '40001', message = 'REQUEST_FOLDER_CUSTOMER_MISSING';
  end if;

  if nullif(btrim(coalesce(thread_row.sales_rep_name, '')), '') is not null
     and regexp_replace(lower(rep_name), '[^a-z0-9]+', '', 'g')
       <> regexp_replace(lower(thread_row.sales_rep_name), '[^a-z0-9]+', '', 'g') then
    raise exception using errcode = '40001', message = 'REQUEST_FOLDER_CONTEXT_CONFLICT';
  end if;
  if nullif(btrim(coalesce(thread_row.request_customer, '')), '') is not null
     and regexp_replace(lower(customer_name), '[^a-z0-9]+', '', 'g')
       <> regexp_replace(lower(thread_row.request_customer), '[^a-z0-9]+', '', 'g') then
    raise exception using errcode = '40001', message = 'REQUEST_FOLDER_CONTEXT_CONFLICT';
  end if;

  select email into actor_email from auth.users where id = actor.id;

  source_itemcode_key := upper(btrim(coalesce(source_master.itemcode, source_request.itemcode, '')));
  source_commonname_key := btrim(regexp_replace(lower(btrim(coalesce(source_master.commonname, source_request.commonname, ''))), '[^a-z0-9]+', ' ', 'g'));
  source_contsize_key := lower(btrim(coalesce(source_master.contsize, source_request.contsize, '')));

  foreach candidate_id in array selected_ids
  loop
    select * into candidate
    from public.ph_master_inventory master
    where master.unique_id = candidate_id
    for update;

    if candidate.unique_id is null then
      raise exception using errcode = 'P0002', message = 'REQUEST_OPTION_INVENTORY_ROW_NOT_FOUND';
    end if;

    candidate_itemcode_key := upper(btrim(coalesce(candidate.itemcode, '')));
    candidate_commonname_key := btrim(regexp_replace(lower(btrim(coalesce(candidate.commonname, ''))), '[^a-z0-9]+', ' ', 'g'));
    candidate_contsize_key := lower(btrim(coalesce(candidate.contsize, '')));

    if not (
      source_itemcode_key <> '' and candidate_itemcode_key = source_itemcode_key
      or (
        source_commonname_key <> ''
        and candidate_commonname_key = source_commonname_key
        and (source_contsize_key = '' or candidate_contsize_key = source_contsize_key)
      )
    ) then
      raise exception using errcode = '22023', message = 'REQUEST_OPTION_NOT_COMPATIBLE';
    end if;

    if exists (
      select 1
      from public.ph_active_request request
      where btrim(coalesce(request.request_folder, '')) = folder_value
        and (
          request.master_id = candidate.unique_id
          or (
            upper(btrim(coalesce(request.itemcode, ''))) = candidate_itemcode_key
            and upper(btrim(coalesce(request.locationcode, ''))) = upper(btrim(coalesce(candidate.locationcode, '')))
            and upper(btrim(coalesce(request.lotcode, ''))) = upper(btrim(coalesce(candidate.lotcode, '')))
          )
        )
    ) then
      skipped_duplicate_count := skipped_duplicate_count + 1;
      continue;
    end if;

    request_id := 'REQ-' || replace(extensions.gen_random_uuid()::text, '-', '');
    insert into public.ph_active_request (
      unique_id, master_id, commonname, contsize, locationcode, lotcode,
      itemcode, ptravailable, season_supply, priority, qualitycode,
      field_tag_color, plantgroupcode, requested_by, request_folder,
      req_customer, req_qty, desired_spec, desired_caliper, est_ship,
      req_reserve, req_photo_link, req_photo_name, req_archived, req_status,
      req_rep_action, created_at, req_match, req_spec, req_caliper,
      req_pic_note, req_sales_note, req_comments, av_note, date_completed,
      completed_by_username, completed_by_display, completed_by_email,
      req_photo_mode, request_note, request_created_by_username,
      request_created_by_display, request_created_by_email,
      request_selected_rep_username, request_selected_rep_display,
      request_selected_rep_email, app_tab_assignment,
      master_app_tab_assignment, request_source, client_batch_id, row_version, customeridentityid, customername, consigneeidentityid, consigneename
    ) values (
      request_id, candidate.unique_id, candidate.commonname, candidate.contsize,
      candidate.locationcode, candidate.lotcode, candidate.itemcode,
      candidate.ptravailable, candidate.season_supply, candidate.priority,
      candidate.qualitycode, candidate.field_tag_color, candidate.plantgroupcode,
      rep_name, folder_value, customer_name, source_request.req_qty,
      source_request.desired_spec, source_request.desired_caliper,
      source_request.est_ship, coalesce(nullif(source_request.req_reserve, ''), 'NO'),
      '', '', false, 'Pending', null, now(), null, null, null, null, null,
      null, null, null, null, null, null, null, source_request.request_note,
      actor.username, coalesce(nullif(actor.display_name, ''), actor.username),
      actor_email, selected_rep_username, coalesce(selected_rep_display, rep_name),
      selected_rep_email, candidate.app_tab_assignment,
      candidate.app_tab_assignment, 'general', p_client_batch_id, 1, source_request.customeridentityid, source_request.customername, source_request.consigneeidentityid, source_request.consigneename
    );

    perform private.upsert_request_history(request_id, 'created', 'delivered', false);
    inserted_ids := array_append(inserted_ids, request_id);
    inserted_count := inserted_count + 1;
  end loop;

  if inserted_count = 0 then
    return jsonb_build_object(
      'status', 'already_in_request',
      'request_folder', folder_value,
      'inserted_count', 0,
      'skipped_duplicate_count', skipped_duplicate_count,
      'rows', '[]'::jsonb,
      'delivery_state', 'silent_until_completion',
      'idempotent_replay', false
    );
  end if;

  select coalesce(jsonb_agg(private.canonical_request_json(request_id_value) order by request_id_value), '[]'::jsonb)
    into snapshots
  from unnest(inserted_ids) request_id_value;

  insert into public.ph_request_delivery_outbox (
    event_key, event_type, request_folder, payload, status,
    delivered_at, delivery_mode, channel_results
  ) values (
    'request-options-appended:' || p_client_batch_id::text,
    'request_options_appended',
    folder_value,
    jsonb_build_object(
      'contractVersion', 'request-options-appended-v1',
      'clientBatchId', p_client_batch_id,
      'sourceRequestId', source_id_value,
      'request_ids', to_jsonb(inserted_ids),
      'insertedCount', inserted_count,
      'skippedDuplicateCount', skipped_duplicate_count,
      'threadContextPreserved', thread_row.request_folder is not null,
      'deliveryPolicy', 'silent_until_completion'
    ),
    'delivered', now(), 'internal_silent_append',
    jsonb_build_object('internal', jsonb_build_object('recorded_at', now()))
  );

  perform private.reconcile_request_folder_completion_v2(folder_value);

  return jsonb_build_object(
    'status', 'options_added',
    'request_folder', folder_value,
    'inserted_count', inserted_count,
    'skipped_duplicate_count', skipped_duplicate_count,
    'rows', snapshots,
    'delivery_state', 'silent_until_completion',
    'idempotent_replay', false
  );
end
$$;


ALTER FUNCTION public.append_request_options_v1(p_client_batch_id uuid, p_request_folder text, p_source_request_id text, p_inventory_row_ids text[]) OWNER TO postgres;

--
-- Name: FUNCTION append_request_options_v1(p_client_batch_id uuid, p_request_folder text, p_source_request_id text, p_inventory_row_ids text[]); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.append_request_options_v1(p_client_batch_id uuid, p_request_folder text, p_source_request_id text, p_inventory_row_ids text[]) IS 'Appends compatible current inventory rows to an open Request folder using server-authoritative folder context. The append is silent until folder completion.';


--
-- Name: apply_codex_ops_repair_result_service_v2(uuid, integer, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.apply_codex_ops_repair_result_service_v2(p_task_id uuid, p_expected_revision integer, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  task private.codex_ops_tasks%rowtype;
  changed text[];
  message_body text;
  recent_repair_attempts integer;
begin
  select * into task
  from private.codex_ops_tasks t
  where t.id = p_task_id
  for update;
  if task.id is null then
    raise exception using errcode = 'P0002', message = 'CODEX_OPS_TASK_NOT_FOUND';
  end if;
  if task.revision <> p_expected_revision then
    raise exception using errcode = '40001', message = 'CODEX_OPS_REVISION_CONFLICT';
  end if;
  if task.status <> 'fixing' then
    raise exception using errcode = '55000', message = 'CODEX_OPS_REPAIR_NOT_ALLOWED';
  end if;
  if octet_length(coalesce(p_payload, '{}'::jsonb)::text) > 131072 then
    raise exception using errcode = '22023', message = 'CODEX_OPS_PAYLOAD_TOO_LARGE';
  end if;
  if task.repair_attempts >= 2 then
    raise exception using errcode = '54000', message = 'CODEX_OPS_REPAIR_LIMIT';
  end if;
  if task.incident_fingerprint is not null then
    select coalesce(sum(t.repair_attempts), 0)::integer
    into recent_repair_attempts
    from private.codex_ops_tasks t
    where t.incident_fingerprint = task.incident_fingerprint
      and t.updated_at >= now() - interval '60 minutes';
    if recent_repair_attempts >= 2 then
      raise exception using errcode = '54000', message = 'CODEX_OPS_FINGERPRINT_REPAIR_LIMIT';
    end if;
  end if;

  changed := coalesce(
    array(select jsonb_array_elements_text(coalesce(p_payload->'changedFiles', '[]'::jsonb))),
    '{}'::text[]
  );
  message_body := left(btrim(coalesce(p_payload->>'summary', 'Repair prepared.')), 12000);
  if coalesce((p_payload->>'escalationRequired')::boolean, false)
     or p_payload->>'risk' in ('high', 'complex') then
    update private.codex_ops_tasks set
      status = 'needs_escalation',
      repair_attempts = repair_attempts + 1,
      risk_level = case
        when p_payload->>'risk' in ('high', 'complex') then p_payload->>'risk'
        else risk_level
      end,
      sanitized_repair_summary = p_payload,
      changed_files = '{}'::text[],
      updated_at = now()
    where id = task.id
    returning * into task;
  else
    update private.codex_ops_tasks set
      status = 'testing',
      repair_attempts = repair_attempts + 1,
      sanitized_repair_summary = p_payload,
      changed_files = changed,
      updated_at = now()
    where id = task.id
    returning * into task;
  end if;

  insert into private.codex_ops_messages
    (task_id, actor_type, actor_username, model, body)
  values
    (task.id, 'agent', 'terra', 'gpt-5.6-terra', message_body);
  insert into private.codex_ops_events
    (task_id, revision, event_type, sanitized_payload)
  values
    (task.id, task.revision, 'repair.result', jsonb_build_object('status', task.status));
  insert into private.codex_ops_audit_events
    (task_id, actor_type, actor_key, action, outcome)
  values
    (task.id, 'runner', 'github-oidc', 'repair.result', 'succeeded');

  return jsonb_build_object(
    'taskId', task.id,
    'revision', task.revision,
    'status', task.status,
    'headSha', task.head_sha
  );
end;
$$;


ALTER FUNCTION public.apply_codex_ops_repair_result_service_v2(p_task_id uuid, p_expected_revision integer, p_payload jsonb) OWNER TO postgres;

--
-- Name: FUNCTION apply_codex_ops_repair_result_service_v2(p_task_id uuid, p_expected_revision integer, p_payload jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.apply_codex_ops_repair_result_service_v2(p_task_id uuid, p_expected_revision integer, p_payload jsonb) IS 'Consumes one sanitized Terra result and stops at Needs Escalation when risk is high or complex.';


--
-- Name: apply_codex_ops_service_event_v1(uuid, integer, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.apply_codex_ops_service_event_v1(p_task_id uuid, p_expected_revision integer, p_action text, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  task private.codex_ops_tasks%rowtype;
  attachment_id uuid;
  media_kind text;
  message_body text;
  next_status text;
  changed text[];
  new_revision integer;
  image_count integer;
  video_count integer;
  recent_repair_attempts integer;
begin
  select * into task from private.codex_ops_tasks t where t.id = p_task_id for update;
  if task.id is null then raise exception using errcode = 'P0002', message = 'CODEX_OPS_TASK_NOT_FOUND'; end if;
  if task.revision <> p_expected_revision then raise exception using errcode = '40001', message = 'CODEX_OPS_REVISION_CONFLICT'; end if;
  if octet_length(coalesce(p_payload, '{}'::jsonb)::text) > 131072 then
    raise exception using errcode = '22023', message = 'CODEX_OPS_PAYLOAD_TOO_LARGE';
  end if;

  if p_action = 'attachment.register' then
    attachment_id := coalesce(nullif(p_payload->>'id', '')::uuid, gen_random_uuid());
    media_kind := lower(coalesce(p_payload->>'mediaKind', ''));
    if media_kind not in ('image', 'video') then raise exception using errcode = '22023', message = 'CODEX_OPS_MEDIA_INVALID'; end if;
    select count(*) filter (where a.media_kind = 'image'), count(*) filter (where a.media_kind = 'video')
    into image_count, video_count
    from private.codex_ops_attachments a where a.task_id = task.id and a.status <> 'deleted';
    if (media_kind = 'image' and image_count >= 10) or (media_kind = 'video' and video_count >= 2) then
      raise exception using errcode = '22023', message = 'CODEX_OPS_ATTACHMENT_LIMIT';
    end if;
    insert into private.codex_ops_attachments (
      id, task_id, uploaded_by, client_idempotency_key, media_kind,
      original_name, declared_mime, object_path
    ) values (
      attachment_id, task.id, task.created_by,
      (p_payload->>'idempotencyKey')::uuid, media_kind,
      left(coalesce(p_payload->>'name', 'evidence'), 240),
      left(coalesce(p_payload->>'declaredMime', 'application/octet-stream'), 120),
      p_payload->>'objectPath'
    ) on conflict (task_id, client_idempotency_key) do nothing;
    return jsonb_build_object('taskId', task.id, 'revision', task.revision, 'attachmentId', attachment_id);

  elsif p_action in ('attachment.verify', 'attachment.reject', 'attachment.delete') then
    attachment_id := (p_payload->>'attachmentId')::uuid;
    update private.codex_ops_attachments a set
      status = case p_action when 'attachment.verify' then 'verified' when 'attachment.reject' then 'rejected' else 'deleted' end,
      detected_mime = case when p_action = 'attachment.verify' then p_payload->>'detectedMime' else a.detected_mime end,
      size_bytes = case when p_action = 'attachment.verify' then (p_payload->>'sizeBytes')::bigint else a.size_bytes end,
      object_etag = case when p_action = 'attachment.verify' then left(coalesce(p_payload->>'etag', ''), 240) else a.object_etag end,
      rejection_code = case when p_action = 'attachment.reject' then left(coalesce(p_payload->>'rejectionCode', 'SIGNATURE_MISMATCH'), 120) else a.rejection_code end,
      verified_at = case when p_action = 'attachment.verify' then now() else a.verified_at end,
      deleted_at = case when p_action = 'attachment.delete' then now() else a.deleted_at end
    where a.id = attachment_id and a.task_id = task.id;
    if not found then raise exception using errcode = 'P0002', message = 'CODEX_OPS_ATTACHMENT_NOT_FOUND'; end if;
    return jsonb_build_object('taskId', task.id, 'revision', task.revision, 'attachmentId', attachment_id, 'action', p_action);

  elsif p_action = 'dispatch.queue' then
    if exists (select 1 from private.codex_ops_attachments a where a.task_id = task.id and a.status = 'pending') then
      raise exception using errcode = '55000', message = 'CODEX_OPS_ATTACHMENTS_PENDING';
    end if;
    insert into private.codex_ops_dispatches (
      task_id, task_revision, action, client_idempotency_key
    ) values (
      task.id, task.revision, p_payload->>'dispatchAction', (p_payload->>'idempotencyKey')::uuid
    ) on conflict (task_id, client_idempotency_key) do nothing;
    insert into private.codex_ops_events (task_id, revision, event_type, sanitized_payload)
    values (task.id, task.revision, 'dispatch.queued', jsonb_build_object('action', p_payload->>'dispatchAction'));
    return jsonb_build_object('taskId', task.id, 'revision', task.revision, 'status', task.status);

  elsif p_action = 'runner.claim' then
    if task.status = 'diagnosing' then
      return jsonb_build_object('taskId', task.id, 'revision', task.revision, 'status', task.status, 'recovered', true);
    end if;
    if task.status <> 'queued' then raise exception using errcode = '55000', message = 'CODEX_OPS_TASK_NOT_QUEUED'; end if;
    next_status := case when p_payload->>'dispatchAction' = 'sol_review' then 'diagnosing' else 'diagnosing' end;
    update private.codex_ops_tasks set status = next_status, updated_at = now() where id = task.id returning * into task;

  elsif p_action = 'diagnosis.result' then
    message_body := left(btrim(coalesce(p_payload->>'summary', 'Diagnosis completed.')), 12000);
    next_status := case
      when coalesce((p_payload->>'needsInput')::boolean, false) then 'needs_input'
      when coalesce((p_payload->>'escalationRequired')::boolean, false) then 'needs_escalation'
      when not coalesce((p_payload->>'reproduced')::boolean, false) then 'blocked'
      when not coalesce((p_payload->>'repairAllowed')::boolean, false) then 'needs_escalation'
      else 'fixing'
    end;
    update private.codex_ops_tasks set
      status = next_status,
      incident_fingerprint = left(nullif(p_payload->>'fingerprint', ''), 240),
      risk_level = case when p_payload->>'risk' in ('low', 'medium', 'high', 'complex') then p_payload->>'risk' else 'medium' end,
      sanitized_diagnosis = p_payload,
      updated_at = now(),
      terminal_at = case when next_status = 'blocked' then now() else null end
    where id = task.id returning * into task;
    insert into private.codex_ops_messages (task_id, actor_type, actor_username, model, body)
    values (task.id, 'agent', 'luna', 'gpt-5.6-luna', message_body);

  elsif p_action = 'repair.result' then
    if task.status <> 'fixing' then raise exception using errcode = '55000', message = 'CODEX_OPS_REPAIR_NOT_ALLOWED'; end if;
    if task.repair_attempts >= 2 then raise exception using errcode = '54000', message = 'CODEX_OPS_REPAIR_LIMIT'; end if;
    if task.incident_fingerprint is not null then
      select coalesce(sum(t.repair_attempts), 0)::integer
      into recent_repair_attempts
      from private.codex_ops_tasks t
      where t.incident_fingerprint = task.incident_fingerprint
        and t.updated_at >= now() - interval '60 minutes';
      if recent_repair_attempts >= 2 then
        raise exception using errcode = '54000', message = 'CODEX_OPS_FINGERPRINT_REPAIR_LIMIT';
      end if;
    end if;
    changed := coalesce(array(select jsonb_array_elements_text(coalesce(p_payload->'changedFiles', '[]'::jsonb))), '{}'::text[]);
    message_body := left(btrim(coalesce(p_payload->>'summary', 'Repair prepared.')), 12000);
    if coalesce((p_payload->>'escalationRequired')::boolean, false)
       or p_payload->>'risk' in ('high', 'complex') then
      update private.codex_ops_tasks set
        status = 'needs_escalation', repair_attempts = repair_attempts + 1,
        risk_level = case when p_payload->>'risk' in ('high', 'complex') then p_payload->>'risk' else risk_level end,
        sanitized_repair_summary = p_payload,
        changed_files = '{}'::text[],
        updated_at = now()
      where id = task.id returning * into task;
    else
      update private.codex_ops_tasks set
        status = 'testing', repair_attempts = repair_attempts + 1,
        sanitized_repair_summary = p_payload,
        changed_files = changed,
        updated_at = now()
      where id = task.id returning * into task;
    end if;
    insert into private.codex_ops_messages (task_id, actor_type, actor_username, model, body)
    values (task.id, 'agent', 'terra', 'gpt-5.6-terra', message_body);

  elsif p_action = 'publish.result' then
    if not coalesce((p_payload->>'pathPolicyPassed')::boolean, false) then
      next_status := 'blocked';
    elsif not coalesce((p_payload->>'requiredChecksPassed')::boolean, false) then
      next_status := 'failed';
    else
      next_status := 'ready_for_approval';
    end if;
    new_revision := task.revision + 1;
    update private.codex_ops_tasks set
      revision = new_revision,
      status = next_status,
      branch_name = left(nullif(p_payload->>'branch', ''), 240),
      pull_request_number = nullif(p_payload->>'pullRequestNumber', '')::bigint,
      pull_request_url = left(nullif(p_payload->>'pullRequestUrl', ''), 1000),
      head_sha = lower(nullif(p_payload->>'headSha', '')),
      approved_sha = null,
      path_policy_passed = coalesce((p_payload->>'pathPolicyPassed')::boolean, false),
      required_checks_passed = coalesce((p_payload->>'requiredChecksPassed')::boolean, false),
      test_summary = coalesce(p_payload->'tests', '[]'::jsonb),
      last_error_code = nullif(p_payload->>'errorCode', ''),
      updated_at = now(),
      terminal_at = case when next_status in ('blocked', 'failed') then now() else null end
    where id = task.id returning * into task;

  elsif p_action = 'deployment.merged' then
    if task.status <> 'deploying' or task.approved_sha is null then
      raise exception using errcode = '55000', message = 'CODEX_OPS_DEPLOYMENT_NOT_APPROVED';
    end if;
    update private.codex_ops_tasks set
      merged_sha = lower(nullif(p_payload->>'mergedSha', '')),
      updated_at = now()
    where id = task.id returning * into task;

  elsif p_action in ('deployment.live', 'deployment.failed', 'deployment.reverted') then
    next_status := case p_action when 'deployment.live' then 'live' when 'deployment.reverted' then 'reverted' else 'failed' end;
    update private.codex_ops_tasks set
      status = next_status,
      merged_sha = case when p_action = 'deployment.live' then lower(nullif(p_payload->>'mergedSha', '')) else merged_sha end,
      last_error_code = nullif(p_payload->>'errorCode', ''),
      updated_at = now(), terminal_at = now()
    where id = task.id returning * into task;
    update private.codex_ops_attachments set expires_at = now() + interval '30 days'
    where task_id = task.id and status = 'verified' and expires_at is null;
  else
    raise exception using errcode = '22023', message = 'CODEX_OPS_SERVICE_ACTION_INVALID';
  end if;

  insert into private.codex_ops_events (task_id, revision, event_type, sanitized_payload)
  values (task.id, task.revision, p_action, jsonb_build_object('status', task.status));
  insert into private.codex_ops_audit_events (task_id, actor_type, actor_key, action, outcome)
  values (task.id, 'runner', 'github-oidc', p_action, 'succeeded');
  return jsonb_build_object('taskId', task.id, 'revision', task.revision, 'status', task.status, 'headSha', task.head_sha);
end;
$$;


ALTER FUNCTION public.apply_codex_ops_service_event_v1(p_task_id uuid, p_expected_revision integer, p_action text, p_payload jsonb) OWNER TO postgres;

--
-- Name: apply_inventory_transaction_v1(uuid, text, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.apply_inventory_transaction_v1(p_actor_id uuid, p_command_id text, p_request jsonb, p_operations jsonb, p_audit jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
declare actor public.profiles:=workflow_private.require_inventory_manager(p_actor_id);
  receipt workflow_private.commands; operation jsonb; old_row jsonb; changed_row jsonb; rows jsonb:='[]'; result jsonb;
  table_name text; row_id text; columns_sql text; values_sql text; patch jsonb; audit_record jsonb;
begin
  if length(coalesce(p_command_id,''))<12 or length(p_command_id)>180 then raise exception 'WORKFLOW_COMMAND_ID_REQUIRED'; end if;
  if p_audit->>'action' not in ('qty','transfer') or p_audit->>'action' is null then raise exception 'INVENTORY_ACTION_INVALID'; end if;
  if jsonb_typeof(p_operations)<>'array' or jsonb_array_length(p_operations)=0 or jsonb_array_length(p_operations)>5000 then raise exception 'INVENTORY_OPERATIONS_INVALID'; end if;
  perform pg_advisory_xact_lock(hashtextextended(actor.id::text||':'||p_command_id,0));
  select * into receipt from workflow_private.commands c where c.actor_id=actor.id and c.command_id=p_command_id;
  if found then
    if receipt.request<>p_request then raise exception using errcode='40001',message='WORKFLOW_COMMAND_CONFLICT'; end if;
    return receipt.result||jsonb_build_object('duplicate',true);
  end if;
  -- Stable lock ordering prevents source/destination inversions between requests.
  for operation in select value from jsonb_array_elements(p_operations) order by value->>'table',value->>'unique_id' loop
    table_name:=operation->>'table'; row_id:=operation->>'unique_id';
    if table_name not in ('ph_master_inventory','tx_master_inventory','nc_master_inventory','hl_master_inventory') or table_name is null or row_id is null
      or operation->>'kind' is null or operation->>'kind' not in ('insert','update') then
      raise exception 'INVENTORY_TARGET_INVALID'; end if;
    execute format('select to_jsonb(m) from public.%I m where unique_id=$1 for update',table_name) into old_row using row_id;
    if operation->>'kind'='insert' then
      if old_row is not null then raise exception using errcode='40001',message='INVENTORY_DESTINATION_CHANGED'; end if;
      patch:=operation->'row';
      if patch->>'unique_id' is distinct from row_id then raise exception 'INVENTORY_TARGET_INVALID'; end if;
      select string_agg(format('%I',a.attname),',' order by a.attnum), string_agg(format('r.%I',a.attname),',' order by a.attnum)
        into columns_sql,values_sql from pg_catalog.pg_attribute a
        where a.attrelid=format('public.%I',table_name)::regclass and a.attnum>0 and not a.attisdropped
        and a.attgenerated='' and a.attidentity='' and patch ? a.attname;
      execute format('insert into public.%I (%s) select %s from jsonb_populate_record(null::public.%I,$1) r returning to_jsonb(%I.*)',
        table_name,columns_sql,values_sql,table_name,table_name) into changed_row using patch;
    else
      if old_row is null or old_row is distinct from operation->'expected' then raise exception using errcode='40001',message='INVENTORY_SOURCE_CHANGED'; end if;
      patch:=operation->'patch';
      if jsonb_typeof(patch)<>'object' or exists(select 1 from jsonb_object_keys(patch) k where k not in ('ptronhand','ptrreviewed','ptravailable','last_updated','holdstopcode','holdstopreason')) then
        raise exception 'INVENTORY_PATCH_INVALID'; end if;
      select string_agg(format('%I=r.%I',key,key),',') into columns_sql from jsonb_object_keys(patch) key;
      execute format('update public.%I m set %s from jsonb_populate_record(null::public.%I,$1) r where m.unique_id=$2 returning to_jsonb(m.*)',table_name,columns_sql,table_name)
        into changed_row using old_row||patch,row_id;
    end if;
    rows:=rows||jsonb_build_array(jsonb_build_object('table',table_name,'row',changed_row));
  end loop;
  audit_record:=p_audit||jsonb_build_object('unique_id',gen_random_uuid()::text,'actor_id',actor.id,'actor_username',actor.username,
    'actor_display',coalesce(actor.display_name,actor.username),'actor_email',null,'created_at',now(),'status','applied','event_type','inventory_mutation',
    'raw_payload',p_request,'search_text',lower(concat_ws(' ',actor.username,p_audit->>'action',p_audit->>'source_itemcode',p_audit->>'source_lotcode',p_audit->>'source_locationcode',
      p_audit->>'destination_itemcode',p_audit->>'destination_lotcode',p_audit->>'destination_locationcode')));
  audit_record:=audit_record||jsonb_build_object('source_after',(select value->'row' from jsonb_array_elements(rows) where value->>'table'=p_audit->>'source_table' and value#>>'{row,unique_id}'=p_audit->>'source_unique_id'),
    'destination_after',(select value->'row' from jsonb_array_elements(rows) where value->>'table'=p_audit->>'destination_table' and value#>>'{row,unique_id}'=p_audit->>'destination_unique_id'));
  insert into public.ph_inventory_transactions select (jsonb_populate_record(null::public.ph_inventory_transactions,audit_record)).*;
  result:=jsonb_build_object('ok',true,'transactionId',audit_record->>'unique_id','rows',rows,'audit',audit_record);
  insert into workflow_private.commands(actor_id,command_id,request,result) values(actor.id,p_command_id,p_request,result);
  return result;
end $_$;


ALTER FUNCTION public.apply_inventory_transaction_v1(p_actor_id uuid, p_command_id text, p_request jsonb, p_operations jsonb, p_audit jsonb) OWNER TO postgres;

--
-- Name: approve_codex_ops_deployment_v1(uuid, integer, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approve_codex_ops_deployment_v1(p_task_id uuid, p_expected_revision integer, p_head_sha text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  profile public.profiles%rowtype;
  task private.codex_ops_tasks%rowtype;
  approval private.codex_ops_approvals%rowtype;
  normalized_sha text := lower(btrim(coalesce(p_head_sha, '')));
begin
  profile := private.require_codex_ops_dylan_v1();
  if not private.codex_ops_flag_enabled_v1('codex_ops_deploy_enabled') then
    raise exception using errcode = '42501', message = 'CODEX_OPS_DEPLOYMENT_DISABLED';
  end if;
  if normalized_sha !~ '^[0-9a-f]{40}$' then raise exception using errcode = '22023', message = 'CODEX_OPS_SHA_INVALID'; end if;
  select * into task from private.codex_ops_tasks t where t.id = p_task_id and t.created_by = profile.id for update;
  if task.id is null then raise exception using errcode = 'P0002', message = 'CODEX_OPS_TASK_NOT_FOUND'; end if;
  select * into approval from private.codex_ops_approvals a
  where a.approved_by = profile.id and a.client_idempotency_key = p_idempotency_key;
  if approval.id is not null then
    return jsonb_build_object('approvalId', approval.id, 'taskId', task.id, 'revision', approval.task_revision, 'headSha', approval.head_sha, 'recovered', true);
  end if;
  if task.revision <> p_expected_revision then raise exception using errcode = '40001', message = 'CODEX_OPS_REVISION_CONFLICT'; end if;
  if task.status <> 'ready_for_approval' then raise exception using errcode = '55000', message = 'CODEX_OPS_NOT_READY'; end if;
  if task.head_sha is distinct from normalized_sha then raise exception using errcode = '40001', message = 'CODEX_OPS_HEAD_CHANGED'; end if;
  if not task.path_policy_passed or not task.required_checks_passed then raise exception using errcode = '55000', message = 'CODEX_OPS_CHECKS_INCOMPLETE'; end if;
  insert into private.codex_ops_approvals (
    task_id, task_revision, head_sha, approved_by, approved_by_username, client_idempotency_key
  ) values (task.id, task.revision, normalized_sha, profile.id, 'dylan_collyge', p_idempotency_key)
  returning * into approval;
  update private.codex_ops_tasks set approved_sha = normalized_sha, status = 'deploying', updated_at = now()
  where id = task.id;
  insert into private.codex_ops_events (task_id, revision, event_type, sanitized_payload)
  values (task.id, task.revision, 'deployment.approved', jsonb_build_object('headSha', normalized_sha));
  insert into private.codex_ops_audit_events (task_id, actor_type, actor_key, action, outcome, sanitized_metadata)
  values (task.id, 'user', 'dylan_collyge', 'deployment.approve', 'succeeded', jsonb_build_object('revision', task.revision, 'headSha', normalized_sha));
  return jsonb_build_object('approvalId', approval.id, 'taskId', task.id, 'revision', approval.task_revision, 'headSha', approval.head_sha, 'recovered', false);
end;
$_$;


ALTER FUNCTION public.approve_codex_ops_deployment_v1(p_task_id uuid, p_expected_revision integer, p_head_sha text, p_idempotency_key uuid) OWNER TO postgres;

--
-- Name: FUNCTION approve_codex_ops_deployment_v1(p_task_id uuid, p_expected_revision integer, p_head_sha text, p_idempotency_key uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.approve_codex_ops_deployment_v1(p_task_id uuid, p_expected_revision integer, p_head_sha text, p_idempotency_key uuid) IS 'Binds Dylan approval to one task revision and exact PR head SHA; any task or head change invalidates it.';


--
-- Name: archive_completed_request(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.archive_completed_request() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'private', 'vault', 'pg_temp'
    AS $$
BEGIN
    -- Copy the approved/rejected row into the history table
    INSERT INTO public.ph_request_history SELECT NEW.*;
    
    -- Delete the original row from the active daily table
    DELETE FROM public.ph_active_request WHERE unique_id = NEW.unique_id;
    
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.archive_completed_request() OWNER TO postgres;

