--

CREATE FUNCTION public.cancel_shear_location_inquiry_v1(p_inquiry_id uuid, p_actor_username text, p_expected_revision integer) RETURNS public.ph_shear_location_inquiries
    LANGUAGE plpgsql SECURITY DEFINER
