--
-- Name: check_inventory_changes_and_reset(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_inventory_changes_and_reset() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'private', 'vault', 'pg_temp'
    AS $$
DECLARE
  needs_reset BOOLEAN := FALSE;
  old_hold VARCHAR;
  new_hold VARCHAR;
BEGIN
  -- Rule 3: Priority Changes
  IF OLD.priority IS DISTINCT FROM NEW.priority THEN
    needs_reset := TRUE;
  END IF;

  -- Rule 4 & 5: Hold Code Changes (Gets H/S, or loses H/S)
  old_hold := UPPER(COALESCE(OLD.holdstopcode, ''));
  new_hold := UPPER(COALESCE(NEW.holdstopcode, ''));

  IF (old_hold NOT SIMILAR TO '%(H|S)%' AND new_hold SIMILAR TO '%(H|S)%') OR
     (old_hold SIMILAR TO '%(H|S)%' AND new_hold NOT SIMILAR TO '%(H|S)%') THEN
    needs_reset := TRUE;
  END IF;

  -- If rules triggered, wipe the data
  IF needs_reset THEN
     NEW.av_note := NULL;
     NEW.spec := NULL;
     NEW.caliper := NULL;
     NEW.photo_link := NULL;
     NEW.photo_name := NULL;
     NEW.match := NULL;
     NEW.loc_match_qty := NULL;
     NEW.initial_ptr := NULL;
     NEW.date_completed := NULL;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.check_inventory_changes_and_reset() OWNER TO postgres;

--
-- Name: claim_request_delivery_events(integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_request_delivery_events(p_limit integer DEFAULT 20, p_worker_id text DEFAULT 'request-delivery-worker'::text) RETURNS SETOF public.ph_request_delivery_outbox
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  safe_limit integer := greatest(1, least(coalesce(p_limit, 20), 100));
  safe_worker text := left(coalesce(nullif(btrim(p_worker_id), ''), 'request-delivery-worker'), 120);
begin
  if not private.is_service_role_request() then
    raise exception using errcode = '42501', message = 'DELIVERY_WORKER_FORBIDDEN';
  end if;

  return query
  with candidates as (
    select o.event_id
    from public.ph_request_delivery_outbox o
    where (
        o.status = 'pending'
        and o.next_attempt_at <= now()
      ) or (
        o.status = 'processing'
        and coalesce(o.lease_expires_at, o.last_attempt_at, o.updated_at, o.created_at)
            <= now()
      )
    order by o.created_at, o.event_id
    for update skip locked
    limit safe_limit
  )
  update public.ph_request_delivery_outbox o
  set status = 'processing',
      lease_token = extensions.gen_random_uuid(),
      lease_owner = safe_worker,
      lease_expires_at = now() + interval '2 minutes',
      first_attempt_at = coalesce(o.first_attempt_at, now()),
      last_attempt_at = now(),
      sanitized_error_code = null
  from candidates c
  where o.event_id = c.event_id
  returning o.*;
end;
$$;


ALTER FUNCTION public.claim_request_delivery_events(p_limit integer, p_worker_id text) OWNER TO postgres;

--
-- Name: FUNCTION claim_request_delivery_events(p_limit integer, p_worker_id text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.claim_request_delivery_events(p_limit integer, p_worker_id text) IS 'Service-only SKIP LOCKED lease claim for independent request delivery workers.';


--
-- Name: complete_password_change_profile(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.complete_password_change_profile(p_attempt_id uuid, p_auth_user_id uuid, p_password text, p_password_fingerprint text) RETURNS TABLE(status text, profile_id uuid, legacy_user_id integer, username text, display_name text, role text, division text, language text, must_change_password boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_attempt private.password_change_attempts%rowtype;
  v_legacy public.ph_app_users%rowtype;
  v_profile public.profiles%rowtype;
  v_fingerprint text := lower(coalesce(p_password_fingerprint, ''));
  v_username text;
  v_auth_password_hash text;
  v_auth_identity_count integer;
  v_auth_identity_username text;
  v_has_trusted_metadata boolean;
  v_email_confirmed_at timestamptz;
  v_banned_until timestamptz;
  v_legacy_id integer;
begin
  if p_attempt_id is null or p_auth_user_id is null then
    raise exception using errcode = '22023', message = 'password_change_attempt_required';
  end if;
  if length(coalesce(p_password, '')) < 6 then
    raise exception using errcode = '22023', message = 'password_too_short';
  end if;
  if v_fingerprint !~ '^[0-9a-f]{64}$' then
    raise exception using errcode = '22023', message = 'password_change_fingerprint_required';
  end if;

  select a.legacy_user_id into v_legacy_id
  from private.password_change_attempts a
  where a.attempt_id = p_attempt_id;
  if not found then
    raise exception using errcode = 'P0002', message = 'password_change_attempt_missing';
  end if;
  select private.password_change_username_v1(u.username) into v_username
  from public.ph_app_users u where u.id = v_legacy_id;
  if not found then
    raise exception using errcode = 'P0002', message = 'password_change_legacy_user_missing';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('password-change-profile:' || v_username, 0)
  );

  -- Keep the same lock order as prepare: advisory, legacy, attempt, profile.
  select u.* into v_legacy
  from public.ph_app_users u where u.id = v_legacy_id for update;
  select a.* into v_attempt
  from private.password_change_attempts a
  where a.attempt_id = p_attempt_id
  for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'password_change_attempt_missing';
  end if;
  if v_attempt.password_fingerprint <> v_fingerprint
     or v_attempt.auth_user_id is distinct from p_auth_user_id
     or v_attempt.legacy_user_id <> v_legacy.id then
    raise exception using errcode = '23514', message = 'password_change_attempt_conflict';
  end if;
  select p.* into v_profile
  from public.profiles p
  where p.id = p_auth_user_id
  for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'password_change_profile_missing';
  end if;

  v_username := private.password_change_username_v1(v_legacy.username);
  if private.password_change_username_v1(v_profile.username) <> v_username
     or v_profile.legacy_user_id is distinct from v_legacy.id then
    raise exception using errcode = '23505', message = 'password_change_profile_link_conflict';
  end if;
  if v_legacy.disabled_at is not null
     or v_profile.disabled_at is not null
     or (v_legacy.locked_until is not null and v_legacy.locked_until > now())
     or (v_profile.locked_until is not null and v_profile.locked_until > now()) then
    raise exception using errcode = '42501', message = 'password_change_inactive_account';
  end if;

  select u.encrypted_password, u.banned_until
    into v_auth_password_hash, v_banned_until
  from auth.users u where u.id = p_auth_user_id for share;
  if not found then
    raise exception using errcode = '23503', message = 'password_change_auth_user_missing';
  end if;
  if v_banned_until is not null and v_banned_until > now() then
    raise exception using errcode = '42501', message = 'password_change_inactive_account';
  end if;

  select count(distinct i.username), min(i.username), bool_or(i.trusted_metadata),
      max(i.email_confirmed_at), max(i.banned_until)
    into v_auth_identity_count, v_auth_identity_username, v_has_trusted_metadata,
      v_email_confirmed_at, v_banned_until
  from private.password_change_auth_identity_v1(p_auth_user_id) i;
  if coalesce(v_auth_identity_count, 0) <> 1 or v_auth_identity_username <> v_username then
    raise exception using errcode = '23514', message = 'password_change_auth_identity_conflict';
  end if;
  if not v_has_trusted_metadata and v_email_confirmed_at is null then
    raise exception using errcode = '23514', message = 'password_change_unconfirmed_auth_alias';
  end if;
  if v_banned_until is not null and v_banned_until > now() then
    raise exception using errcode = '42501', message = 'password_change_inactive_account';
  end if;
  if v_auth_password_hash is null
     or extensions.crypt(p_password, v_auth_password_hash) is distinct from v_auth_password_hash then
    raise exception using errcode = '23514', message = 'password_change_auth_password_mismatch';
  end if;

  if v_attempt.status = 'completed' then
    if v_legacy.must_change_password is distinct from false
       or v_profile.must_change_password is distinct from false
       or v_legacy.password is distinct from p_password then
      raise exception using errcode = '40001', message = 'password_change_attempt_stale';
    end if;
    return query select 'completed', v_profile.id, v_legacy.id, v_username,
      v_profile.display_name, v_profile.role, v_profile.division, v_profile.language, false;
    return;
  end if;

  if v_legacy.must_change_password is distinct from true
     or v_profile.must_change_password is distinct from true then
    raise exception using errcode = '40001', message = 'password_change_attempt_stale';
  end if;

  update public.ph_app_users
  set password = p_password,
      password_hash = null,
      password_salt = null,
      password_changed_at = now(),
      must_change_password = false
  where id = v_legacy.id;

  update public.profiles
  set must_change_password = false,
      updated_at = now()
  where id = v_profile.id;

  update private.password_change_attempts
  set status = 'completed', completed_at = now()
  where attempt_id = v_attempt.attempt_id;

  return query select 'completed', v_profile.id, v_legacy.id, v_username,
    v_profile.display_name, v_profile.role, v_profile.division, v_profile.language, false;
end
$_$;


ALTER FUNCTION public.complete_password_change_profile(p_attempt_id uuid, p_auth_user_id uuid, p_password text, p_password_fingerprint text) OWNER TO postgres;

--
-- Name: FUNCTION complete_password_change_profile(p_attempt_id uuid, p_auth_user_id uuid, p_password text, p_password_fingerprint text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.complete_password_change_profile(p_attempt_id uuid, p_auth_user_id uuid, p_password text, p_password_fingerprint text) IS 'Service-only atomic legacy/profile password completion for a prepared Auth update; preserves roles and account restrictions.';


--
-- Name: complete_request_delivery_event(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.complete_request_delivery_event(p_event_id uuid, p_lease_token uuid, p_channel_results jsonb DEFAULT '{}'::jsonb) RETURNS public.ph_request_delivery_outbox
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  updated_event public.ph_request_delivery_outbox%rowtype;
  email_result jsonb := coalesce(p_channel_results->'email', '{}'::jsonb);
  event_recipients jsonb := coalesce(email_result->'recipients', '[]'::jsonb);
  initial_message_id text := nullif(email_result->>'reply_to_message_id', '');
  thread_customer text;
  thread_rep_name text;
  thread_rep_email text;
begin
  if not private.is_service_role_request() then
    raise exception using errcode = '42501', message = 'DELIVERY_WORKER_FORBIDDEN';
  end if;

  perform public.record_request_delivery_channel_result(
    p_event_id, p_lease_token, coalesce(p_channel_results, '{}'::jsonb)
  );

  update public.ph_request_delivery_outbox o
  set status = 'delivered',
      delivered_at = now(),
      sanitized_error_code = null,
      lease_token = null,
      lease_owner = null,
      lease_expires_at = null
  where o.event_id = p_event_id
    and o.status = 'processing'
    and o.lease_token = p_lease_token
  returning o.* into updated_event;

  if not found then
    raise exception using errcode = '40001', message = 'DELIVERY_LEASE_LOST';
  end if;

  if updated_event.request_id is not null then
    update public.ph_request_history
    set delivery_state = 'delivered', updated_at = now()
    where unique_id = updated_event.request_id;
  end if;

  if updated_event.event_type in ('request_created', 'request_completed')
     and nullif(btrim(coalesce(updated_event.request_folder, '')), '') is not null
     and nullif(btrim(coalesce(updated_event.gmail_thread_id, '')), '') is not null then
    select
      coalesce(h.req_customer, a.req_customer, ''),
      coalesce(h.requested_by, a.requested_by, ''),
      coalesce(
        h.request_selected_rep_email, h.request_created_by_email,
        a.request_selected_rep_email, a.request_created_by_email, ''
      )
    into thread_customer, thread_rep_name, thread_rep_email
    from (values (1)) seed(n)
    left join public.ph_request_history h on h.unique_id = updated_event.request_id
    left join public.ph_active_request a on a.unique_id = updated_event.request_id
    limit 1;

    insert into public.ph_request_email_threads (
      request_folder, request_customer, sales_rep_name, sales_rep_email,
      recipients, initial_thread_id, initial_message_id,
      initial_email_sent_at, last_reply_sent_at, status, metadata
    )
    values (
      updated_event.request_folder,
      coalesce(thread_customer, ''),
      coalesce(thread_rep_name, ''),
      coalesce(thread_rep_email, ''),
      event_recipients,
      updated_event.gmail_thread_id,
      coalesce(
        case when updated_event.event_type = 'request_created'
          then nullif(email_result->>'message_id', '') end,
        initial_message_id,
        nullif(email_result->>'message_id', '')
      ),
      case when updated_event.event_type = 'request_created' then now() else null end,
      case when updated_event.event_type = 'request_completed' then now() else null end,
      case when updated_event.event_type = 'request_completed' then 'completed' else 'open' end,
      jsonb_build_object(
        'authority', 'request_delivery_worker',
        'delivery_event_id', updated_event.event_id,
        'delivery_mode', updated_event.delivery_mode
      )
    )
    on conflict (request_folder) do update set
      request_customer = coalesce(nullif(excluded.request_customer, ''), public.ph_request_email_threads.request_customer),
      sales_rep_name = coalesce(nullif(excluded.sales_rep_name, ''), public.ph_request_email_threads.sales_rep_name),
      sales_rep_email = coalesce(nullif(excluded.sales_rep_email, ''), public.ph_request_email_threads.sales_rep_email),
      recipients = case when excluded.recipients <> '[]'::jsonb then excluded.recipients else public.ph_request_email_threads.recipients end,
      initial_thread_id = coalesce(nullif(public.ph_request_email_threads.initial_thread_id, ''), excluded.initial_thread_id),
      initial_message_id = coalesce(nullif(public.ph_request_email_threads.initial_message_id, ''), excluded.initial_message_id),
      initial_email_sent_at = coalesce(public.ph_request_email_threads.initial_email_sent_at, excluded.initial_email_sent_at),
      last_reply_sent_at = coalesce(excluded.last_reply_sent_at, public.ph_request_email_threads.last_reply_sent_at),
      status = excluded.status,
      metadata = coalesce(public.ph_request_email_threads.metadata, '{}'::jsonb) || excluded.metadata;
  end if;

  return updated_event;
end;
$$;


ALTER FUNCTION public.complete_request_delivery_event(p_event_id uuid, p_lease_token uuid, p_channel_results jsonb) OWNER TO postgres;

--
-- Name: complete_season_sales_office_v1(text, text, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.complete_season_sales_office_v1(p_actor_username text, p_master_id text, p_expected_revision integer, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'extensions'
    AS $$
declare
  actor public.profiles := private.season_sales_assert_actor_v1(p_actor_username);
  settings jsonb := private.season_sales_settings_v1();
  current_season text := upper(btrim(coalesce(settings->>'seasonCode', '')));
  current_sales_year integer := private.season_sales_year_v1(settings->>'salesYear');
  state_row public.ph_season_sales_office_state;
  winner public.ph_master_inventory;
  evidence jsonb;
  watermark timestamptz;
  request_hash text;
  prior private.season_sales_office_idempotency;
  response_value jsonb;
  removed_mirror_ids jsonb := '[]'::jsonb;
  refresh_result jsonb;
begin
  perform set_config('lock_timeout', '2000', true);
  perform set_config('statement_timeout', '12000', true);
  if length(btrim(coalesce(p_idempotency_key, ''))) not between 12 and 180 then
    raise exception using errcode = '22023', message = 'SEASON_SALES_TOKEN_INVALID';
  end if;
  if btrim(coalesce(p_master_id, '')) = '' or p_expected_revision is null or p_expected_revision < 1 then
    raise exception using errcode = '22023', message = 'SEASON_SALES_REVISION_REQUIRED';
  end if;
  if current_season = '' or current_sales_year is null then
    raise exception using errcode = '22023', message = 'SEASON_SALES_SETTINGS_INVALID';
  end if;

  -- Match the reconciler's transaction lock before touching state or mirrors.
  -- This also serializes simultaneous retries of the same request token.
  perform pg_advisory_xact_lock(hashtextextended('season-sales-office-v1', 0));
  request_hash := encode(extensions.digest(concat_ws('|', p_master_id, p_expected_revision::text), 'sha256'), 'hex');
  select * into prior from private.season_sales_office_idempotency request
  where request.operation = 'complete' and request.actor_username = lower(actor.username)
    and request.idempotency_key = btrim(p_idempotency_key);
  if prior.idempotency_key is not null and prior.request_hash <> request_hash then
    raise exception using errcode = '22023', message = 'SEASON_SALES_TOKEN_CONFLICT';
  end if;

  select * into state_row from public.ph_season_sales_office_state state
  where state.winner_unique_id = btrim(p_master_id)
    and state.season_code = current_season and state.sales_year = current_sales_year
  order by state.updated_at desc limit 1 for update;

  if prior.idempotency_key is not null then
    -- A lost-response retry may acknowledge only that same completion. Never
    -- erase work that the rules reopened or whose winner/sales scope changed.
    if state_row.id is null or state_row.status <> 'done'
       or state_row.revision is distinct from (prior.response->>'revision')::integer
       or (prior.response ? 'stateId' and state_row.id::text <> prior.response->>'stateId')
       or (not (prior.response ? 'stateId') and
           (prior.response->>'completedAt' is null or state_row.completed_at is distinct from (prior.response->>'completedAt')::timestamptz)) then
      raise exception using errcode = '40001', message = 'SEASON_SALES_STALE_REVISION';
    end if;
    response_value := prior.response || jsonb_build_object('idempotentReplay', true);
  else
    if state_row.id is null then
      -- Legacy view rows can precede durable state. Classify only their linked
      -- ITEMCODE, then require this exact master to be the selected winner.
      select * into winner from public.ph_master_inventory m where m.unique_id = btrim(p_master_id);
      if winner.unique_id is null then
        raise exception using errcode = '40001', message = 'SEASON_SALES_NOT_FOUND';
      end if;
      refresh_result := private.refresh_eligible_season_sales_itemcode_v1(winner.itemcode, 'complete-legacy-row', null);
      if refresh_result->>'status' = 'maintenance_deferred' then
        raise exception using errcode = '55P03', message = 'SEASON_SALES_BUSY';
      end if;
      select * into state_row from public.ph_season_sales_office_state state
      where state.winner_unique_id = btrim(p_master_id)
        and state.season_code = current_season and state.sales_year = current_sales_year
      order by state.updated_at desc limit 1 for update;
      if state_row.id is null then
        raise exception using errcode = '40001', message = 'SEASON_SALES_WINNER_CHANGED';
      end if;
    end if;

    if state_row.status = 'done' then
      response_value := jsonb_build_object('ok', true, 'status', 'already_done',
        'masterId', p_master_id, 'stateId', state_row.id, 'revision', state_row.revision,
        'completedAt', state_row.completed_at);
    else
      if state_row.status <> 'open' then
        raise exception using errcode = '40001', message = 'SEASON_SALES_NOT_OPEN';
      end if;
      if state_row.revision <> p_expected_revision then
        raise exception using errcode = '40001', message = 'SEASON_SALES_STALE_REVISION';
      end if;
      select * into winner from public.ph_master_inventory m where m.unique_id = state_row.winner_unique_id for share;
      if winner.unique_id is null then
        raise exception using errcode = '40001', message = 'SEASON_SALES_WINNER_CHANGED';
      end if;
      winner.av_note := state_row.retained_av_note;
      evidence := private.season_sales_evidence_v1(to_jsonb(winner));
      select max(c.last_updated) into watermark from public.ph_cav_import c
      where upper(btrim(coalesce(c.itemcode, ''))) = state_row.itemcode_normalized
        and upper(btrim(coalesce(c.season, ''))) = state_row.season_code;
      update public.ph_season_sales_office_state state set
        status = 'done', revision = state.revision + 1, readiness_status = 'done',
        reopen_reason = null, completed_by = lower(actor.username), completed_at = now(),
        cav_watermark = watermark, evidence_ready_at_completion = coalesce((evidence->>'ready')::boolean, false),
        evidence_ready_seen_after_completion = coalesce((evidence->>'ready')::boolean, false),
        completed_evidence_snapshot = evidence, current_evidence_snapshot = evidence,
        source_fingerprint = evidence->>'fingerprint', updated_at = now()
      where state.id = state_row.id returning * into state_row;
      insert into public.ph_season_sales_office_events (state_id, event_type, actor_username, revision, metadata)
      values (state_row.id, 'completed', lower(actor.username), state_row.revision,
        jsonb_build_object('evidenceReady', state_row.evidence_ready_at_completion));
      response_value := jsonb_build_object('ok', true, 'status', 'done',
        'masterId', winner.unique_id, 'stateId', state_row.id,
        'revision', state_row.revision, 'completedAt', state_row.completed_at);
    end if;
  end if;

  -- Legacy/flyer aliases admitted by the Season view share the same master.
  -- Bloom Picker and Move work have independent lifecycles and are untouched.
  -- A different open scope owning this master wins over historical cleanup.
  with removed as (
    delete from public.ph_sales_office sales
    where (sales.unique_id = state_row.winner_unique_id or sales.master_id = state_row.winner_unique_id)
      and lower(btrim(coalesce(sales.so_source, 'season'))) not in ('bloom_picker', 'bloom-picker', 'move', 'moves')
      and btrim(coalesce(sales.order_folder, '')) = ''
      and btrim(coalesce(sales.order_number, '')) = ''
      and btrim(coalesce(sales.order_customer, '')) = ''
      and not exists (
        select 1 from public.ph_season_sales_office_state newer
        where newer.winner_unique_id = state_row.winner_unique_id
          and newer.status = 'open' and newer.id <> state_row.id
      )
    returning sales.unique_id
  )
  select coalesce(jsonb_agg(removed.unique_id order by removed.unique_id), '[]'::jsonb)
  into removed_mirror_ids from removed;
  response_value := response_value || jsonb_build_object('removedMirrorIds', removed_mirror_ids);

  if prior.idempotency_key is null then
    insert into private.season_sales_office_idempotency(operation, actor_username, idempotency_key, request_hash, response)
    values ('complete', lower(actor.username), btrim(p_idempotency_key), request_hash, response_value);
  end if;
  return response_value;
end
$$;


ALTER FUNCTION public.complete_season_sales_office_v1(p_actor_username text, p_master_id text, p_expected_revision integer, p_idempotency_key text) OWNER TO postgres;

--
-- Name: complete_shear_location_inquiry_v1(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.complete_shear_location_inquiry_v1(p_inquiry_id uuid, p_actor_username text, p_expected_revision integer) RETURNS public.ph_shear_location_inquiries
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor public.profiles;
  inquiry public.ph_shear_location_inquiries;
begin
  actor := private.shear_assert_active_actor_v1(p_actor_username);
  select * into inquiry from public.ph_shear_location_inquiries where id = p_inquiry_id for update;
  if inquiry.id is null then raise exception using errcode = '22023', message = 'shear_inquiry_not_found'; end if;
  if inquiry.revision <> p_expected_revision then raise exception using errcode = '40001', message = 'shear_revision_conflict'; end if;
  if inquiry.status not in ('open', 'in_progress') then raise exception using errcode = '40001', message = 'shear_status_conflict'; end if;
  update public.ph_shear_location_inquiries set status = 'complete', revision = revision + 1,
    completed_by_username = actor.username, completed_at = now(), updated_at = now()
  where id = inquiry.id returning * into inquiry;
  insert into public.ph_shear_location_events(inquiry_id, event_type, actor_username, revision)
  values (inquiry.id, 'completed', actor.username, inquiry.revision);
  return inquiry;
end
$$;


