-- Name: create_av_request_batch(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_av_request_batch(client_batch_id uuid, requests jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not private.can_create_av_requests() then
    raise exception using errcode = '42501', message = 'AV_REQUEST_CREATE_FORBIDDEN';
  end if;
  return private.insert_request_batch(
    client_batch_id,
    private.stamp_request_batch_creator(requests),
    'av'
  );
end;
$$;


