--
-- Name: create_codex_ops_task_v1(text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_codex_ops_task_v1(p_description text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  profile public.profiles%rowtype;
  task private.codex_ops_tasks%rowtype;
  clean_description text := btrim(coalesce(p_description, ''));
begin
  profile := private.require_codex_ops_dylan_v1();
  if not private.codex_ops_flag_enabled_v1('codex_ops_enabled') then
    raise exception using errcode = '42501', message = 'CODEX_OPS_SUBMISSION_DISABLED';
  end if;
  if char_length(clean_description) not between 4 and 12000 then
    raise exception using errcode = '22023', message = 'CODEX_OPS_DESCRIPTION_INVALID';
  end if;
  select * into task from private.codex_ops_tasks t
  where t.created_by = profile.id and t.client_idempotency_key = p_idempotency_key;
  if task.id is null then
    insert into private.codex_ops_tasks (
      created_by, created_by_username, client_idempotency_key,
      title, description
    ) values (
      profile.id, 'dylan_collyge', p_idempotency_key,
      left(regexp_replace(clean_description, E'[\\n\\r]+', ' ', 'g'), 120),
      clean_description
    ) returning * into task;
    insert into private.codex_ops_messages (
      task_id, actor_type, actor_username, body, client_idempotency_key
    ) values (task.id, 'user', 'dylan_collyge', clean_description, p_idempotency_key);
    insert into private.codex_ops_events (task_id, revision, event_type, sanitized_payload)
    values (task.id, task.revision, 'task.created', jsonb_build_object('status', task.status));
    insert into private.codex_ops_audit_events (task_id, actor_type, actor_key, action, outcome)
    values (task.id, 'user', 'dylan_collyge', 'task.create', 'succeeded');
  end if;
  return jsonb_build_object('id', task.id, 'status', task.status, 'revision', task.revision);
end;
$$;


ALTER FUNCTION public.create_codex_ops_task_v1(p_description text, p_idempotency_key uuid) OWNER TO postgres;

--
-- Name: create_eval_report2_batch_v1(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_eval_report2_batch_v1(p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  actor public.profiles;
  actor_username text;
  raw_items jsonb := coalesce(p_payload->'items', '[]'::jsonb);
  item jsonb;
  valid_items jsonb := '[]'::jsonb;
  resolved_items jsonb := '[]'::jsonb;
  report_id text;
  report_ids text[];
  matching_report_ids text[];
  itemcode text;
  work_rows jsonb := '[]'::jsonb;
  assignment_emails text[];
  required_actor_emails text[];
  work_record public.ph_eval_work;
begin
  actor := private.eval_work_assert_actor_v1(p_payload->>'actorUsername');
  actor_username := private.eval_normalize_user_v2(actor.username);
  if actor_username not in ('dylan_collyge', 'megan_kelly', 'jd_jones') then
    raise exception using errcode = '42501', message = 'eval_work_batch_create_forbidden';
  end if;
  if jsonb_typeof(raw_items) <> 'array' or jsonb_array_length(raw_items) < 1 or jsonb_array_length(raw_items) > 50 then
    raise exception using errcode = '22023', message = 'eval_work_batch_size_invalid';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('gnc-eval-report2-create:' || coalesce(p_payload->>'batchToken', ''), 0));

  for item in select value from jsonb_array_elements(raw_items) loop
    report_ids := private.eval_report2_context_ids_v1(item->'reportContext');
    report_id := report_ids[1];
    itemcode := upper(btrim(coalesce(item->>'itemcode', item #>> '{source,itemcode}', '')));
    if lower(btrim(coalesce(item #>> '{reportContext,sourceMode}', ''))) <> 'eval-report-2' then
      raise exception using errcode = '22023', message = 'eval_report2_source_invalid';
    end if;
    if itemcode = '' then
      raise exception using errcode = '22023', message = 'eval_work_batch_itemcode_invalid';
    end if;
    matching_report_ids := private.eval_report2_matching_reports_v1(item->'reportContext', itemcode, now());
    if cardinality(matching_report_ids) > 0 then
      item := jsonb_set(item, '{reportContext}', (item->'reportContext') || jsonb_build_object(
        'reportId', matching_report_ids[1],
        'reportIds', to_jsonb(matching_report_ids),
        'reportLabel', private.eval_report2_labels_v1(matching_report_ids)
      ), true);
      valid_items := valid_items || jsonb_build_array(
        jsonb_set(item, '{itemcode}', to_jsonb(itemcode), true)
      );
    else
      resolved_items := resolved_items || jsonb_build_array(
        jsonb_build_object('itemcode', itemcode, 'reportId', report_id, 'reportIds', to_jsonb(report_ids), 'result', 'already_resolved')
      );
    end if;
  end loop;

  if jsonb_array_length(valid_items) = 0 then
    return jsonb_build_object(
      'result', 'already_resolved',
      'rows', '[]'::jsonb,
      'resolvedItemcodes', resolved_items,
      'assignmentRefreshed', false
    );
  end if;

  for work_record in
    select * from public.create_eval_work_batch_multi_v2(
      p_payload || jsonb_build_object('items', valid_items)
    )
  loop
    work_rows := work_rows || jsonb_build_array(to_jsonb(work_record));
  end loop;

  if actor_username = 'jd_jones' then
    required_actor_emails := private.eval_report2_verified_user_emails_v1(array['jd_jones']);
    if cardinality(required_actor_emails) <> 1 then
      raise exception using errcode = '40001', message = 'eval_work_required_assignment_recipient_unavailable';
    end if;
    update public.ph_request_delivery_outbox outbox
    set payload = jsonb_set(
      outbox.payload,
      '{assignmentRecipients}',
      (
        select to_jsonb(array_agg(distinct email order by email))
        from (
          select lower(btrim(value)) as email
          from jsonb_array_elements_text(coalesce(outbox.payload->'assignmentRecipients', '[]'::jsonb))
          union all
          select unnest(required_actor_emails)
        ) recipients
        where email ~* '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$'
      ),
      true
    ), updated_at = now()
    where outbox.event_id in (
      select (row_payload->>'assignment_event_id')::uuid
      from jsonb_array_elements(work_rows) as selected_work(row_payload)
    );
  end if;

  work_rows := private.eval_report2_group_assignment_delivery_v1(
    work_rows,
    p_payload->>'batchToken'
  );

  select coalesce(array_agg(distinct lower(btrim(value)) order by lower(btrim(value))), '{}'::text[])
  into assignment_emails
  from jsonb_array_elements(work_rows) as selected_work(row_payload)
  join public.ph_request_delivery_outbox outbox
    on outbox.event_id = (row_payload->>'assignment_event_id')::uuid
  cross join lateral jsonb_array_elements_text(coalesce(outbox.payload->'assignmentRecipients', '[]'::jsonb)) value;

  return jsonb_build_object(
    'result', case when jsonb_array_length(resolved_items) > 0 then 'partial_success' else 'created' end,
    'rows', work_rows,
    'resolvedItemcodes', resolved_items,
    'assignmentRecipients', to_jsonb(coalesce(assignment_emails, '{}'::text[])),
    'assignmentRefreshed', exists (
      select 1 from jsonb_array_elements(work_rows) as selected_work(row_payload)
      where coalesce((row_payload #>> '{source_context,assignmentRefreshed}')::boolean, false)
    )
  );
end
$_$;


ALTER FUNCTION public.create_eval_report2_batch_v1(p_payload jsonb) OWNER TO postgres;

--
-- Name: FUNCTION create_eval_report2_batch_v1(p_payload jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.create_eval_report2_batch_v1(p_payload jsonb) IS 'Transactional stale-safe Eval Reports #2 batch creation. Resolved ITEMCODEs are skipped while valid selections are created.';


--
-- Name: create_eval_work_batch_multi_v2(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_eval_work_batch_multi_v2(p_payload jsonb) RETURNS SETOF public.ph_eval_work
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  normalized jsonb := private.eval_work_normalize_assignees_v1(p_payload->'assignees');
  usernames text[];
  emails text[];
  profiles jsonb;
  primary_assignee jsonb;
  assignment_recipients text[];
  work public.ph_eval_work;
begin
  select array_agg(value order by ordinality) into usernames
  from jsonb_array_elements_text(normalized->'usernames') with ordinality;
  select array_agg(value order by ordinality) into emails
  from jsonb_array_elements_text(normalized->'emails') with ordinality;
  profiles := normalized->'profiles';
  primary_assignee := profiles->0;
  select array_agg(distinct value order by value) into assignment_recipients
  from unnest(private.eval_work_required_manager_emails_v2() || emails) value;
  for work in
    select * from public.create_eval_work_batch_v2(p_payload || jsonb_build_object(
      'assigneeUsername', primary_assignee->>'username',
      'assigneeEmail', primary_assignee->>'email'
    ))
  loop
    if cardinality(work.assignee_usernames) > 0 and work.assignee_usernames is distinct from usernames then
      raise exception using errcode = '40001', message = 'eval_work_create_token_assignees_conflict';
    end if;
    update public.ph_eval_work
      set assignee_usernames = usernames, assignee_profiles = profiles
      where id = work.id returning * into work;
    update public.ph_request_delivery_outbox
      set payload = payload || jsonb_build_object(
        'assigneeUsernames', to_jsonb(usernames),
        'assignees', profiles,
        'assignmentRecipients', to_jsonb(assignment_recipients)
      ), updated_at = now()
      where event_id = work.assignment_event_id;
    return next work;
  end loop;
  return;
end
$$;


ALTER FUNCTION public.create_eval_work_batch_multi_v2(p_payload jsonb) OWNER TO postgres;

--
-- Name: create_eval_work_batch_v1(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_eval_work_batch_v1(p_payload jsonb) RETURNS SETOF public.ph_eval_work
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor public.profiles;
  item jsonb;
  origin public.ph_master_inventory;
  context_rows jsonb;
  settings jsonb;
  inquiry jsonb;
  create_payload jsonb;
  new_work public.ph_eval_work;
  batch_token_value text := trim(coalesce(p_payload->>'batchToken', ''));
  items jsonb := coalesce(p_payload->'items', '[]'::jsonb);
  item_count integer;
  distinct_item_count integer;
  report_context jsonb;
  overlay jsonb;
  temporary_key text;
  temporary_values jsonb;
  temporary_fields jsonb;
  temporary_limit integer;
begin
  actor := private.eval_work_assert_actor_v1(p_payload->>'actorUsername');
  if lower(actor.username) not in ('dylan_collyge', 'megan_kelly') then
    raise exception using errcode = '42501', message = 'eval_work_batch_create_forbidden';
  end if;
  if length(batch_token_value) < 16 or length(batch_token_value) > 200 then
    raise exception using errcode = '22023', message = 'eval_work_batch_token_invalid';
  end if;
  if jsonb_typeof(items) <> 'array' then
    raise exception using errcode = '22023', message = 'eval_work_batch_items_invalid';
  end if;
  item_count := jsonb_array_length(items);
  if item_count < 1 or item_count > 50 then
    raise exception using errcode = '22023', message = 'eval_work_batch_size_invalid';
  end if;
  select count(distinct lower(trim(coalesce(value#>>'{source,itemcode}', ''))))
    into distinct_item_count
  from jsonb_array_elements(items);
  if distinct_item_count <> item_count then
    raise exception using errcode = '22023', message = 'eval_work_batch_duplicate_itemcode';
  end if;

  -- Validate every member before creating any durable assignment. The RPC call
  -- is one database transaction, so any later conflict also rolls back all rows.
  for item in select value from jsonb_array_elements(items) loop
    if jsonb_typeof(item) <> 'object'
       or length(trim(coalesce(item->>'createToken', ''))) < 16
       or jsonb_typeof(coalesce(item->'source', '{}'::jsonb)) <> 'object'
       or jsonb_typeof(coalesce(item->'inquiry', '{}'::jsonb)) <> 'object' then
      raise exception using errcode = '22023', message = 'eval_work_batch_item_invalid';
    end if;
    select m.* into origin
    from public.ph_master_inventory m
    where m.unique_id = trim(coalesce(item#>>'{source,unique_id}', ''))
    limit 1;
    if origin.unique_id is null
       or lower(trim(coalesce(origin.itemcode, ''))) <> lower(trim(coalesce(item#>>'{source,itemcode}', '')))
       or trim(coalesce(origin.locationcode, '')) <> trim(coalesce(item#>>'{source,locationcode}', ''))
       or trim(coalesce(origin.lotcode, '')) <> trim(coalesce(item#>>'{source,lotcode}', '')) then
      raise exception using errcode = '40001', message = 'eval_work_batch_origin_identity_conflict';
    end if;
    context_rows := private.eval_work_context_rows_v1(origin.itemcode);
    settings := private.eval_work_settings_v1();
    if jsonb_typeof(settings) <> 'object' or coalesce(settings->>'seasonCode', '') = '' or coalesce(settings->>'salesYear', '') = '' then
      raise exception using errcode = '40001', message = 'eval_work_batch_settings_unavailable';
    end if;
    inquiry := item->'inquiry';
    perform private.validate_eval_work_inquiry_v1(inquiry, origin.itemcode, context_rows);
    if jsonb_typeof(coalesce(inquiry->'rowOverlays', '[]'::jsonb)) <> 'array'
       or jsonb_array_length(coalesce(inquiry->'rowOverlays', '[]'::jsonb)) <> jsonb_array_length(context_rows)
       or (select count(distinct value->>'unique_id') from jsonb_array_elements(coalesce(inquiry->'rowOverlays', '[]'::jsonb))) <> jsonb_array_length(context_rows) then
      raise exception using errcode = '40001', message = 'eval_work_batch_complete_row_set_required';
    end if;
    for overlay in select value from jsonb_array_elements(coalesce(inquiry->'rowOverlays', '[]'::jsonb)) loop
      if (overlay ? 'temporaryValues') <> (overlay ? 'temporaryChangedFields') then
        raise exception using errcode = '22023', message = 'eval_work_batch_temporary_fields_invalid';
      end if;
      if overlay ? 'temporaryValues' then
        temporary_values := overlay->'temporaryValues';
        temporary_fields := overlay->'temporaryChangedFields';
        if jsonb_typeof(temporary_values) <> 'object'
           or jsonb_typeof(temporary_fields) <> 'array'
           or (select count(*) from jsonb_object_keys(temporary_values)) <> jsonb_array_length(temporary_fields)
           or (select count(distinct value) from jsonb_array_elements_text(temporary_fields)) <> jsonb_array_length(temporary_fields) then
          raise exception using errcode = '22023', message = 'eval_work_batch_temporary_fields_invalid';
        end if;
        for temporary_key in select key from jsonb_each(temporary_values) loop
          temporary_limit := case temporary_key
            when 'holdstopreason' then 1000
            when 'holdstopbegindate' then 180
            when 'locationnote' then 4000
            when 'locationnotedate' then 180
            when 'locationptn1' then 2000
            when 'suspendto' then 1000
            when 'specialpuller' then 1000
            else null
          end;
          if temporary_limit is null
             or not (temporary_fields ? temporary_key)
             or jsonb_typeof(temporary_values->temporary_key) <> 'string'
             or length(temporary_values->>temporary_key) > temporary_limit then
            raise exception using errcode = '22023', message = 'eval_work_batch_temporary_field_invalid';
          end if;
        end loop;
      end if;
    end loop;
    report_context := coalesce(item->'reportContext', '{}'::jsonb);
    if jsonb_typeof(report_context) <> 'object' or octet_length(report_context::text) > 4096 then
      raise exception using errcode = '22023', message = 'eval_work_batch_report_context_invalid';
    end if;
  end loop;

  for item in select value from jsonb_array_elements(items) loop
    create_payload := jsonb_build_object(
      'actorUsername', lower(actor.username),
      'createToken', trim(item->>'createToken'),
      'assigneeUsername', p_payload->>'assigneeUsername',
      'assigneeEmail', p_payload->>'assigneeEmail',
      'instructions', p_payload->>'instructions',
      'completionRecipients', coalesce(p_payload->'completionRecipients', '[]'::jsonb),
      'source', item->'source',
      'inquiry', item->'inquiry'
    );
    select * into new_work from public.create_eval_work_v1(create_payload);
    update public.ph_eval_work
    set batch_token = batch_token_value,
        source_context = jsonb_build_object(
          'report', coalesce(item->'reportContext', '{}'::jsonb),
          'inventorySignature', left(coalesce(p_payload->>'inventorySignature', ''), 512),
          'settingsSignature', left(coalesce(p_payload->>'settingsSignature', ''), 1024)
        ),
        updated_at = now()
    where id = new_work.id
    returning * into new_work;
    return next new_work;
  end loop;
  return;
end
$$;


ALTER FUNCTION public.create_eval_work_batch_v1(p_payload jsonb) OWNER TO postgres;

--
-- Name: FUNCTION create_eval_work_batch_v1(p_payload jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.create_eval_work_batch_v1(p_payload jsonb) IS 'Service-only atomic and idempotent Eval Reports #2 batch creation. One item creates one Eval Work assignment and existing delivery-outbox event.';


--
-- Name: create_eval_work_batch_v2(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_eval_work_batch_v2(p_payload jsonb) RETURNS SETOF public.ph_eval_work
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  actor public.profiles;
  assignee public.profiles;
  item jsonb;
  origin public.ph_master_inventory;
  first_origin public.ph_master_inventory;
  work public.ph_eval_work;
  delivery public.ph_request_delivery_outbox;
  items jsonb := coalesce(p_payload->'items', '[]'::jsonb);
  inquiry jsonb;
  context_rows jsonb;
  settings jsonb;
  origin_ids text[];
  selected_filters text[];
  matched_users text[];
  hinted_users text[];
  assignment_refreshed boolean := false;
  extra_recipients text[];
  required_recipients text[];
  completion_recipients text[];
  assignment_recipients text[];
  create_token_value text;
  batch_token_value text := trim(coalesce(p_payload->>'batchToken', ''));
  membership_signature text;
  ordinal_value integer;
  normalized_assignees jsonb;
  normalized_usernames text[];
  normalized_profiles jsonb;
begin
  actor := private.eval_work_assert_actor_v1(p_payload->>'actorUsername');
  if lower(actor.username) not in ('dylan_collyge', 'megan_kelly', 'jd_jones') then
    raise exception using errcode = '42501', message = 'eval_work_batch_create_forbidden';
  end if;
  assignee := private.eval_work_assert_actor_v1(p_payload->>'assigneeUsername');
  if trim(coalesce(p_payload->>'assigneeEmail', '')) !~* '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then
    raise exception using errcode = '22023', message = 'eval_work_assignee_email_invalid';
  end if;
  if jsonb_typeof(p_payload->'assignees') = 'array' then
    normalized_assignees := private.eval_work_normalize_assignees_v1(p_payload->'assignees');
    select array_agg(assignee_name order by ordinal)
      into normalized_usernames
    from jsonb_array_elements_text(normalized_assignees->'usernames') with ordinality as names(assignee_name, ordinal);
    normalized_profiles := normalized_assignees->'profiles';
  else
    normalized_usernames := array[lower(assignee.username)];
    normalized_profiles := jsonb_build_array(jsonb_build_object(
      'username', lower(assignee.username),
      'display', coalesce(nullif(assignee.display_name, ''), assignee.username),
      'email', lower(trim(p_payload->>'assigneeEmail'))
    ));
  end if;
  if length(batch_token_value) < 16 or length(batch_token_value) > 240
     or jsonb_typeof(items) <> 'array' or jsonb_array_length(items) < 1 or jsonb_array_length(items) > 50 then
    raise exception using errcode = '22023', message = 'eval_work_batch_invalid';
  end if;

  required_recipients := private.eval_work_required_manager_emails_v2();
  if cardinality(required_recipients) <> 2 then
    raise exception using errcode = '40001', message = 'eval_work_required_manager_recipient_unavailable';
  end if;
  select coalesce(array_agg(distinct lower(trim(value))) filter (
    where trim(value) ~* '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'), '{}'::text[])
  into extra_recipients
  from jsonb_array_elements_text(coalesce(p_payload->'completionRecipients', '[]'::jsonb));
  select array_agg(distinct value order by value) into completion_recipients
  from unnest(required_recipients || coalesce(extra_recipients, '{}'::text[])) value;
  select array_agg(distinct value order by value) into assignment_recipients
  from unnest(required_recipients || array[lower(trim(p_payload->>'assigneeEmail'))]) value;

  for item in select value from jsonb_array_elements(items) loop
    create_token_value := trim(coalesce(item->>'createToken', ''));
    if length(create_token_value) < 16 or length(create_token_value) > 240
       or trim(coalesce(item->>'itemcode', '')) = '' then
      raise exception using errcode = '22023', message = 'eval_work_multi_origin_item_invalid';
    end if;
    context_rows := private.eval_work_itemcode_context_rows_v1(item->>'itemcode');
    if jsonb_array_length(context_rows) < 1 then
      raise exception using errcode = '40001', message = 'eval_work_itemcode_membership_empty';
    end if;
    select coalesce(array_agg(value), '{}'::text[]) into selected_filters
    from jsonb_array_elements_text(coalesce(
      item#>'{reportContext,selectedUserFilters}',
      item#>'{reportContext,assignedToUsers}',
      jsonb_build_array('all_users')
    )) value;
    matched_users := private.eval_work_match_assignment_users_v1(item->>'itemcode', selected_filters);
    inquiry := private.eval_work_expand_inquiry_rows_v1(coalesce(item->'inquiry', '{}'::jsonb), context_rows);
    perform private.validate_eval_work_inquiry_v1(inquiry, item->>'itemcode', context_rows);
  end loop;

  settings := private.eval_work_settings_v1();
  if jsonb_typeof(settings) <> 'object' or coalesce(settings->>'seasonCode', '') = '' or coalesce(settings->>'salesYear', '') = '' then
    raise exception using errcode = '40001', message = 'eval_work_settings_unavailable';
  end if;

  for item in select value from jsonb_array_elements(items) loop
    create_token_value := trim(item->>'createToken');
    select * into work from public.ph_eval_work where create_token = create_token_value limit 1;
    if work.id is not null then
      if lower(work.creator_username) <> lower(actor.username) or work.contract_version <> 'eval-work-v2-multi-origin' then
        raise exception using errcode = '42501', message = 'eval_work_create_token_forbidden';
      end if;
      return next work;
      continue;
    end if;

    context_rows := private.eval_work_itemcode_context_rows_v1(item->>'itemcode');
    select array_agg(value->>'unique_id' order by ordinality) into origin_ids
    from jsonb_array_elements(context_rows) with ordinality;
    membership_signature := private.eval_work_membership_signature_v1(context_rows);
    select * into first_origin from public.ph_master_inventory where unique_id = origin_ids[1];
    inquiry := private.eval_work_expand_inquiry_rows_v1(coalesce(item->'inquiry', '{}'::jsonb), context_rows);
    select coalesce(array_agg(value), '{}'::text[]) into selected_filters
    from jsonb_array_elements_text(coalesce(
      item#>'{reportContext,selectedUserFilters}',
      item#>'{reportContext,assignedToUsers}',
      jsonb_build_array('all_users')
    )) value;
    matched_users := private.eval_work_match_assignment_users_v1(item->>'itemcode', selected_filters);
    select coalesce(array_agg(distinct private.eval_normalize_user_v2(value) order by private.eval_normalize_user_v2(value)), '{}'::text[])
      into hinted_users
    from jsonb_array_elements_text(coalesce(item#>'{reportContext,matchedAssignedToUsers}', '[]'::jsonb)) value
    where private.eval_normalize_user_v2(value) <> '';
    assignment_refreshed := cardinality(hinted_users) > 0 and hinted_users is distinct from matched_users;

    insert into public.ph_eval_work (
      create_token, contract_version, creator_username, creator_display,
      assignee_username, assignee_display, assignee_email, instructions,
      completion_recipients, itemcode, commonname, contsize,
      origin_unique_id, origin_locationcode, origin_lotcode, origin_source,
      origin_snapshot, context_rows, inventory_signature, settings_signature,
      inquiry_draft, origin_count, assigned_to_users, assignee_usernames, assignee_profiles, batch_token, source_context
    ) values (
      create_token_value, 'eval-work-v2-multi-origin', lower(actor.username), coalesce(nullif(actor.display_name, ''), actor.username),
      lower(assignee.username), coalesce(nullif(assignee.display_name, ''), assignee.username), lower(trim(p_payload->>'assigneeEmail')),
      left(trim(coalesce(p_payload->>'instructions', '')), 4000), completion_recipients,
      first_origin.itemcode, coalesce(first_origin.commonname, ''), coalesce(first_origin.contsize, ''),
      first_origin.unique_id, coalesce(first_origin.locationcode, ''), coalesce(first_origin.lotcode, ''), coalesce(first_origin.source, ''),
      to_jsonb(first_origin), context_rows, membership_signature, md5(settings::text), inquiry,
      cardinality(origin_ids), matched_users, normalized_usernames, normalized_profiles, batch_token_value,
      jsonb_build_object(
        'scopeContract', 'itemcode-all-rows-v1',
        'membershipSignature', membership_signature,
        'membershipCount', cardinality(origin_ids),
        'assignmentRefreshed', assignment_refreshed,
        'report', coalesce(item->'reportContext', '{}'::jsonb) || jsonb_build_object(
          'selectedUserFilters', to_jsonb(selected_filters),
          'matchedAssignedToUsers', to_jsonb(matched_users),
          'assignmentRefreshed', assignment_refreshed
        ),
        'inventorySignature', left(coalesce(p_payload->>'inventorySignature', ''), 512),
        'settingsSignature', left(coalesce(p_payload->>'settingsSignature', ''), 1024)
      )
    ) returning * into work;

    ordinal_value := 0;
    for origin in
      select m.*
      from public.ph_master_inventory m
      join unnest(origin_ids) with ordinality selected(uid, ordinal) on selected.uid = m.unique_id
      order by selected.ordinal
    loop
      ordinal_value := ordinal_value + 1;
      insert into public.ph_eval_work_origin_rows (
        eval_work_id, origin_unique_id, itemcode, locationcode, lotcode, source,
        block_alpha, block_number, ordinal, origin_snapshot
      ) values (
        work.id, origin.unique_id, origin.itemcode, coalesce(origin.locationcode, ''),
        coalesce(origin.lotcode, ''), coalesce(origin.source, ''),
        private.eval_work_block_alpha_v2(origin.locationcode), private.eval_work_block_number_v2(origin.locationcode),
        ordinal_value, to_jsonb(origin)
      );
    end loop;

    insert into public.ph_eval_work_events(eval_work_id, event_type, actor_username, version, metadata)
    values (work.id, 'created', lower(actor.username), work.version,
      jsonb_build_object('originCount', work.origin_count, 'scopeContract', 'itemcode-all-rows-v1',
        'proposalCount', coalesce(jsonb_array_length(inquiry#>'{transaction,requestActions}'), 0),
        'assignmentRefreshed', assignment_refreshed));

    insert into public.ph_request_delivery_outbox(event_key, event_type, request_id, payload, status, next_attempt_at)
    values (
      'eval-work:' || work.id::text || ':assignment:v' || work.version::text,
      'eval_work_assignment', work.id::text,
      jsonb_build_object(
        'contractVersion', 'eval-work-v2-multi-origin', 'scopeContract', 'itemcode-all-rows-v1',
        'membershipSignature', membership_signature, 'membershipCount', work.origin_count,
        'deliveryKind', 'assignment', 'evalWorkId', work.id,
        'assigneeUsername', work.assignee_username, 'assigneeDisplay', work.assignee_display,
        'assigneeEmail', work.assignee_email, 'assignmentRecipients', to_jsonb(assignment_recipients),
        'lockedManagerRecipients', jsonb_build_array('dylan_collyge', 'megan_kelly'),
        'creatorUsername', work.creator_username, 'creatorDisplay', work.creator_display,
        'instructions', work.instructions, 'itemcode', work.itemcode,
        'commonname', work.commonname, 'contsize', work.contsize,
        'source', jsonb_build_object('unique_id', work.origin_unique_id, 'itemcode', work.itemcode,
          'locationcode', work.origin_locationcode, 'lotcode', work.origin_lotcode, 'source_table', 'ph_master_inventory'),
        'origins', context_rows, 'selectedUserFilters', to_jsonb(selected_filters),
        'matchedAssignedToUsers', to_jsonb(matched_users), 'assignedToUsers', to_jsonb(work.assigned_to_users),
        'assignmentRefreshed', assignment_refreshed,
        'inquiry', work.inquiry_draft
      ), 'pending', now()
    ) on conflict (event_key) do update set payload = excluded.payload, updated_at = now()
    returning * into delivery;
    update public.ph_eval_work set assignment_event_id = delivery.event_id where id = work.id returning * into work;
    return next work;
  end loop;
  return;
end
$_$;


ALTER FUNCTION public.create_eval_work_batch_v2(p_payload jsonb) OWNER TO postgres;

--
-- Name: FUNCTION create_eval_work_batch_v2(p_payload jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.create_eval_work_batch_v2(p_payload jsonb) IS 'Service-only atomic batch creation. New work derives every current ITEMCODE row and stores itemcode-all-rows-v1 membership.';


--
-- Name: create_eval_work_legacy_sep09_v1(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_eval_work_legacy_sep09_v1(p_payload jsonb) RETURNS public.ph_eval_work
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  normalized jsonb := private.eval_work_normalize_assignees_v1(p_payload->'assignees');
  usernames text[];
  emails text[];
  profiles jsonb;
  primary_assignee jsonb;
  assignment_recipients text[];
  work public.ph_eval_work;
begin
  -- The App API supplies authenticated actor and verified evaluator emails.
  if not private.is_service_role_request() then
    raise exception using errcode = '42501', message = 'eval_work_create_forbidden';
  end if;
  select array_agg(value order by ordinality) into usernames
  from jsonb_array_elements_text(normalized->'usernames') with ordinality;
  select array_agg(value order by ordinality) into emails
  from jsonb_array_elements_text(normalized->'emails') with ordinality;
  profiles := normalized->'profiles';
  primary_assignee := profiles->0;
  work := public.create_eval_work_v1(p_payload || jsonb_build_object(
    'assigneeUsername', primary_assignee->>'username',
    'assigneeEmail', primary_assignee->>'email'
  ));
  if cardinality(work.assignee_usernames) > 0 and work.assignee_usernames is distinct from usernames then
    raise exception using errcode = '40001', message = 'eval_work_create_token_assignees_conflict';
  end if;
  -- A retry originating in a newer open client may reuse its saved create token
  -- after a rollback. Keep that review's already-frozen assignment and recipients.
  if coalesce(work.source_context, '{}'::jsonb) ? 'reviewAssignment' then
    return work;
  end if;
  select array_agg(distinct value order by value) into assignment_recipients
  from unnest(private.eval_work_required_manager_emails_v2() || emails) value;
  update public.ph_eval_work
    set assignee_usernames = usernames, assignee_profiles = profiles
    where id = work.id returning * into work;
  update public.ph_request_delivery_outbox
    set payload = payload || jsonb_build_object(
      'assigneeUsernames', to_jsonb(usernames),
      'assignees', profiles,
      'assignmentRecipients', to_jsonb(assignment_recipients)
    ), updated_at = now()
    where event_id = work.assignment_event_id;
  return work;
end
$$;


ALTER FUNCTION public.create_eval_work_legacy_sep09_v1(p_payload jsonb) OWNER TO postgres;

--
-- Name: FUNCTION create_eval_work_legacy_sep09_v1(p_payload jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.create_eval_work_legacy_sep09_v1(p_payload jsonb) IS 'Service-only Sep 9 manual-assignee creation contract. Preserves baseline actor, token, source, inquiry and recipient checks; frozen modern review retries remain unchanged.';


--
-- Name: create_eval_work_multi_v1(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_eval_work_multi_v1(p_payload jsonb) RETURNS public.ph_eval_work
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  actor public.profiles;
  token_value text := btrim(coalesce(p_payload->>'createToken', ''));
  setup jsonb;
  evaluator jsonb;
  extras jsonb := coalesce(p_payload->'additionalCompletionRecipients', '[]'::jsonb);
  entry jsonb;
  email_value text;
  recipient_profile public.profiles;
  recipients text[];
  recipient_profiles jsonb;
  frozen_context jsonb;
  assignment_recipients text[];
  work public.ph_eval_work;
begin
  if not private.is_service_role_request() then
    raise exception using errcode = '42501', message = 'eval_work_create_forbidden';
  end if;
  actor := private.eval_work_assert_actor_v1(p_payload->>'actorUsername');
  if lower(actor.username) not in ('dylan_collyge', 'megan_kelly', 'jd_jones') or actor.must_change_password then
    raise exception using errcode = '42501', message = 'eval_work_create_forbidden';
  end if;
  if length(token_value) < 16 or length(token_value) > 240 then
    raise exception using errcode = '22023', message = 'eval_work_create_token_invalid';
  end if;
  -- Serialize only retries of this token, never a global creation lock. A retry
  -- returns the frozen work before reading today's assignment or recipients.
  perform pg_advisory_xact_lock(hashtextextended('eval-review-create:' || token_value, 0));
  select w.* into work from public.ph_eval_work w where w.create_token = token_value;
  if work.id is not null then
    if lower(work.creator_username) <> lower(actor.username) then
      raise exception using errcode = '42501', message = 'eval_work_create_token_forbidden';
    end if;
    return work;
  end if;
  if btrim(coalesce(p_payload->>'expectedAssignmentRevision', '')) = '' then
    raise exception using errcode = '22023', message = 'REVIEW_CONFIRMATION_REQUIRED';
  end if;
  setup := private.eval_work_review_setup_v1(p_payload, true);
  if p_payload->>'expectedAssignmentRevision' <> setup->>'assignmentRevision' then
    raise exception using errcode = '22023', message = 'REVIEW_ASSIGNMENT_CHANGED';
  end if;
  evaluator := setup->'evaluator';
  recipients := array[evaluator->>'email'];
  recipient_profiles := jsonb_build_array(evaluator);
  if jsonb_typeof(extras) <> 'array' or jsonb_array_length(extras) > 100 then
    raise exception using errcode = '22023', message = 'REVIEW_RECIPIENT_INVALID';
  end if;
  for entry in select value from jsonb_array_elements(extras) loop
    if jsonb_typeof(entry) <> 'string' then
      raise exception using errcode = '22023', message = 'REVIEW_RECIPIENT_INVALID';
    end if;
    email_value := lower(btrim(entry #>> '{}'));
    if email_value !~* '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$' then
      raise exception using errcode = '22023', message = 'REVIEW_RECIPIENT_INVALID';
    end if;
    if email_value = any(recipients) then continue; end if;
    select p.* into recipient_profile from public.profiles p
    join auth.users u on u.id = p.id
    where lower(btrim(u.email)) = email_value and p.disabled_at is null
      and (p.locked_until is null or p.locked_until <= now()) for share of p, u;
    if recipient_profile.id is null then
      raise exception using errcode = '22023', message = 'REVIEW_RECIPIENT_INVALID';
    end if;
    recipients := array_append(recipients, email_value);
    recipient_profiles := recipient_profiles || jsonb_build_array(jsonb_build_object(
      'username', lower(recipient_profile.username),
      'displayName', coalesce(nullif(btrim(recipient_profile.display_name), ''), recipient_profile.username),
      'email', email_value));
  end loop;
  frozen_context := jsonb_build_object('reviewAssignment', jsonb_build_object('evaluator', evaluator,
    'completionRecipients', recipient_profiles, 'assignmentRevision', setup->>'assignmentRevision'));
  if octet_length(frozen_context::text) > 8192 then
    raise exception using errcode = '22023', message = 'REVIEW_RECIPIENT_INVALID';
  end if;
  -- Construct the base payload from an allowlist. Manual assignees, recipient
  -- arrays, and browser actor fields cannot override the authoritative result.
  work := private.create_eval_work_review_base_v1(jsonb_build_object(
    'actorUsername', lower(actor.username), 'createToken', token_value,
    'source', setup->'source',
    'instructions', p_payload->>'instructions',
    'assigneeUsername', evaluator->>'username', 'assigneeEmail', evaluator->>'email',
    'completionRecipients', to_jsonb(recipients)
  ) || case when p_payload->'inquiry' is null or p_payload->'inquiry' = 'null'::jsonb
       then '{}'::jsonb else jsonb_build_object('inquiry', p_payload->'inquiry') end);
  frozen_context := coalesce(work.source_context, '{}'::jsonb) || frozen_context;
  if octet_length(frozen_context::text) > 8192 then
    raise exception using errcode = '22023', message = 'REVIEW_RECIPIENT_INVALID';
  end if;
  update public.ph_eval_work set source_context = frozen_context
    where id = work.id returning * into work;
  select array_agg(distinct value order by value) into assignment_recipients
  from unnest(private.eval_work_required_manager_emails_v2() || array[evaluator->>'email']) value;
  update public.ph_request_delivery_outbox
    set payload = payload || jsonb_build_object(
      'assigneeUsernames', to_jsonb(work.assignee_usernames), 'assignees', work.assignee_profiles,
      'assignmentRecipients', to_jsonb(assignment_recipients)), updated_at = now()
    where event_id = work.assignment_event_id;
  return work;
end
$_$;


ALTER FUNCTION public.create_eval_work_multi_v1(p_payload jsonb) OWNER TO postgres;

--
-- Name: create_eval_work_v1(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_eval_work_v1(p_payload jsonb) RETURNS public.ph_eval_work
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  actor public.profiles;
  assignee public.profiles;
  origin public.ph_master_inventory;
  context_rows jsonb;
  settings jsonb;
  inquiry jsonb;
  recipients text[];
  new_work public.ph_eval_work;
  delivery public.ph_request_delivery_outbox;
  create_token_value text;
  normalized_assignees jsonb;
  normalized_usernames text[];
  normalized_profiles jsonb;
begin
  actor := private.eval_work_assert_actor_v1(p_payload->>'actorUsername');
  if lower(actor.username) not in ('dylan_collyge', 'megan_kelly') then
    raise exception using errcode = '42501', message = 'eval_work_create_forbidden';
  end if;
  create_token_value := trim(coalesce(p_payload->>'createToken', ''));
  if length(create_token_value) < 16 or length(create_token_value) > 240 then
    raise exception using errcode = '22023', message = 'eval_work_create_token_invalid';
  end if;
  select * into new_work from public.ph_eval_work where create_token = create_token_value limit 1;
  if new_work.id is not null then
    if lower(new_work.creator_username) <> lower(actor.username) then
      raise exception using errcode = '42501', message = 'eval_work_create_token_forbidden';
    end if;
    return new_work;
  end if;
  assignee := private.eval_work_assert_actor_v1(p_payload->>'assigneeUsername');
  if trim(coalesce(p_payload->>'assigneeEmail', '')) !~* '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then
    raise exception using errcode = '22023', message = 'eval_work_assignee_email_invalid';
  end if;
  if jsonb_typeof(p_payload->'assignees') = 'array' then
    normalized_assignees := private.eval_work_normalize_assignees_v1(p_payload->'assignees');
    select array_agg(assignee_name order by ordinal)
      into normalized_usernames
    from jsonb_array_elements_text(normalized_assignees->'usernames') with ordinality as names(assignee_name, ordinal);
    normalized_profiles := normalized_assignees->'profiles';
  else
    normalized_usernames := array[lower(assignee.username)];
    normalized_profiles := jsonb_build_array(jsonb_build_object(
      'username', lower(assignee.username),
      'display', coalesce(nullif(assignee.display_name, ''), assignee.username),
      'email', lower(trim(p_payload->>'assigneeEmail'))
    ));
  end if;
  select coalesce(array_agg(distinct lower(trim(value))) filter (where trim(value) ~* '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'), '{}'::text[])
    into recipients
  from jsonb_array_elements_text(coalesce(p_payload->'completionRecipients', '[]'::jsonb));
  if cardinality(recipients) = 0 then
    raise exception using errcode = '22023', message = 'eval_work_completion_recipient_required';
  end if;
  select m.* into origin
  from public.ph_master_inventory m
  where m.unique_id = trim(coalesce(p_payload#>>'{source,unique_id}', p_payload->>'originUniqueId'))
  limit 1;
  if origin.unique_id is null
     or lower(trim(coalesce(origin.itemcode, ''))) <> lower(trim(coalesce(p_payload#>>'{source,itemcode}', p_payload->>'itemcode', '')))
     or trim(coalesce(origin.locationcode, '')) <> trim(coalesce(p_payload#>>'{source,locationcode}', p_payload->>'originLocationcode', ''))
     or trim(coalesce(origin.lotcode, '')) <> trim(coalesce(p_payload#>>'{source,lotcode}', p_payload->>'originLotcode', '')) then
    raise exception using errcode = '40001', message = 'eval_work_origin_identity_conflict';
  end if;
  context_rows := private.eval_work_context_rows_v1(origin.itemcode);
  settings := private.eval_work_settings_v1();
  if jsonb_typeof(settings) <> 'object' or coalesce(settings->>'seasonCode', '') = '' or coalesce(settings->>'salesYear', '') = '' then
    raise exception using errcode = '40001', message = 'eval_work_settings_unavailable';
  end if;
  inquiry := coalesce(p_payload->'inquiry', jsonb_build_object(
    'type', 'reclass_inquiry_email',
    'workflowPolicyVersion', 'reclass-action-workflow-v3-row-actions-20260826',
    'source', jsonb_build_object('unique_id', origin.unique_id, 'itemcode', origin.itemcode, 'lotcode', origin.lotcode, 'locationcode', origin.locationcode),
    'transaction', jsonb_build_object('requestActions', jsonb_build_array(), 'holdStopProposals', jsonb_build_array(), 'scope', jsonb_build_object()),
    'rowOverlays', jsonb_build_array()
  ));
  perform private.validate_eval_work_inquiry_v1(inquiry, origin.itemcode, context_rows);

  insert into public.ph_eval_work (
    create_token, creator_username, creator_display, assignee_username, assignee_display, assignee_email,
    instructions, completion_recipients, itemcode, commonname, contsize,
    origin_unique_id, origin_locationcode, origin_lotcode, origin_source,
    origin_snapshot, context_rows, inventory_signature, settings_signature, inquiry_draft,
    assignee_usernames, assignee_profiles
  ) values (
    create_token_value, lower(actor.username), coalesce(nullif(actor.display_name, ''), actor.username), lower(assignee.username),
    coalesce(nullif(assignee.display_name, ''), assignee.username), lower(trim(p_payload->>'assigneeEmail')),
    left(trim(coalesce(p_payload->>'instructions', '')), 4000), recipients,
    origin.itemcode, coalesce(origin.commonname, ''), coalesce(origin.contsize, ''),
    origin.unique_id, coalesce(origin.locationcode, ''), coalesce(origin.lotcode, ''), coalesce(origin.source, ''),
    to_jsonb(origin), context_rows, md5(context_rows::text), md5(settings::text), inquiry,
    normalized_usernames, normalized_profiles
  ) returning * into new_work;

  insert into public.ph_eval_work_events(eval_work_id, event_type, actor_username, version, metadata)
  values (new_work.id, 'created', lower(actor.username), new_work.version, jsonb_build_object('proposalCount', coalesce(jsonb_array_length(inquiry#>'{transaction,requestActions}'), 0))) ;

  insert into public.ph_request_delivery_outbox(event_key, event_type, request_id, payload, status, next_attempt_at)
  values (
    'eval-work:' || new_work.id::text || ':assignment:v' || new_work.version::text,
    'eval_work_assignment', new_work.id::text,
    jsonb_build_object(
      'contractVersion', 'eval-work-v1', 'deliveryKind', 'assignment', 'evalWorkId', new_work.id,
      'assigneeUsername', new_work.assignee_username, 'assigneeDisplay', new_work.assignee_display,
      'assigneeEmail', new_work.assignee_email, 'creatorUsername', new_work.creator_username,
      'creatorDisplay', new_work.creator_display, 'instructions', new_work.instructions,
      'itemcode', new_work.itemcode, 'commonname', new_work.commonname, 'contsize', new_work.contsize,
      'source', jsonb_build_object('unique_id', new_work.origin_unique_id, 'itemcode', new_work.itemcode, 'locationcode', new_work.origin_locationcode, 'lotcode', new_work.origin_lotcode, 'source_table', 'ph_master_inventory'),
      'inquiry', new_work.inquiry_draft
    ), 'pending', now()
  ) on conflict (event_key) do update set updated_at = now()
  returning * into delivery;
  update public.ph_eval_work set assignment_event_id = delivery.event_id where id = new_work.id returning * into new_work;
  return new_work;
end
$_$;


ALTER FUNCTION public.create_eval_work_v1(p_payload jsonb) OWNER TO postgres;

--
-- Name: create_flyer_folder_batch_v1(text, text[], text[], boolean, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_flyer_folder_batch_v1(p_folder_name text, p_master_uids text[], p_assignee_usernames text[], p_add_to_existing boolean, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_actor public.profiles%rowtype;
  v_existing private.flyer_folder_batch_idempotency%rowtype;
  v_folder text := regexp_replace(btrim(coalesce(p_folder_name, '')), '\s+', ' ', 'g');
  v_master_uids text[];
  v_assignees text[];
  v_assignee_display text;
  v_primary_assignee text;
  v_request_hash text;
  v_response jsonb;
  v_rows jsonb;
  v_expected_count integer;
  v_found_count integer;
  v_assignee_count integer;
  v_now timestamptz := now();
begin
  v_actor := private.require_active_flyer_creator_profile();

  if char_length(v_folder) not between 1 and 160 or v_folder ~ '^\[ARCHIVED\]' then
    raise exception using errcode = '22023', message = 'INVALID_FLYER_FOLDER_NAME';
  end if;
  if char_length(btrim(coalesce(p_idempotency_key, ''))) not between 12 and 180 then
    raise exception using errcode = '22023', message = 'INVALID_IDEMPOTENCY_KEY';
  end if;

  select coalesce(array_agg(value order by value), '{}'::text[]) into v_master_uids
  from (select distinct btrim(value) value from unnest(coalesce(p_master_uids, '{}'::text[])) value where btrim(value) <> '') q;
  select coalesce(array_agg(value order by value), '{}'::text[]) into v_assignees
  from (select distinct lower(btrim(value)) value from unnest(coalesce(p_assignee_usernames, '{}'::text[])) value where btrim(value) <> '') q;

  v_expected_count := cardinality(v_master_uids);
  if v_expected_count not between 1 and 100 then
    raise exception using errcode = '22023', message = 'INVALID_FLYER_ROW_COUNT';
  end if;
  if cardinality(v_assignees) not between 1 and 50 then
    raise exception using errcode = '22023', message = 'INVALID_FLYER_ASSIGNEE_COUNT';
  end if;

  v_request_hash := md5(concat_ws('|', v_folder, array_to_string(v_master_uids, ','), array_to_string(v_assignees, ','), coalesce(p_add_to_existing, false)::text));
  select * into v_existing
  from private.flyer_folder_batch_idempotency
  where profile_id = v_actor.id and idempotency_key = btrim(p_idempotency_key);
  if found then
    if v_existing.request_hash <> v_request_hash then
      raise exception using errcode = '40001', message = 'IDEMPOTENCY_CONFLICT';
    end if;
    return jsonb_set(v_existing.response_payload, '{recovered}', 'true'::jsonb, true);
  end if;

  select count(*) into v_assignee_count
  from public.profiles
  where lower(btrim(username)) = any(v_assignees)
    and disabled_at is null
    and (locked_until is null or locked_until <= now());
  if v_assignee_count <> cardinality(v_assignees) then
    raise exception using errcode = '22023', message = 'INVALID_FLYER_ASSIGNEE';
  end if;

  select string_agg(coalesce(nullif(btrim(display_name), ''), username), ', ' order by array_position(v_assignees, lower(btrim(username)))),
         min(lower(btrim(username))) filter (where lower(btrim(username)) = v_assignees[1])
  into v_assignee_display, v_primary_assignee
  from public.profiles
  where lower(btrim(username)) = any(v_assignees);
  v_primary_assignee := coalesce(v_primary_assignee, v_assignees[1]);

  select count(*) into v_found_count
  from public.ph_master_inventory
  where unique_id = any(v_master_uids);
  if v_found_count <> v_expected_count then
    raise exception using errcode = '40001', message = 'FLYER_SOURCE_ROW_CONFLICT';
  end if;

  if coalesce(p_add_to_existing, false) then
    if not exists (
      select 1 from public.ph_flyer_folder_rows
      where lower(btrim(flyer_title)) = lower(v_folder)
    ) then
      raise exception using errcode = '40001', message = 'FLYER_FOLDER_NOT_OPEN';
    end if;
  elsif exists (
    select 1 from public.ph_flyer_folder_rows
    where lower(btrim(flyer_title)) = lower(v_folder)
  ) then
    raise exception using errcode = '40001', message = 'FLYER_FOLDER_ALREADY_EXISTS';
  end if;
  if exists (
    select 1 from public.ph_flyer_folder_history
    where lower(btrim(coalesce(folder_name, flyer_title))) = lower(v_folder)
      and folder_tab = 'archive'
  ) then
    raise exception using errcode = '40001', message = 'FLYER_FOLDER_ARCHIVED';
  end if;

  with sources as (
    select m.*,
      'FF-' || left(regexp_replace(v_folder, '[^a-zA-Z0-9]+', '-', 'g'), 90) || '-' ||
        left(regexp_replace(m.unique_id, '[^a-zA-Z0-9]+', '-', 'g'), 90) as flyer_unique_id,
      jsonb_build_object(
        'UNIQUE_ID', m.unique_id, 'SOURCE_TABLE', 'ph_master_inventory', 'SOURCE', m.source,
        'ITEMCODE', m.itemcode, 'COMMONNAME', m.commonname, 'CONTSIZE', m.contsize,
        'LOCATIONCODE', m.locationcode, 'LOTCODE', m.lotcode, 'PRIORITY', m.priority,
        'PTRAVAILABLE', m.ptravailable, 'S_LTS', m.s_lts, 'HOLDSTOPCODE', m.holdstopcode,
        'PLANTGROUPCODE', m.plantgroupcode, 'LOCATIONNOTE', m.locationnote,
        'AV_NOTE', m.av_note, 'MATCH', m.match, 'LOC_MATCH_QTY', m.loc_match_qty,
        'SPEC', m.spec, 'CALIPER', m.caliper, 'PICK', m.pic_note,
        'INITIAL_PTR', m.initial_ptr, 'PHOTO_LINK', m.photo_link, 'PHOTO_NAME', m.photo_name,
        'PRODUCTIVITY_ORIGIN_ASSIGNMENT', m.app_tab_assignment
      ) as snapshot_json
    from public.ph_master_inventory m
    where m.unique_id = any(v_master_uids)
  ), inserted as (
    insert into public.ph_flyer_folder_rows (
      unique_id, master_unique_id, source_table, flyer_title, flyer_assigned, assignedto,
      itemcode, commonname, contsize, locationcode, lotcode, priority, ptravailable, s_lts,
      holdstopcode, plantgroupcode, locationnote, av_note, match, loc_match_qty, spec, caliper,
      pick, initial_ptr, flyer_av_note, flyer_match, flyer_loc_match_qty, flyer_spec,
      flyer_caliper, flyer_pick, flyer_initial_ptr, flyer_photo_link, flyer_photo_name,
      snapshot, created_by_username, created_by_display, created_at, updated_at
    )
    select
      s.flyer_unique_id, s.unique_id, 'ph_master_inventory', v_folder, v_assignee_display, v_primary_assignee,
      s.itemcode, s.commonname, s.contsize, s.locationcode, s.lotcode, s.priority, s.ptravailable, s.s_lts,
      s.holdstopcode, s.plantgroupcode, s.locationnote, s.av_note,
      case when regexp_replace(coalesce(s.match, ''), '[^0-9.-]+', '', 'g') ~ '^-?[0-9]+([.][0-9]+)?$' then regexp_replace(s.match, '[^0-9.-]+', '', 'g')::numeric end,
      case when regexp_replace(coalesce(s.loc_match_qty, ''), '[^0-9.-]+', '', 'g') ~ '^-?[0-9]+([.][0-9]+)?$' then regexp_replace(s.loc_match_qty, '[^0-9.-]+', '', 'g')::numeric end,
      s.spec, s.caliper, s.pic_note,
      case when regexp_replace(coalesce(s.initial_ptr, ''), '[^0-9.-]+', '', 'g') ~ '^-?[0-9]+([.][0-9]+)?$' then regexp_replace(s.initial_ptr, '[^0-9.-]+', '', 'g')::numeric end,
      s.av_note,
      case when regexp_replace(coalesce(s.match, ''), '[^0-9.-]+', '', 'g') ~ '^-?[0-9]+([.][0-9]+)?$' then regexp_replace(s.match, '[^0-9.-]+', '', 'g')::numeric end,
      case when regexp_replace(coalesce(s.loc_match_qty, ''), '[^0-9.-]+', '', 'g') ~ '^-?[0-9]+([.][0-9]+)?$' then regexp_replace(s.loc_match_qty, '[^0-9.-]+', '', 'g')::numeric end,
      s.spec, s.caliper, s.pic_note,
      case when regexp_replace(coalesce(s.initial_ptr, ''), '[^0-9.-]+', '', 'g') ~ '^-?[0-9]+([.][0-9]+)?$' then regexp_replace(s.initial_ptr, '[^0-9.-]+', '', 'g')::numeric end,
      s.photo_link, s.photo_name, s.snapshot_json,
      lower(btrim(v_actor.username)), coalesce(nullif(btrim(v_actor.display_name), ''), v_actor.username), v_now, v_now
    from sources s
    on conflict (unique_id) do update set
      flyer_assigned = excluded.flyer_assigned,
      assignedto = excluded.assignedto,
      updated_at = excluded.updated_at
    returning *
  ), history_rows as (
    insert into public.ph_flyer_folder_history (
      unique_id, master_unique_id, source_table, flyer_title, flyer_assigned, assignedto,
      itemcode, commonname, contsize, locationcode, lotcode, priority, ptravailable, s_lts,
      holdstopcode, plantgroupcode, locationnote, av_note, match, loc_match_qty, spec, caliper,
      pick, initial_ptr, flyer_av_note, flyer_match, flyer_loc_match_qty, flyer_spec,
      flyer_caliper, flyer_pick, flyer_initial_ptr, flyer_photo_link, flyer_photo_name,
      snapshot, created_by_username, created_by_display, created_at, updated_at,
      folder_name, folder_tab, history_state, last_event
    )
    select
      i.unique_id, i.master_unique_id, i.source_table, i.flyer_title, i.flyer_assigned, i.assignedto,
      i.itemcode, i.commonname, i.contsize, i.locationcode, i.lotcode, i.priority, i.ptravailable, i.s_lts,
      i.holdstopcode, i.plantgroupcode, i.locationnote, i.av_note, i.match, i.loc_match_qty, i.spec, i.caliper,
      i.pick, i.initial_ptr, i.flyer_av_note, i.flyer_match, i.flyer_loc_match_qty, i.flyer_spec,
      i.flyer_caliper, i.flyer_pick, i.flyer_initial_ptr, i.flyer_photo_link, i.flyer_photo_name,
      i.snapshot, i.created_by_username, i.created_by_display, i.created_at, i.updated_at,
      v_folder, 'active', 'active', 'created'
    from inserted i
    on conflict (unique_id) do update set
      flyer_assigned = excluded.flyer_assigned,
      assignedto = excluded.assignedto,
      updated_at = excluded.updated_at,
      last_event = 'rows_added'
    returning unique_id
  )
  select jsonb_agg(to_jsonb(i) order by i.locationcode, i.lotcode, i.unique_id)
  into v_rows
  from inserted i;

  v_response := jsonb_build_object(
    'ok', true,
    'contractVersion', 'create-flyer-folder-batch-v1',
    'folderName', v_folder,
    'rows', coalesce(v_rows, '[]'::jsonb),
    'rowCount', v_expected_count,
    'assigneeUsernames', to_jsonb(v_assignees),
    'assigneeDisplay', v_assignee_display,
    'recovered', false
  );

  insert into private.flyer_folder_batch_idempotency
    (profile_id, idempotency_key, request_hash, response_payload)
  values
    (v_actor.id, btrim(p_idempotency_key), v_request_hash, v_response);

  return v_response;
end
$_$;


