--
-- Name: dispatch_github_ml_worker(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.dispatch_github_ml_worker() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'vault'
    AS $$
declare
    github_owner text := 'collygedylan';
    github_repo text := 'GNC-Sales-Command-PRO-';
    github_token text;
    event_type text := 'supabase-ml-queue';
    row_id text := coalesce(new.unique_id::text, '');
    should_dispatch boolean := false;
    prior_dispatch_at timestamptz;
    request_id bigint;
begin
    if tg_table_name = 'ph_ml_image_jobs' then
        if coalesce(new.status, '') <> 'pending_ml' then
            return new;
        end if;
        if tg_op = 'INSERT' then
            should_dispatch := true;
        elsif coalesce(old.status, '') is distinct from coalesce(new.status, '') then
            should_dispatch := true;
        end if;
        event_type := 'ml-photo-created';
    elsif tg_table_name = 'ph_disease_training_assets' then
        if coalesce(new.processed_status, '') <> 'pending_ml' then
            return new;
        end if;
        if tg_op = 'INSERT' then
            should_dispatch := true;
        elsif coalesce(old.processed_status, '') is distinct from coalesce(new.processed_status, '') then
            should_dispatch := true;
        end if;
        event_type := 'ml-training-asset-created';
    elsif tg_table_name = 'ph_grower_scout_reports' then
        if coalesce(new.status, '') <> 'pending_ai' then
            return new;
        end if;
        if tg_op = 'INSERT' then
            should_dispatch := true;
        elsif coalesce(old.status, '') is distinct from coalesce(new.status, '') then
            should_dispatch := true;
        end if;
        event_type := 'grower-scout-report-created';
    end if;

    if not should_dispatch then
        return new;
    end if;

    select last_dispatched_at
    into prior_dispatch_at
    from public.ph_ml_github_dispatch_state
    where dispatch_key = 'ml-worker';

    -- GitHub Actions is the worker, not one run per row. One wake-up per minute is enough.
    if prior_dispatch_at is not null and prior_dispatch_at > now() - interval '60 seconds' then
        return new;
    end if;

    select decrypted_secret
    into github_token
    from vault.decrypted_secrets
    where name = 'GITHUB_ML_WORKER_PAT'
    limit 1;

    if github_token is null or length(trim(github_token)) = 0 then
        raise warning 'GITHUB_ML_WORKER_PAT is not set in Supabase Vault. GitHub ML worker dispatch skipped.';
        return new;
    end if;

    insert into public.ph_ml_github_dispatch_state (
        dispatch_key,
        last_dispatched_at,
        last_event_type,
        last_table_name,
        last_row_id,
        dispatch_count,
        updated_at
    )
    values (
        'ml-worker',
        now(),
        event_type,
        tg_table_name,
        row_id,
        1,
        now()
    )
    on conflict (dispatch_key)
    do update set
        last_dispatched_at = excluded.last_dispatched_at,
        last_event_type = excluded.last_event_type,
        last_table_name = excluded.last_table_name,
        last_row_id = excluded.last_row_id,
        dispatch_count = public.ph_ml_github_dispatch_state.dispatch_count + 1,
        updated_at = now();

    select net.http_post(
        url := format('https://api.github.com/repos/%s/%s/dispatches', github_owner, github_repo),
        headers := jsonb_build_object(
            'Authorization', 'Bearer ' || github_token,
            'Accept', 'application/vnd.github+json',
            'X-GitHub-Api-Version', '2022-11-28',
            'User-Agent', 'gnc-supabase-ml-dispatch'
        ),
        body := jsonb_build_object(
            'event_type', event_type,
            'client_payload', jsonb_build_object(
                'table', tg_table_name,
                'unique_id', row_id,
                'created_at', now()
            )
        ),
        timeout_milliseconds := 5000
    )
    into request_id;

    return new;
exception
    when others then
        raise warning 'GitHub ML worker dispatch failed: %', sqlerrm;
        return new;
end;
$$;


ALTER FUNCTION public.dispatch_github_ml_worker() OWNER TO postgres;

--
-- Name: emit_v2_app_live_event(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.emit_v2_app_live_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  safe_area text := nullif(btrim(coalesce(tg_argv[0], '')), '');
  safe_table text := tg_table_name;
  safe_method text := lower(tg_op);
  bucket text := to_char(date_trunc('second', clock_timestamp()), 'YYYYMMDDHH24MISS');
  safe_event_key text;
  existing_count integer;
begin
  if safe_area is null or safe_table = 'ph_app_live_events' then
    return null;
  end if;

  safe_event_key := 'db:' || safe_area || ':' || safe_table || ':' || safe_method || ':' || bucket;

  insert into public.ph_app_live_events (
    event_key,
    event_type,
    area,
    source_table,
    row_ids,
    payload,
    client_id,
    created_at
  ) values (
    safe_event_key,
    safe_area || ':' || safe_method,
    safe_area,
    safe_table,
    '{}'::text[],
    jsonb_build_object(
      'method', tg_op,
      'bulk', true,
      'db_trigger', true,
      'coalesced_count', 1,
      'bucket', bucket,
      'client_id', 'db_trigger'
    ),
    'db_trigger',
    clock_timestamp()
  )
  on conflict (event_key) do update
  set
    payload = jsonb_set(
      coalesce(public.ph_app_live_events.payload, '{}'::jsonb),
      '{coalesced_count}',
      to_jsonb(
        case
          when coalesce(public.ph_app_live_events.payload->>'coalesced_count', '') ~ '^[0-9]+$'
            then (public.ph_app_live_events.payload->>'coalesced_count')::integer + 1
          else 2
        end
      ),
      true
    ),
    created_at = excluded.created_at;

  return null;
exception
  when others then
    return null;
end;
$_$;


ALTER FUNCTION public.emit_v2_app_live_event() OWNER TO postgres;

--
-- Name: enqueue_drive_reclass_inquiry_v1(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.enqueue_drive_reclass_inquiry_v1(p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  actor public.profiles;
  actor_username text := lower(btrim(coalesce(p_payload->>'actorUsername', '')));
  actor_role text;
  access_scope text;
  source_uid text := btrim(coalesce(p_payload #>> '{source,unique_id}', p_payload #>> '{source,uniqueId}', ''));
  source_row public.ph_master_inventory;
  source_json jsonb;
  token text := btrim(coalesce(p_payload->>'idempotencyToken', p_payload->>'idempotency_token', ''));
  event_key_value text;
  event_row public.ph_request_delivery_outbox;
  is_manager boolean := false;
  is_evaluator boolean := false;
  assigned_to_actor boolean := false;
  required_usernames text[];
  recipient_emails text[] := '{}'::text[];
  unavailable_usernames text[] := '{}'::text[];
  safe_payload jsonb;
begin
  if jsonb_typeof(coalesce(p_payload, '{}'::jsonb)) <> 'object' then
    raise exception using errcode = '22023', message = 'DRIVE_RECLASS_PAYLOAD_INVALID';
  end if;
  if actor_username = '' then
    raise exception using errcode = '42501', message = 'DRIVE_RECLASS_ACTOR_REQUIRED';
  end if;
  select p.* into actor
  from public.profiles p
  where lower(btrim(p.username)) = actor_username
    and p.disabled_at is null
    and (p.locked_until is null or p.locked_until <= now())
    and not p.must_change_password
  limit 1;
  if actor.id is null then
    raise exception using errcode = '42501', message = 'DRIVE_RECLASS_PROFILE_NOT_ACTIVE';
  end if;

  actor_role := private.normalized_profile_role(actor.role);
  is_manager := actor_role in ('ADMIN', 'ADMINISTRATOR', 'MANAGER');
  is_evaluator := actor_role in ('EVAL', 'EVALUATOR') or actor_role like '%EVAL%';
  if not is_manager and not is_evaluator then
    raise exception using errcode = '42501', message = 'DRIVE_RECLASS_FORBIDDEN';
  end if;

  select e.access_scope into access_scope
  from private.get_effective_app_permissions_v1(
    actor.id,
    private.resolve_app_access_policy_id_v1(false)
  ) e
  where e.permission_key = 'drive.reclass.submit'
    and e.allowed
  limit 1;
  if access_scope is null then
    raise exception using errcode = '42501', message = 'DRIVE_RECLASS_PERMISSION_REQUIRED';
  end if;

  if coalesce(p_payload->>'workflowPolicyVersion', '') <> 'reclass-action-workflow-v3-row-actions-20260826' then
    raise exception using errcode = '22023', message = 'DRIVE_RECLASS_V3_REQUIRED';
  end if;
  if length(token) < 12 or length(token) > 180 then
    raise exception using errcode = '22023', message = 'DRIVE_RECLASS_TOKEN_INVALID';
  end if;
  if source_uid = '' then
    raise exception using errcode = '22023', message = 'DRIVE_RECLASS_SOURCE_REQUIRED';
  end if;
  if jsonb_typeof(coalesce(p_payload->'transaction', '{}'::jsonb)) <> 'object'
     or jsonb_typeof(coalesce(p_payload->'rowOverlays', '[]'::jsonb)) <> 'array' then
    raise exception using errcode = '22023', message = 'DRIVE_RECLASS_ACTIONS_INVALID';
  end if;

  select m.* into source_row
  from public.ph_master_inventory m
  where btrim(coalesce(m.unique_id, '')) = source_uid
  limit 1
  for share;
  if source_row.unique_id is null then
    raise exception using errcode = '40001', message = 'DRIVE_RECLASS_SOURCE_MISSING';
  end if;
  source_json := to_jsonb(source_row);
  if nullif(btrim(coalesce(p_payload #>> '{source,itemcode}', '')), '') is not null
     and upper(btrim(p_payload #>> '{source,itemcode}')) <> upper(btrim(coalesce(source_row.itemcode, ''))) then
    raise exception using errcode = '40001', message = 'DRIVE_RECLASS_SOURCE_CHANGED';
  end if;
  if nullif(btrim(coalesce(p_payload #>> '{source,lotcode}', '')), '') is not null
     and upper(btrim(p_payload #>> '{source,lotcode}')) <> upper(btrim(coalesce(source_json->>'lotcode', ''))) then
    raise exception using errcode = '40001', message = 'DRIVE_RECLASS_SOURCE_CHANGED';
  end if;
  if nullif(btrim(coalesce(p_payload #>> '{source,locationcode}', '')), '') is not null
     and upper(btrim(p_payload #>> '{source,locationcode}')) <> upper(btrim(coalesce(source_json->>'locationcode', ''))) then
    raise exception using errcode = '40001', message = 'DRIVE_RECLASS_SOURCE_CHANGED';
  end if;

  if is_evaluator and not is_manager then
    select exists (
      select 1
      from public.ph_warehouse_assigned_items a
      where a.present_in_drive
        and upper(btrim(coalesce(a.itemcode_normalized, a.itemcode, ''))) = upper(btrim(coalesce(source_row.itemcode, '')))
        and lower(regexp_replace(btrim(coalesce(a.genusname_normalized, a.genusname, '')), '[[:space:]]+', ' ', 'g'))
          = lower(regexp_replace(btrim(coalesce(source_json->>'genusname', '')), '[[:space:]]+', ' ', 'g'))
        and lower(regexp_replace(btrim(coalesce(a.assignedto, '')), '[^a-z0-9]+', '_', 'g')) = actor_username
    ) into assigned_to_actor;
    if not assigned_to_actor then
      raise exception using errcode = '42501', message = 'DRIVE_RECLASS_ROW_NOT_ASSIGNED';
    end if;
  end if;

  required_usernames := array['dylan_collyge', 'megan_kelly', 'sharon_combs', actor_username];
  with wanted as (
    select lower(btrim(value)) as username, min(ordinality) as ordinal
    from unnest(required_usernames) with ordinality entry(value, ordinality)
    where btrim(coalesce(value, '')) <> ''
    group by lower(btrim(value))
  ), resolved as (
    select w.username, w.ordinal, lower(btrim(u.email)) as email
    from wanted w
    join public.profiles p on lower(btrim(p.username)) = w.username
    join auth.users u on u.id = p.id
    where p.disabled_at is null
      and (p.locked_until is null or p.locked_until <= now())
      and not p.must_change_password
      and u.email_confirmed_at is not null
      and btrim(coalesce(u.email, '')) ~* '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$'
  )
  select
    coalesce(array_agg(distinct r.email order by r.email) filter (where r.email is not null), '{}'::text[]),
    coalesce(array_agg(w.username order by w.ordinal) filter (where r.username is null), '{}'::text[])
  into recipient_emails, unavailable_usernames
  from wanted w
  left join resolved r on r.username = w.username;

  if cardinality(recipient_emails) = 0 then
    raise exception using errcode = 'P0001', message = 'DRIVE_RECLASS_RECIPIENTS_UNAVAILABLE';
  end if;

  event_key_value := 'reclass-inquiry:' || left(encode(extensions.digest(token, 'sha256'), 'hex'), 40);
  perform pg_advisory_xact_lock(hashtextextended(event_key_value, 0));
  select o.* into event_row
  from public.ph_request_delivery_outbox o
  where o.event_key = event_key_value
    and o.event_type = 'reclass_inquiry'
  limit 1
  for update;
  if event_row.event_id is not null then
    if event_row.payload #>> '{reclassPayload,protectedDelivery,contractVersion}' <> 'drive-reclass-protected-v1' then
      raise exception using errcode = 'P0001', message = 'DRIVE_RECLASS_TOKEN_CONFLICT';
    end if;
    if lower(btrim(coalesce(event_row.payload #>> '{reclassPayload,actor,username}', ''))) <> actor_username then
      raise exception using errcode = '42501', message = 'DRIVE_RECLASS_TOKEN_OWNERSHIP_CONFLICT';
    end if;
    return private.drive_reclass_delivery_result_v1(event_row) || jsonb_build_object('duplicate', true);
  end if;

  safe_payload := jsonb_build_object(
    'type', 'reclass_inquiry_email',
    'action', 'reclass',
    'workflowPolicyVersion', 'reclass-action-workflow-v3-row-actions-20260826',
    'idempotencyToken', token,
    'actor', jsonb_build_object(
      'username', actor_username,
      'display', coalesce(nullif(btrim(actor.display_name), ''), actor.username),
      'role', actor.role
    ),
    'source', jsonb_build_object(
      'unique_id', source_row.unique_id,
      'source_table', 'ph_master_inventory',
      'itemcode', source_row.itemcode,
      'lotcode', source_json->>'lotcode',
      'locationcode', source_json->>'locationcode',
      'season', source_json->>'season',
      'saleyear', source_json->>'saleyear'
    ),
    'transaction', p_payload->'transaction',
    'rowOverlays', p_payload->'rowOverlays',
    'clientVersion', left(btrim(coalesce(p_payload->>'clientVersion', '')), 80),
    'sourceContext', jsonb_build_object('sourceMode', 'drive'),
    'recipientEmails', to_jsonb(recipient_emails),
    'emailRecipients', to_jsonb(recipient_emails),
    'recipients', (
      select coalesce(jsonb_agg(jsonb_build_object('email', email, 'role', 'required_drive_reclass') order by email), '[]'::jsonb)
      from unnest(recipient_emails) email
    ),
    'protectedDelivery', jsonb_build_object(
      'contractVersion', 'drive-reclass-protected-v1',
      'actorProfileId', actor.id,
      'unavailableUsernames', to_jsonb(unavailable_usernames)
    )
  );
  if octet_length(safe_payload::text) > 4 * 1024 * 1024 then
    raise exception using errcode = '22023', message = 'DRIVE_RECLASS_PAYLOAD_TOO_LARGE';
  end if;

  insert into public.ph_request_delivery_outbox
    (event_key, event_type, request_id, request_folder, payload, status, next_attempt_at)
  values
    (event_key_value, 'reclass_inquiry', null, null, jsonb_build_object('reclassPayload', safe_payload), 'pending', now())
  returning * into event_row;

  return private.drive_reclass_delivery_result_v1(event_row)
    || jsonb_build_object('duplicate', false, 'unavailableUsernames', to_jsonb(unavailable_usernames));
end
$_$;


ALTER FUNCTION public.enqueue_drive_reclass_inquiry_v1(p_payload jsonb) OWNER TO postgres;

--
-- Name: fail_dataset_import_v1(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fail_dataset_import_v1(p_run_id uuid) RETURNS jsonb
    LANGUAGE sql
    SET search_path TO ''
    AS $$ select app_sync_private.advance_import(p_run_id,'fail') $$;


ALTER FUNCTION public.fail_dataset_import_v1(p_run_id uuid) OWNER TO postgres;

--
-- Name: fail_request_delivery_event(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fail_request_delivery_event(p_event_id uuid, p_lease_token uuid, p_error_code text) RETURNS public.ph_request_delivery_outbox
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  updated_event public.ph_request_delivery_outbox%rowtype;
  next_attempt_count integer;
  safe_error text := upper(left(regexp_replace(coalesce(p_error_code, 'DELIVERY_WORKER_FAILED'), '[^A-Za-z0-9_]+', '_', 'g'), 120));
begin
  if not private.is_service_role_request() then
    raise exception using errcode = '42501', message = 'DELIVERY_WORKER_FORBIDDEN';
  end if;

  select attempt_count + 1 into next_attempt_count
  from public.ph_request_delivery_outbox
  where event_id = p_event_id and status = 'processing' and lease_token = p_lease_token
  for update;
  if not found then
    raise exception using errcode = '40001', message = 'DELIVERY_LEASE_LOST';
  end if;

  update public.ph_request_delivery_outbox o
  set status = case when next_attempt_count >= 8 then 'failed' else 'pending' end,
      attempt_count = next_attempt_count,
      next_attempt_at = now() + make_interval(mins => least(360, power(2, least(next_attempt_count, 6))::integer)),
      sanitized_error_code = coalesce(nullif(safe_error, ''), 'DELIVERY_WORKER_FAILED'),
      lease_token = null,
      lease_owner = null,
      lease_expires_at = null
  where o.event_id = p_event_id
  returning o.* into updated_event;

  if updated_event.request_id is not null then
    update public.ph_request_history
    set delivery_state = case when updated_event.status = 'failed' then 'failed' else 'pending' end,
        updated_at = now()
    where unique_id = updated_event.request_id;
  end if;
  return updated_event;
end;
$$;


ALTER FUNCTION public.fail_request_delivery_event(p_event_id uuid, p_lease_token uuid, p_error_code text) OWNER TO postgres;

--
-- Name: finalize_eval_item_low_stock_file_v1(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.finalize_eval_item_low_stock_file_v1(p_file_version_id uuid, p_content_sha256 text, p_expected_row_count integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  target private.ph_eval_item_low_stock_file_versions%rowtype;
  actual_row_count integer;
begin
  select * into target
  from private.ph_eval_item_low_stock_file_versions
  where file_version_id = p_file_version_id
  for update;
  if not found then raise exception using errcode = 'P0002', message = 'LOW_STOCK_IMPORT_FILE_NOT_FOUND'; end if;
  if target.content_sha256 <> p_content_sha256
     or target.expected_row_count <> p_expected_row_count then
    raise exception using errcode = '22023', message = 'LOW_STOCK_IMPORT_FILE_MANIFEST_MISMATCH';
  end if;
  select count(*)::integer into actual_row_count
  from private.ph_eval_item_low_stock_order_rows
  where file_version_id = p_file_version_id;
  if actual_row_count <> target.expected_row_count then
    raise exception using errcode = '22023', message = 'LOW_STOCK_IMPORT_ROW_COUNT_MISMATCH';
  end if;
  update private.ph_eval_item_low_stock_file_versions
  set status = 'finalized', finalized_at = coalesce(finalized_at, now())
  where file_version_id = p_file_version_id;
  update private.ph_eval_item_low_stock_run_files r
  set file_version_id = target.file_version_id
  from private.ph_eval_item_low_stock_import_runs run
  where run.run_id = r.run_id
    and run.status = 'building'
    and r.drive_file_id = target.drive_file_id
    and r.source_revision = target.source_revision;
  return jsonb_build_object(
    'file_version_id', target.file_version_id,
    'status', 'finalized',
    'eligible_row_count', actual_row_count
  );
end
$$;


ALTER FUNCTION public.finalize_eval_item_low_stock_file_v1(p_file_version_id uuid, p_content_sha256 text, p_expected_row_count integer) OWNER TO postgres;

--
-- Name: finalize_pikes_order_import(text, text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.finalize_pikes_order_import(p_drive_file_id text, p_content_sha256 text, p_source_sheet_name text, p_source_header_row integer, p_expected_row_count integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  target public.ph_pikes_order_batches%rowtype;
  actual_row_count integer;
  distinct_count integer;
  matched_count integer;
  unmatched_count integer;
  snapshot_count integer;
  effective_date date;
  effective_sequence integer;
  effective_label text;
  effective_name text;
begin
  select * into target
  from public.ph_pikes_order_batches b
  where b.drive_file_id = p_drive_file_id
  for update;

  if not found or target.content_sha256 <> p_content_sha256 then
    raise exception 'MANAGER_ORDER_IMPORT_MANIFEST_MISSING';
  end if;
  if target.source_key not in ('pikes', 'stine_lumber') then
    raise exception 'MANAGER_ORDER_SOURCE_INVALID';
  end if;
  if target.status in ('archive_pending', 'processed') then
    return jsonb_build_object(
      'status', target.status,
      'batchId', target.batch_id,
      'rowCount', target.source_row_count,
      'inventoryRowCount', target.inventory_row_count,
      'displayName', target.display_name,
      'sourceKey', target.source_key
    );
  end if;
  if target.status <> 'importing' then raise exception 'MANAGER_ORDER_IMPORT_INVALID_STATE'; end if;
  if p_expected_row_count is null or p_expected_row_count < 1 then raise exception 'MANAGER_ORDER_IMPORT_EMPTY'; end if;

  select count(*)::integer into actual_row_count
  from public.ph_pikes_order_source_rows r where r.batch_id = target.batch_id;
  if actual_row_count <> p_expected_row_count then raise exception 'MANAGER_ORDER_IMPORT_ROW_COUNT_MISMATCH'; end if;

  select count(distinct r.itemcode_normalized)::integer into distinct_count
  from public.ph_pikes_order_source_rows r where r.batch_id = target.batch_id;

  delete from public.ph_pikes_order_inventory_rows where batch_id = target.batch_id;
  insert into public.ph_pikes_order_inventory_rows (
    batch_id, master_unique_id, itemcode, itemcode_normalized, commonname, contsize,
    locationcode, lotcode, assignedto, assignment_authority_key,
    assignment_authority_assigned_at, assignment_match_method,
    priority, ptronhand, ptrreviewed, ptravailable, s_lts, season, blockalpha,
    blocknumber, fieldtagcolor, desigitem, desigloc, holdstopcode, holdstopreason,
    itemspec, locationnote, locationnotedate, photo_link, photo_name, snapshotted_at
  )
  select distinct on (m.unique_id)
    target.batch_id, m.unique_id, m.itemcode, upper(btrim(m.itemcode)), m.commonname, m.contsize,
    m.locationcode, m.lotcode, nullif(btrim(a.assignedto), ''), a.assignment_key,
    a.assigned_at,
    case when nullif(btrim(a.assignedto), '') is null then 'unassigned' else 'exact' end,
    m.priority, m.ptronhand, m.ptrreviewed, m.ptravailable, m.s_lts, m.season,
    m.blockalpha, m.blocknumber, coalesce(nullif(m.fieldtagcolor, ''), m.field_tag_color),
    m.desigitem, m.desigloc, m.holdstopcode, m.holdstopreason, m.itemspec,
    m.locationnote, m.locationnotedate, m.photo_link, m.photo_name, now()
  from public.ph_master_inventory m
  join (
    select distinct itemcode_normalized
    from public.ph_pikes_order_source_rows
    where batch_id = target.batch_id
  ) requested on requested.itemcode_normalized = upper(btrim(m.itemcode))
  left join public.ph_warehouse_assigned_items a
    on a.assignment_key = private.normalize_eval_assignment_key(m.itemcode, m.genusname)
   and a.present_in_drive
  where m.unique_id is not null and btrim(m.unique_id) <> ''
  order by m.unique_id;

  update public.ph_pikes_order_source_rows r
  set matched = exists (
    select 1 from public.ph_pikes_order_inventory_rows i
    where i.batch_id = r.batch_id and i.itemcode_normalized = r.itemcode_normalized
  )
  where r.batch_id = target.batch_id;

  select count(distinct r.itemcode_normalized)::integer into matched_count
  from public.ph_pikes_order_source_rows r where r.batch_id = target.batch_id and r.matched;
  unmatched_count := greatest(0, distinct_count - matched_count);
  select count(*)::integer into snapshot_count
  from public.ph_pikes_order_inventory_rows i where i.batch_id = target.batch_id;

  effective_date := (now() at time zone 'America/Chicago')::date;
  perform pg_advisory_xact_lock(hashtext('manager-orders-' || target.source_key || '-' || effective_date::text));
  select coalesce(max(b.daily_sequence), 0) + 1 into effective_sequence
  from public.ph_pikes_order_batches b
  where b.source_key = target.source_key and b.batch_date = effective_date;
  effective_label := case target.source_key
    when 'stine_lumber' then 'Stine Lumber'
    else 'Pikes'
  end;
  effective_name := effective_label || ' ' || to_char(effective_date, 'MM-DD-YYYY') ||
    case when effective_sequence > 1 then ' (' || effective_sequence::text || ')' else '' end;

  update public.ph_pikes_order_batches
  set source_sheet_name = nullif(btrim(coalesce(p_source_sheet_name, '')), ''),
      source_header_row = p_source_header_row,
      status = 'archive_pending',
      batch_date = effective_date,
      daily_sequence = effective_sequence,
      display_name = effective_name,
      source_row_count = actual_row_count,
      distinct_item_count = distinct_count,
      matched_item_count = matched_count,
      unmatched_item_count = unmatched_count,
      inventory_row_count = snapshot_count,
      last_error_code = null,
      imported_at = now(),
      updated_at = now()
  where drive_file_id = p_drive_file_id
  returning * into target;

  return jsonb_build_object(
    'status', target.status,
    'batchId', target.batch_id,
    'rowCount', target.source_row_count,
    'distinctItemCount', target.distinct_item_count,
    'matchedItemCount', target.matched_item_count,
    'unmatchedItemCount', target.unmatched_item_count,
    'inventoryRowCount', target.inventory_row_count,
    'displayName', target.display_name,
    'sourceKey', target.source_key
  );
end;
$$;


ALTER FUNCTION public.finalize_pikes_order_import(p_drive_file_id text, p_content_sha256 text, p_source_sheet_name text, p_source_header_row integer, p_expected_row_count integer) OWNER TO postgres;

--
-- Name: FUNCTION finalize_pikes_order_import(p_drive_file_id text, p_content_sha256 text, p_source_sheet_name text, p_source_header_row integer, p_expected_row_count integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.finalize_pikes_order_import(p_drive_file_id text, p_content_sha256 text, p_source_sheet_name text, p_source_header_row integer, p_expected_row_count integer) IS 'Service-only transactional Pikes/Stine finalizer; owner execution is required for private assignment-key resolution.';


--
-- Name: finalize_transactions_keyed_import(text, text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.finalize_transactions_keyed_import(source_drive_file_id text, source_content_sha256 text, source_sheet_name text, source_header_row integer, expected_row_count integer) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
declare
  safe_file_id text := btrim(coalesce(source_drive_file_id, ''));
  safe_hash text := lower(btrim(coalesce(source_content_sha256, '')));
  safe_sheet_name text := btrim(coalesce(source_sheet_name, ''));
  safe_header_row integer := source_header_row;
  imported_count integer;
  first_date date;
  last_date date;
  canonical_file_id text;
begin
  if safe_file_id = '' or safe_sheet_name = '' or safe_hash !~ '^[0-9a-f]{64}$' then
    raise exception using errcode = '22023', message = 'TRANSACTIONS_KEYED_FINALIZE_IDENTITY_INVALID';
  end if;
  if coalesce(safe_header_row, 0) < 1 or coalesce(expected_row_count, 0) < 1 then
    raise exception using errcode = '22023', message = 'TRANSACTIONS_KEYED_FINALIZE_COUNTS_INVALID';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(safe_hash, 0));

  select count(*)::integer, min(r.transaction_business_date), max(r.transaction_business_date)
  into imported_count, first_date, last_date
  from public.ph_transactions_keyed_rows r
  where r.drive_file_id = safe_file_id
    and r.content_sha256 = safe_hash
    and r.source_sheet_name = safe_sheet_name;

  if imported_count <> expected_row_count then
    raise exception using errcode = '22023', message = 'TRANSACTIONS_KEYED_ROW_COUNT_MISMATCH';
  end if;

  select f.drive_file_id into canonical_file_id
  from public.ph_transactions_keyed_files f
  where f.content_sha256 = safe_hash
    and f.drive_file_id <> safe_file_id
    and f.duplicate_of_drive_file_id is null
    and f.status in ('archive_pending', 'processed')
  order by f.imported_at nulls last, f.created_at
  limit 1;

  if canonical_file_id is not null then
    delete from public.ph_transactions_keyed_rows
    where drive_file_id = safe_file_id
      and content_sha256 = safe_hash;

    update public.ph_transactions_keyed_files
    set source_sheet_name = safe_sheet_name,
        source_header_row = safe_header_row,
        row_count = 0,
        first_transaction_date = null,
        last_transaction_date = null,
        status = 'duplicate_archive_pending',
        duplicate_of_drive_file_id = canonical_file_id,
        imported_at = now(),
        last_error_code = null,
        updated_at = now()
    where drive_file_id = safe_file_id and content_sha256 = safe_hash;

    return jsonb_build_object(
      'status', 'duplicate_archive_pending',
      'driveFileId', safe_file_id,
      'duplicateOfDriveFileId', canonical_file_id,
      'rowCount', 0
    );
  end if;

  update public.ph_transactions_keyed_files
  set source_sheet_name = safe_sheet_name,
      source_header_row = safe_header_row,
      row_count = imported_count,
      first_transaction_date = first_date,
      last_transaction_date = last_date,
      status = 'archive_pending',
      duplicate_of_drive_file_id = null,
      imported_at = now(),
      last_error_code = null,
      updated_at = now()
  where drive_file_id = safe_file_id and content_sha256 = safe_hash;

  if not found then
    raise exception using errcode = '22023', message = 'TRANSACTIONS_KEYED_MANIFEST_NOT_PREPARED';
  end if;

  return jsonb_build_object(
    'status', 'archive_pending',
    'driveFileId', safe_file_id,
    'rowCount', imported_count,
    'firstTransactionDate', first_date,
    'lastTransactionDate', last_date
  );
end;
$_$;


ALTER FUNCTION public.finalize_transactions_keyed_import(source_drive_file_id text, source_content_sha256 text, source_sheet_name text, source_header_row integer, expected_row_count integer) OWNER TO postgres;

