--
-- Name: get_drive_evidence_save_health_v2(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_drive_evidence_save_health_v2() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_active_sessions bigint := 0;
  v_lock_waits bigint := 0;
  v_recent_outcomes jsonb := '{}'::jsonb;
  v_recent_unique_tokens bigint := 0;
begin
  select
    count(*) filter (where state <> 'idle'),
    count(*) filter (where state <> 'idle' and wait_event_type = 'Lock')
  into v_active_sessions, v_lock_waits
  from pg_catalog.pg_stat_activity
  where pid <> pg_backend_pid()
    and datname = current_database()
    and query ilike '%save_drive_evidence%';

  select coalesce(jsonb_object_agg(outcome_code, outcome_count), '{}'::jsonb),
         coalesce(sum(outcome_count), 0)
  into v_recent_outcomes, v_recent_unique_tokens
  from (
    select upper(btrim(coalesce(outcome_code, 'UNKNOWN'))) as outcome_code,
           count(*)::bigint as outcome_count
    from private.drive_evidence_idempotency
    where created_at >= now() - interval '5 minutes'
    group by upper(btrim(coalesce(outcome_code, 'UNKNOWN')))
  ) recent;

  return jsonb_build_object(
    'contractVersion', 'drive-evidence-save-health-v2',
    'windowMinutes', 5,
    'recentUniqueTokens', v_recent_unique_tokens,
    'outcomes', v_recent_outcomes,
    'activeSaveSessions', v_active_sessions,
    'lockWaits', v_lock_waits,
    'healthy', v_lock_waits = 0 and v_active_sessions <= 10
  );
end
$$;


ALTER FUNCTION public.get_drive_evidence_save_health_v2() OWNER TO postgres;

--
-- Name: FUNCTION get_drive_evidence_save_health_v2(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.get_drive_evidence_save_health_v2() IS 'Service-only sanitized five-minute Drive evidence save concurrency and outcome health.';


--
-- Name: get_drive_reclass_inquiry_status_v1(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_drive_reclass_inquiry_status_v1(p_actor_username text, p_idempotency_token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_username text := lower(btrim(coalesce(p_actor_username, '')));
  token text := btrim(coalesce(p_idempotency_token, ''));
  event_row public.ph_request_delivery_outbox;
begin
  if actor_username = '' or length(token) < 12 or length(token) > 180 then
    raise exception using errcode = '22023', message = 'DRIVE_RECLASS_STATUS_INVALID';
  end if;
  select o.* into event_row
  from public.ph_request_delivery_outbox o
  where o.event_key = 'reclass-inquiry:' || left(encode(extensions.digest(token, 'sha256'), 'hex'), 40)
    and o.event_type = 'reclass_inquiry'
    and lower(btrim(coalesce(o.payload #>> '{reclassPayload,actor,username}', ''))) = actor_username
    and o.payload #>> '{reclassPayload,protectedDelivery,contractVersion}' = 'drive-reclass-protected-v1'
  limit 1;
  if event_row.event_id is null then
    return jsonb_build_object('ok', false, 'status', 'missing', 'message', 'This inquiry was not found.');
  end if;
  return private.drive_reclass_delivery_result_v1(event_row);
end
$$;


ALTER FUNCTION public.get_drive_reclass_inquiry_status_v1(p_actor_username text, p_idempotency_token text) OWNER TO postgres;

--
-- Name: get_eval_item_low_stock_targets_v1(text[], text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_eval_item_low_stock_targets_v1(p_itemcodes text[] DEFAULT NULL::text[], p_after_itemcode text DEFAULT NULL::text, p_limit integer DEFAULT 500) RETURNS TABLE(itemcode_normalized text, qualifying_line_count integer, qualifying_day_count integer, source_file_count integer, mean_quantity numeric, p75_quantity numeric, suggested_qty integer, manual_override_qty integer, effective_qty integer, override_revision bigint, history_ready boolean, history_pending_files integer, history_total_files integer, history_from_date date, history_through_date date, calculated_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor public.profiles;
  requested_count integer;
  fallback_qty integer;
begin
  if coalesce(auth.jwt()->>'role', '') <> 'service_role' then
    actor := private.current_active_profile();
    if actor.id is null or not private.can_view_eval_item_low_stock_targets_v1() then
      raise exception using errcode = '42501', message = 'LOW_STOCK_TARGETS_FORBIDDEN';
    end if;
  end if;
  if p_limit is null or p_limit < 1 or p_limit > 500 then
    raise exception using errcode = '22023', message = 'LOW_STOCK_TARGETS_LIMIT_INVALID';
  end if;
  if p_itemcodes is not null then
    select count(*) into requested_count from unnest(p_itemcodes);
    if requested_count > 500 then
      raise exception using errcode = '22023', message = 'LOW_STOCK_TARGETS_LIMIT_INVALID';
    end if;
  end if;
  select coalesce((select s.low_stock_max_slts from public.ph_eval_report_settings s where s.singleton limit 1), 150)
  into fallback_qty;

  return query
  with requested as (
    select distinct upper(btrim(code)) as itemcode_normalized
  from unnest(coalesce(p_itemcodes, '{}'::text[])) as requested_codes(code)
    where nullif(btrim(code), '') is not null
    union
    select stats.itemcode_normalized
    from private.eval_item_low_stock_target_stats_v1 stats
    where p_itemcodes is null
    union
    select o.itemcode_normalized
    from private.ph_eval_item_low_stock_overrides o
    where p_itemcodes is null
  ), page as (
    select r.itemcode_normalized
    from requested r
    where p_itemcodes is not null
       or p_after_itemcode is null
       or r.itemcode_normalized > upper(btrim(p_after_itemcode))
    order by r.itemcode_normalized
    limit p_limit
  ), history_state as (
    select
      s.active_run_id is not null and s.pending_run_id is null as history_ready,
      coalesce(jsonb_array_length(scan.expected_manifest), 0)::integer as history_total_files,
      coalesce((
        select count(*)::integer
        from private.ph_eval_item_low_stock_run_files rf
        left join private.ph_eval_item_low_stock_file_versions fv on fv.file_version_id = rf.file_version_id
        where rf.run_id = scan.run_id
          and (rf.file_version_id is null or fv.status <> 'finalized')
      ), 0) as history_pending_files
    from private.ph_eval_item_low_stock_import_state s
    left join private.ph_eval_item_low_stock_import_runs scan
      on scan.run_id = coalesce(s.pending_run_id, s.active_run_id)
    where s.singleton
  )
  select
    p.itemcode_normalized,
    coalesce(s.qualifying_line_count, 0),
    coalesce(s.qualifying_day_count, 0),
    coalesce(s.source_file_count, 0),
    s.mean_quantity,
    s.p75_quantity,
    s.suggested_qty,
    o.manual_override_qty,
    coalesce(o.manual_override_qty, s.suggested_qty, fallback_qty),
    coalesce(o.revision, 0),
    coalesce(h.history_ready, false),
    coalesce(h.history_pending_files, 0),
    coalesce(h.history_total_files, 0),
    s.history_from_date,
    s.history_through_date,
    s.updated_at,
    greatest(s.updated_at, o.updated_at)
  from page p
  left join private.eval_item_low_stock_target_stats_v1 s
    on s.itemcode_normalized = p.itemcode_normalized
  left join private.ph_eval_item_low_stock_overrides o
    on o.itemcode_normalized = p.itemcode_normalized
  cross join history_state h
  order by p.itemcode_normalized;
end
$$;


ALTER FUNCTION public.get_eval_item_low_stock_targets_v1(p_itemcodes text[], p_after_itemcode text, p_limit integer) OWNER TO postgres;

--
-- Name: get_eval_itemcode_work_health_snapshot_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_eval_itemcode_work_health_snapshot_v1() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  scoped_assignments bigint := 0;
  stored_membership_mismatches bigint := 0;
  pdf_origin_mismatches bigint := 0;
  excel_attachment_violations bigint := 0;
  over_limit_assignments bigint := 0;
  largest_origin_count integer := 0;
begin
  if not private.is_service_role_request() then
    raise exception using errcode = '42501', message = 'EVAL_ITEMCODE_HEALTH_FORBIDDEN';
  end if;

  select count(*), coalesce(max(work.origin_count), 0),
    count(*) filter (where work.origin_count > 100)
  into scoped_assignments, largest_origin_count, over_limit_assignments
  from public.ph_eval_work work
  where work.source_context->>'scopeContract' = 'itemcode-all-rows-v1';

  select count(*) into stored_membership_mismatches
  from public.ph_eval_work work
  where work.source_context->>'scopeContract' = 'itemcode-all-rows-v1'
    and (
      coalesce((work.source_context->>'membershipCount')::integer, -1) <> work.origin_count
      or coalesce(work.source_context->>'membershipSignature', '') = ''
      or work.origin_count <> (
        select count(*) from public.ph_eval_work_origin_rows origin where origin.eval_work_id = work.id
      )
    );

  select count(*) into pdf_origin_mismatches
  from public.ph_request_delivery_outbox delivery
  join public.ph_eval_work work on work.id::text = delivery.request_id
  where work.source_context->>'scopeContract' = 'itemcode-all-rows-v1'
    and delivery.event_type in ('eval_work_assignment', 'eval_work_completion')
    and delivery.status <> 'suppressed'
    and (
      coalesce(delivery.payload->>'scopeContract', '') <> 'itemcode-all-rows-v1'
      or coalesce(
        (delivery.payload->>'originCount')::integer,
        (delivery.payload->>'membershipCount')::integer,
        -1
      ) <> work.origin_count
      or coalesce(jsonb_array_length(delivery.payload->'origins'), 0) <> work.origin_count
    );

  select count(*) into excel_attachment_violations
  from public.ph_request_delivery_outbox delivery
  join public.ph_eval_work work on work.id::text = delivery.request_id
  where work.source_context->>'scopeContract' = 'itemcode-all-rows-v1'
    and delivery.event_type in ('eval_work_assignment', 'eval_work_completion')
    and delivery.status <> 'suppressed'
    and lower(delivery.payload::text) ~ '(\.xlsx|\.xls\"|spreadsheetml|excelattachment)';

  return jsonb_build_object(
    'contract_version', 'eval-itemcode-work-health-v1',
    'scope_contract', 'itemcode-all-rows-v1',
    'scoped_assignment_count', scoped_assignments,
    'stored_membership_mismatch_count', stored_membership_mismatches,
    'pdf_origin_mismatch_count', pdf_origin_mismatches,
    'excel_attachment_violation_count', excel_attachment_violations,
    'over_limit_assignment_count', over_limit_assignments,
    'largest_origin_count', largest_origin_count
  );
end
$$;


ALTER FUNCTION public.get_eval_itemcode_work_health_snapshot_v1() OWNER TO postgres;

--
-- Name: FUNCTION get_eval_itemcode_work_health_snapshot_v1(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.get_eval_itemcode_work_health_snapshot_v1() IS 'Service-only sanitized audit for ITEMCODE-wide origin, PDF, Queue, and PDF-only delivery parity.';


--
-- Name: get_eval_itemcode_work_health_snapshot_v2(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_eval_itemcode_work_health_snapshot_v2() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  contract_started_at constant timestamptz := '2026-09-03 18:24:00+00'::timestamptz;
  scoped_assignments bigint := 0;
  stored_membership_mismatches bigint := 0;
  pdf_origin_mismatches bigint := 0;
  historical_pdf_origin_mismatches bigint := 0;
  excel_attachment_violations bigint := 0;
  over_limit_assignments bigint := 0;
  largest_origin_count integer := 0;
begin
  if not private.is_service_role_request() then
    raise exception using errcode = '42501', message = 'EVAL_ITEMCODE_HEALTH_FORBIDDEN';
  end if;
  select count(*), coalesce(max(work.origin_count), 0), count(*) filter (where work.origin_count > 100)
    into scoped_assignments, largest_origin_count, over_limit_assignments
  from public.ph_eval_work work where work.source_context->>'scopeContract' = 'itemcode-all-rows-v1';
  select count(*) into stored_membership_mismatches
  from public.ph_eval_work work
  where work.source_context->>'scopeContract' = 'itemcode-all-rows-v1'
    and (coalesce(private.eval_itemcode_health_count_v1(work.source_context->'membershipCount'), -1) <> coalesce(work.origin_count, -1)
      or coalesce(work.source_context->>'membershipSignature', '') = ''
      or coalesce(work.origin_count, -1) <> (select count(*) from public.ph_eval_work_origin_rows origin where origin.eval_work_id = work.id));

  with inspected as (
    select delivery.created_at, case
      when delivery.payload->>'contractVersion' = 'eval-work-assignment-batch-v1' then
        delivery.event_type <> 'eval_work_assignment'
        or not private.eval_itemcode_health_group_valid_v1(delivery.payload, delivery.request_id, delivery.event_key)
      -- Unknown or misspelled envelopes cannot pass as a permissive singleton.
      when delivery.payload ? 'assignments' or delivery.payload ? 'evalWorkIds' then true
      else
        coalesce(delivery.payload->>'scopeContract', '') <> 'itemcode-all-rows-v1'
        or (delivery.payload->>'originCount' is not null and private.eval_itemcode_health_count_v1(delivery.payload->'originCount') is null)
        or (delivery.payload->>'membershipCount' is not null and private.eval_itemcode_health_count_v1(delivery.payload->'membershipCount') is null)
        or coalesce(private.eval_itemcode_health_count_v1(delivery.payload->'originCount'), private.eval_itemcode_health_count_v1(delivery.payload->'membershipCount'), -1) <> coalesce(work.origin_count, -1)
        or case when jsonb_typeof(delivery.payload->'origins') = 'array'
             then jsonb_array_length(delivery.payload->'origins') else 0 end <> coalesce(work.origin_count, -1)
      end as mismatch
    from public.ph_request_delivery_outbox delivery
    left join public.ph_eval_work work on work.id::text = delivery.request_id
    where delivery.event_type in ('eval_work_assignment', 'eval_work_completion')
      and delivery.status <> 'suppressed'
      and (work.source_context->>'scopeContract' = 'itemcode-all-rows-v1'
        or delivery.payload->>'contractVersion' = 'eval-work-assignment-batch-v1'
        or delivery.payload ? 'assignments' or delivery.payload ? 'evalWorkIds')
  )
  select count(*) filter (where created_at >= contract_started_at),
         count(*) filter (where created_at < contract_started_at)
    into pdf_origin_mismatches, historical_pdf_origin_mismatches
  from inspected where mismatch;

  -- Preserve the original whole-payload Excel check, including nested members.
  select count(*) into excel_attachment_violations
  from public.ph_request_delivery_outbox delivery
  left join public.ph_eval_work work on work.id::text = delivery.request_id
  where (work.source_context->>'scopeContract' = 'itemcode-all-rows-v1'
      or delivery.payload->>'contractVersion' = 'eval-work-assignment-batch-v1'
      or delivery.payload ? 'assignments' or delivery.payload ? 'evalWorkIds')
    and delivery.created_at >= contract_started_at
    and delivery.event_type in ('eval_work_assignment', 'eval_work_completion')
    and delivery.status <> 'suppressed'
    and lower(delivery.payload::text) ~ '(\.xlsx|\.xls"|spreadsheetml|excelattachment)';
  return jsonb_build_object(
    'contract_version', 'eval-itemcode-work-health-v2', 'scope_contract', 'itemcode-all-rows-v1',
    'contract_started_at', contract_started_at, 'scoped_assignment_count', scoped_assignments,
    'stored_membership_mismatch_count', stored_membership_mismatches,
    'pdf_origin_mismatch_count', pdf_origin_mismatches,
    'historical_pdf_origin_mismatch_count', historical_pdf_origin_mismatches,
    'excel_attachment_violation_count', excel_attachment_violations,
    'over_limit_assignment_count', over_limit_assignments, 'largest_origin_count', largest_origin_count);
end
$$;


ALTER FUNCTION public.get_eval_itemcode_work_health_snapshot_v2() OWNER TO postgres;

--
-- Name: FUNCTION get_eval_itemcode_work_health_snapshot_v2(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.get_eval_itemcode_work_health_snapshot_v2() IS 'Service-only read-only ITEMCODE health. Validates grouped assignment envelopes and every frozen member; preserves single-delivery checks, cutoff and immutable history.';


--
-- Name: get_eval_report2_direct_inquiry_recipients_v1(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_eval_report2_direct_inquiry_recipients_v1(p_actor_username text) RETURNS text[]
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor public.profiles;
  actor_username text;
  usernames text[] := array['dylan_collyge', 'megan_kelly', 'sharon_combs'];
  emails text[];
  expected_count integer := 3;
begin
  actor := private.eval_work_assert_actor_v1(p_actor_username);
  actor_username := private.eval_normalize_user_v2(actor.username);
  if actor_username not in ('dylan_collyge', 'megan_kelly', 'jd_jones') then
    raise exception using errcode = '42501', message = 'eval_report2_direct_inquiry_forbidden';
  end if;
  if actor_username = 'jd_jones' then
    usernames := array_append(usernames, 'jd_jones');
    expected_count := 4;
  end if;
  emails := private.eval_report2_verified_user_emails_v1(usernames);
  if cardinality(emails) <> expected_count then
    raise exception using errcode = '40001', message = 'eval_report2_direct_recipient_unavailable';
  end if;
  return emails;
end
$$;


