--
-- Name: get_limited_access_control_matrix_v1(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_limited_access_control_matrix_v1(p_query jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  query_value jsonb := coalesce(p_query, '{}'::jsonb);
  policy private.app_access_policy_versions;
  access_state private.app_limited_access_state;
  search_value text := lower(left(btrim(coalesce(query_value->>'search', '')), 100));
  role_filter text := private.normalized_profile_role(left(btrim(coalesce(query_value->>'role', '')), 80));
  module_filter text := lower(left(btrim(coalesce(query_value->>'module', '')), 100));
  subject_offset_value integer := greatest(0, least(100000, coalesce((query_value->>'subjectOffset')::integer, 0)));
  subject_limit_value integer := greatest(1, least(100, coalesce((query_value->>'subjectLimit')::integer, 24)));
  permission_offset_value integer := greatest(0, least(100000, coalesce((query_value->>'permissionOffset')::integer, 0)));
  permission_limit_value integer := greatest(1, least(24, coalesce((query_value->>'permissionLimit')::integer, 8)));
  permission_rows jsonb := '[]'::jsonb;
  user_rows jsonb := '[]'::jsonb;
  module_rows jsonb := '[]'::jsonb;
  filtered_subject_count bigint := 0;
  filtered_permission_count bigint := 0;
begin
  if not private.is_kayla_limited_access_manager_v1() then
    raise exception using errcode = '42501', message = 'LIMITED_ACCESS_CONTROL_FORBIDDEN';
  end if;
  if jsonb_typeof(query_value) <> 'object' then
    raise exception using errcode = '22023', message = 'LIMITED_ACCESS_CONTROL_QUERY_INVALID';
  end if;

  select * into policy
  from private.app_access_policy_versions v
  where v.id = private.resolve_app_access_policy_id_v1(false)
  limit 1;
  select * into access_state from private.app_limited_access_state where singleton;

  select coalesce(jsonb_agg(x.module_key order by x.module_key), '[]'::jsonb)
  into module_rows
  from (
    select distinct p.module_key
    from private.app_access_permissions p
    where private.is_kayla_managed_permission_v1(p.permission_key)
  ) x;

  with filtered_permissions as (
    select p.*
    from private.app_access_permissions p
    where private.is_kayla_managed_permission_v1(p.permission_key)
      and (module_filter in ('', 'all') or p.module_key = module_filter)
  ), page_permissions as (
    select * from filtered_permissions
    order by sort_order, permission_key
    offset permission_offset_value limit permission_limit_value
  )
  select
    (select count(*) from filtered_permissions),
    coalesce(jsonb_agg(jsonb_build_object(
      'permissionKey', p.permission_key,
      'kind', p.permission_kind,
      'moduleKey', p.module_key,
      'label', p.label,
      'description', p.description,
      'scopeOptions', to_jsonb(p.scope_options),
      'sortOrder', p.sort_order
    ) order by p.sort_order, p.permission_key), '[]'::jsonb)
  into filtered_permission_count, permission_rows
  from page_permissions p;

  with filtered_profiles as (
    select p.*
    from public.profiles p
    where p.disabled_at is null
      and (p.locked_until is null or p.locked_until <= now())
      and private.is_kayla_managed_role_v1(p.role)
      and (role_filter = '' or private.normalized_profile_role(p.role) = role_filter)
      and (
        search_value = ''
        or lower(coalesce(p.username, '') || ' ' || coalesce(p.display_name, '') || ' ' || coalesce(p.role, '')) like '%' || search_value || '%'
      )
  ), page_profiles as (
    select p.* from filtered_profiles p
    order by lower(coalesce(nullif(p.display_name, ''), p.username)), lower(p.username)
    offset subject_offset_value limit subject_limit_value
  ), decisions as (
    select p.id as profile_id, e.permission_key,
           coalesce(o.allowed, e.allowed) as allowed,
           e.access_scope,
           case when o.permission_key is not null then 'limited-user' else e.decision_source end as decision_source
    from page_profiles p
    cross join lateral private.get_effective_app_permissions_v1(p.id, policy.id) e
    left join private.app_limited_live_overrides o
      on o.profile_id = p.id and o.permission_key = e.permission_key
    where e.permission_key in (
      select page_perm."permissionKey"
      from jsonb_to_recordset(permission_rows) as page_perm("permissionKey" text)
    )
  ), user_decisions as (
    select d.profile_id,
           jsonb_object_agg(d.permission_key, jsonb_build_object(
             'allowed', d.allowed,
             'scope', d.access_scope,
             'source', d.decision_source,
             'baselinePresent', true,
             'mismatch', false
           )) as decisions
    from decisions d group by d.profile_id
  )
  select
    (select count(*) from filtered_profiles),
    coalesce(jsonb_agg(jsonb_build_object(
      'username', lower(btrim(p.username)),
      'displayName', coalesce(nullif(p.display_name, ''), p.username),
      'role', p.role,
      'roleKey', private.normalized_profile_role(p.role),
      'decisions', coalesce(d.decisions, '{}'::jsonb)
    ) order by lower(coalesce(nullif(p.display_name, ''), p.username)), lower(p.username)), '[]'::jsonb)
  into filtered_subject_count, user_rows
  from page_profiles p
  left join user_decisions d on d.profile_id = p.id;

  return jsonb_build_object(
    'contractVersion', 'app-access-view-v2',
    'enforcementMode', 'limited-live',
    'capabilities', jsonb_build_object(
      'canView', true,
      'canEdit', true,
      'canPublish', false,
      'editScope', 'limited-users',
      'liveChanges', true,
      'managedRoleKeys', jsonb_build_array('CSR', 'SALESREP', 'SALESMARKETING')
    ),
    'policy', jsonb_build_object(
      'id', policy.id,
      'version', policy.version_number,
      'revision', access_state.revision,
      'status', 'limited-live'
    ),
    'permissions', permission_rows,
    'users', user_rows,
    'roles', '[]'::jsonb,
    'filters', jsonb_build_object(
      'modules', module_rows,
      'roles', jsonb_build_array('CSR', 'SALESREP', 'SALESMARKETING')
    ),
    'page', jsonb_build_object(
      'subjectType', 'users',
      'subjectOffset', subject_offset_value,
      'subjectLimit', subject_limit_value,
      'subjectTotal', filtered_subject_count,
      'permissionOffset', permission_offset_value,
      'permissionLimit', permission_limit_value,
      'permissionTotal', filtered_permission_count
    ),
    'summary', jsonb_build_object(
      'userCount', filtered_subject_count,
      'permissionCount', filtered_permission_count,
      'mismatchCount', 0,
      'baselineMissingCount', 0
    )
  );
exception
  when invalid_text_representation then
    raise exception using errcode = '22023', message = 'LIMITED_ACCESS_CONTROL_QUERY_INVALID';
end
$$;


ALTER FUNCTION public.get_limited_access_control_matrix_v1(p_query jsonb) OWNER TO postgres;

--
-- Name: FUNCTION get_limited_access_control_matrix_v1(p_query jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.get_limited_access_control_matrix_v1(p_query jsonb) IS 'Returns only active CSR, SALESREP, and SALES/MARKETING profiles and safe module permissions to Kayla Knepp.';


--
-- Name: get_manager_order_batch_v1(uuid, text[], text, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_manager_order_batch_v1(p_batch_id uuid, p_assignedto_keys text[] DEFAULT NULL::text[], p_after_itemcode text DEFAULT NULL::text, p_after_unique_id text DEFAULT NULL::text, p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare
  safe_limit integer := least(greatest(coalesce(p_limit, 100), 1), 200);
  result jsonb;
begin
  if not private.can_view_manager_orders() then raise exception 'PIKES_ORDERS_FORBIDDEN'; end if;
  if not exists (
    select 1 from public.ph_pikes_order_batches b
    where b.batch_id = p_batch_id and b.status in ('archive_pending', 'processed')
  ) then raise exception 'PIKES_ORDERS_BATCH_NOT_FOUND'; end if;

  with normalized_filter as (
    select distinct case
      when lower(btrim(value)) in ('', 'unassigned', '__unassigned__') then '__unassigned__'
      else lower(btrim(value)) end as key
    from unnest(coalesce(p_assignedto_keys, '{}'::text[])) value
  ), filtered as (
    select i.*
    from public.ph_pikes_order_inventory_rows i
    where i.batch_id = p_batch_id
      and (
        not exists (select 1 from normalized_filter)
        or i.assignedto_key in (select key from normalized_filter)
      )
      and (
        p_after_itemcode is null
        or (i.itemcode_normalized, i.master_unique_id) > (p_after_itemcode, coalesce(p_after_unique_id, ''))
      )
    order by i.itemcode_normalized, i.master_unique_id
    limit safe_limit + 1
  ), shown as (
    select * from filtered order by itemcode_normalized, master_unique_id limit safe_limit
  ), source_context as (
    select r.itemcode_normalized,
      jsonb_agg(jsonb_build_object(
        'sourceRowNumber', r.source_row_number,
        'orderTot', r.order_tot,
        'pickNotes', r.pick_notes
      ) order by r.source_row_number) as entries
    from public.ph_pikes_order_source_rows r
    where r.batch_id = p_batch_id
    group by r.itemcode_normalized
  )
  select jsonb_build_object(
    'batch', (select jsonb_build_object(
      'batchId', b.batch_id, 'displayName', b.display_name, 'fileName', b.file_name,
      'status', b.status, 'sourceRowCount', b.source_row_count,
      'distinctItemCount', b.distinct_item_count, 'matchedItemCount', b.matched_item_count,
      'unmatchedItemCount', b.unmatched_item_count, 'inventoryRowCount', b.inventory_row_count,
      'importedAt', b.imported_at, 'archivedAt', b.archived_at
    ) from public.ph_pikes_order_batches b where b.batch_id = p_batch_id),
    'assignees', coalesce((select jsonb_agg(jsonb_build_object(
      'key', a.assignedto_key,
      'label', case when a.assignedto_key = '__unassigned__' then 'Unassigned' else a.assignedto end,
      'rowCount', a.row_count
    ) order by case when a.assignedto_key = '__unassigned__' then 1 else 0 end, lower(a.assignedto))
    from (
      select i.assignedto_key, max(nullif(btrim(i.assignedto), '')) as assignedto, count(*)::integer as row_count
      from public.ph_pikes_order_inventory_rows i where i.batch_id = p_batch_id
      group by i.assignedto_key
    ) a), '[]'::jsonb),
    'unmatchedItems', coalesce((select jsonb_agg(jsonb_build_object(
      'itemcode', u.itemcode,
      'itemcodeNormalized', u.itemcode_normalized,
      'sourceEntries', u.entries
    ) order by u.itemcode_normalized)
    from (
      select min(r.itemcode) as itemcode, r.itemcode_normalized,
        jsonb_agg(jsonb_build_object('sourceRowNumber', r.source_row_number, 'orderTot', r.order_tot, 'pickNotes', r.pick_notes)
          order by r.source_row_number) as entries
      from public.ph_pikes_order_source_rows r
      where r.batch_id = p_batch_id and not r.matched
      group by r.itemcode_normalized
      order by r.itemcode_normalized
      limit 200
    ) u), '[]'::jsonb),
    'unmatchedItemsTruncated', (select b.unmatched_item_count > 200
      from public.ph_pikes_order_batches b where b.batch_id = p_batch_id),
    'rows', coalesce((select jsonb_agg(jsonb_build_object(
      'masterUniqueId', s.master_unique_id, 'itemcode', s.itemcode,
      'itemcodeNormalized', s.itemcode_normalized, 'commonname', s.commonname,
      'contsize', s.contsize, 'locationcode', s.locationcode, 'lotcode', s.lotcode,
      'assignedto', s.assignedto, 'assignedtoKey', s.assignedto_key,
      'priority', s.priority, 'ptronhand', s.ptronhand, 'ptrreviewed', s.ptrreviewed,
      'ptravailable', s.ptravailable, 'sLts', s.s_lts, 'season', s.season,
      'blockalpha', s.blockalpha, 'blocknumber', s.blocknumber,
      'fieldtagcolor', s.fieldtagcolor, 'desigitem', s.desigitem, 'desigloc', s.desigloc,
      'holdstopcode', s.holdstopcode, 'holdstopreason', s.holdstopreason,
      'itemspec', s.itemspec, 'locationnote', s.locationnote,
      'locationnotedate', s.locationnotedate, 'photoLink', s.photo_link,
      'photoName', s.photo_name, 'snapshottedAt', s.snapshotted_at,
      'sourceEntries', coalesce(sc.entries, '[]'::jsonb)
    ) order by s.itemcode_normalized, s.master_unique_id)
    from shown s left join source_context sc on sc.itemcode_normalized = s.itemcode_normalized), '[]'::jsonb),
    'filteredRowCount', (select count(*) from public.ph_pikes_order_inventory_rows i
      where i.batch_id = p_batch_id and (
        not exists (select 1 from normalized_filter)
        or i.assignedto_key in (select key from normalized_filter)
      )),
    'hasMore', (select count(*) > safe_limit from filtered),
    'nextCursor', (select jsonb_build_object('itemcode', s.itemcode_normalized, 'uniqueId', s.master_unique_id)
      from shown s order by s.itemcode_normalized desc, s.master_unique_id desc limit 1)
  ) into result;
  return result;
end;
$$;


ALTER FUNCTION public.get_manager_order_batch_v1(p_batch_id uuid, p_assignedto_keys text[], p_after_itemcode text, p_after_unique_id text, p_limit integer) OWNER TO postgres;

--
-- Name: get_manager_order_batches_v1(text, timestamp with time zone, uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_manager_order_batches_v1(p_source_key text DEFAULT 'pikes'::text, p_before_imported_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_before_batch_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 25) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare
  safe_source_key text := lower(btrim(coalesce(p_source_key, '')));
  safe_limit integer := least(greatest(coalesce(p_limit, 25), 1), 50);
  source_label text;
  result jsonb;
begin
  if not private.can_view_manager_orders() then raise exception 'MANAGER_ORDERS_FORBIDDEN'; end if;
  if safe_source_key not in ('pikes', 'stine_lumber') then raise exception 'MANAGER_ORDERS_SOURCE_INVALID'; end if;
  source_label := case safe_source_key when 'stine_lumber' then 'Stine Lumber' else 'Pikes' end;

  with page as (
    select b.*
    from public.ph_pikes_order_batches b
    where b.source_key = safe_source_key
      and b.status in ('archive_pending', 'processed')
      and (
        p_before_imported_at is null
        or (b.imported_at, b.batch_id) < (p_before_imported_at, p_before_batch_id)
      )
    order by b.imported_at desc, b.batch_id desc
    limit safe_limit + 1
  ), shown as (
    select * from page order by imported_at desc, batch_id desc limit safe_limit
  )
  select jsonb_build_object(
    'sourceKey', safe_source_key,
    'sourceLabel', source_label,
    'batches', coalesce((select jsonb_agg(jsonb_build_object(
      'batchId', s.batch_id,
      'displayName', s.display_name,
      'fileName', s.file_name,
      'status', s.status,
      'sourceRowCount', s.source_row_count,
      'distinctItemCount', s.distinct_item_count,
      'matchedItemCount', s.matched_item_count,
      'unmatchedItemCount', s.unmatched_item_count,
      'inventoryRowCount', s.inventory_row_count,
      'importedAt', s.imported_at,
      'archivedAt', s.archived_at
    ) order by s.imported_at desc, s.batch_id desc) from shown s), '[]'::jsonb),
    'hasMore', (select count(*) > safe_limit from page),
    'nextCursor', (select jsonb_build_object('importedAt', s.imported_at, 'batchId', s.batch_id)
      from shown s order by s.imported_at asc, s.batch_id asc limit 1)
  ) into result;
  return result;
end;
$$;


ALTER FUNCTION public.get_manager_order_batches_v1(p_source_key text, p_before_imported_at timestamp with time zone, p_before_batch_id uuid, p_limit integer) OWNER TO postgres;

--
-- Name: get_manager_order_sources_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_manager_order_sources_v1() RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare result jsonb;
begin
  if not private.can_view_manager_orders() then raise exception 'MANAGER_ORDERS_FORBIDDEN'; end if;
  with source_defs(source_key, label, sort_order) as (
    values ('pikes'::text, 'Pikes'::text, 1),
           ('stine_lumber'::text, 'Stine Lumber'::text, 2)
  )
  select jsonb_build_object(
    'sources', coalesce(jsonb_agg(jsonb_build_object(
      'sourceKey', source.source_key,
      'label', source.label,
      'batchCount', (select count(*) from public.ph_pikes_order_batches b
        where b.source_key = source.source_key and b.status in ('archive_pending', 'processed')),
      'failedCount', (select count(*) from public.ph_pikes_order_batches b
        where b.source_key = source.source_key and b.status = 'failed'),
      'latestImportedAt', (select max(b.imported_at) from public.ph_pikes_order_batches b
        where b.source_key = source.source_key and b.status in ('archive_pending', 'processed')),
      'latestDisplayName', (select b.display_name from public.ph_pikes_order_batches b
        where b.source_key = source.source_key and b.status in ('archive_pending', 'processed')
        order by b.imported_at desc nulls last, b.batch_id desc limit 1)
    ) order by source.sort_order), '[]'::jsonb)
  ) into result
  from source_defs source;
  return coalesce(result, '{"sources":[]}'::jsonb);
end;
$$;


ALTER FUNCTION public.get_manager_order_sources_v1() OWNER TO postgres;

--
-- Name: get_my_app_permissions_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_my_app_permissions_v1() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare profile public.profiles; state private.app_access_runtime_state; policy private.app_access_policy_versions;
  permissions jsonb; permission_version text;
begin
  profile:=private.current_active_profile();
  if profile.id is null then raise exception using errcode='42501',message='APP_ACCESS_PROFILE_REQUIRED'; end if;
  select * into state from private.app_access_runtime_state where singleton;
  select * into policy from private.app_access_policy_versions where id=private.resolve_app_access_policy_id_v1(false);
  select coalesce(jsonb_agg(jsonb_build_object('permissionKey',e.permission_key,'kind',e.permission_kind,
    'moduleKey',e.module_key,'label',e.label,'allowed',case when private.is_kayla_managed_role_v1(profile.role)
      and o.permission_key is not null then o.allowed else e.allowed end,
    'scope',e.access_scope,'source',case when private.is_kayla_managed_role_v1(profile.role)
      and o.permission_key is not null then 'limited-user' else e.decision_source end)
    order by e.sort_order,e.permission_key),'[]'::jsonb) into permissions
  from private.get_effective_app_permissions_v1(profile.id,policy.id) e
  left join private.app_limited_live_overrides o on o.profile_id=profile.id and o.permission_key=e.permission_key;
  permission_version:=app_sync_private.data_permission_version(profile.id);
  return jsonb_build_object('contractVersion','app-access-v1','enforcementMode',state.enforcement_mode,
    'policyVersion',policy.version_number,'policyRevision',policy.revision,
    'dataPermissionVersion',permission_version,
    'username',lower(btrim(profile.username)),'role',profile.role,'permissions',permissions);
end $$;


ALTER FUNCTION public.get_my_app_permissions_v1() OWNER TO postgres;

