--
-- Name: get_photo_delivery_health_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_photo_delivery_health_v1() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  released_at timestamptz;
  recent_upload_count bigint := 0;
  recent_oversized_count bigint := 0;
  recent_mime_extension_mismatch_count bigint := 0;
  recent_png_count bigint := 0;
  static_original_count bigint := 0;
  complete_static_thumbnail_set_count bigint := 0;
  active_reference_count bigint := 0;
  active_v2_reference_count bigint := 0;
begin
  if not private.is_service_role_request() then
    raise exception using errcode = '42501', message = 'PHOTO_DELIVERY_HEALTH_FORBIDDEN';
  end if;

  select b.released_at into released_at
  from private.photo_delivery_health_baseline_v1 b
  where b.baseline_key = 'photo-egress-v1';

  with recent as materialized (
    select
      o.bucket_id,
      o.name,
      lower(coalesce(o.metadata ->> 'mimetype', '')) as mime_type,
      coalesce(nullif(o.metadata ->> 'size', '')::bigint, 0) as byte_count
    from storage.objects o
    where o.bucket_id = any (array[
      'request_photos',
      'flyer_photos',
      'season_sales_notes_photos',
      'location_sales_notes_photos'
    ]::text[])
      and o.created_at >= coalesce(released_at, clock_timestamp())
  )
  select
    count(*),
    count(*) filter (
      where (name ~ '(^|/)v2/[0-9a-f]{64}\.(jpg|webp)$' and byte_count > 1310720)
         or (name ~ '(^|/)_thumbs/v2/[0-9a-f]{64}-w144\.(jpg|webp)$' and byte_count > 81920)
         or (name ~ '(^|/)_thumbs/v2/[0-9a-f]{64}-w320\.(jpg|webp)$' and byte_count > 163840)
    ),
    count(*) filter (
      where (mime_type = 'image/jpeg' and name !~* '\.jpe?g$')
         or (mime_type = 'image/webp' and name !~* '\.webp$')
         or mime_type not in ('image/jpeg', 'image/webp')
    ),
    count(*) filter (where mime_type = 'image/png')
  into recent_upload_count, recent_oversized_count, recent_mime_extension_mismatch_count, recent_png_count
  from recent;

  with originals as materialized (
    select o.bucket_id, o.name,
      regexp_replace(o.name, '(^|/)v2/([0-9a-f]{64})\.(jpg|webp)$', '\2') as content_hash,
      regexp_replace(o.name, '^.*\.', '') as extension
    from storage.objects o
    where o.bucket_id = any (array[
      'request_photos',
      'flyer_photos',
      'season_sales_notes_photos',
      'location_sales_notes_photos'
    ]::text[])
      and o.name ~ '(^|/)v2/[0-9a-f]{64}\.(jpg|webp)$'
  )
  select count(*), count(*) filter (
    where exists (
      select 1 from storage.objects t144
      where t144.bucket_id = originals.bucket_id
        and t144.name = '_thumbs/v2/' || originals.content_hash || '-w144.' || originals.extension
    )
    and exists (
      select 1 from storage.objects t320
      where t320.bucket_id = originals.bucket_id
        and t320.name = '_thumbs/v2/' || originals.content_hash || '-w320.' || originals.extension
    )
  )
  into static_original_count, complete_static_thumbnail_set_count
  from originals;

  with raw_references as materialized (
    select nullif(btrim(m.photo_link), '') as photo_csv
    from public.ph_master_inventory m
    where nullif(btrim(m.photo_link), '') is not null
    union all
    select nullif(btrim(r.req_photo_link), '') as photo_csv
    from public.ph_active_request r
    where nullif(btrim(r.req_photo_link), '') is not null
  ), photo_references as materialized (
    select distinct btrim(value) as photo_url
    from raw_references,
      lateral regexp_split_to_table(raw_references.photo_csv, '\s*,\s*') value
    where btrim(value) <> ''
  )
  select count(*), count(*) filter (where photo_url ~ '/v2/[0-9a-f]{64}\.(jpg|webp)(\?|$)')
  into active_reference_count, active_v2_reference_count
  from photo_references;

  return jsonb_build_object(
    'ok', true,
    'healthy', recent_oversized_count = 0
      and recent_mime_extension_mismatch_count = 0
      and recent_png_count = 0
      and static_original_count = complete_static_thumbnail_set_count,
    'shell_version', 'V2026.09.04.04',
    'observed_since', released_at,
    'recent_upload_count', recent_upload_count,
    'recent_oversized_upload_count', recent_oversized_count,
    'recent_mime_extension_mismatch_count', recent_mime_extension_mismatch_count,
    'recent_png_upload_count', recent_png_count,
    'active_reference_count', active_reference_count,
    'active_v2_reference_count', active_v2_reference_count,
    'static_original_count', static_original_count,
    'complete_static_thumbnail_set_count', complete_static_thumbnail_set_count,
    'static_thumbnail_coverage_percent', case
      when static_original_count = 0 then 100
      else round((complete_static_thumbnail_set_count::numeric * 100) / static_original_count, 2)
    end
  );
end
$_$;


ALTER FUNCTION public.get_photo_delivery_health_v1() OWNER TO postgres;

--
-- Name: FUNCTION get_photo_delivery_health_v1(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.get_photo_delivery_health_v1() IS 'Service-only aggregate health for V2 plant-photo delivery. Never returns filenames, URLs, users, or inventory identities.';


--
-- Name: get_pikes_order_assignment_health_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_pikes_order_assignment_health_v1() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  latest_batch_id uuid;
  inventory_count integer := 0;
  snapshot_unassigned integer := 0;
  false_unassigned integer := 0;
  ambiguous_count integer := 0;
  unresolved_count integer := 0;
begin
  select b.batch_id into latest_batch_id
  from public.ph_pikes_order_batches b
  where b.source_key = 'pikes'
    and b.status in ('archive_pending', 'processed')
  order by b.imported_at desc nulls last, b.batch_id desc
  limit 1;

  if latest_batch_id is null then
    return jsonb_build_object(
      'contractVersion', 1, 'hasBatch', false, 'inventoryRowCount', 0,
      'snapshotUnassignedCount', 0, 'falseUnassignedCount', 0,
      'ambiguousCount', 0, 'unresolvedCount', 0
    );
  end if;

  select
    count(*)::integer,
    count(*) filter (where nullif(btrim(coalesce(i.assignedto, '')), '') is null)::integer
  into inventory_count, snapshot_unassigned
  from public.ph_pikes_order_inventory_rows i
  where i.batch_id = latest_batch_id;

  select
    count(*) filter (where r.resolution = 'eligible')::integer,
    count(*) filter (where r.resolution = 'ambiguous')::integer,
    count(*) filter (where r.resolution in ('newer', 'no_match'))::integer
  into false_unassigned, ambiguous_count, unresolved_count
  from private.resolve_pikes_order_assignment_repair_v1(latest_batch_id) r;

  return jsonb_build_object(
    'contractVersion', 1, 'hasBatch', true,
    'inventoryRowCount', inventory_count,
    'snapshotUnassignedCount', snapshot_unassigned,
    'falseUnassignedCount', false_unassigned,
    'ambiguousCount', ambiguous_count,
    'unresolvedCount', unresolved_count
  );
end;
$$;


ALTER FUNCTION public.get_pikes_order_assignment_health_v1() OWNER TO postgres;

--
-- Name: get_po_management_health_snapshot(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_po_management_health_snapshot() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  row_count_value bigint := 0;
  latest_built_at_value timestamptz := null;
  source_authenticated_select boolean := false;
  view_authenticated_select boolean := false;
  anon_source_select boolean := false;
  anon_view_select boolean := false;
  authenticated_write_access boolean := false;
  policy_present boolean := false;
  security_invoker_enabled boolean := false;
  imp hl_order_private.po_imports; control hl_order_private.po_control;
  pdf_valid boolean := false; projection_valid boolean := false; s1_access boolean := false;
  page_count integer := 0; pdf_rows bigint := 0; expected_count bigint := 0; review_count bigint := 0;
  pending_count bigint := 0; latest_f1 text; latest_s1 text;
  authority_valid boolean := false; printed_at timestamptz;
begin
  if not private.is_service_role_request() then
    raise exception using errcode = '42501', message = 'PO_MANAGEMENT_HEALTH_FORBIDDEN';
  end if;

  with latest_scope as materialized (
    select coalesce(nullif(p.run_id, ''), p.source_file_id) as scope_key
    from public.ph_27f1_hl_po p
    where coalesce(nullif(p.run_id, ''), p.source_file_id) is not null
    order by p.imported_at desc, p.id desc
    limit 1
  )
  select
    count(*) filter (where nullif(btrim(p.item_code), '') is not null)::bigint,
    max(coalesce(p.imported_at, p.created_at))
  into row_count_value, latest_built_at_value
  from public.ph_27f1_hl_po p
  join latest_scope latest
    on coalesce(nullif(p.run_id, ''), p.source_file_id) = latest.scope_key;

  source_authenticated_select := has_table_privilege(
    'authenticated', 'public.ph_27f1_hl_po', 'SELECT'
  );
  view_authenticated_select := has_table_privilege(
    'authenticated', 'public.ph_view_po_27f1_hl', 'SELECT'
  );
  anon_source_select := has_table_privilege(
    'anon', 'public.ph_27f1_hl_po', 'SELECT'
  );
  anon_view_select := has_table_privilege(
    'anon', 'public.ph_view_po_27f1_hl', 'SELECT'
  );
  authenticated_write_access :=
    has_table_privilege('authenticated', 'public.ph_27f1_hl_po', 'INSERT')
    or has_table_privilege('authenticated', 'public.ph_27f1_hl_po', 'UPDATE')
    or has_table_privilege('authenticated', 'public.ph_27f1_hl_po', 'DELETE')
    or has_table_privilege('authenticated', 'public.ph_view_po_27f1_hl', 'INSERT')
    or has_table_privilege('authenticated', 'public.ph_view_po_27f1_hl', 'UPDATE')
    or has_table_privilege('authenticated', 'public.ph_view_po_27f1_hl', 'DELETE');

  select exists (
    select 1
    from pg_catalog.pg_policies
    where schemaname = 'public'
      and tablename = 'ph_27f1_hl_po'
      and policyname = 'ph_27f1_hl_po_manager_read'
      and cmd = 'SELECT'
      and 'authenticated' = any(roles)
  ) into policy_present;

  select coalesce(c.reloptions @> array['security_invoker=true']::text[], false)
  into security_invoker_enabled
  from pg_catalog.pg_class c
  join pg_catalog.pg_namespace n on n.oid = c.relnamespace
  where n.nspname = 'public'
    and c.relname = 'ph_view_po_27f1_hl'
    and c.relkind = 'v';


  select * into control from hl_order_private.po_control where singleton;
  select * into imp from hl_order_private.po_imports where id=control.active_import_id;
  if imp.source_format='pdf' then
    begin
      printed_at:=(imp.metadata->>'report_printed_at')::timestamptz;
    exception when invalid_datetime_format or datetime_field_overflow then printed_at:=null;
    end;
    page_count:=case when imp.metadata->>'page_count' ~ '^[1-9][0-9]{0,3}$'
      then (imp.metadata->>'page_count')::integer else 0 end;
    select count(*) into pdf_rows from hl_order_private.po_import_rows where import_id=imp.id;
    pdf_valid:=coalesce(imp.status='reconciled' and control.active_scope=imp.id::text
      and imp.reconciled_by is not null and imp.receipt_cutoff=control.receipt_cutoff
      and imp.receipt_cutoff<=imp.created_at and imp.created_at<=imp.completed_at
      and imp.completed_at<=imp.reconciled_at and imp.reconciled_at<=now()
      and imp.report_date is not null and imp.report_date<=current_date
      and nullif(btrim(imp.metadata->>'source_file_id'),'') is not null
      and nullif(btrim(imp.metadata->>'parser_version'),'') is not null
      and isfinite(printed_at) and printed_at<=imp.created_at
      and imp.report_date=(printed_at at time zone 'America/Chicago')::date
      and imp.fingerprint ~ '^[a-f0-9]{64}$' and imp.fingerprint=imp.metadata->>'fingerprint'
      and page_count>0 and pdf_rows=imp.row_count and pdf_rows>0
      and (select count(*)=page_count and min(page)=1 and max(page)=page_count
        and sum(jsonb_array_length(rows))=pdf_rows
        from hl_order_private.po_pdf_pages where import_id=imp.id),false);

    -- Compare the complete active projection with the authoritative ledger.
    -- EXCEPT ALL also detects duplicate rows and preserves zero/NULL/negative values.
    with expected as materialized (
      select itemcode,size,lot,po_ordered,imported,remaining,status
      from hl_order_private.po_balances_v2()
    ), projected as materialized (
      select item_code,size,lot,po_ordered,imported_po_remain,po_remain,run_id,source_file_id,'27.F1'::text table_lot
        from public.ph_27f1_hl_po where run_id=imp.id::text or source_file_id='pdf:'||imp.id
      union all
      select item_code,size,lot,po_ordered,imported_po_remain,po_remain,run_id,source_file_id,'27.S1'::text table_lot
        from public.ph_27s1_hl_po where run_id=imp.id::text or source_file_id='pdf:'||imp.id
    ), differences as (
      (select itemcode,size,lot,po_ordered,imported,remaining,imp.id::text,'pdf:'||imp.id,lot from expected
        except all select * from projected)
      union all
      (select * from projected except all
        select itemcode,size,lot,po_ordered,imported,remaining,imp.id::text,'pdf:'||imp.id,lot from expected)
    )
    select not exists(select 1 from differences),(select count(*) from expected),
      (select count(*) from expected where status='review')
      into projection_valid,expected_count,review_count;

    -- The presentation views still select the latest run per season. An old
    -- season must not silently remain visible when a replacement has no rows.
    select run_id into latest_f1 from public.ph_27f1_hl_po order by imported_at desc,id desc limit 1;
    select run_id into latest_s1 from public.ph_27s1_hl_po order by imported_at desc,id desc limit 1;
    projection_valid:=projection_valid and (latest_f1 is null or latest_f1=imp.id::text)
      and (latest_s1 is null or latest_s1=imp.id::text);
    s1_access:=has_table_privilege('authenticated','public.ph_27s1_hl_po','SELECT')
      and has_table_privilege('authenticated','public.ph_view_po_27s1_hl','SELECT')
      and not has_table_privilege('anon','public.ph_27s1_hl_po','SELECT')
      and not has_table_privilege('anon','public.ph_view_po_27s1_hl','SELECT')
      and not has_table_privilege('authenticated','public.ph_27s1_hl_po','INSERT,UPDATE,DELETE')
      and not has_table_privilege('authenticated','public.ph_view_po_27s1_hl','INSERT,UPDATE,DELETE')
      and exists(select 1 from pg_catalog.pg_policies where schemaname='public'
        and tablename='ph_27s1_hl_po' and policyname='ph_27s1_hl_po_manager_read' and cmd='SELECT'
        and 'authenticated'=any(roles))
      and coalesce((select reloptions @> array['security_invoker=true']::text[]
        from pg_catalog.pg_class where oid='public.ph_view_po_27s1_hl'::regclass),false);
    row_count_value:=expected_count;
    latest_built_at_value:=imp.reconciled_at;
    authority_valid:=pdf_valid;
  else
    -- A missing PDF/control must not be reclassified as a fresh legacy import.
    authority_valid:=coalesce(control.singleton and nullif(control.active_scope,'') is not null
      and (control.active_import_id is null or (imp.source_format='legacy' and imp.status='reconciled'))
      and control.active_scope=(select coalesce(nullif(run_id,''),source_file_id)
        from public.ph_27f1_hl_po order by imported_at desc,id desc limit 1)
      and not exists(select 1 from public.ph_27f1_hl_po
        where source_file_id like 'pdf:%'
          and coalesce(nullif(run_id,''),source_file_id)=control.active_scope),false);
  end if;
  select count(*) into pending_count from hl_order_private.po_imports
    where source_format='pdf' and status='pending';

  return jsonb_build_object(
    'contract_version', 'po-management-native-auth-v1',
    'row_count', row_count_value,
    'source_authority_valid', authority_valid, 'report_printed_at', printed_at,
    'source_format', coalesce(imp.source_format,'legacy'),
    'freshness_mode', case when imp.source_format='pdf' then 'manual_pdf' else 'scheduled_import' end,
    'pdf_health_contract', 'confirmed-pdf-ledger-v1',
    'pdf_report_valid', pdf_valid, 'projection_matches_ledger', projection_valid,
    'season_access_healthy', s1_access, 'pending_pdf_count', pending_count,
    'review_balance_count', review_count, 'report_date', imp.report_date,
    'latest_built_at', latest_built_at_value,
    'source_authenticated_select', source_authenticated_select,
    'view_authenticated_select', view_authenticated_select,
    'anonymous_access_denied', not anon_source_select and not anon_view_select,
    'authenticated_writes_denied', not authenticated_write_access,
    'manager_policy_present', policy_present,
    'security_invoker_enabled', security_invoker_enabled
  );
end;
$_$;


ALTER FUNCTION public.get_po_management_health_snapshot() OWNER TO postgres;

--
-- Name: FUNCTION get_po_management_health_snapshot(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.get_po_management_health_snapshot() IS 'Read-only PO health: confirmed PDF provenance and seasonal ledger parity; report age is informational for manually replaced PDFs.';


--
-- Name: get_request_capabilities(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_request_capabilities() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  profile public.profiles%rowtype;
  username_key text;
  role_key text;
  global_access boolean;
  save_access boolean;
  general_create_access boolean;
  av_create_access boolean;
  request_scope text;
begin
  profile := private.current_active_profile();
  if profile.id is null then
    raise exception using errcode = '42501', message = 'REQUEST_PROFILE_REQUIRED';
  end if;

  username_key := lower(btrim(coalesce(profile.username, '')));
  role_key := private.normalized_profile_role(profile.role);
  global_access := private.can_manage_requests();
  save_access := private.can_save_request_work();
  general_create_access := private.can_create_general_requests();
  av_create_access := private.can_create_av_requests();

  request_scope := case
    when global_access then 'global'
    when username_key in ('ben_brown', 'chance_alldredge') then 'own'
    when private.is_sales_request_role() then 'rep'
    when role_key = 'CSR' then 'created'
    when role_key like 'EVAL%' then 'eval'
    else 'role'
  end;

  return jsonb_build_object(
    'contract_version', 2,
    'username', username_key,
    'scope', request_scope,
    'can_create_general', general_create_access,
    'can_create_av', av_create_access,
    'can_view_queue', true,
    'can_take_photo', save_access,
    'can_edit', save_access,
    'can_complete', save_access,
    'can_archive', global_access
  );
end;
$$;


ALTER FUNCTION public.get_request_capabilities() OWNER TO postgres;

--
-- Name: get_request_delivery_recovery_queue(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_request_delivery_recovery_queue() RETURNS TABLE(event_id uuid, event_type text, request_id text, request_folder text, status text, attempt_count integer, next_attempt_at timestamp with time zone, first_attempt_at timestamp with time zone, last_attempt_at timestamp with time zone, lease_expires_at timestamp with time zone, sanitized_error_code text, email_delivered_at timestamp with time zone, push_delivered_at timestamp with time zone, delivery_mode text, created_at timestamp with time zone, pending_age_seconds bigint, history_snapshot jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not private.can_manage_requests() then raise exception using errcode='42501',message='REQUEST_RECOVERY_FORBIDDEN'; end if;
  return query
  select o.event_id,o.event_type,o.request_id,o.request_folder,o.status,o.attempt_count,o.next_attempt_at,o.first_attempt_at,
    o.last_attempt_at,o.lease_expires_at,o.sanitized_error_code,o.email_delivered_at,o.push_delivered_at,o.delivery_mode,
    o.created_at,extract(epoch from (now()-o.created_at))::bigint,h.snapshot
  from public.ph_request_delivery_outbox o left join public.ph_request_history h on h.unique_id=o.request_id
  where o.event_type not in ('hl_order_submission','hl_order_cancellation','bunch_note_submission')
    and (o.status in ('unknown','failed') or (o.status='pending' and o.next_attempt_at<=now()-interval '2 minutes')
      or (o.status='processing' and coalesce(o.lease_expires_at,o.last_attempt_at)<=now()))
  order by o.created_at desc;
end $$;


ALTER FUNCTION public.get_request_delivery_recovery_queue() OWNER TO postgres;

--
-- Name: get_request_drive_evidence_health_snapshot_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_request_drive_evidence_health_snapshot_v1() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  mismatch_count bigint := 0;
  checked_count bigint := 0;
  mismatch_request_ids jsonb := '[]'::jsonb;
begin
  if not private.is_service_role_request() then
    raise exception using errcode = '42501', message = 'REQUEST_DRIVE_HEALTH_FORBIDDEN';
  end if;

  with latest_completion as (
    select distinct on (history.master_id)
      history.unique_id,
      history.master_id,
      history.req_spec,
      history.req_caliper,
      history.req_match,
      history.req_pic_note,
      history.av_note,
      history.req_photo_link,
      history.req_photo_name,
      coalesce(history.date_completed, history.updated_at) as completed_at,
      master.spec as master_spec,
      master.caliper as master_caliper,
      master.match as master_match,
      master.pic_note as master_pic_note,
      master.av_note as master_av_note,
      master.photo_link as master_photo_link,
      master.photo_name as master_photo_name,
      master.av_rule_last_cleared_at,
      master.av_rule_last_clear_reason,
      master.av_rule_bundle_updated_at,
      master.av_rule_av_note_updated_at,
      master.av_rule_spec_updated_at,
      master.av_rule_match_updated_at,
      master.av_rule_caliper_updated_at,
      master.av_rule_photo_updated_at
    from public.ph_request_history history
    join public.ph_master_inventory master on master.unique_id = history.master_id
    where history.date_completed >= now() - interval '48 hours'
      and lower(btrim(coalesce(history.req_status, ''))) in ('complete','completed','done')
    order by history.master_id, history.date_completed desc nulls last, history.updated_at desc nulls last
  ), evaluated as (
    select completion.*,
      (
        (
          nullif(btrim(completion.req_spec), '') is not null
          and coalesce(btrim(completion.req_spec), '') is distinct from coalesce(btrim(completion.master_spec), '')
          and (completion.av_rule_spec_updated_at is null or completion.av_rule_spec_updated_at <= completion.completed_at)
        )
        or (
          nullif(btrim(completion.req_caliper), '') is not null
          and coalesce(btrim(completion.req_caliper), '') is distinct from coalesce(btrim(completion.master_caliper), '')
          and (completion.av_rule_caliper_updated_at is null or completion.av_rule_caliper_updated_at <= completion.completed_at)
        )
        or (
          nullif(btrim(completion.req_match), '') is not null
          and coalesce(btrim(completion.req_match), '') is distinct from coalesce(btrim(completion.master_match), '')
          and (completion.av_rule_match_updated_at is null or completion.av_rule_match_updated_at <= completion.completed_at)
        )
        or (
          nullif(btrim(completion.req_pic_note), '') is not null
          and coalesce(btrim(completion.req_pic_note), '') is distinct from coalesce(btrim(completion.master_pic_note), '')
        )
        or (
          nullif(btrim(completion.av_note), '') is not null
          and coalesce(btrim(completion.av_note), '') is distinct from coalesce(btrim(completion.master_av_note), '')
          and (completion.av_rule_av_note_updated_at is null or completion.av_rule_av_note_updated_at <= completion.completed_at)
        )
        or (
          nullif(btrim(completion.req_photo_link), '') is not null
          and coalesce(btrim(completion.req_photo_link), '') is distinct from coalesce(btrim(completion.master_photo_link), '')
          and (completion.av_rule_photo_updated_at is null or completion.av_rule_photo_updated_at <= completion.completed_at)
        )
        or (
          nullif(btrim(completion.req_photo_name), '') is not null
          and coalesce(btrim(completion.req_photo_name), '') is distinct from coalesce(btrim(completion.master_photo_name), '')
          and (completion.av_rule_photo_updated_at is null or completion.av_rule_photo_updated_at <= completion.completed_at)
        )
      )
      and (
        completion.av_rule_bundle_updated_at is null
        or completion.av_rule_bundle_updated_at <= completion.completed_at
      )
      and (completion.av_rule_last_cleared_at is null
           or completion.av_rule_last_cleared_at < completion.completed_at) as has_repairable_mismatch
    from latest_completion completion
  )
  select
    count(*),
    count(*) filter (where evaluated.has_repairable_mismatch),
    coalesce(
      jsonb_agg(to_jsonb(evaluated.unique_id) order by evaluated.completed_at, evaluated.unique_id)
        filter (where evaluated.has_repairable_mismatch and evaluated.unique_id is not null),
      '[]'::jsonb
    )
  into checked_count, mismatch_count, mismatch_request_ids
  from evaluated;

  return jsonb_build_object(
    'contract_version', 'request-drive-evidence-health-v1',
    'recent_completed_count', checked_count,
    'evidence_mismatch_count', mismatch_count,
    'mismatch_request_ids', mismatch_request_ids
  );
end
$$;


ALTER FUNCTION public.get_request_drive_evidence_health_snapshot_v1() OWNER TO postgres;

--
-- Name: FUNCTION get_request_drive_evidence_health_snapshot_v1(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.get_request_drive_evidence_health_snapshot_v1() IS 'Service-only health snapshot. Flags only non-empty completion evidence that can be repaired without superseding a shared reset or newer master-field update.';


--
-- Name: get_request_schema_compatibility(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_request_schema_compatibility() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select jsonb_build_object(
    'compatible', not exists (
      select 1
      from unnest(array[
        'app_tab_assignment', 'master_app_tab_assignment', 'request_source',
        'client_batch_id', 'updated_at', 'row_version'
      ]) required(column_name)
      where not exists (
        select 1 from information_schema.columns c
        where c.table_schema = 'public'
          and c.table_name = 'ph_active_request'
          and c.column_name = required.column_name
      )
    ),
    'contract_version', 2,
    'required_columns', jsonb_build_array(
      'app_tab_assignment', 'master_app_tab_assignment', 'request_source',
      'client_batch_id', 'updated_at', 'row_version'
    )
  )
$$;


ALTER FUNCTION public.get_request_schema_compatibility() OWNER TO postgres;

--
-- Name: get_season_sales_note_access_v1(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_season_sales_note_access_v1(p_actor_username text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor public.profiles;
  can_view boolean := false;
  can_manage boolean := false;
  allowed_usernames text[] := private.season_sales_note_allowed_usernames_v1();
  setting_row public.ph_app_settings;
begin
  select profile.* into actor
  from public.profiles profile
  where lower(btrim(profile.username)) = lower(btrim(coalesce(p_actor_username, '')))
    and profile.disabled_at is null
    and (profile.locked_until is null or profile.locked_until <= now())
    and not profile.must_change_password
  limit 1;
  if actor.id is null then
    raise exception using errcode = '42501', message = 'SEASON_SALES_PROFILE_NOT_ACTIVE';
  end if;

  select coalesce(permission.allowed, false) into can_view
  from private.get_effective_app_permissions_v1(
    actor.id, private.resolve_app_access_policy_id_v1(false)
  ) permission
  where permission.permission_key = 'module.sales-office.view'
  limit 1;

  select coalesce(permission.allowed, false) into can_manage
  from private.get_effective_app_permissions_v1(
    actor.id, private.resolve_app_access_policy_id_v1(false)
  ) permission
  where permission.permission_key = 'manager.av_blanks_bypass.manage'
  limit 1;

  select setting.* into setting_row
  from public.ph_app_settings setting
  where setting.key = 'av_blanks_photo_bypass_users'
  limit 1;

  return jsonb_build_object(
    'ok', true,
    'allowed', can_view and lower(btrim(actor.username)) = any(allowed_usernames),
    'canManage', can_manage,
    'users', to_jsonb(allowed_usernames),
    'updatedAt', setting_row.updated_at,
    'updatedBy', coalesce(setting_row.updated_by, '')
  );
end
$$;


ALTER FUNCTION public.get_season_sales_note_access_v1(p_actor_username text) OWNER TO postgres;

--
-- Name: get_season_sales_office_health_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_season_sales_office_health_v1() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with settings as (select private.season_sales_settings_v1() value), scope as (
    select upper(btrim(value->>'seasonCode')) season_code,
      private.season_sales_year_v1(value->>'salesYear') sales_year from settings
  ), counts as (
    select
      count(*) filter (where state.status = 'open') open_states,
      count(*) filter (where state.status = 'done') done_states,
      count(*) filter (where state.status = 'retired') retired_states
    from public.ph_season_sales_office_state state, scope
    where state.season_code = scope.season_code and state.sales_year = scope.sales_year
  ), mirrors as (
    select count(*) mirror_count, count(distinct upper(btrim(itemcode))) mirror_itemcodes
    from public.ph_sales_office where lower(btrim(coalesce(so_source, 'season'))) = 'season'
  )
  select jsonb_build_object('ok', true, 'openStates', counts.open_states,
    'doneStates', counts.done_states, 'retiredStates', counts.retired_states,
    'mirrorCount', mirrors.mirror_count, 'mirrorItemcodes', mirrors.mirror_itemcodes,
    'parity', counts.open_states = mirrors.mirror_count and mirrors.mirror_count = mirrors.mirror_itemcodes)
  from counts, mirrors
$$;


ALTER FUNCTION public.get_season_sales_office_health_v1() OWNER TO postgres;

--
-- Name: get_transactions_keyed_dashboard(date, text, integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_transactions_keyed_dashboard(selected_date date DEFAULT NULL::date, creator_search text DEFAULT ''::text, all_dates_offset integer DEFAULT 0, all_dates_limit integer DEFAULT 250, files_offset integer DEFAULT 0, files_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare
  safe_search text := lower(btrim(coalesce(creator_search, '')));
  safe_all_dates_offset integer := greatest(coalesce(all_dates_offset, 0), 0);
  safe_all_dates_limit integer := least(greatest(coalesce(all_dates_limit, 250), 1), 500);
  safe_files_offset integer := greatest(coalesce(files_offset, 0), 0);
  safe_files_limit integer := least(greatest(coalesce(files_limit, 50), 1), 100);
  effective_date date;
  summary_json jsonb;
  available_dates_json jsonb;
  date_metrics_json jsonb;
  all_dates_json jsonb;
  files_json jsonb;
  all_dates_total bigint;
  files_total bigint;
begin
  if not private.can_view_transactions_keyed() then
    raise exception using errcode = '42501', message = 'TRANSACTIONS_KEYED_FORBIDDEN';
  end if;

  select max(r.transaction_business_date)
  into effective_date
  from public.ph_transactions_keyed_rows r
  join public.ph_transactions_keyed_files f
    on f.drive_file_id = r.drive_file_id
   and f.content_sha256 = r.content_sha256
  where f.status = 'processed'
    and f.duplicate_of_drive_file_id is null;

  effective_date := coalesce(selected_date, effective_date);

  select jsonb_build_object(
    'canonicalFiles', count(distinct f.drive_file_id) filter (where f.status = 'processed' and f.duplicate_of_drive_file_id is null),
    'duplicateFiles', (select count(*) from public.ph_transactions_keyed_files df where df.status = 'duplicate'),
    'totalRows', count(r.drive_file_id),
    'firstTransactionDate', min(r.transaction_business_date),
    'lastTransactionDate', max(r.transaction_business_date),
    'distinctCreators', count(distinct nullif(r.created_by_key, '')),
    'excludedRows', count(*) filter (where r.transaction_business_date is null or r.created_by_key = ''),
    'selectedDate', effective_date
  )
  into summary_json
  from public.ph_transactions_keyed_files f
  left join public.ph_transactions_keyed_rows r
    on r.drive_file_id = f.drive_file_id
   and r.content_sha256 = f.content_sha256
  where f.status = 'processed'
    and f.duplicate_of_drive_file_id is null;

  select coalesce(jsonb_agg(to_jsonb(d) order by d.transaction_date desc), '[]'::jsonb)
  into available_dates_json
  from (
    select r.transaction_business_date as transaction_date, count(*)::bigint as row_count
    from public.ph_transactions_keyed_rows r
    join public.ph_transactions_keyed_files f
      on f.drive_file_id = r.drive_file_id and f.content_sha256 = r.content_sha256
    where f.status = 'processed'
      and f.duplicate_of_drive_file_id is null
      and r.transaction_business_date is not null
    group by r.transaction_business_date
  ) d;

  with canonical_rows as materialized (
    select r.*
    from public.ph_transactions_keyed_rows r
    join public.ph_transactions_keyed_files f
      on f.drive_file_id = r.drive_file_id and f.content_sha256 = r.content_sha256
    where f.status = 'processed' and f.duplicate_of_drive_file_id is null
      and r.created_by_key <> ''
  ), historical as (
    select created_by_key, max(btrim(created_by_detail)) as display_name, count(*)::bigint as historical_count
    from canonical_rows
    group by created_by_key
  ), historical_total as (
    select count(*)::numeric as total_count from canonical_rows
  ), daily as (
    select created_by_key, max(btrim(created_by_detail)) as display_name, count(*)::bigint as day_count
    from canonical_rows
    where transaction_business_date = effective_date
    group by created_by_key
  ), daily_total as (
    select coalesce(sum(day_count), 0)::numeric as total_count from daily
  )
  select coalesce(jsonb_agg(to_jsonb(metric) order by metric.day_count desc, metric.display_name), '[]'::jsonb)
  into date_metrics_json
  from (
    select
      d.created_by_key,
      d.display_name,
      d.day_count,
      case when dt.total_count > 0 then round((d.day_count::numeric / dt.total_count) * 100, 2) else 0 end as day_percentage,
      h.historical_count,
      case when ht.total_count > 0 then round((h.historical_count::numeric / ht.total_count) * 100, 2) else 0 end as historical_percentage
    from daily d
    join historical h using (created_by_key)
    cross join daily_total dt
    cross join historical_total ht
    where safe_search = '' or strpos(d.created_by_key, safe_search) > 0
  ) metric;

  with canonical_rows as materialized (
    select r.*
    from public.ph_transactions_keyed_rows r
    join public.ph_transactions_keyed_files f
      on f.drive_file_id = r.drive_file_id and f.content_sha256 = r.content_sha256
    where f.status = 'processed' and f.duplicate_of_drive_file_id is null
      and r.transaction_business_date is not null and r.created_by_key <> ''
  ), daily as (
    select
      transaction_business_date as transaction_date,
      created_by_key,
      max(btrim(created_by_detail)) as display_name,
      count(*)::bigint as day_count
    from canonical_rows
    group by transaction_business_date, created_by_key
  ), daily_with_total as (
    select d.*, sum(d.day_count) over (partition by d.transaction_date)::numeric as day_total
    from daily d
  ), historical as (
    select created_by_key, count(*)::bigint as historical_count
    from canonical_rows
    group by created_by_key
  ), historical_total as (
    select count(*)::numeric as total_count from canonical_rows
  ), filtered as (
    select
      d.transaction_date,
      d.created_by_key,
      d.display_name,
      d.day_count,
      round((d.day_count::numeric / nullif(d.day_total, 0)) * 100, 2) as day_percentage,
      h.historical_count,
      round((h.historical_count::numeric / nullif(ht.total_count, 0)) * 100, 2) as historical_percentage
    from daily_with_total d
    join historical h using (created_by_key)
    cross join historical_total ht
    where safe_search = '' or strpos(d.created_by_key, safe_search) > 0
  ), paged as (
    select * from filtered
    order by transaction_date desc, day_count desc, display_name
    offset safe_all_dates_offset limit safe_all_dates_limit
  )
  select
    (select count(*) from filtered),
    coalesce((select jsonb_agg(to_jsonb(p) order by p.transaction_date desc, p.day_count desc, p.display_name) from paged p), '[]'::jsonb)
  into all_dates_total, all_dates_json;

  with file_rows as (
    select
      f.drive_file_id,
      f.file_name,
      f.row_count,
      f.first_transaction_date,
      f.last_transaction_date,
      f.status,
      f.duplicate_of_drive_file_id,
      canonical.file_name as duplicate_of_file_name,
      f.imported_at,
      f.archived_at
    from public.ph_transactions_keyed_files f
    left join public.ph_transactions_keyed_files canonical
      on canonical.drive_file_id = f.duplicate_of_drive_file_id
    where f.status in ('processed', 'duplicate')
  ), paged as (
    select * from file_rows
    order by coalesce(archived_at, imported_at) desc, file_name
    offset safe_files_offset limit safe_files_limit
  )
  select
    (select count(*) from file_rows),
    coalesce((select jsonb_agg(to_jsonb(p) order by coalesce(p.archived_at, p.imported_at) desc, p.file_name) from paged p), '[]'::jsonb)
  into files_total, files_json;

  return jsonb_build_object(
    'summary', coalesce(summary_json, '{}'::jsonb),
    'availableDates', coalesce(available_dates_json, '[]'::jsonb),
    'dateMetrics', coalesce(date_metrics_json, '[]'::jsonb),
    'allDates', coalesce(all_dates_json, '[]'::jsonb),
    'allDatesTotal', coalesce(all_dates_total, 0),
    'allDatesHasMore', coalesce(all_dates_total, 0) > safe_all_dates_offset + safe_all_dates_limit,
    'files', coalesce(files_json, '[]'::jsonb),
    'filesTotal', coalesce(files_total, 0),
    'filesHasMore', coalesce(files_total, 0) > safe_files_offset + safe_files_limit
  );
end;
$$;


ALTER FUNCTION public.get_transactions_keyed_dashboard(selected_date date, creator_search text, all_dates_offset integer, all_dates_limit integer, files_offset integer, files_limit integer) OWNER TO postgres;

--
-- Name: get_v2_crop_roll_completion_master_ids(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_v2_crop_roll_completion_master_ids(row_data jsonb) RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'extensions', 'private', 'vault', 'pg_temp'
    AS $$
  with candidates(raw_id) as (
    values
      (row_data->>'master_unique_id'),
      (row_data->>'MASTER_UNIQUE_ID'),
      (row_data->>'unique_id'),
      (row_data->>'UNIQUE_ID'),
      (row_data->>'source_unique_id'),
      (row_data->>'SOURCE_UNIQUE_ID'),
      (row_data #>> '{metadata,master_unique_id}'),
      (row_data #>> '{metadata,unique_id}'),
      (row_data #>> '{metadata,source_unique_id}'),
      (row_data #>> '{metadata,crop_roll_form_values,master_unique_id}'),
      (row_data #>> '{metadata,crop_roll_form_values,unique_id}'),
      (row_data #>> '{snapshot,master_unique_id}'),
      (row_data #>> '{snapshot,unique_id}'),
      (row_data->>'row_id'),
      (case
        when btrim(coalesce(row_data->>'row_id', '')) like '%:%'
          then regexp_replace(btrim(row_data->>'row_id'), '^.*:', '')
        else null
      end)
  )
  select coalesce(array_agg(distinct cleaned), array[]::text[])
  from (
    select nullif(btrim(coalesce(raw_id, '')), '') as cleaned
    from candidates
  ) normalized
  where cleaned is not null
$$;


ALTER FUNCTION public.get_v2_crop_roll_completion_master_ids(row_data jsonb) OWNER TO postgres;

--
-- Name: get_v2_crop_roll_completion_view(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_v2_crop_roll_completion_view(row_data jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'extensions', 'private', 'vault', 'pg_temp'
    AS $$
  select case
    when lower(coalesce(
      row_data #>> '{metadata,completion_source_view}',
      row_data #>> '{metadata,crop_roll_source_view}',
      row_data->>'completion_source_view',
      row_data->>'crop_roll_source_view',
      ''
    )) in ('carryover', 'carry-over', 'co')
      then 'carryover'
    when lower(coalesce(
      row_data #>> '{metadata,completion_source_view}',
      row_data #>> '{metadata,crop_roll_source_view}',
      row_data->>'completion_source_view',
      row_data->>'crop_roll_source_view',
      ''
    )) in ('sy27', 'sy-27', 'sy 27')
      then 'sy27'
    else public.get_v2_crop_roll_drive_view(row_data)
  end
$$;


ALTER FUNCTION public.get_v2_crop_roll_completion_view(row_data jsonb) OWNER TO postgres;

--
-- Name: get_v2_crop_roll_drive_view(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_v2_crop_roll_drive_view(row_data jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'extensions', 'private', 'vault', 'pg_temp'
    AS $$
  select case
    when coalesce(row_data->>'saleyear', row_data->>'salesyear', row_data->>'sale_year', row_data->>'sales_year', '') like '%27%'
      then 'sy27'
    when coalesce(row_data->>'saleyear', row_data->>'salesyear', row_data->>'sale_year', row_data->>'sales_year', '') like '%26%'
      and coalesce(row_data->>'desigitem', row_data->>'desig_item', '') like '%=%'
      then 'sy27'
    else 'carryover'
  end
$$;


ALTER FUNCTION public.get_v2_crop_roll_drive_view(row_data jsonb) OWNER TO postgres;

