-- Name: notify_new_assignment(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.notify_new_assignment() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'private', 'vault', 'pg_temp'
    AS $$
BEGIN
  IF NEW.assignedto != OLD.assignedto AND NEW.assignedto IS NOT NULL THEN
      PERFORM send_onesignal_push(NEW.assignedto, 'You have been assigned a new task: ' || NEW.commonname);
  END IF;
  RETURN NEW;
END;
$$;


