--
-- Name: photo_history_gallery_v1(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.photo_history_gallery_v1(p_actor_id uuid, p_operation text, p_input jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET statement_timeout TO '12s'
    AS $_$
declare
  result jsonb; photos jsonb; recipient record; asset public.ph_photo_history_assets%rowtype;
  saved public.ph_photo_history_shares%rowtype; ev public.ph_request_delivery_outbox%rowtype;
  ids uuid[]; token text; fingerprint text; share_id uuid; event_id uuid;
  required_copies jsonb; recipient_emails jsonb; actor_username text;
  q text; page_size integer; cursor_at timestamptz; cursor_id uuid; as_of timestamptz;
begin
  actor_username := private.photo_history_require_actor_v1(p_actor_id);
  if p_operation='search' then
    q:=regexp_replace(lower(left(btrim(coalesce(p_input->>'q','')),120)),'[^a-z0-9]','','g');
    page_size:=least(48,greatest(1,coalesce((p_input->>'limit')::int,36)));
    cursor_at:=nullif(p_input#>>'{cursor,at}','')::timestamptz;
    cursor_id:=nullif(p_input#>>'{cursor,id}','')::uuid;
    as_of:=coalesce(nullif(p_input->>'asOf','')::timestamptz,now());
    with matches as (
      select a.* from public.ph_photo_history_assets a
      where a.photo_at<=as_of and (a.storage_available or a.drive_file_id is not null)
        and (q='' or a.search_text like '%'||q||'%')
        and (nullif(p_input->>'from','') is null or a.photo_at >= (p_input->>'from')::date)
        and (nullif(p_input->>'to','') is null or a.photo_at < (p_input->>'to')::date+interval '1 day')
        and (coalesce(p_input->>'container','')='' or exists(select 1 from jsonb_array_elements(a.contexts)c
             where lower(c->>'contsize')=lower(p_input->>'container')))
        and (coalesce(p_input->>'location','')='' or exists(select 1 from jsonb_array_elements(a.contexts)c
             where upper(c->>'locationcode')=upper(p_input->>'location')))
        and (coalesce(p_input->>'lot','')='' or exists(select 1 from jsonb_array_elements(a.contexts)c
             where upper(c->>'lotcode')=upper(p_input->>'lot')))
        and (cursor_at is null or (a.photo_at,a.id)<(cursor_at,cursor_id))
      order by a.photo_at desc,a.id desc limit page_size+1
    )
    select jsonb_build_object('ok',true,'asOf',as_of,'hasMore',count(*)>page_size,
      'photos',coalesce((select jsonb_agg(to_jsonb(p) order by p.photo_at desc,p.id desc) from
        (select id,filename,photo_at,itemcode,commonname,contsize,locationcode,lotcode,contexts,bucket,path,storage_available
          from matches order by photo_at desc,id desc limit page_size)p),'[]'),
      'indexedAt',(select refreshed_at from public.ph_photo_history_index_state)) into result from matches;
    return result;
  elsif p_operation='recipients' then
    select jsonb_build_object('ok',true,'recipients',coalesce(jsonb_agg(jsonb_build_object('id',p.id,'name',
      coalesce(nullif(p.display_name,''),p.username)) order by p.display_name,p.username),'[]')) into result
    from public.profiles p join auth.users u on u.id=p.id
    where lower(regexp_replace(p.role,'^[[:space:]]+|[[:space:]]+$','','g')) in ('rep','salesrep','sales rep') and p.disabled_at is null and not p.must_change_password
      and (p.locked_until is null or p.locked_until<=now()) and u.email_confirmed_at is not null
      and btrim(coalesce(u.email,'')) ~* '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$';
    return result;
  elsif p_operation='asset' then
    select * into asset from public.ph_photo_history_assets where id=(p_input->>'id')::uuid;
    if not found then raise exception 'PHOTO_HISTORY_ASSET_UNAVAILABLE'; end if;
    return jsonb_build_object('ok',true,'asset',to_jsonb(asset));
  elsif p_operation='send' then
    token:=btrim(coalesce(p_input->>'idempotencyKey',''));
    if length(token)<16 or length(token)>160 then raise exception 'PHOTO_HISTORY_TOKEN_INVALID'; end if;
    if jsonb_typeof(p_input->'ids') is distinct from 'array' or jsonb_array_length(p_input->'ids') not between 1 and 20
      or length(coalesce(p_input->>'message',''))>2000 then raise exception 'PHOTO_HISTORY_SELECTION_INVALID'; end if;
    select array_agg(distinct x::uuid order by x::uuid) into ids from jsonb_array_elements_text(p_input->'ids')x;
    fingerprint:=encode(extensions.digest(jsonb_build_object('ids',ids,'rep',p_input->>'recipientId','message',coalesce(p_input->>'message',''))::text,'sha256'),'hex');
    if not pg_try_advisory_xact_lock(hashtextextended('photo-history-send:'||p_actor_id||':'||token,0)) then
      return jsonb_build_object('ok',false,'code','PHOTO_HISTORY_BUSY'); end if;
    select * into saved from public.ph_photo_history_shares where actor_id=p_actor_id and idempotency_key=token;
    if found then
      if saved.fingerprint<>fingerprint then raise exception 'PHOTO_HISTORY_TOKEN_CONFLICT'; end if;
      return jsonb_build_object('ok',true,'id',saved.id,'duplicate',true);
    end if;
    select p.id,coalesce(nullif(p.display_name,''),p.username) name,lower(btrim(u.email)) email into recipient
    from public.profiles p join auth.users u on u.id=p.id where p.id=(p_input->>'recipientId')::uuid
      and lower(regexp_replace(p.role,'^[[:space:]]+|[[:space:]]+$','','g')) in ('rep','salesrep','sales rep') and p.disabled_at is null and not p.must_change_password
      and (p.locked_until is null or p.locked_until<=now()) and u.email_confirmed_at is not null
      and btrim(coalesce(u.email,'')) ~* '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$';
    if recipient.id is null then raise exception 'PHOTO_HISTORY_RECIPIENT_UNAVAILABLE'; end if;
    -- Required copies are resolved from verified active profiles, never browser addresses.
    select jsonb_agg(jsonb_build_object('username',lower(btrim(p.username)),'email',lower(btrim(u.email)))
      order by lower(btrim(p.username))) into required_copies
    from public.profiles p join auth.users u on u.id=p.id
    where lower(btrim(p.username)) in ('dylan_collyge','jd_jones')
      and p.disabled_at is null and not p.must_change_password
      and (p.locked_until is null or p.locked_until<=now()) and u.email_confirmed_at is not null
      and btrim(coalesce(u.email,'')) ~* '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$';
    if coalesce(jsonb_array_length(required_copies),0)<>2 then
      raise exception 'PHOTO_HISTORY_REQUIRED_COPY_UNAVAILABLE';
    end if;
    select jsonb_agg(email order by email) into recipient_emails from (
      select recipient.email as email union select c->>'email' from jsonb_array_elements(required_copies)c
    ) recipients;
    -- Freeze the authoritative catalog references, never browser URLs or recipient addresses.
    select jsonb_agg(jsonb_build_object('id',a.id,'bucket',a.bucket,'path',a.path,'filename',a.filename,
      'date',a.photo_at,'commonname',a.commonname,'itemcode',a.itemcode,'contsize',a.contsize,
      'locationcode',a.locationcode,'lotcode',a.lotcode,'storageAvailable',a.storage_available,'driveFileId',a.drive_file_id)
      order by a.photo_at desc,a.id desc) into photos from public.ph_photo_history_assets a
    where a.id=any(ids) and (a.storage_available or a.drive_file_id is not null);
    if coalesce(jsonb_array_length(photos),0)<>cardinality(ids) then raise exception 'PHOTO_HISTORY_ASSET_UNAVAILABLE'; end if;
    share_id:=gen_random_uuid();
    insert into public.ph_request_delivery_outbox(event_key,event_type,payload)
    values('photo-history:'||share_id,'photo_history_share',jsonb_build_object('contractVersion','photo-history-share-v2',
      'shareId',share_id,'actorUsername',actor_username,'recipientEmails',recipient_emails,
      'selectedRecipientEmail',recipient.email,'requiredCopies',required_copies,
      'recipientName',recipient.name,'message',coalesce(p_input->>'message',''),'photos',photos)) returning ph_request_delivery_outbox.event_id into event_id;
    insert into public.ph_photo_history_shares(id,actor_id,idempotency_key,fingerprint,event_id,photo_count,recipient_name)
      values(share_id,p_actor_id,token,fingerprint,event_id,cardinality(ids),recipient.name);
    insert into public.ph_photo_history_audit(share_id,event) values(share_id,'created');
    return jsonb_build_object('ok',true,'id',share_id,'duplicate',false);
  elsif p_operation in ('status','retry','dismiss') then
    if p_operation<>'status' then
      select * into saved from public.ph_photo_history_shares where id=(p_input->>'id')::uuid and actor_id=p_actor_id for update;
      if not found then raise exception 'PHOTO_HISTORY_SHARE_MISSING'; end if;
      select * into ev from public.ph_request_delivery_outbox where ph_request_delivery_outbox.event_id=saved.event_id for update;
      if p_operation='retry' then
        if ev.status='delivered' or ev.email_delivered_at is not null then return jsonb_build_object('ok',true,'status','delivered'); end if;
        if ev.status not in ('failed','unknown') then return jsonb_build_object('ok',true,'status',ev.status); end if;
        update public.ph_request_delivery_outbox set status='pending',next_attempt_at=now(),sanitized_error_code=null,
          lease_token=null,lease_owner=null,lease_expires_at=null where ph_request_delivery_outbox.event_id=saved.event_id;
        insert into public.ph_photo_history_audit(share_id,event) values(saved.id,'retry');
      else
        if ev.status not in ('delivered','failed','unknown') then raise exception 'PHOTO_HISTORY_NOT_TERMINAL'; end if;
        update public.ph_photo_history_shares set dismissed_at=now() where id=saved.id;
        insert into public.ph_photo_history_audit(share_id,event) values(saved.id,'dismissed');
      end if;
    end if;
    select jsonb_build_object('ok',true,'shares',coalesce(jsonb_agg(to_jsonb(s) order by s.created_at desc),'[]')) into result from
      (select h.id,h.created_at,h.photo_count,h.recipient_name,
        case when o.payload->>'contractVersion'='photo-history-share-v2' then jsonb_build_array('dylan_collyge','jd_jones') else '[]'::jsonb end as copied_usernames,
        o.status,(o.email_delivered_at is not null or o.status='delivered') delivered
      from public.ph_photo_history_shares h join public.ph_request_delivery_outbox o on o.event_id=h.event_id
      where h.actor_id=p_actor_id and h.dismissed_at is null order by h.created_at desc limit 40)s;
    return result;
  end if;
  raise exception 'PHOTO_HISTORY_OPERATION_INVALID';
end $_$;


ALTER FUNCTION public.photo_history_gallery_v1(p_actor_id uuid, p_operation text, p_input jsonb) OWNER TO postgres;

--
-- Name: prepare_eval_item_low_stock_file_v1(uuid, text, text, text, date, timestamp with time zone, text, text, bigint, text, integer, integer, jsonb, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.prepare_eval_item_low_stock_file_v1(p_run_id uuid, p_drive_file_id text, p_source_revision text, p_file_name text, p_source_report_date date, p_snapshot_at timestamp with time zone, p_source_date_method text, p_content_sha256 text, p_content_bytes bigint, p_source_sheet_name text, p_source_row_count integer, p_expected_row_count integer, p_exclusion_counts jsonb, p_disposition text DEFAULT 'eligible'::text, p_exclusion_reason text DEFAULT NULL::text, p_source_created_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  run_status text;
  expected_version boolean;
  version_row private.ph_eval_item_low_stock_file_versions%rowtype;
begin
  select status into run_status
  from private.ph_eval_item_low_stock_import_runs
  where run_id = p_run_id;
  if run_status is null or run_status <> 'building' then
    raise exception using errcode = '55000', message = 'LOW_STOCK_IMPORT_RUN_NOT_BUILDING';
  end if;
  perform 1 from private.ph_eval_item_low_stock_import_state s
    where s.singleton and s.pending_run_id = p_run_id
    for update;
  if not found then
    raise exception using errcode = '55000', message = 'LOW_STOCK_IMPORT_RUN_SUPERSEDED';
  end if;
  if nullif(btrim(coalesce(p_drive_file_id, '')), '') is null
     or nullif(btrim(coalesce(p_source_revision, '')), '') is null
     or nullif(btrim(coalesce(p_file_name, '')), '') is null
     or p_source_report_date is null
     or p_snapshot_at is null
     or p_source_date_method not in (
       'filename_timestamp', 'filename_date_sequence', 'filename_date',
       'filename_date_inferred_year', 'filename_date_creation_clock',
       'filename_date_inferred_year_creation_clock', 'creation_time_fallback'
     )
     or coalesce(p_content_sha256, '') !~ '^[0-9a-f]{64}$'
     or p_content_bytes is null or p_content_bytes < 0
     or p_source_row_count is null or p_source_row_count < 0
     or p_expected_row_count is null or p_expected_row_count < 0
     or p_source_row_count < p_expected_row_count
     or jsonb_typeof(p_exclusion_counts) <> 'object'
     or p_disposition not in ('eligible', 'excluded')
     or (p_disposition = 'excluded' and (
       p_expected_row_count <> 0
       or nullif(btrim(coalesce(p_exclusion_reason, '')), '') not in ('non_soc_reserves', 'non_soc_drivearound_mc')
     ))
     or (p_disposition = 'eligible' and nullif(btrim(coalesce(p_source_sheet_name, '')), '') is null) then
    raise exception using errcode = '22023', message = 'LOW_STOCK_IMPORT_FILE_INVALID';
  end if;
  select exists (
    select 1 from private.ph_eval_item_low_stock_run_files r
    where r.run_id = p_run_id
      and r.drive_file_id = btrim(p_drive_file_id)
      and r.source_revision = btrim(p_source_revision)
  ) into expected_version;
  if not expected_version then
    raise exception using errcode = '22023', message = 'LOW_STOCK_IMPORT_FILE_NOT_IN_MANIFEST';
  end if;

  insert into private.ph_eval_item_low_stock_file_versions(
    drive_file_id, source_revision, file_name, source_report_date, snapshot_at,
    source_created_at, source_date_method, content_sha256, content_bytes, source_sheet_name,
    source_row_count, expected_row_count, exclusion_counts, disposition, exclusion_reason
  ) values (
    btrim(p_drive_file_id), btrim(p_source_revision), btrim(p_file_name), p_source_report_date, p_snapshot_at, p_source_created_at,
    p_source_date_method, p_content_sha256, p_content_bytes, nullif(btrim(p_source_sheet_name), ''),
    p_source_row_count, p_expected_row_count, p_exclusion_counts, p_disposition, nullif(btrim(p_exclusion_reason), '')
  ) on conflict (drive_file_id, source_revision) do nothing;

  select * into version_row
  from private.ph_eval_item_low_stock_file_versions v
  where v.drive_file_id = btrim(p_drive_file_id)
    and v.source_revision = btrim(p_source_revision)
  for update;

  if version_row.content_sha256 <> p_content_sha256
     or version_row.file_name <> btrim(p_file_name)
     or version_row.source_report_date <> p_source_report_date
     or version_row.snapshot_at <> p_snapshot_at
     or version_row.source_created_at is distinct from p_source_created_at
     or version_row.source_date_method <> p_source_date_method
     or version_row.content_bytes <> p_content_bytes
     or version_row.source_row_count <> p_source_row_count
     or version_row.expected_row_count <> p_expected_row_count
     or version_row.exclusion_counts <> p_exclusion_counts
     or version_row.disposition <> p_disposition
     or version_row.exclusion_reason is distinct from nullif(btrim(p_exclusion_reason), '') then
    raise exception using errcode = '22023', message = 'LOW_STOCK_IMPORT_REVISION_METADATA_CHANGED';
  end if;
  if version_row.status = 'finalized' then
    update private.ph_eval_item_low_stock_run_files
    set file_version_id = version_row.file_version_id
    where run_id = p_run_id and drive_file_id = btrim(p_drive_file_id);
  end if;
  return jsonb_build_object(
    'file_version_id', version_row.file_version_id,
    'status', case when version_row.status = 'finalized' then 'complete' else 'staging' end,
    'already_complete', version_row.status = 'finalized',
    'last_staged_row_number', coalesce((
      select max(r.source_row_number)
      from private.ph_eval_item_low_stock_order_rows r
      where r.file_version_id = version_row.file_version_id
    ), 0)
  );
end
$_$;


ALTER FUNCTION public.prepare_eval_item_low_stock_file_v1(p_run_id uuid, p_drive_file_id text, p_source_revision text, p_file_name text, p_source_report_date date, p_snapshot_at timestamp with time zone, p_source_date_method text, p_content_sha256 text, p_content_bytes bigint, p_source_sheet_name text, p_source_row_count integer, p_expected_row_count integer, p_exclusion_counts jsonb, p_disposition text, p_exclusion_reason text, p_source_created_at timestamp with time zone) OWNER TO postgres;

--
-- Name: prepare_manager_order_import_v2(text, text, text, text, bigint, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.prepare_manager_order_import_v2(p_source_key text, p_drive_file_id text, p_file_name text, p_content_sha256 text, p_content_bytes bigint, p_batch_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
declare
  safe_source_key text := lower(btrim(coalesce(p_source_key, '')));
  existing public.ph_pikes_order_batches%rowtype;
  prepared public.ph_pikes_order_batches%rowtype;
begin
  if safe_source_key not in ('pikes', 'stine_lumber') then
    raise exception 'MANAGER_ORDER_SOURCE_INVALID';
  end if;
  if btrim(coalesce(p_drive_file_id, '')) = ''
     or btrim(coalesce(p_file_name, '')) = ''
     or coalesce(p_content_sha256, '') !~ '^[0-9a-f]{64}$'
     or p_batch_id is null then
    raise exception 'MANAGER_ORDER_IMPORT_INVALID_FILE';
  end if;

  select * into existing
  from public.ph_pikes_order_batches b
  where b.drive_file_id = p_drive_file_id
  for update;

  if found then
    if existing.source_key <> safe_source_key then
      raise exception 'MANAGER_ORDER_FILE_SOURCE_MISMATCH';
    end if;
    if existing.content_sha256 <> p_content_sha256 then
      raise exception 'MANAGER_ORDER_FILE_ID_CHANGED';
    end if;
    if existing.status = 'failed' then
      delete from public.ph_pikes_order_inventory_rows where batch_id = existing.batch_id;
      delete from public.ph_pikes_order_source_rows where batch_id = existing.batch_id;
      update public.ph_pikes_order_batches
      set status = 'importing',
          file_name = btrim(p_file_name),
          content_bytes = p_content_bytes,
          source_sheet_name = null,
          source_header_row = null,
          source_row_count = 0,
          distinct_item_count = 0,
          matched_item_count = 0,
          unmatched_item_count = 0,
          inventory_row_count = 0,
          last_error_code = null,
          updated_at = now()
      where drive_file_id = p_drive_file_id
      returning * into existing;
    end if;
    return jsonb_build_object(
      'status', existing.status,
      'batchId', existing.batch_id,
      'rowCount', existing.source_row_count,
      'displayName', existing.display_name,
      'sourceKey', existing.source_key
    );
  end if;

  insert into public.ph_pikes_order_batches (
    batch_id, drive_file_id, source_key, file_name, content_sha256, content_bytes
  ) values (
    p_batch_id, btrim(p_drive_file_id), safe_source_key,
    btrim(p_file_name), p_content_sha256, p_content_bytes
  ) returning * into prepared;

  return jsonb_build_object(
    'status', prepared.status,
    'batchId', prepared.batch_id,
    'rowCount', 0,
    'sourceKey', prepared.source_key
  );
end;
$_$;


ALTER FUNCTION public.prepare_manager_order_import_v2(p_source_key text, p_drive_file_id text, p_file_name text, p_content_sha256 text, p_content_bytes bigint, p_batch_id uuid) OWNER TO postgres;

--
-- Name: prepare_password_change_profile(text, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.prepare_password_change_profile(p_username text, p_auth_user_id uuid DEFAULT NULL::uuid, p_password_fingerprint text DEFAULT NULL::text) RETURNS TABLE(status text, attempt_id uuid, profile_id uuid, legacy_user_id integer, username text, display_name text, role text, division text, language text, must_change_password boolean, locked_until timestamp with time zone, disabled_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_username text := '';
  v_input_username text := '';
  v_auth_user_id uuid := p_auth_user_id;
  v_auth_count integer := 0;
  v_auth_candidate_id uuid;
  v_profile_candidate_id uuid;
  v_auth_identity_count integer := 0;
  v_auth_identity_username text;
  v_has_trusted_metadata boolean := false;
  v_email_confirmed_at timestamptz;
  v_banned_until timestamptz;
  v_legacy_id integer;
  v_legacy public.ph_app_users%rowtype;
  v_profile public.profiles%rowtype;
  v_has_profile boolean := false;
  v_forced boolean := false;
  v_attempt private.password_change_attempts%rowtype;
  v_existing_pending boolean := false;
  v_existing_completed boolean := false;
  v_fingerprint text := lower(coalesce(p_password_fingerprint, ''));
begin
  if v_fingerprint !~ '^[0-9a-f]{64}$' then
    raise exception using errcode = '22023', message = 'password_change_fingerprint_required';
  end if;

  v_input_username := private.password_change_username_v1(p_username);

  -- A legacy-only signed session provides its already verified username. A
  -- native session may omit it when the profile is missing; derive identity
  -- only from Auth email/app_metadata, never raw_user_meta_data.
  if v_auth_user_id is null then
    v_username := v_input_username;
    if v_username = '' then
      raise exception using errcode = '22023', message = 'password_change_username_required';
    end if;
  else
    select count(distinct i.username), min(i.username), bool_or(i.trusted_metadata),
        max(i.email_confirmed_at), max(i.banned_until)
      into v_auth_identity_count, v_username, v_has_trusted_metadata,
        v_email_confirmed_at, v_banned_until
    from private.password_change_auth_identity_v1(v_auth_user_id) i;
    if v_auth_identity_count <> 1
       or (v_input_username <> '' and v_input_username <> v_username) then
      raise exception using errcode = '23514', message = 'password_change_auth_identity_conflict';
    end if;
    if not v_has_trusted_metadata and v_email_confirmed_at is null then
      raise exception using errcode = '23514', message = 'password_change_unconfirmed_auth_alias';
    end if;
    if v_banned_until is not null and v_banned_until > now() then
      raise exception using errcode = '42501', message = 'password_change_inactive_account';
    end if;
  end if;

  if v_username = '' then
    raise exception using errcode = '22023', message = 'password_change_username_required';
  end if;

  -- Serialize account resolution, profile repair, and pending-intent changes.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('password-change-profile:' || v_username, 0)
  );

  select count(*)::integer, min(u.id)
    into v_auth_count, v_legacy_id
  from public.ph_app_users u
  where private.password_change_username_v1(u.username) = v_username;
  if v_auth_count = 0 then
    raise exception using errcode = 'P0002', message = 'password_change_legacy_user_missing';
  elsif v_auth_count <> 1 then
    raise exception using errcode = '21000', message = 'password_change_duplicate_legacy_username';
  end if;

  select u.* into v_legacy
  from public.ph_app_users u
  where u.id = v_legacy_id
  for update;
  if v_legacy.disabled_at is not null
     or (v_legacy.locked_until is not null and v_legacy.locked_until > now()) then
    raise exception using errcode = '42501', message = 'password_change_inactive_account';
  end if;
  v_forced := coalesce(v_legacy.must_change_password, false)
    or upper(regexp_replace(coalesce(v_legacy.password, ''), '\s+', '', 'g'))
      in ('GREENLEAF25', '1234', '12345', 'WELCOME', 'PASSWORD');

  if v_auth_user_id is null then
    -- Existing profile links and canonical/trusted Auth metadata are separate
    -- identity sources. If both exist they must identify the same UUID.
    select count(*)::integer into v_auth_count
    from public.profiles p
    where private.password_change_username_v1(p.username) = v_username
       or p.legacy_user_id = v_legacy.id;
    if v_auth_count > 1 then
      raise exception using errcode = '23505', message = 'password_change_profile_link_conflict';
    elsif v_auth_count = 1 then
      select p.id into v_profile_candidate_id
      from public.profiles p
      where private.password_change_username_v1(p.username) = v_username
         or p.legacy_user_id = v_legacy.id;
    end if;

    select count(distinct u.id)::integer,
        (array_agg(distinct u.id order by u.id))[1]
      into v_auth_count, v_auth_candidate_id
    from auth.users u
    where (lower(split_part(coalesce(u.email, ''), '@', 2)) = 'greenleafnursery.com'
       and private.password_change_username_v1(split_part(coalesce(u.email, ''), '@', 1)) = v_username)
       or private.password_change_username_v1(u.raw_app_meta_data->>'username') = v_username
       or u.raw_app_meta_data->>'legacy_user_id' = v_legacy_id::text;
    if v_auth_count > 1 then
      raise exception using errcode = '21000', message = 'password_change_auth_identity_conflict';
    end if;
    if v_profile_candidate_id is not null and v_auth_candidate_id is not null
       and v_profile_candidate_id <> v_auth_candidate_id then
      raise exception using errcode = '23514', message = 'password_change_auth_identity_conflict';
    end if;
    v_auth_user_id := coalesce(v_profile_candidate_id, v_auth_candidate_id);
    if v_auth_user_id is not null then
      select count(distinct i.username), min(i.username), bool_or(i.trusted_metadata),
          max(i.email_confirmed_at), max(i.banned_until)
        into v_auth_identity_count, v_auth_identity_username, v_has_trusted_metadata,
          v_email_confirmed_at, v_banned_until
      from private.password_change_auth_identity_v1(v_auth_user_id) i;
      if coalesce(v_auth_identity_count, 0) <> 1 or v_auth_identity_username <> v_username then
        raise exception using errcode = '23514', message = 'password_change_auth_identity_conflict';
      end if;
      if not v_has_trusted_metadata and v_email_confirmed_at is null then
        raise exception using errcode = '23514', message = 'password_change_unconfirmed_auth_alias';
      end if;
      if v_banned_until is not null and v_banned_until > now() then
        raise exception using errcode = '42501', message = 'password_change_inactive_account';
      end if;
    end if;
  end if;

  -- A legacy account without a native identity gets a durable reservation.
  -- The caller creates Auth from these trusted legacy attributes, then calls
  -- prepare again with that new UUID to bind the profile safely.
  if v_auth_user_id is null then
    select a.* into v_attempt
    from private.password_change_attempts a
    where a.legacy_user_id = v_legacy.id and a.status = 'pending'
    for update;
    if found then
      if v_attempt.password_fingerprint <> v_fingerprint then
        raise exception using errcode = '40001', message = 'password_change_attempt_conflict';
      end if;
      if not v_forced then
        raise exception using errcode = '23514', message = 'password_change_gate_missing';
      end if;
      update public.ph_app_users set must_change_password = true where id = v_legacy.id;
      return query select 'needs_native_identity', v_attempt.attempt_id, null::uuid,
        v_legacy.id, v_username, v_username, v_legacy.role, v_legacy.division,
        v_legacy.language, true, v_legacy.locked_until, v_legacy.disabled_at;
      return;
    end if;
    if not v_forced then
      return query select 'password_change_not_required', null::uuid, null::uuid,
        v_legacy.id, v_username, v_username, v_legacy.role, v_legacy.division,
        v_legacy.language, false, v_legacy.locked_until, v_legacy.disabled_at;
      return;
    end if;
    update public.ph_app_users set must_change_password = true where id = v_legacy.id;
    insert into private.password_change_attempts (
      legacy_user_id, profile_id, auth_user_id, password_fingerprint, status
    ) values (v_legacy.id, null, null, v_fingerprint, 'pending')
    returning * into v_attempt;
    return query select 'needs_native_identity', v_attempt.attempt_id, null::uuid,
      v_legacy.id, v_username, v_username, v_legacy.role, v_legacy.division,
      v_legacy.language, true, v_legacy.locked_until, v_legacy.disabled_at;
    return;
  end if;

  -- Lock an in-flight attempt before the profile row. The completion RPC uses
  -- the same advisory -> legacy -> attempt -> profile order to avoid deadlocks.
  select a.* into v_attempt
  from private.password_change_attempts a
  where a.legacy_user_id = v_legacy.id and a.status = 'pending'
  for update;
  v_existing_pending := found;
  if v_existing_pending and (
    v_attempt.password_fingerprint <> v_fingerprint
    or (v_attempt.auth_user_id is not null and v_attempt.auth_user_id <> v_auth_user_id)
    or (v_attempt.profile_id is not null and v_attempt.profile_id <> v_auth_user_id)
  ) then
    raise exception using errcode = '40001', message = 'password_change_attempt_conflict';
  end if;

  -- Recheck profile constraints by UUID, username, and legacy link. Never
  -- adopt another Auth account's profile or overwrite role/access state.
  select count(*)::integer into v_auth_count
  from public.profiles p
  where p.id = v_auth_user_id
     or private.password_change_username_v1(p.username) = v_username
     or p.legacy_user_id = v_legacy.id;
  if v_auth_count > 1 then
    raise exception using errcode = '23505', message = 'password_change_profile_link_conflict';
  end if;

  select p.* into v_profile
  from public.profiles p
  where p.id = v_auth_user_id
     or private.password_change_username_v1(p.username) = v_username
     or p.legacy_user_id = v_legacy.id
  for update;
  v_has_profile := found;
  if v_has_profile then
    if v_profile.id <> v_auth_user_id
       or v_profile.username <> v_username
       or (v_profile.legacy_user_id is not null and v_profile.legacy_user_id <> v_legacy.id) then
      raise exception using errcode = '23505', message = 'password_change_profile_link_conflict';
    end if;
    if v_profile.disabled_at is not null
       or (v_profile.locked_until is not null and v_profile.locked_until > now()) then
      raise exception using errcode = '42501', message = 'password_change_inactive_account';
    end if;
  else
    insert into public.profiles (
      id, legacy_user_id, username, display_name, role, division, language,
      disabled_at, locked_until, must_change_password, updated_at
    ) values (
      v_auth_user_id, v_legacy.id, v_username, v_username,
      coalesce(nullif(btrim(v_legacy.role), ''), 'User'),
      coalesce(nullif(btrim(v_legacy.division), ''), '10'),
      coalesce(nullif(btrim(v_legacy.language), ''), 'English'),
      v_legacy.disabled_at, v_legacy.locked_until, true, now()
    ) returning * into v_profile;
    v_has_profile := true;
  end if;

  if v_existing_pending then
    if v_attempt.profile_id is not null and v_attempt.profile_id <> v_profile.id then
      raise exception using errcode = '40001', message = 'password_change_attempt_conflict';
    end if;
    update private.password_change_attempts a
    set auth_user_id = v_auth_user_id, profile_id = v_profile.id
    where a.attempt_id = v_attempt.attempt_id
    returning * into v_attempt;
  else
    v_forced := v_forced or coalesce(v_profile.must_change_password, false);

    if not v_forced then
      select a.* into v_attempt
      from private.password_change_attempts a
      where a.legacy_user_id = v_legacy.id
        and a.status = 'completed'
        and a.password_fingerprint = v_fingerprint
        and a.auth_user_id = v_auth_user_id
        and a.profile_id = v_profile.id
        and a.completed_at = v_legacy.password_changed_at
        and exists (
          select 1 from auth.users au
          where au.id = v_auth_user_id
            and au.encrypted_password is not null
            and extensions.crypt(v_legacy.password, au.encrypted_password) = au.encrypted_password
        )
      order by a.completed_at desc
      limit 1;
      v_existing_completed := found;
      if v_existing_completed then
        return query select 'completed', v_attempt.attempt_id, v_profile.id,
          v_legacy.id, v_username, v_profile.display_name, v_profile.role,
          v_profile.division, v_profile.language, false,
          v_profile.locked_until, v_profile.disabled_at;
      else
        return query select 'password_change_not_required', null::uuid, v_profile.id,
          v_legacy.id, v_username, v_profile.display_name, v_profile.role,
          v_profile.division, v_profile.language, false,
          v_profile.locked_until, v_profile.disabled_at;
      end if;
      return;
    end if;

    insert into private.password_change_attempts (
      legacy_user_id, profile_id, auth_user_id, password_fingerprint, status
    ) values (v_legacy.id, v_profile.id, v_auth_user_id, v_fingerprint, 'pending')
    returning * into v_attempt;
  end if;

  -- Set the normal forced-reset gate for any pending password operation.
  -- This also protects optional paths if they are ever enabled in the future.
  update public.ph_app_users
  set must_change_password = true
  where id = v_legacy.id;
  update public.profiles
  set legacy_user_id = v_legacy.id,
      must_change_password = true,
      updated_at = now()
  where id = v_profile.id;

  return query select 'ready', v_attempt.attempt_id, v_profile.id,
    v_legacy.id, v_username, v_profile.display_name, v_profile.role,
    v_profile.division, v_profile.language, true,
    v_profile.locked_until, v_profile.disabled_at;
end
$_$;


ALTER FUNCTION public.prepare_password_change_profile(p_username text, p_auth_user_id uuid, p_password_fingerprint text) OWNER TO postgres;

--
-- Name: FUNCTION prepare_password_change_profile(p_username text, p_auth_user_id uuid, p_password_fingerprint text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.prepare_password_change_profile(p_username text, p_auth_user_id uuid, p_password_fingerprint text) IS 'Service-only, idempotent profile/link reconciliation and durable password-change preparation. Stores only the server HMAC fingerprint, never a password.';


--
-- Name: prepare_pikes_order_import(text, text, text, bigint, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.prepare_pikes_order_import(p_drive_file_id text, p_file_name text, p_content_sha256 text, p_content_bytes bigint, p_batch_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
declare
  existing public.ph_pikes_order_batches%rowtype;
  prepared public.ph_pikes_order_batches%rowtype;
begin
  if btrim(coalesce(p_drive_file_id, '')) = ''
     or btrim(coalesce(p_file_name, '')) = ''
     or coalesce(p_content_sha256, '') !~ '^[0-9a-f]{64}$'
     or p_batch_id is null then
    raise exception 'PIKES_IMPORT_INVALID_FILE';
  end if;

  select * into existing
  from public.ph_pikes_order_batches b
  where b.drive_file_id = p_drive_file_id
  for update;

  if found then
    if existing.content_sha256 <> p_content_sha256 then
      raise exception 'PIKES_IMPORT_FILE_ID_CHANGED';
    end if;
    if existing.status = 'failed' then
      delete from public.ph_pikes_order_inventory_rows where batch_id = existing.batch_id;
      delete from public.ph_pikes_order_source_rows where batch_id = existing.batch_id;
      update public.ph_pikes_order_batches
      set status = 'importing',
          file_name = btrim(p_file_name),
          content_bytes = p_content_bytes,
          source_sheet_name = null,
          source_header_row = null,
          source_row_count = 0,
          distinct_item_count = 0,
          matched_item_count = 0,
          unmatched_item_count = 0,
          inventory_row_count = 0,
          last_error_code = null,
          updated_at = now()
      where drive_file_id = p_drive_file_id
      returning * into existing;
    end if;
    return jsonb_build_object(
      'status', existing.status,
      'batchId', existing.batch_id,
      'rowCount', existing.source_row_count,
      'displayName', existing.display_name
    );
  end if;

  insert into public.ph_pikes_order_batches (
    batch_id, drive_file_id, file_name, content_sha256, content_bytes
  ) values (
    p_batch_id, btrim(p_drive_file_id), btrim(p_file_name), p_content_sha256, p_content_bytes
  ) returning * into prepared;

  return jsonb_build_object('status', prepared.status, 'batchId', prepared.batch_id, 'rowCount', 0);
end;
$_$;


ALTER FUNCTION public.prepare_pikes_order_import(p_drive_file_id text, p_file_name text, p_content_sha256 text, p_content_bytes bigint, p_batch_id uuid) OWNER TO postgres;

--
-- Name: prepare_request_folder_completion_v2(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.prepare_request_folder_completion_v2(p_event_id uuid, p_lease_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  event_row public.ph_request_delivery_outbox;
  state_row private.ph_request_folder_delivery_state;
  current_ids text[];
  current_signature text;
  all_complete boolean;
  dependencies_ready boolean;
begin
  if not private.is_service_role_request() then
    raise exception using errcode = '42501', message = 'DELIVERY_WORKER_FORBIDDEN';
  end if;
  select * into event_row from public.ph_request_delivery_outbox
  where event_id = p_event_id and lease_token = p_lease_token and status = 'processing' for update;
  if event_row.event_id is null or event_row.payload->>'contractVersion' <> 'request-folder-completion-v2' then
    raise exception using errcode = 'P0002', message = 'FOLDER_COMPLETION_EVENT_NOT_FOUND';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('request-folder-v2:' || event_row.request_folder, 0));
  select coalesce(array_agg(r.unique_id order by r.unique_id), '{}'::text[]),
         coalesce(bool_and(lower(trim(coalesce(r.req_status, ''))) in ('complete','completed','done')
           or nullif(trim(coalesce(r.date_completed, '')), '') is not null), false)
    into current_ids, all_complete
  from public.ph_active_request r
  where trim(coalesce(r.request_folder, '')) = trim(event_row.request_folder)
    and coalesce(r.req_archived, false) = false
    and lower(trim(coalesce(r.req_status, 'pending'))) not in ('archived','cancelled','canceled');
  current_signature := md5(coalesce(array_to_string(current_ids, E'\n'), 'empty'));
  select * into state_row from private.ph_request_folder_delivery_state
  where request_folder = event_row.request_folder;
  if state_row.request_folder is null or current_signature <> event_row.payload->>'membershipSignature'
     or current_ids <> array(select jsonb_array_elements_text(event_row.payload->'activeRequestIds'))
     or not all_complete then
    update public.ph_request_delivery_outbox set status = 'suppressed',
      sanitized_error_code = 'FOLDER_COMPLETION_STALE', lease_token = null,
      lease_owner = null, lease_expires_at = null, updated_at = now()
    where event_id = event_row.event_id;
    perform private.reconcile_request_folder_completion_v2(event_row.request_folder);
    return jsonb_build_object('ready', false, 'terminal', true, 'code', 'FOLDER_COMPLETION_STALE');
  end if;
  select not exists (
    select 1 from jsonb_array_elements_text(coalesce(event_row.payload->'dependencyEventKeys', '[]'::jsonb)) dep(event_key)
    left join public.ph_request_delivery_outbox created on created.event_key = dep.event_key
    where created.event_key is null or created.status <> 'delivered'
  ) into dependencies_ready;
  if not dependencies_ready then
    update public.ph_request_delivery_outbox set status = 'pending', next_attempt_at = now() + interval '10 seconds',
      sanitized_error_code = 'WAITING_FOR_REQUEST_CREATED', lease_token = null,
      lease_owner = null, lease_expires_at = null, updated_at = now()
    where event_id = event_row.event_id;
    return jsonb_build_object('ready', false, 'terminal', false, 'code', 'WAITING_FOR_REQUEST_CREATED');
  end if;
  return jsonb_build_object('ready', true, 'requestIds', to_jsonb(current_ids),
    'membershipVersion', state_row.membership_version,
    'updatedCompletion', coalesce((event_row.payload->>'updatedCompletion')::boolean, false));
end
$$;


ALTER FUNCTION public.prepare_request_folder_completion_v2(p_event_id uuid, p_lease_token uuid) OWNER TO postgres;

--
-- Name: FUNCTION prepare_request_folder_completion_v2(p_event_id uuid, p_lease_token uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.prepare_request_folder_completion_v2(p_event_id uuid, p_lease_token uuid) IS 'Service-only final membership and request-created dependency gate immediately before folder completion delivery.';


--
-- Name: prepare_transactions_keyed_import(text, text, text, bigint, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.prepare_transactions_keyed_import(source_drive_file_id text, source_file_name text, source_content_sha256 text, source_content_bytes bigint DEFAULT NULL::bigint, source_import_batch_id uuid DEFAULT gen_random_uuid()) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
declare
  safe_file_id text := btrim(coalesce(source_drive_file_id, ''));
  safe_file_name text := btrim(coalesce(source_file_name, ''));
  safe_hash text := lower(btrim(coalesce(source_content_sha256, '')));
  safe_batch_id uuid := coalesce(source_import_batch_id, gen_random_uuid());
  existing_file public.ph_transactions_keyed_files%rowtype;
  canonical_file public.ph_transactions_keyed_files%rowtype;
begin
  if safe_file_id = '' or safe_file_name = '' then
    raise exception using errcode = '22023', message = 'TRANSACTIONS_KEYED_FILE_IDENTITY_REQUIRED';
  end if;
  if safe_hash !~ '^[0-9a-f]{64}$' then
    raise exception using errcode = '22023', message = 'TRANSACTIONS_KEYED_CONTENT_HASH_INVALID';
  end if;
  if source_content_bytes is not null and source_content_bytes < 0 then
    raise exception using errcode = '22023', message = 'TRANSACTIONS_KEYED_CONTENT_SIZE_INVALID';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(safe_hash, 0));

  select f.* into existing_file
  from public.ph_transactions_keyed_files f
  where f.drive_file_id = safe_file_id;

  if existing_file.drive_file_id is not null
     and existing_file.content_sha256 = safe_hash
     and existing_file.status in ('archive_pending', 'processed', 'duplicate_archive_pending', 'duplicate') then
    return jsonb_build_object(
      'status', existing_file.status,
      'driveFileId', existing_file.drive_file_id,
      'duplicateOfDriveFileId', existing_file.duplicate_of_drive_file_id,
      'rowCount', existing_file.row_count
    );
  end if;

  select f.* into canonical_file
  from public.ph_transactions_keyed_files f
  where f.content_sha256 = safe_hash
    and f.drive_file_id <> safe_file_id
    and f.duplicate_of_drive_file_id is null
    and f.status in ('archive_pending', 'processed')
  order by f.imported_at nulls last, f.created_at
  limit 1;

  if canonical_file.drive_file_id is not null then
    insert into public.ph_transactions_keyed_files (
      drive_file_id, file_name, content_sha256, content_bytes, row_count,
      status, duplicate_of_drive_file_id, import_batch_id, imported_at,
      archived_at, last_error_code, updated_at
    ) values (
      safe_file_id, safe_file_name, safe_hash, source_content_bytes, 0,
      'duplicate_archive_pending', canonical_file.drive_file_id, safe_batch_id,
      now(), null, null, now()
    )
    on conflict (drive_file_id) do update set
      file_name = excluded.file_name,
      content_sha256 = excluded.content_sha256,
      content_bytes = excluded.content_bytes,
      source_sheet_name = null,
      source_header_row = null,
      row_count = 0,
      first_transaction_date = null,
      last_transaction_date = null,
      status = 'duplicate_archive_pending',
      duplicate_of_drive_file_id = excluded.duplicate_of_drive_file_id,
      import_batch_id = excluded.import_batch_id,
      imported_at = excluded.imported_at,
      archived_at = null,
      last_error_code = null,
      updated_at = now();

    return jsonb_build_object(
      'status', 'duplicate_archive_pending',
      'driveFileId', safe_file_id,
      'duplicateOfDriveFileId', canonical_file.drive_file_id,
      'rowCount', 0
    );
  end if;

  insert into public.ph_transactions_keyed_files (
    drive_file_id, file_name, content_sha256, content_bytes, status,
    duplicate_of_drive_file_id, import_batch_id, imported_at, archived_at,
    last_error_code, updated_at
  ) values (
    safe_file_id, safe_file_name, safe_hash, source_content_bytes, 'importing',
    null, safe_batch_id, null, null, null, now()
  )
  on conflict (drive_file_id) do update set
    file_name = excluded.file_name,
    content_sha256 = excluded.content_sha256,
    content_bytes = excluded.content_bytes,
    source_sheet_name = null,
    source_header_row = null,
    row_count = 0,
    first_transaction_date = null,
    last_transaction_date = null,
    status = 'importing',
    duplicate_of_drive_file_id = null,
    import_batch_id = excluded.import_batch_id,
    imported_at = null,
    archived_at = null,
    last_error_code = null,
    updated_at = now();

  return jsonb_build_object(
    'status', 'importing',
    'driveFileId', safe_file_id,
    'importBatchId', safe_batch_id,
    'rowCount', 0
  );
end;
$_$;


ALTER FUNCTION public.prepare_transactions_keyed_import(source_drive_file_id text, source_file_name text, source_content_sha256 text, source_content_bytes bigint, source_import_batch_id uuid) OWNER TO postgres;

--
-- Name: production_workflow_command_v1(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.production_workflow_command_v1(p_actor_id uuid, p_operation text, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
declare actor public.profiles := workflow_private.active_actor(p_actor_id);
  kind text:=p_payload->>'workflow_type'; command_value text:=btrim(p_payload->>'command_id');
  source_row jsonb; row_value public.ph_production_workflow_rows; receipt workflow_private.commands;
  result jsonb; request_value jsonb:=jsonb_build_object('operation',p_operation,'payload',p_payload);
  amount numeric; expected bigint; source_id text:=btrim(p_payload->>'source_unique_id');
begin
  if not public.navigation_module_allowed_v1(actor.id,'production-workflow') then
    raise exception using errcode='42501',message='PRODUCTION_FORBIDDEN'; end if;
  if kind is null or kind not in ('propagation','planting') then raise exception 'PRODUCTION_TYPE_INVALID'; end if;
  if not public.navigation_module_allowed_v1(actor.id,'production:'||kind) then
    raise exception using errcode='42501',message='PRODUCTION_FORBIDDEN'; end if;
  if p_operation='list' then
    select jsonb_build_object('ok',true,'rows',coalesce(jsonb_agg(to_jsonb(w) order by w.blockalpha,w.locationcode,w.updated_at desc,w.unique_id),'[]'))
      into result from public.ph_production_workflow_rows w where workflow_type=kind and status=coalesce(nullif(p_payload->>'status',''),'open');
    return result;
  end if;
  if p_operation not in ('add','complete') then raise exception 'PRODUCTION_OPERATION_INVALID'; end if;
  if command_value is null or length(command_value)<12 or length(command_value)>180 then raise exception 'WORKFLOW_COMMAND_ID_REQUIRED'; end if;
  perform pg_advisory_xact_lock(hashtextextended(actor.id::text||':'||command_value,0));
  select * into receipt from workflow_private.commands c where c.actor_id=actor.id and c.command_id=command_value;
  if found then
    if receipt.request<>request_value then raise exception using errcode='40001',message='WORKFLOW_COMMAND_CONFLICT'; end if;
    return receipt.result||jsonb_build_object('duplicate',true);
  end if;
  expected:=(p_payload->>'expected_revision')::bigint;
  if expected is null then raise exception 'WORKFLOW_REVISION_REQUIRED'; end if;
  if p_operation='add' then
    if expected<>0 then raise exception using errcode='40001',message='WORKFLOW_REVISION_CONFLICT'; end if;
    amount:=(p_payload->>'quantity')::numeric;
    if amount is null or amount<=0 or amount in ('NaN'::numeric,'Infinity'::numeric,'-Infinity'::numeric) then raise exception 'PRODUCTION_QUANTITY_REQUIRED'; end if;
    if length(coalesce(p_payload->>'instructions',''))>12000 or length(coalesce(p_payload->>'baynumber',''))>150 then raise exception 'PRODUCTION_TEXT_TOO_LONG'; end if;
    perform pg_advisory_xact_lock(hashtextextended('production:'||kind||':'||source_id,0));
    select to_jsonb(m) into source_row from public.ph_master_inventory m where m.unique_id=source_id for share;
    if source_row is null then raise exception using errcode='40001',message='PRODUCTION_SOURCE_MISSING'; end if;
    if jsonb_typeof(p_payload->'source_identity') is distinct from 'object'
      or not (p_payload->'source_identity') ?& array['unique_id','itemcode','contsize','locationcode','lotcode']
      or not source_row @> (p_payload->'source_identity') then
      raise exception using errcode='40001',message='PRODUCTION_SOURCE_CHANGED'; end if;
    if exists(select 1 from public.ph_production_workflow_rows where workflow_type=kind and source_unique_id=source_id and status='open') then
      raise exception using errcode='40001',message='PRODUCTION_ALREADY_OPEN'; end if;
    insert into public.ph_production_workflow_rows(workflow_type,source_unique_id,itemcode,commonname,genus,contsize,locationcode,lotcode,season,blockalpha,ptravailable,
      quantity,baynumber,instructions,snapshot,created_by_username,created_by_display,updated_by_username,updated_by_display)
    values(kind,source_id,source_row->>'itemcode',source_row->>'commonname',coalesce(source_row->>'genus',source_row->>'genusname'),source_row->>'contsize',source_row->>'locationcode',
      source_row->>'lotcode',source_row->>'season',source_row->>'blockalpha',
      case when replace(btrim(source_row->>'ptravailable'),',','') ~ '^[+-]?([0-9]+(\.[0-9]*)?|\.[0-9]+)$'
        then replace(btrim(source_row->>'ptravailable'),',','')::numeric else null end,amount,
      coalesce(p_payload->>'baynumber',''),coalesce(p_payload->>'instructions',''),source_row,actor.username,coalesce(actor.display_name,actor.username),
      actor.username,coalesce(actor.display_name,actor.username)) returning * into row_value;
  else
    select * into row_value from public.ph_production_workflow_rows where unique_id=p_payload->>'unique_id' and workflow_type=kind for update;
    if row_value.unique_id is null then raise exception 'PRODUCTION_ROW_MISSING'; end if;
    if row_value.revision<>expected or row_value.status<>'open' then raise exception using errcode='40001',message='WORKFLOW_REVISION_CONFLICT'; end if;
    update public.ph_production_workflow_rows set status='complete',revision=revision+1,completed_at=now(),updated_at=now(),
      completed_by_username=actor.username,completed_by_display=coalesce(actor.display_name,actor.username),updated_by_username=actor.username,
      updated_by_display=coalesce(actor.display_name,actor.username) where unique_id=row_value.unique_id returning * into row_value;
  end if;
  result:=jsonb_build_object('ok',true,'row',to_jsonb(row_value));
  insert into workflow_private.commands(actor_id,command_id,request,result) values(actor.id,command_value,request_value,result);
  return result;
end $_$;


ALTER FUNCTION public.production_workflow_command_v1(p_actor_id uuid, p_operation text, p_payload jsonb) OWNER TO postgres;

--
-- Name: provision_native_auth_app_user(uuid, text, text, text, text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.provision_native_auth_app_user(p_auth_user_id uuid, p_username text, p_password text, p_display_name text DEFAULT NULL::text, p_role text DEFAULT 'User'::text, p_division text DEFAULT '10'::text, p_language text DEFAULT 'English'::text, p_must_change_password boolean DEFAULT true) RETURNS TABLE(legacy_user_id integer)
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_username text := lower(btrim(coalesce(p_username, '')));
  v_display_name text := btrim(coalesce(nullif(p_display_name, ''), p_username, ''));
  v_role text := btrim(coalesce(nullif(p_role, ''), 'User'));
  v_division text := btrim(coalesce(nullif(p_division, ''), '10'));
  v_language text := btrim(coalesce(nullif(p_language, ''), 'English'));
  v_profile public.profiles%rowtype;
  v_legacy_user_id integer;
  v_normalized_legacy_count integer := 0;
begin
  if p_auth_user_id is null then
    raise exception using errcode = '22023', message = 'auth_user_id_required';
  end if;
  if v_username = '' then
    raise exception using errcode = '22023', message = 'username_required';
  end if;
  if length(coalesce(p_password, '')) < 6 then
    raise exception using errcode = '22023', message = 'password_too_short';
  end if;

  select p.*
  into v_profile
  from public.profiles p
  where p.id = p_auth_user_id
  for update;

  if v_profile.id is not null and lower(btrim(v_profile.username)) <> v_username then
    raise exception using errcode = '23514', message = 'profile_username_mismatch';
  end if;

  select min(u.id), count(*)::integer
  into v_legacy_user_id, v_normalized_legacy_count
  from public.ph_app_users u
  where lower(btrim(u.username)) = v_username;

  if v_normalized_legacy_count > 1 then
    raise exception using errcode = '21000', message = 'duplicate_normalized_legacy_username';
  end if;

  if v_profile.legacy_user_id is not null then
    if v_legacy_user_id is not null and v_legacy_user_id <> v_profile.legacy_user_id then
      raise exception using errcode = '23505', message = 'profile_legacy_link_conflict';
    end if;
    v_legacy_user_id := v_profile.legacy_user_id;
  end if;

  if v_legacy_user_id is not null and exists (
    select 1
    from public.profiles p
    where p.legacy_user_id = v_legacy_user_id
      and p.id <> p_auth_user_id
  ) then
    raise exception using errcode = '23505', message = 'legacy_user_already_linked';
  end if;

  if v_legacy_user_id is null then
    insert into public.ph_app_users (
      username,
      password,
      role,
      password_hash,
      password_salt,
      password_changed_at,
      must_change_password,
      failed_login_count,
      locked_until,
      disabled_at,
      division,
      language
    ) values (
      v_username,
      p_password,
      v_role,
      null,
      null,
      case when p_must_change_password then null else now() end,
      p_must_change_password,
      0,
      null,
      null,
      v_division,
      v_language
    )
    returning id into v_legacy_user_id;
  else
    update public.ph_app_users
    set username = v_username,
        password = p_password,
        role = v_role,
        password_hash = null,
        password_salt = null,
        password_changed_at = case when p_must_change_password then password_changed_at else now() end,
        must_change_password = p_must_change_password,
        failed_login_count = 0,
        locked_until = null,
        disabled_at = null,
        division = v_division,
        language = v_language
    where id = v_legacy_user_id;

    if not found then
      raise exception using errcode = '23503', message = 'linked_legacy_user_missing';
    end if;
  end if;

  insert into public.profiles (
    id,
    legacy_user_id,
    username,
    display_name,
    role,
    division,
    language,
    disabled_at,
    locked_until,
    must_change_password,
    updated_at
  ) values (
    p_auth_user_id,
    v_legacy_user_id,
    v_username,
    coalesce(nullif(v_display_name, ''), v_username),
    v_role,
    v_division,
    v_language,
    null,
    null,
    p_must_change_password,
    now()
  )
  on conflict (id) do update
  set legacy_user_id = excluded.legacy_user_id,
      username = excluded.username,
      display_name = excluded.display_name,
      role = excluded.role,
      division = excluded.division,
      language = excluded.language,
      disabled_at = null,
      locked_until = null,
      must_change_password = excluded.must_change_password,
      updated_at = now();

  return query select v_legacy_user_id;
end
$$;


ALTER FUNCTION public.provision_native_auth_app_user(p_auth_user_id uuid, p_username text, p_password text, p_display_name text, p_role text, p_division text, p_language text, p_must_change_password boolean) OWNER TO postgres;

--
-- Name: FUNCTION provision_native_auth_app_user(p_auth_user_id uuid, p_username text, p_password text, p_display_name text, p_role text, p_division text, p_language text, p_must_change_password boolean); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.provision_native_auth_app_user(p_auth_user_id uuid, p_username text, p_password text, p_display_name text, p_role text, p_division text, p_language text, p_must_change_password boolean) IS 'Server-only transactional provisioning and repair for the dual-auth profile/legacy-user link.';


--
-- Name: prune_v2_app_live_events(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.prune_v2_app_live_events(retention_days integer DEFAULT 3) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  deleted_count integer := 0;
begin
  delete from public.ph_app_live_events
  where created_at < now() - make_interval(days => greatest(coalesce(retention_days, 3), 1));
  get diagnostics deleted_count = row_count;
  return deleted_count;
end;
$$;


ALTER FUNCTION public.prune_v2_app_live_events(retention_days integer) OWNER TO postgres;

--
-- Name: prune_v2_app_live_events_by_count(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.prune_v2_app_live_events_by_count(max_events integer DEFAULT 5000) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  deleted_count integer := 0;
begin
  with doomed as (
    select id
    from public.ph_app_live_events
    order by created_at desc
    offset greatest(coalesce(max_events, 5000), 500)
  )
  delete from public.ph_app_live_events e
  using doomed d
  where e.id = d.id;

  get diagnostics deleted_count = row_count;
  return deleted_count;
end;
$$;


ALTER FUNCTION public.prune_v2_app_live_events_by_count(max_events integer) OWNER TO postgres;

--
-- Name: publish_access_control_policy_v1(integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.publish_access_control_policy_v1(p_expected_revision integer, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor public.profiles;
  reviewed private.app_access_policy_versions;
  next_draft private.app_access_policy_versions;
begin
  actor := private.current_active_profile();
  if actor.id is null or not private.is_access_control_maintainer() then
    raise exception using errcode = '42501', message = 'ACCESS_CONTROL_FORBIDDEN';
  end if;
  if char_length(btrim(coalesce(p_reason, ''))) not between 4 and 500 then
    raise exception using errcode = '22023', message = 'ACCESS_CONTROL_REASON_REQUIRED';
  end if;

  select * into reviewed
  from private.app_access_policy_versions
  where status = 'draft'
  order by version_number desc
  limit 1
  for update;
  if reviewed.id is null or reviewed.revision <> p_expected_revision then
    raise exception using errcode = '40001', message = 'ACCESS_CONTROL_VERSION_CONFLICT';
  end if;

  update private.app_access_policy_versions
  set status = 'reviewed', reviewed_by_username = lower(btrim(actor.username)),
      reviewed_at = now(), review_reason = btrim(p_reason)
  where id = reviewed.id
  returning * into reviewed;

  update private.app_access_runtime_state
  set reviewed_policy_id = reviewed.id, updated_at = now()
  where singleton;

  insert into private.app_access_change_events
    (policy_id, actor_username, event_type, target_type, target_key,
     permission_key, previous_value, next_value, reason)
  values
    (reviewed.id, lower(btrim(actor.username)), 'policy_reviewed', 'policy',
     reviewed.version_number::text, null,
     jsonb_build_object('status', 'draft'), jsonb_build_object('status', 'reviewed'), btrim(p_reason));

  insert into private.app_access_policy_versions
    (version_number, revision, status, base_policy_id, created_by_username, review_reason)
  values
    ((select coalesce(max(version_number), 0) + 1 from private.app_access_policy_versions),
     1, 'draft', reviewed.id, lower(btrim(actor.username)), 'Draft copied from reviewed policy')
  returning * into next_draft;

  insert into private.app_access_role_grants
    (policy_id, role_key, permission_key, allowed, access_scope, updated_at)
  select next_draft.id, role_key, permission_key, allowed, access_scope, now()
  from private.app_access_role_grants where policy_id = reviewed.id;

  insert into private.app_access_user_overrides
    (policy_id, profile_id, permission_key, allowed, access_scope, updated_at)
  select next_draft.id, profile_id, permission_key, allowed, access_scope, now()
  from private.app_access_user_overrides where policy_id = reviewed.id;

  insert into private.app_access_change_events
    (policy_id, actor_username, event_type, target_type, target_key,
     permission_key, previous_value, next_value, reason)
  values
    (next_draft.id, lower(btrim(actor.username)), 'draft_created', 'policy',
     next_draft.version_number::text, null, null,
     jsonb_build_object('basePolicyId', reviewed.id), 'Draft created after audit publication');

  return jsonb_build_object(
    'contractVersion', 'app-access-v1',
    'enforcementMode', 'audit',
    'reviewedPolicyId', reviewed.id,
    'reviewedPolicyVersion', reviewed.version_number,
    'draftPolicyId', next_draft.id,
    'draftPolicyVersion', next_draft.version_number,
    'draftRevision', next_draft.revision
  );
end
$$;


ALTER FUNCTION public.publish_access_control_policy_v1(p_expected_revision integer, p_reason text) OWNER TO postgres;

--
-- Name: FUNCTION publish_access_control_policy_v1(p_expected_revision integer, p_reason text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.publish_access_control_policy_v1(p_expected_revision integer, p_reason text) IS 'Publishes an immutable reviewed audit policy and creates the next draft; enforcement remains audit-only.';


--
-- Name: reassign_eval_work_v1(uuid, text, integer, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reassign_eval_work_v1(p_work_id uuid, p_actor_username text, p_expected_version integer, p_assignee_username text, p_assignee_email text) RETURNS public.ph_eval_work
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  actor public.profiles;
  assignee public.profiles;
  work public.ph_eval_work;
  delivery public.ph_request_delivery_outbox;
begin
  actor := private.eval_work_assert_actor_v1(p_actor_username);
  if lower(actor.username) not in ('dylan_collyge', 'megan_kelly') then raise exception using errcode = '42501', message = 'eval_work_manage_forbidden'; end if;
  assignee := private.eval_work_assert_actor_v1(p_assignee_username);
  if trim(coalesce(p_assignee_email, '')) !~* '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then raise exception using errcode = '22023', message = 'eval_work_assignee_email_invalid'; end if;
  select * into work from public.ph_eval_work where id = p_work_id for update;
  if work.id is null or work.status not in ('open', 'in_progress') then raise exception using errcode = '22023', message = 'eval_work_not_reassignable'; end if;
  if work.version <> p_expected_version then raise exception using errcode = '40001', message = 'eval_work_version_conflict'; end if;
  if exists (
    select 1 from public.ph_request_delivery_outbox o
    where o.event_id = work.assignment_event_id
      and (
        o.status = 'processing'
        or (
          o.status in ('pending', 'failed', 'unknown')
          and exists (
            select 1
            from public.ph_eval_work sibling
            where sibling.assignment_event_id = work.assignment_event_id
              and sibling.id <> work.id
          )
        )
      )
  ) then
    raise exception using errcode = '40001', message = 'eval_work_assignment_delivery_in_progress';
  end if;
  update public.ph_request_delivery_outbox
  set status = 'suppressed', sanitized_error_code = 'EVAL_WORK_REASSIGNED', updated_at = now()
  where event_id = work.assignment_event_id and status in ('pending', 'failed', 'unknown');
  update public.ph_eval_work set assignee_username = lower(assignee.username), assignee_display = coalesce(nullif(assignee.display_name, ''), assignee.username),
    assignee_email = lower(trim(p_assignee_email)), version = version + 1, updated_at = now()
  where id = work.id returning * into work;
  insert into public.ph_eval_work_events(eval_work_id, event_type, actor_username, version, metadata)
  values (work.id, 'reassigned', lower(actor.username), work.version, '{}'::jsonb);
  insert into public.ph_request_delivery_outbox(event_key, event_type, request_id, payload, status, next_attempt_at)
  values ('eval-work:' || work.id::text || ':assignment:v' || work.version::text, 'eval_work_assignment', work.id::text,
    jsonb_build_object('contractVersion','eval-work-v1','deliveryKind','assignment','evalWorkId',work.id,'assigneeUsername',work.assignee_username,'assigneeDisplay',work.assignee_display,'assigneeEmail',work.assignee_email,'creatorUsername',work.creator_username,'creatorDisplay',work.creator_display,'instructions',work.instructions,'itemcode',work.itemcode,'commonname',work.commonname,'contsize',work.contsize,'source',jsonb_build_object('unique_id',work.origin_unique_id,'itemcode',work.itemcode,'locationcode',work.origin_locationcode,'lotcode',work.origin_lotcode,'source_table','ph_master_inventory'),'inquiry',work.inquiry_draft), 'pending', now())
  on conflict (event_key) do update set updated_at = now() returning * into delivery;
  update public.ph_eval_work set assignment_event_id = delivery.event_id where id = work.id returning * into work;
  return work;
end
$_$;


ALTER FUNCTION public.reassign_eval_work_v1(p_work_id uuid, p_actor_username text, p_expected_version integer, p_assignee_username text, p_assignee_email text) OWNER TO postgres;

--
-- Name: reassign_eval_work_v2(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reassign_eval_work_v2(p_payload jsonb) RETURNS public.ph_eval_work
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  normalized jsonb := private.eval_work_normalize_assignees_v1(p_payload->'assignees');
  usernames text[];
  emails text[];
  profiles jsonb;
  primary_assignee jsonb;
  assignment_recipients text[];
  work public.ph_eval_work;
begin
  select array_agg(value order by ordinality) into usernames
  from jsonb_array_elements_text(normalized->'usernames') with ordinality;
  select array_agg(value order by ordinality) into emails
  from jsonb_array_elements_text(normalized->'emails') with ordinality;
  profiles := normalized->'profiles';
  primary_assignee := profiles->0;
  work := public.reassign_eval_work_v1(
    (p_payload->>'workId')::uuid,
    p_payload->>'actorUsername',
    (p_payload->>'expectedVersion')::integer,
    primary_assignee->>'username',
    primary_assignee->>'email'
  );
  select array_agg(distinct value order by value) into assignment_recipients
  from unnest(private.eval_work_required_manager_emails_v2() || emails) value;
  update public.ph_eval_work
    set assignee_usernames = usernames, assignee_profiles = profiles
    where id = work.id returning * into work;
  update public.ph_request_delivery_outbox
    set payload = payload || jsonb_build_object(
      'assigneeUsernames', to_jsonb(usernames),
      'assignees', profiles,
      'assignmentRecipients', to_jsonb(assignment_recipients)
    ), updated_at = now()
    where event_id = work.assignment_event_id;
  return work;
end
$$;


ALTER FUNCTION public.reassign_eval_work_v2(p_payload jsonb) OWNER TO postgres;

--
-- Name: reconcile_eval_itemcodes(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reconcile_eval_itemcodes() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin return public.reconcile_eval_itemcodes(null::uuid); end $$;


ALTER FUNCTION public.reconcile_eval_itemcodes() OWNER TO postgres;

--
-- Name: reconcile_eval_itemcodes(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reconcile_eval_itemcodes(p_import_run_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare lock_acquired boolean; source_state text; run app_sync_private.import_runs;
  inventory_revision bigint; zone_candidates boolean;
  discovered integer:=0; changed integer:=0; removed integer:=0; alerted integer:=0; unassigned_total integer:=0;
  policy_changed integer:=0;
  previous_action text:=current_setting('app.perennial_assignment_action',true);
  previous_run text:=current_setting('app.perennial_import_run_id',true);
begin
  if p_import_run_id is null then
    select state into source_state from public.app_dataset_revisions where key='ph_master_inventory' for share;
    if source_state is distinct from 'ready' then
      return jsonb_build_object('status','deferred','errorCode','MASTER_SNAPSHOT_NOT_READY','discovered',0,'changed',0,'removed',0,'alerts_queued',0);
    end if;
    if not coalesce((select activated from private.ph_perennial_assignment_policy_state where singleton),false) then
      return jsonb_build_object('status','deferred','errorCode','PERENNIAL_POLICY_AWAITING_MASTER_IMPORT','discovered',0,'changed',0,'removed',0,'alerts_queued',0);
    end if;
  else
    select * into run from app_sync_private.import_runs where id=p_import_run_id;
    if run.id is null or run.state<>'active' or run.expires_at<=clock_timestamp()
      or not ('ph_master_inventory'=any(run.source_keys))
      or not ('ph_master_inventory'=any(run.canonical_keys))
      or not exists(select 1 from app_sync_private.import_leases l where l.key='ph_master_inventory' and l.run_id=run.id) then
      raise exception using errcode='55000',message='PERENNIAL_RECONCILE_IMPORT_FENCE_LOST';
    end if;
  end if;
  lock_acquired:=pg_try_advisory_xact_lock(hashtextextended('gnc-reconcile-eval-itemcodes-v2',0));
  if not lock_acquired then return jsonb_build_object('status','deferred','errorCode','MAINTENANCE_DEFERRED','discovered',0,'changed',0,'removed',0,'alerts_queued',0); end if;
  select revision into inventory_revision from public.app_dataset_revisions where key='ph_master_inventory';
  if p_import_run_id is not null then inventory_revision:=inventory_revision+1; end if;
  select exists(
    select 1 from public.ph_master_inventory mi
    where private.eval_location_zone(mi.locationcode)='inside'
      and nullif(btrim(coalesce(mi.itemcode,'')),'') is not null
      and not exists(select 1 from public.ph_master_inventory rose
        where upper(btrim(rose.itemcode))=upper(btrim(mi.itemcode))
          and lower(regexp_replace(btrim(coalesce(rose.genusname,'')),'[[:space:]]+',' ','g'))=
            lower(regexp_replace(btrim(coalesce(mi.genusname,'')),'[[:space:]]+',' ','g'))
          and upper(btrim(coalesce(rose.plantgroupcode,'')))='135_ROSES')
  ) into zone_candidates;
  if zone_candidates and not exists(select 1 from public.ph_eval_assignment_users where active and lower(btrim(username))='zoe_green') then
    raise exception using errcode='55000',message='PERENNIAL_ZONE_ZOE_INACTIVE';
  end if;
  perform set_config('app.perennial_assignment_action','zone_reconcile',true);
  perform set_config('app.perennial_import_run_id',coalesce(p_import_run_id::text,''),true);

  with normalized_drive as materialized (
    select upper(btrim(itemcode)) itemcode_normalized,
      lower(regexp_replace(btrim(coalesce(genusname,'')),'[[:space:]]+',' ','g')) genusname_normalized,
      genusname,commonname,contsize,locationcode,plantgroupcode
    from public.ph_master_inventory where nullif(btrim(coalesce(itemcode,'')),'') is not null
  ), drive_codes as materialized (
    select itemcode_normalized,genusname_normalized,itemcode_normalized||'|'||genusname_normalized assignment_key,
      max(genusname) genusname,max(commonname) commonname,max(contsize) contsize,max(locationcode) locationcode
    from normalized_drive group by itemcode_normalized,genusname_normalized
  ), changed_codes as materialized (
    select d.* from drive_codes d left join public.ph_warehouse_assigned_items a using(assignment_key)
    where a.assignment_key is null or a.itemcode is distinct from d.itemcode_normalized
      or a.itemcode_normalized is distinct from d.itemcode_normalized or a.genusname is distinct from d.genusname
      or a.genusname_normalized is distinct from d.genusname_normalized
      or a.concat is distinct from (d.itemcode_normalized||d.genusname) or a.commonname is distinct from d.commonname
      or a.contsize is distinct from d.contsize or a.locationcode is distinct from d.locationcode or not a.present_in_drive
  ), written as (
    insert into public.ph_warehouse_assigned_items(unique_id,itemcode,itemcode_normalized,genusname,genusname_normalized,
      concat,assignment_key,commonname,contsize,locationcode,source,first_seen_at,last_seen_at,present_in_drive,raw_row,updated_at)
    select 'eval-itemcode-genus-'||md5(d.assignment_key),d.itemcode_normalized,d.itemcode_normalized,d.genusname,
      d.genusname_normalized,d.itemcode_normalized||d.genusname,d.assignment_key,d.commonname,d.contsize,d.locationcode,
      'supabase_drive_reconcile',now(),now(),true,jsonb_build_object('authority','supabase','scope','itemcode_genus'),now()
    from changed_codes d on conflict(assignment_key) where assignment_key is not null do update set
      itemcode=excluded.itemcode,itemcode_normalized=excluded.itemcode_normalized,genusname=excluded.genusname,
      genusname_normalized=excluded.genusname_normalized,concat=excluded.concat,commonname=excluded.commonname,
      contsize=excluded.contsize,locationcode=excluded.locationcode,
      source=case when public.ph_warehouse_assigned_items.source='google_sheet_cutover_20260820'
        then public.ph_warehouse_assigned_items.source else 'supabase_drive_reconcile' end,
      last_seen_at=now(),present_in_drive=true,updated_at=now() returning (xmax=0) was_inserted
  ), removed_rows as (
    update public.ph_warehouse_assigned_items a set present_in_drive=false,updated_at=now()
    where a.present_in_drive and a.assignment_key is not null
      and not exists(select 1 from drive_codes d where d.assignment_key=a.assignment_key) returning 1
  )
  select (select count(*) filter(where was_inserted)::integer from written),
    (select count(*) filter(where not was_inserted)::integer from written),(select count(*)::integer from removed_rows)
  into discovered,changed,removed;

  -- Group presence must be resolved by a parseable source row. An absent key or
  -- a group with only malformed locations retains its prior assignment state.
  with group_state as materialized (
    select upper(btrim(mi.itemcode))||'|'||lower(regexp_replace(btrim(coalesce(mi.genusname,'')),'[[:space:]]+',' ','g')) assignment_key,
      bool_or(upper(btrim(coalesce(mi.plantgroupcode,'')))='135_ROSES') rose,
      bool_or(private.eval_location_zone(mi.locationcode)='inside') in_zone,
      bool_or(private.eval_location_zone(mi.locationcode) is null) unresolved,
      bool_and(private.eval_location_zone(mi.locationcode)='outside') all_outside
    from public.ph_master_inventory mi where nullif(btrim(coalesce(mi.itemcode,'')),'') is not null
    group by 1
  ), action_rows as materialized (
    select a.id,a.assignment_key,a.assignedto,a.assigned_by,a.assigned_at,a.zone_override_active,
      s.rose,s.in_zone,s.unresolved,s.all_outside,
      case when not s.rose and s.in_zone and not a.zone_override_active then 'enforce'
        when not s.rose and s.in_zone and a.zone_override_active and a.assignedto is distinct from 'zoe_green' then 'reassert'
        when s.rose and a.zone_override_active then 'restore'
        when not s.rose and not s.in_zone and not s.unresolved and s.all_outside and a.zone_override_active then 'exit'
        else null end action
    from public.ph_warehouse_assigned_items a join group_state s using(assignment_key)
    where a.assignment_key is not null and a.present_in_drive
  ), audit_rows as (
    insert into private.ph_warehouse_assignment_audit(assignment_key,event_type,actor_username,old_assignedto,new_assignedto,
      old_zone_override_active,new_zone_override_active,reason,rule_version,evaluated_inventory_revision,import_run_id)
    select action_rows.assignment_key,case action_rows.action when 'enforce' then 'zone_enforced'
      when 'reassert' then 'zone_lock_reasserted' when 'restore' then 'rose_exemption_restore' else 'zone_exit_unassigned' end,
      'system',action_rows.assignedto,
      case action_rows.action when 'enforce' then 'zoe_green' when 'reassert' then 'zoe_green'
        when 'restore' then case when exists(select 1 from public.ph_eval_assignment_users u
          where u.active and lower(btrim(u.username))=lower(btrim(a.zone_override_prior_assignedto)))
          then a.zone_override_prior_assignedto else null end else null end,
      action_rows.zone_override_active,action_rows.action in ('enforce','reassert'),
      case action_rows.action when 'enforce' then 'entered_perennial_zone' when 'reassert' then 'zone_owner_reasserted'
        when 'restore' then case when a.zone_override_prior_assignedto is not null and not exists(
          select 1 from public.ph_eval_assignment_users u where u.active
            and lower(btrim(u.username))=lower(btrim(a.zone_override_prior_assignedto)))
          then 'saved_owner_inactive_reset' else 'rose_exemption_restore' end
        else 'left_perennial_zone' end,
      'perennial-zone-2026-09-v1',inventory_revision,p_import_run_id
    from action_rows join public.ph_warehouse_assigned_items a using(id) where action_rows.action is not null
    returning 1
  )
  update public.ph_warehouse_assigned_items a set
    assignedto=case r.action when 'enforce' then 'zoe_green' when 'reassert' then 'zoe_green'
      when 'restore' then case when exists(select 1 from public.ph_eval_assignment_users u
        where u.active and lower(btrim(u.username))=lower(btrim(a.zone_override_prior_assignedto)))
        then a.zone_override_prior_assignedto else null end else null end,
    assigned_by=case r.action when 'enforce' then 'perennial_zone_policy' when 'reassert' then 'perennial_zone_policy'
      when 'restore' then case when exists(select 1 from public.ph_eval_assignment_users u
        where u.active and lower(btrim(u.username))=lower(btrim(a.zone_override_prior_assignedto)))
        then a.zone_override_prior_assigned_by else null end else null end,
    assigned_at=case r.action when 'enforce' then clock_timestamp() when 'reassert' then clock_timestamp()
      when 'restore' then case when exists(select 1 from public.ph_eval_assignment_users u
        where u.active and lower(btrim(u.username))=lower(btrim(a.zone_override_prior_assignedto)))
        then a.zone_override_prior_assigned_at else null end else null end,
    zone_override_active=(r.action in ('enforce','reassert')),
    zone_override_prior_assignedto=case r.action when 'enforce' then a.assignedto when 'reassert' then a.zone_override_prior_assignedto else null end,
    zone_override_prior_assigned_by=case r.action when 'enforce' then a.assigned_by when 'reassert' then a.zone_override_prior_assigned_by else null end,
    zone_override_prior_assigned_at=case r.action when 'enforce' then a.assigned_at when 'reassert' then a.zone_override_prior_assigned_at else null end,
    zone_override_rule_version=case when r.action in ('enforce','reassert') then 'perennial-zone-2026-09-v1' else null end,
    zone_override_evaluated_revision=case when r.action in ('enforce','reassert') then inventory_revision else null end,
    assignment_reason=case r.action when 'enforce' then 'perennial_zone_area'
      when 'reassert' then 'perennial_zone_owner_reasserted'
      when 'restore' then case when a.zone_override_prior_assignedto is not null and not exists(
        select 1 from public.ph_eval_assignment_users u where u.active
          and lower(btrim(u.username))=lower(btrim(a.zone_override_prior_assignedto)))
        then 'saved_owner_inactive_reset' else 'rose_exemption_restore' end
      else 'left_perennial_zone' end,
    unassigned_notified_at=case when r.action='exit' or (r.action='restore' and not exists(
      select 1 from public.ph_eval_assignment_users u where u.active
        and lower(btrim(u.username))=lower(btrim(a.zone_override_prior_assignedto)))) then null
      when r.action='enforce' then clock_timestamp() else a.unassigned_notified_at end,
    updated_at=clock_timestamp()
    from action_rows r where r.id=a.id and r.action is not null;
  get diagnostics policy_changed=row_count;

  -- Track every successful full evaluation without producing another transition audit.
  update public.ph_warehouse_assigned_items a set
    zone_override_evaluated_revision=inventory_revision,
    zone_override_rule_version='perennial-zone-2026-09-v1',
    updated_at=clock_timestamp()
  where a.present_in_drive and a.zone_override_active and a.assignedto='zoe_green'
    and a.zone_override_evaluated_revision is distinct from inventory_revision
    and exists(select 1 from public.ph_master_inventory mi
      where upper(btrim(mi.itemcode))||'|'||lower(regexp_replace(btrim(coalesce(mi.genusname,'')),'[[:space:]]+',' ','g'))=a.assignment_key
        and private.eval_location_zone(mi.locationcode)='inside')
    and not exists(select 1 from public.ph_master_inventory rose
      where upper(btrim(rose.itemcode))||'|'||lower(regexp_replace(btrim(coalesce(rose.genusname,'')),'[[:space:]]+',' ','g'))=a.assignment_key
        and upper(btrim(coalesce(rose.plantgroupcode,'')))='135_ROSES');
  changed:=changed+policy_changed;

  with needs_alert as (
    select id,itemcode_normalized,genusname,assignment_key from public.ph_warehouse_assigned_items
    where present_in_drive and nullif(btrim(coalesce(assignedto,'')),'') is null and unassigned_notified_at is null for update
  ), queued as (
    insert into public.ph_request_delivery_outbox(event_key,event_type,payload,status)
    select 'eval-unassigned:'||md5(assignment_key),'eval_assignment_unassigned',jsonb_build_object('itemcode',itemcode_normalized,
      'genusname',genusname,'assignment_key',assignment_key,'manager_usernames',jsonb_build_array('dylan_collyge','megan_kelly')),'pending'
    from needs_alert on conflict(event_key) do update set
      status=case when public.ph_request_delivery_outbox.status='delivered' then 'pending' else public.ph_request_delivery_outbox.status end,
      next_attempt_at=now(),delivered_at=null,sanitized_error_code=null returning event_key
  ) select count(*)::integer into alerted from queued;
  update public.ph_warehouse_assigned_items set unassigned_notified_at=now(),updated_at=now()
    where present_in_drive and nullif(btrim(coalesce(assignedto,'')),'') is null and unassigned_notified_at is null;
  select count(*)::integer into unassigned_total from public.ph_warehouse_assigned_items where present_in_drive
    and nullif(btrim(coalesce(assignedto,'')),'') is null;
  if p_import_run_id is not null then
    update private.ph_perennial_assignment_policy_state set activated=true,activated_at=coalesce(activated_at,clock_timestamp()),
      activation_import_run_id=coalesce(activation_import_run_id,p_import_run_id) where singleton;
  end if;
  perform set_config('app.perennial_assignment_action',coalesce(previous_action,''),true);
  perform set_config('app.perennial_import_run_id',coalesce(previous_run,''),true);
  return jsonb_build_object('status','completed','discovered',discovered,'changed',changed,'assignment_changes',policy_changed,'removed',removed,
    'alerts_queued',alerted,'unassigned_count',unassigned_total,'policy_activated',
    coalesce((select activated from private.ph_perennial_assignment_policy_state where singleton),false));
end $$;


ALTER FUNCTION public.reconcile_eval_itemcodes(p_import_run_id uuid) OWNER TO postgres;

--
-- Name: reconcile_eval_report2_work_v1(text, boolean, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reconcile_eval_report2_work_v1(p_import_revision text, p_dry_run boolean DEFAULT true, p_limit integer DEFAULT 1000) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  lock_acquired boolean;
  work_row public.ph_eval_work;
  report_id text;
  checked_count integer := 0;
  resolved_count integer := 0;
  resolved_ids jsonb := '[]'::jsonb;
  safe_limit integer := least(5000, greatest(1, coalesce(p_limit, 1000)));
  safe_revision text := left(regexp_replace(btrim(coalesce(p_import_revision, '')), '[^A-Za-z0-9_.:+-]', '', 'g'), 160);
begin
  lock_acquired := pg_try_advisory_xact_lock(hashtextextended('gnc-eval-report2-import-reconcile-v1', 0));
  if not lock_acquired then
    return jsonb_build_object('status', 'deferred', 'errorCode', 'RECONCILIATION_DEFERRED', 'checked', 0, 'resolved', 0);
  end if;
  if safe_revision = '' then safe_revision := to_char(now() at time zone 'UTC', 'YYYYMMDDHH24MISSMS'); end if;

  for work_row in
    select work.*
    from public.ph_eval_work work
    where work.status in ('open', 'in_progress')
      and lower(btrim(coalesce(work.source_context #>> '{report,sourceMode}', ''))) = 'eval-report-2'
      and nullif(btrim(coalesce(work.source_context #>> '{report,reportId}', '')), '') is not null
    order by work.created_at, work.id
    limit safe_limit
    for update skip locked
  loop
    checked_count := checked_count + 1;
    report_id := lower(btrim(work_row.source_context #>> '{report,reportId}'));
    if cardinality(private.eval_report2_matching_reports_v1(work_row.source_context->'report', work_row.itemcode, now())) > 0 then
      continue;
    end if;
    resolved_count := resolved_count + 1;
    resolved_ids := resolved_ids || jsonb_build_array(work_row.id);
    if not coalesce(p_dry_run, true) then
      update public.ph_eval_work
      set status = 'resolved_import',
          resolved_import_at = now(),
          resolved_import_revision = safe_revision,
          resolved_import_report_id = report_id,
          updated_at = now(),
          version = version + 1
      where id = work_row.id and status in ('open', 'in_progress')
      returning * into work_row;

      if found then
        insert into public.ph_eval_work_events(eval_work_id, event_type, actor_username, version, metadata)
        values (
          work_row.id,
          'resolved_import',
          'inventory_import',
          work_row.version,
          jsonb_build_object('reportId', report_id, 'reportIds', to_jsonb(private.eval_report2_context_ids_v1(work_row.source_context->'report')), 'importRevision', safe_revision, 'deliveryQueued', false)
        );
      end if;
    end if;
  end loop;

  return jsonb_build_object(
    'status', case when coalesce(p_dry_run, true) then 'dry_run' else 'completed' end,
    'checked', checked_count,
    'resolved', resolved_count,
    'resolvedWorkIds', resolved_ids,
    'deliveryEventsCreated', 0,
    'importRevision', safe_revision
  );
end
$$;


ALTER FUNCTION public.reconcile_eval_report2_work_v1(p_import_revision text, p_dry_run boolean, p_limit integer) OWNER TO postgres;

--
-- Name: FUNCTION reconcile_eval_report2_work_v1(p_import_revision text, p_dry_run boolean, p_limit integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.reconcile_eval_report2_work_v1(p_import_revision text, p_dry_run boolean, p_limit integer) IS 'Idempotently closes open Eval Reports #2 work as resolved_import when canonical data clears its originating report; no email is queued.';


--
-- Name: reconcile_request_folder_completion_window_v2(timestamp with time zone, timestamp with time zone, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reconcile_request_folder_completion_window_v2(p_from timestamp with time zone, p_to timestamp with time zone, p_dry_run boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  candidate record;
  result jsonb;
  eligible_count integer := 0;
  eligible_row_count integer := 0;
  queued_count integer := 0;
begin
  if not private.is_service_role_request() then
    raise exception using errcode = '42501', message = 'REQUEST_COMPLETION_RECONCILE_FORBIDDEN';
  end if;
  if p_from is null or p_to is null or p_to <= p_from or p_to - p_from > interval '8 days' then
    raise exception using errcode = '22023', message = 'REQUEST_COMPLETION_RECONCILE_WINDOW_INVALID';
  end if;

  for candidate in
    with active as (
      select trim(r.request_folder) as request_folder,
             count(*)::integer as active_count,
             bool_and(lower(trim(coalesce(r.req_status, ''))) in ('complete','completed','done')
               or nullif(trim(coalesce(r.date_completed, '')), '') is not null) as all_complete,
             max(private.try_timestamptz(r.date_completed)) as completed_at
      from public.ph_active_request r
      where trim(coalesce(r.request_folder, '')) <> ''
        and coalesce(r.req_archived, false) = false
        and lower(trim(coalesce(r.req_status, 'pending'))) not in ('archived','cancelled','canceled')
      group by trim(r.request_folder)
    )
    select active.request_folder, active.active_count
    from active
    left join private.ph_request_folder_delivery_state state
      on state.request_folder = active.request_folder
    where active.all_complete
      and active.completed_at >= p_from and active.completed_at < p_to
      and not exists (
        select 1
        from public.ph_request_delivery_outbox completion
        where completion.request_folder = active.request_folder
          and completion.event_type = 'request_completed'
          and completion.payload->>'contractVersion' = 'request-folder-completion-v2'
          and completion.status <> 'suppressed'
          and (state.request_folder is null
            or coalesce((completion.payload->>'membershipVersion')::bigint, 0) = state.membership_version)
      )
    order by active.request_folder
  loop
    eligible_count := eligible_count + 1;
    eligible_row_count := eligible_row_count + candidate.active_count;
    if not coalesce(p_dry_run, true) then
      result := private.reconcile_request_folder_completion_v2(candidate.request_folder);
      if coalesce((result->>'queued')::boolean, false) then queued_count := queued_count + 1; end if;
    end if;
  end loop;

  return jsonb_build_object(
    'contract_version', 'request-folder-completion-reconcile-v2',
    'dry_run', coalesce(p_dry_run, true),
    'eligible_folder_count', eligible_count,
    'eligible_row_count', eligible_row_count,
    'queued_folder_count', queued_count
  );
end
$$;


ALTER FUNCTION public.reconcile_request_folder_completion_window_v2(p_from timestamp with time zone, p_to timestamp with time zone, p_dry_run boolean) OWNER TO postgres;

--
-- Name: FUNCTION reconcile_request_folder_completion_window_v2(p_from timestamp with time zone, p_to timestamp with time zone, p_dry_run boolean); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.reconcile_request_folder_completion_window_v2(p_from timestamp with time zone, p_to timestamp with time zone, p_dry_run boolean) IS 'Service-only bounded and idempotent recovery for fully completed Request folders missing their V2 completion event.';


--
-- Name: reconcile_season_sales_office_v1(text[], boolean, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reconcile_season_sales_office_v1(p_itemcodes text[] DEFAULT NULL::text[], p_dry_run boolean DEFAULT true, p_import_revision text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'extensions'
    SET statement_timeout TO '60s'
    AS $_$
declare
  settings jsonb := private.season_sales_settings_v1();
  current_season text;
  current_sales_year integer;
  scope_hash text;
  prior_response jsonb;
  prior_hash text;
  winner public.ph_master_inventory;
  state_row public.ph_season_sales_office_state;
  evidence jsonb;
  current_cav_watermark timestamptz;
  newer_blank_at timestamptz;
  event_type text;
  reopen_reason_value text;
  expected_count integer := 0;
  open_count integer := 0;
  done_count integer := 0;
  create_count integer := 0;
  winner_change_count integer := 0;
  reopen_count integer := 0;
  retire_count integer := 0;
  mirror_upsert_count integer := 0;
  response_value jsonb;
begin
  perform set_config('lock_timeout', '2000', true);
  perform set_config('statement_timeout', '120000', true);
  current_season := upper(btrim(coalesce(settings->>'seasonCode', '')));
  current_sales_year := private.season_sales_year_v1(settings->>'salesYear');
  if current_season = '' or current_sales_year is null then
    raise exception using errcode = '22023', message = 'SEASON_SALES_SETTINGS_INVALID';
  end if;
  if p_idempotency_key is not null and (length(btrim(p_idempotency_key)) < 12 or length(btrim(p_idempotency_key)) > 180) then
    raise exception using errcode = '22023', message = 'SEASON_SALES_TOKEN_INVALID';
  end if;

  scope_hash := encode(digest(concat_ws('|', current_season, current_sales_year::text,
    coalesce(array_to_string(p_itemcodes, ','), '*'), coalesce(p_import_revision, '')), 'sha256'), 'hex');
  if not coalesce(p_dry_run, true) and p_idempotency_key is not null then
    select request.response, request.request_hash into prior_response, prior_hash
    from private.season_sales_office_idempotency request
    where request.operation = 'reconcile'
      and request.actor_username = 'service_role'
      and request.idempotency_key = btrim(p_idempotency_key);
    if prior_response is not null then
      if prior_hash is distinct from scope_hash then
        raise exception using errcode = '22023', message = 'SEASON_SALES_TOKEN_CONFLICT';
      end if;
      return prior_response;
    end if;
  end if;

  if coalesce(p_import_revision, '') like 'scheduled_maintenance:%' and exists (
    select 1 from public.app_dataset_revisions revision
    where revision.key = 'ph_master_inventory' and revision.state <> 'ready'
  ) then
    return jsonb_build_object('ok', true, 'status', 'maintenance_deferred',
      'code', 'DATASET_RECOVERY_IN_PROGRESS');
  end if;

  if coalesce(p_import_revision, '') like 'scheduled_maintenance:%' and exists (
    select 1 from public.ph_season_sales_office_events event
    where event.event_type = 'reconciled'
      and event.created_at > clock_timestamp() - interval '60 minutes'
  ) then
    return jsonb_build_object('ok', true, 'status', 'maintenance_deferred',
      'code', 'RECENT_RECONCILIATION');
  end if;

  if not pg_try_advisory_xact_lock(hashtextextended('season-sales-office-v1', 0)) then
    return jsonb_build_object('ok', true, 'status', 'maintenance_deferred',
      'code', 'MAINTENANCE_DEFERRED');
  end if;

  create temporary table if not exists season_sales_target_items_v1 (
    itemcode_normalized text primary key
  ) on commit drop;
  truncate season_sales_target_items_v1;
  if cardinality(coalesce(p_itemcodes, '{}'::text[])) > 0 then
    insert into season_sales_target_items_v1(itemcode_normalized)
    select distinct upper(btrim(requested.value))
    from unnest(p_itemcodes) requested(value)
    where btrim(coalesce(requested.value, '')) <> ''
      and (
        exists (
          select 1
          from public.ph_master_inventory scoped
          where upper(btrim(coalesce(scoped.itemcode, ''))) = upper(btrim(requested.value))
            and upper(btrim(coalesce(scoped.season, ''))) = current_season
            and private.season_sales_year_v1(scoped.saleyear) <= current_sales_year
            and lower(btrim(coalesce(scoped.app_tab_assignment, ''))) in ('season', 'location')
        )
        or exists (
          select 1
          from public.ph_season_sales_office_state state
          where state.season_code = current_season
            and state.sales_year = current_sales_year
            and state.itemcode_normalized = upper(btrim(requested.value))
        )
        or exists (
          select 1
          from public.ph_sales_office sales
          where lower(btrim(coalesce(sales.so_source, 'season'))) = 'season'
            and upper(btrim(coalesce(sales.itemcode, ''))) = upper(btrim(requested.value))
        )
      );
  else
    insert into season_sales_target_items_v1(itemcode_normalized)
    select distinct upper(btrim(m.itemcode))
    from public.ph_master_inventory m
    where btrim(coalesce(m.itemcode, '')) <> ''
      and upper(btrim(coalesce(m.season, ''))) = current_season
      and private.season_sales_year_v1(m.saleyear) <= current_sales_year
      and lower(btrim(coalesce(m.app_tab_assignment, ''))) in ('season', 'location')
    union
    select state.itemcode_normalized
    from public.ph_season_sales_office_state state
    where state.season_code = current_season and state.sales_year = current_sales_year
    union
    select distinct upper(btrim(sales.itemcode))
    from public.ph_sales_office sales
    where lower(btrim(coalesce(sales.so_source, 'season'))) = 'season'
      and btrim(coalesce(sales.itemcode, '')) <> '';
  end if;

  create temporary table if not exists season_sales_winners_v1 (
    itemcode_normalized text primary key,
    unique_id text not null
  ) on commit drop;
  truncate season_sales_winners_v1;
  insert into season_sales_winners_v1(itemcode_normalized, unique_id)
  select ranked.itemcode_normalized, ranked.unique_id
  from (
    select upper(btrim(m.itemcode)) itemcode_normalized, m.unique_id,
      row_number() over (
        partition by upper(btrim(m.itemcode))
        order by coalesce(private.season_sales_safe_numeric_v1(m.ptravailable), -1) desc,
          btrim(m.priority)::integer asc,
          private.eval_work_natural_sort_key_v1(m.locationcode),
          private.eval_work_natural_sort_key_v1(m.lotcode),
          m.unique_id
      ) winner_rank
    from public.ph_master_inventory m
    join season_sales_target_items_v1 target
      on target.itemcode_normalized = upper(btrim(m.itemcode))
    where upper(btrim(coalesce(m.season, ''))) = current_season
      and private.season_sales_year_v1(m.saleyear) <= current_sales_year
      and btrim(coalesce(m.priority, '')) ~ '^[1-4]$'
      and upper(btrim(coalesce(m.end_cap_folder, ''))) in ('', 'NULL', 'N/A', '-')
      and upper(coalesce(m.holdstopcode, '')) !~ '[HS]'
      and not private.season_sales_assignment_protected_v1(m.app_tab_assignment)
  ) ranked
  where ranked.winner_rank = 1;

  select count(*) into expected_count from season_sales_winners_v1;
  select count(*) into create_count
  from season_sales_winners_v1 winner_key
  left join public.ph_season_sales_office_state state
    on state.season_code = current_season and state.sales_year = current_sales_year
   and state.itemcode_normalized = winner_key.itemcode_normalized
  where state.id is null;
  select count(*) into winner_change_count
  from season_sales_winners_v1 winner_key
  join public.ph_season_sales_office_state state
    on state.season_code = current_season and state.sales_year = current_sales_year
   and state.itemcode_normalized = winner_key.itemcode_normalized
  where state.winner_unique_id <> winner_key.unique_id;
  select count(*) into retire_count
  from public.ph_season_sales_office_state state
  join season_sales_target_items_v1 target using (itemcode_normalized)
  left join season_sales_winners_v1 winner_key using (itemcode_normalized)
  where state.season_code = current_season and state.sales_year = current_sales_year
    and state.status <> 'retired' and winner_key.unique_id is null;

  select count(*) into reopen_count
  from public.ph_season_sales_office_state state
  join season_sales_winners_v1 winner_key using (itemcode_normalized)
  join public.ph_master_inventory m on m.unique_id = winner_key.unique_id
  where state.season_code = current_season
    and state.sales_year = current_sales_year
    and state.status = 'done'
    and state.winner_unique_id = winner_key.unique_id
    and (
      exists (
        select 1 from public.ph_cav_import c
        where upper(btrim(coalesce(c.itemcode, ''))) = state.itemcode_normalized
          and upper(btrim(coalesce(c.season, ''))) = current_season
          and btrim(coalesce(c.holdstopreason, '')) = ''
          and c.last_updated > coalesce(state.cav_watermark, state.completed_at, '-infinity'::timestamptz)
      )
      or m.av_rule_last_cleared_at > state.completed_at
      or (
        state.evidence_ready_seen_after_completion
        and not coalesce((private.season_sales_evidence_v1(to_jsonb(m) || jsonb_build_object('av_note', state.retained_av_note))->>'ready')::boolean, false)
      )
    );

  if coalesce(p_dry_run, true) then
    return jsonb_build_object('ok', true, 'status', 'dry_run',
      'seasonCode', current_season, 'salesYear', current_sales_year,
      'winnerCount', expected_count, 'newStateCount', create_count,
      'winnerChangeCount', winner_change_count, 'retireCount', retire_count,
      'reopenCount', reopen_count,
      'scopeCount', (select count(*) from season_sales_target_items_v1));
  end if;

  -- Keep Season/Location assignment classification authoritative for current
  -- scope rows, including H/S rows which are always Location Sales Notes.
  update public.ph_master_inventory m
  set app_tab_assignment = case when winner_key.unique_id = m.unique_id then 'season' else 'location' end,
      last_updated = coalesce(m.last_updated, now())
  from season_sales_target_items_v1 target
  left join season_sales_winners_v1 winner_key using (itemcode_normalized)
  where target.itemcode_normalized = upper(btrim(coalesce(m.itemcode, '')))
    and upper(btrim(coalesce(m.season, ''))) = current_season
    and private.season_sales_year_v1(m.saleyear) <= current_sales_year
    and upper(btrim(coalesce(m.end_cap_folder, ''))) in ('', 'NULL', 'N/A', '-')
    and not private.season_sales_assignment_protected_v1(m.app_tab_assignment)
    and m.app_tab_assignment is distinct from case when winner_key.unique_id = m.unique_id then 'season' else 'location' end;

  for winner in
    select m.*
    from season_sales_winners_v1 winner_key
    join public.ph_master_inventory m on m.unique_id = winner_key.unique_id
    order by winner_key.itemcode_normalized
  loop
    select * into state_row
    from public.ph_season_sales_office_state state
    where state.season_code = current_season and state.sales_year = current_sales_year
      and state.itemcode_normalized = upper(btrim(winner.itemcode))
    for update;
    if state_row.id is not null and state_row.winner_unique_id = winner.unique_id then
      perform private.clear_season_sales_av_note_for_reset_v1(winner);
      select * into state_row from public.ph_season_sales_office_state state where state.id = state_row.id;
      winner.av_note := state_row.retained_av_note;
    end if;
    evidence := private.season_sales_evidence_v1(to_jsonb(winner));
    select max(c.last_updated) into current_cav_watermark
    from public.ph_cav_import c
    where upper(btrim(coalesce(c.itemcode, ''))) = upper(btrim(winner.itemcode))
      and upper(btrim(coalesce(c.season, ''))) = current_season;
    event_type := null;
    reopen_reason_value := null;

    if state_row.id is null then
      insert into public.ph_season_sales_office_state (
        season_code, sales_year, itemcode_normalized, winner_unique_id,
        status, revision, readiness_status, current_evidence_snapshot,
        source_fingerprint, import_revision
      ) values (
        current_season, current_sales_year, upper(btrim(winner.itemcode)),
        winner.unique_id, 'open', 1, evidence->>'status', evidence,
        evidence->>'fingerprint', p_import_revision
      ) returning * into state_row;
      event_type := 'opened';
    elsif state_row.winner_unique_id <> winner.unique_id then
      update public.ph_season_sales_office_state state set
        winner_unique_id = winner.unique_id, status = 'open', revision = state.revision + 1,
        readiness_status = evidence->>'status', reopen_reason = 'winner_changed',
        completed_by = null, completed_at = null, cav_watermark = null,
        evidence_ready_at_completion = null, evidence_ready_seen_after_completion = false,
        completed_evidence_snapshot = null, current_evidence_snapshot = evidence,
        source_fingerprint = evidence->>'fingerprint', import_revision = p_import_revision,
        updated_at = now()
      where state.id = state_row.id returning * into state_row;
      event_type := 'winner_changed';
    else
      if state_row.status = 'done' then
        select max(c.last_updated) into newer_blank_at
        from public.ph_cav_import c
        where upper(btrim(coalesce(c.itemcode, ''))) = upper(btrim(winner.itemcode))
          and upper(btrim(coalesce(c.season, ''))) = current_season
          and btrim(coalesce(c.holdstopreason, '')) = ''
          and c.last_updated > coalesce(state_row.cav_watermark, state_row.completed_at, '-infinity'::timestamptz);
        if newer_blank_at is not null then
          reopen_reason_value := 'cav_blank';
        elsif nullif(to_jsonb(winner)->>'av_rule_last_cleared_at', '')::timestamptz > state_row.completed_at then
          reopen_reason_value := 'evidence_invalid';
        elsif state_row.evidence_ready_seen_after_completion
              and not coalesce((evidence->>'ready')::boolean, false) then
          reopen_reason_value := 'evidence_invalid';
        end if;
        if reopen_reason_value is not null then
          update public.ph_season_sales_office_state state set
            status = 'open', revision = state.revision + 1,
            readiness_status = case when reopen_reason_value = 'cav_blank'
              then 'reopened_cav_blank' else 'reopened_evidence_invalid' end,
            reopen_reason = reopen_reason_value, completed_by = null, completed_at = null,
            current_evidence_snapshot = evidence,
            source_fingerprint = evidence->>'fingerprint', import_revision = p_import_revision,
            updated_at = now()
          where state.id = state_row.id returning * into state_row;
          event_type := 'reopened';
          reopen_count := reopen_count + 1;
        else
          update public.ph_season_sales_office_state state set
            evidence_ready_seen_after_completion = state.evidence_ready_seen_after_completion
              or coalesce((evidence->>'ready')::boolean, false),
            current_evidence_snapshot = evidence,
            source_fingerprint = evidence->>'fingerprint', import_revision = p_import_revision,
            updated_at = now()
          where state.id = state_row.id returning * into state_row;
        end if;
      else
        update public.ph_season_sales_office_state state set
          status = 'open', readiness_status = case
            when state.reopen_reason = 'cav_blank' then 'reopened_cav_blank'
            when state.reopen_reason = 'evidence_invalid' then 'reopened_evidence_invalid'
            else evidence->>'status' end,
          current_evidence_snapshot = evidence,
          source_fingerprint = evidence->>'fingerprint', import_revision = p_import_revision,
          updated_at = now()
        where state.id = state_row.id returning * into state_row;
      end if;
    end if;

    if state_row.status = 'open' then
      perform private.season_sales_mirror_winner_v1(winner, state_row);
      mirror_upsert_count := mirror_upsert_count + 1;
      open_count := open_count + 1;
    else
      delete from public.ph_sales_office sales
      where lower(btrim(coalesce(sales.so_source, 'season'))) = 'season'
        and upper(btrim(coalesce(sales.itemcode, ''))) = upper(btrim(winner.itemcode));
      done_count := done_count + 1;
    end if;
    if event_type is not null then
      insert into public.ph_season_sales_office_events (
        state_id, event_type, actor_username, revision, reason_code, metadata
      ) values (
        state_row.id, event_type, 'service_role', state_row.revision,
        coalesce(reopen_reason_value, state_row.reopen_reason),
        jsonb_build_object('seasonCode', current_season, 'salesYear', current_sales_year,
          'importRevision', p_import_revision)
      );
    end if;
  end loop;

  for state_row in
    select state.* from public.ph_season_sales_office_state state
    join season_sales_target_items_v1 target using (itemcode_normalized)
    left join season_sales_winners_v1 winner_key using (itemcode_normalized)
    where state.season_code = current_season and state.sales_year = current_sales_year
      and winner_key.unique_id is null and state.status <> 'retired'
    for update of state
  loop
    update public.ph_season_sales_office_state state set
      status = 'retired', revision = state.revision + 1,
      readiness_status = 'retired', reopen_reason = null,
      import_revision = p_import_revision, updated_at = now()
    where state.id = state_row.id returning * into state_row;
    delete from public.ph_sales_office sales
    where lower(btrim(coalesce(sales.so_source, 'season'))) = 'season'
      and upper(btrim(coalesce(sales.itemcode, ''))) = state_row.itemcode_normalized;
    insert into public.ph_season_sales_office_events (
      state_id, event_type, actor_username, revision, reason_code, metadata
    ) values (state_row.id, 'retired', 'service_role', state_row.revision,
      'no_current_winner', jsonb_build_object('importRevision', p_import_revision));
  end loop;

  -- ph_sales_office is the open-work mirror only. Remove legacy Season rows
  -- that are no longer the current open lifecycle winner.
  delete from public.ph_sales_office sales
  using season_sales_target_items_v1 target
  where lower(btrim(coalesce(sales.so_source, 'season'))) = 'season'
    and target.itemcode_normalized = upper(btrim(coalesce(sales.itemcode, '')))
    and not exists (
      select 1
      from public.ph_season_sales_office_state state
      where state.season_code = current_season
        and state.sales_year = current_sales_year
        and state.status = 'open'
        and state.winner_unique_id = coalesce(sales.master_id, sales.unique_id)
    );

  response_value := jsonb_build_object('ok', true, 'status', 'completed',
    'seasonCode', current_season, 'salesYear', current_sales_year,
    'winnerCount', expected_count, 'openCount', open_count, 'doneCount', done_count,
    'newStateCount', create_count, 'winnerChangeCount', winner_change_count,
    'reopenCount', reopen_count, 'retireCount', retire_count,
    'mirrorUpsertCount', mirror_upsert_count, 'scopeHash', scope_hash);
  if p_idempotency_key is not null then
    insert into private.season_sales_office_idempotency (
      operation, actor_username, idempotency_key, request_hash, response
    ) values ('reconcile', 'service_role', btrim(p_idempotency_key), scope_hash, response_value)
    on conflict (operation, actor_username, idempotency_key) do nothing;
  end if;
  insert into public.ph_season_sales_office_events (
    state_id, event_type, actor_username, metadata
  ) values (null, 'reconciled', 'service_role', response_value - 'scopeHash');
  return response_value;
exception
  when lock_not_available or query_canceled then
    return jsonb_build_object('ok', true, 'status', 'maintenance_deferred',
      'code', 'MAINTENANCE_DEFERRED');
end
$_$;


ALTER FUNCTION public.reconcile_season_sales_office_v1(p_itemcodes text[], p_dry_run boolean, p_import_revision text, p_idempotency_key text) OWNER TO postgres;

--
-- Name: record_pikes_order_import_failure(text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_pikes_order_import_failure(p_drive_file_id text, p_content_sha256 text, p_sanitized_error_code text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
declare
  target public.ph_pikes_order_batches%rowtype;
begin
  if coalesce(p_sanitized_error_code, '') !~ '^PIKES_[A-Z0-9_]{3,100}$' then
    raise exception 'PIKES_IMPORT_ERROR_CODE_INVALID';
  end if;
  update public.ph_pikes_order_batches
  set status = 'failed', last_error_code = p_sanitized_error_code, updated_at = now()
  where drive_file_id = p_drive_file_id
    and content_sha256 = p_content_sha256
    and status = 'importing'
  returning * into target;
  return jsonb_build_object('recorded', found, 'batchId', target.batch_id, 'status', target.status);
end;
$_$;


ALTER FUNCTION public.record_pikes_order_import_failure(p_drive_file_id text, p_content_sha256 text, p_sanitized_error_code text) OWNER TO postgres;

--
-- Name: record_request_delivery_channel_result(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_request_delivery_channel_result(p_event_id uuid, p_lease_token uuid, p_channel_results jsonb) RETURNS public.ph_request_delivery_outbox
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  updated_event public.ph_request_delivery_outbox%rowtype;
  email_result jsonb := coalesce(p_channel_results->'email', '{}'::jsonb);
  push_result jsonb := coalesce(p_channel_results->'push', '{}'::jsonb);
begin
  if not private.is_service_role_request() then
    raise exception using errcode = '42501', message = 'DELIVERY_WORKER_FORBIDDEN';
  end if;
  if p_channel_results is null or jsonb_typeof(p_channel_results) <> 'object' then
    raise exception using errcode = '22023', message = 'DELIVERY_CHANNEL_RESULT_INVALID';
  end if;

  update public.ph_request_delivery_outbox o
  set email_delivered_at = case
        when nullif(email_result->>'delivered_at', '') is not null
          then (email_result->>'delivered_at')::timestamptz
        else o.email_delivered_at end,
      push_delivered_at = case
        when nullif(push_result->>'delivered_at', '') is not null
          then (push_result->>'delivered_at')::timestamptz
        else o.push_delivered_at end,
      gmail_message_id = coalesce(nullif(email_result->>'gmail_message_id', ''), o.gmail_message_id),
      gmail_thread_id = coalesce(nullif(email_result->>'thread_id', ''), o.gmail_thread_id),
      message_id_header = coalesce(nullif(email_result->>'message_id_header', ''), o.message_id_header),
      delivery_mode = coalesce(nullif(email_result->>'mode', ''), nullif(push_result->>'mode', ''), o.delivery_mode),
      channel_results = coalesce(o.channel_results, '{}'::jsonb) || p_channel_results,
      lease_expires_at = now() + interval '2 minutes'
  where o.event_id = p_event_id
    and o.status = 'processing'
    and o.lease_token = p_lease_token
  returning o.* into updated_event;

  if not found then
    raise exception using errcode = '40001', message = 'DELIVERY_LEASE_LOST';
  end if;
  return updated_event;
end;
$$;


ALTER FUNCTION public.record_request_delivery_channel_result(p_event_id uuid, p_lease_token uuid, p_channel_results jsonb) OWNER TO postgres;

--
-- Name: record_transactions_keyed_import_failure(text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_transactions_keyed_import_failure(source_drive_file_id text, source_content_sha256 text, sanitized_error_code text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  safe_file_id text := btrim(coalesce(source_drive_file_id, ''));
  safe_hash text := lower(btrim(coalesce(source_content_sha256, '')));
  safe_error_code text := left(upper(regexp_replace(coalesce(sanitized_error_code, 'IMPORT_FAILED'), '[^A-Za-z0-9_]+', '_', 'g')), 80);
  current_status text;
begin
  update public.ph_transactions_keyed_files
  set status = case when status in ('archive_pending', 'duplicate_archive_pending') then status else 'failed' end,
      last_error_code = coalesce(nullif(safe_error_code, ''), 'IMPORT_FAILED'),
      updated_at = now()
  where drive_file_id = safe_file_id and content_sha256 = safe_hash
  returning status into current_status;

  return jsonb_build_object(
    'status', coalesce(current_status, 'missing'),
    'driveFileId', safe_file_id,
    'errorCode', coalesce(nullif(safe_error_code, ''), 'IMPORT_FAILED')
  );
end;
$$;


ALTER FUNCTION public.record_transactions_keyed_import_failure(source_drive_file_id text, source_content_sha256 text, sanitized_error_code text) OWNER TO postgres;

--
-- Name: refresh_photo_history_catalog_v1(boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.refresh_photo_history_catalog_v1(p_dry_run boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET statement_timeout TO '45s'
    AS $_$
declare n bigint; changed bigint;
begin
  if not private.is_service_role_request() then
    raise exception using errcode='42501',message='PHOTO_HISTORY_FORBIDDEN'; end if;
  if not pg_try_advisory_xact_lock(hashtextextended('photo-history-index-v1',0)) then
    return jsonb_build_object('ok',true,'status','busy'); end if;
  select count(*) into n from storage.objects where bucket_id in
    ('request_photos','flyer_photos','season_sales_notes_photos','location_sales_notes_photos')
    and name !~ '^_thumbs/' and name ~* '\.(jpe?g|png|webp|heic|heif)$';
  if p_dry_run then return jsonb_build_object('ok',true,'sourcePhotoCount',n,'metadataOnly',true); end if;
  if exists(select 1 from public.ph_photo_history_index_state where refreshed_at>now()-interval '15 minutes') then
    return jsonb_build_object('ok',true,'status','fresh','sourcePhotoCount',n); end if;
  with source_rows as materialized (
    select to_jsonb(m) j from public.ph_master_inventory m
    union all select to_jsonb(a) from public.ph_active_request a
    union all select coalesce(h.snapshot,'{}'::jsonb)||jsonb_strip_nulls(to_jsonb(h)) from public.ph_request_history h
    union all select coalesce(f.snapshot,'{}'::jsonb)||jsonb_strip_nulls(to_jsonb(f)) from public.ph_flyer_folder_history f
    union all select coalesce(p.snapshot,'{}'::jsonb)||jsonb_strip_nulls(to_jsonb(p)) from public.ph_productivity_history p
  ), refs as materialized (
    select split_part(regexp_replace(btrim(u), '^https://[^/]+/storage/v1/(object|render/image)/public/', ''),'?',1) source_key,
      jsonb_build_object('itemcode',coalesce(j->>'itemcode',''),'commonname',coalesce(j->>'commonname',''),
       'contsize',coalesce(j->>'contsize',''),'locationcode',coalesce(j->>'locationcode',''),'lotcode',coalesce(j->>'lotcode','')) context
    from source_rows cross join lateral regexp_split_to_table(concat_ws(',',j->>'photo_link',j->>'req_photo_link',j->>'flyer_photo_link'),E'[,\n]+') u
    where u ~ '^https://[^/]+/storage/v1/(object|render/image)/public/'
  ), reference_groups as (
    select source_key,jsonb_agg(distinct context) contexts from refs group by source_key
  ), objects as (
    select o.bucket_id bucket,o.name path,o.created_at photo_at,true storage_available,a.drive_file_id,
      a.drive_file_name from storage.objects o left join public.ph_photo_archive_jobs a
      on a.source_bucket=o.bucket_id and a.source_path=o.name
    where o.bucket_id in ('request_photos','flyer_photos','season_sales_notes_photos','location_sales_notes_photos')
      and o.name !~ '^_thumbs/' and o.name ~* '\.(jpe?g|png|webp|heic|heif)$'
    union all
    select a.source_bucket,a.source_path,coalesce(a.source_created_at,a.created_at),false,a.drive_file_id,a.drive_file_name
    from public.ph_photo_archive_jobs a where nullif(a.drive_file_id,'') is not null and a.verified_at is not null
      and a.source_bucket in ('request_photos','flyer_photos','season_sales_notes_photos','location_sales_notes_photos')
      and not exists(select 1 from storage.objects o where o.bucket_id=a.source_bucket and o.name=a.source_path)
  ), catalog as (
    select o.*,o.bucket||'/'||o.path source_key,
      coalesce(r.contexts,'[]') contexts,
      coalesce((select c from jsonb_array_elements(r.contexts)c order by
         (nullif(c->>'commonname','') is not null) desc,c->>'commonname',c->>'itemcode',c->>'locationcode',c->>'lotcode' limit 1),'{}') c,
      regexp_replace(o.path,'^.*/','') filename
    from objects o left join reference_groups r on r.source_key=o.bucket||'/'||o.path
  )
  insert into public.ph_photo_history_assets(source_key,bucket,path,filename,photo_at,itemcode,commonname,contsize,
    locationcode,lotcode,contexts,search_text,storage_available,drive_file_id)
  select source_key,bucket,path,filename,photo_at,coalesce(c->>'itemcode',''),coalesce(c->>'commonname',''),
    coalesce(c->>'contsize',''),coalesce(c->>'locationcode',''),coalesce(c->>'lotcode',''),contexts,
    lower(concat_ws(' ',filename,drive_file_name,contexts::text))||' '||regexp_replace(lower(concat_ws(' ',filename,contexts::text)),'[^a-z0-9]','','g'),
    storage_available,drive_file_id from catalog
  on conflict(source_key) do update set
    storage_available=excluded.storage_available,drive_file_id=coalesce(excluded.drive_file_id,ph_photo_history_assets.drive_file_id),
    -- Retain known plant labels when a historical source row is subsequently removed.
    itemcode=coalesce(nullif(excluded.itemcode,''),ph_photo_history_assets.itemcode),
    commonname=coalesce(nullif(excluded.commonname,''),ph_photo_history_assets.commonname),
    contsize=coalesce(nullif(excluded.contsize,''),ph_photo_history_assets.contsize),
    locationcode=coalesce(nullif(excluded.locationcode,''),ph_photo_history_assets.locationcode),
    lotcode=coalesce(nullif(excluded.lotcode,''),ph_photo_history_assets.lotcode),
    contexts=case when excluded.contexts='[]' then ph_photo_history_assets.contexts else excluded.contexts end,
    search_text=case when excluded.contexts='[]' then ph_photo_history_assets.search_text else excluded.search_text end,
    indexed_at=now()
  where ph_photo_history_assets.storage_available is distinct from excluded.storage_available
    or (excluded.drive_file_id is not null and ph_photo_history_assets.drive_file_id is distinct from excluded.drive_file_id)
    or (excluded.contexts<>'[]' and ph_photo_history_assets.contexts is distinct from excluded.contexts);
  get diagnostics changed=row_count;
  update public.ph_photo_history_assets a set storage_available=false,indexed_at=now()
  where a.storage_available and not exists(select 1 from storage.objects o where o.bucket_id=a.bucket and o.name=a.path);
  update public.ph_photo_history_index_state set refreshed_at=now(),asset_count=(select count(*) from public.ph_photo_history_assets) where singleton = true;
  return jsonb_build_object('ok',true,'status','refreshed','indexed',changed,'metadataOnly',true);
end $_$;


ALTER FUNCTION public.refresh_photo_history_catalog_v1(p_dry_run boolean) OWNER TO postgres;

--
-- Name: refresh_season_sales_office_v1(text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.refresh_season_sales_office_v1(p_actor_username text, p_itemcode text, p_import_revision text, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor public.profiles := private.season_sales_assert_actor_v1(p_actor_username);
  normalized_itemcode text := upper(btrim(coalesce(p_itemcode, '')));
begin
  if normalized_itemcode = '' then
    raise exception using errcode = '22023', message = 'SEASON_SALES_NOT_FOUND';
  end if;
  return private.refresh_eligible_season_sales_itemcode_v1(
    normalized_itemcode,
    left(coalesce(nullif(btrim(p_import_revision), ''), 'client-refresh'), 180),
    p_idempotency_key
  );
end
$$;


ALTER FUNCTION public.refresh_season_sales_office_v1(p_actor_username text, p_itemcode text, p_import_revision text, p_idempotency_key text) OWNER TO postgres;

--
-- Name: refresh_v2_crop_roll_completed_drive_keys(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.refresh_v2_crop_roll_completed_drive_keys() RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'private', 'vault', 'pg_temp'
    AS $$
begin
  truncate table public.ph_crop_roll_completed_drive_keys;

  insert into public.ph_crop_roll_completed_drive_keys (
    completion_row_id, match_key, key_type, master_unique_id, itemcode, locationcode, lotcode, contsize, updated_at
  )
  select
    coalesce(nullif(btrim(c.row_id), ''), 'no-row:' || md5(to_jsonb(c)::text)),
    k.match_key, k.key_type, k.master_unique_id, k.itemcode, k.locationcode, k.lotcode, k.contsize, now()
  from public.ph_crop_roll_rows c
  cross join lateral public.v2_crop_roll_completion_key_rows(to_jsonb(c)) k
  where c.run_id = 'CR-LIVE-COMPLETIONS'
    and lower(coalesce(c.row_status, '')) = 'complete'
  on conflict (completion_row_id, match_key) do update set
    key_type = excluded.key_type,
    master_unique_id = excluded.master_unique_id,
    itemcode = excluded.itemcode,
    locationcode = excluded.locationcode,
    lotcode = excluded.lotcode,
    contsize = excluded.contsize,
    updated_at = now();
end;
$$;


ALTER FUNCTION public.refresh_v2_crop_roll_completed_drive_keys() OWNER TO postgres;

--
-- Name: repair_pikes_order_batch_assignments_v1(uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.repair_pikes_order_batch_assignments_v1(p_batch_id uuid, p_dry_run boolean, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  target public.ph_pikes_order_batches%rowtype;
  prior jsonb;
  eligible_count integer := 0;
  corrected_count integer := 0;
  ambiguous_count integer := 0;
  newer_count integer := 0;
  no_match_count integer := 0;
  repair_fingerprint text;
  response jsonb;
begin
  if p_batch_id is null
     or coalesce(p_idempotency_key, '') !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,127}$' then
    raise exception 'PIKES_ASSIGNMENT_REPAIR_INVALID_REQUEST';
  end if;

  select * into target
  from public.ph_pikes_order_batches b
  where b.batch_id = p_batch_id
  for update;
  if not found or target.status not in ('archive_pending', 'processed') then
    raise exception 'PIKES_ASSIGNMENT_REPAIR_BATCH_NOT_READY';
  end if;

  select a.result into prior
  from public.ph_pikes_order_assignment_repair_audit a
  where a.batch_id = p_batch_id and a.idempotency_key = p_idempotency_key;
  if found then
    return prior || jsonb_build_object('replayed', true);
  end if;

  with resolved as (
    select * from private.resolve_pikes_order_assignment_repair_v1(p_batch_id)
  )
  select
    count(*) filter (where resolution = 'eligible')::integer,
    count(*) filter (where resolution = 'ambiguous')::integer,
    count(*) filter (where resolution = 'newer')::integer,
    count(*) filter (where resolution = 'no_match')::integer,
    md5(coalesce(string_agg(
      master_unique_id || ':' || coalesce(assignedto, '') || ':' || resolution,
      '|' order by master_unique_id
    ), ''))
  into eligible_count, ambiguous_count, newer_count, no_match_count, repair_fingerprint
  from resolved;

  if coalesce(p_dry_run, false) then
    return jsonb_build_object(
      'status', 'dry_run',
      'eligibleCount', eligible_count,
      'correctedCount', 0,
      'ambiguousCount', ambiguous_count,
      'newerCount', newer_count,
      'noMatchCount', no_match_count,
      'fingerprint', repair_fingerprint,
      'replayed', false
    );
  end if;

  with eligible as (
    select *
    from private.resolve_pikes_order_assignment_repair_v1(p_batch_id)
    where resolution = 'eligible'
  ), corrected as (
    update public.ph_pikes_order_inventory_rows i
    set assignedto = e.assignedto,
        assignment_authority_key = e.assignment_authority_key,
        assignment_authority_assigned_at = e.assignment_authority_assigned_at,
        assignment_match_method = e.assignment_match_method
    from eligible e
    where i.batch_id = p_batch_id
      and i.master_unique_id = e.master_unique_id
      and nullif(btrim(coalesce(i.assignedto, '')), '') is null
    returning 1
  )
  select count(*)::integer into corrected_count from corrected;

  response := jsonb_build_object(
    'status', 'completed',
    'eligibleCount', eligible_count,
    'correctedCount', corrected_count,
    'ambiguousCount', ambiguous_count,
    'newerCount', newer_count,
    'noMatchCount', no_match_count,
    'fingerprint', repair_fingerprint,
    'replayed', false
  );

  insert into public.ph_pikes_order_assignment_repair_audit (
    batch_id, idempotency_key, repair_fingerprint, eligible_count,
    corrected_count, ambiguous_count, newer_count, no_match_count, result
  ) values (
    p_batch_id, p_idempotency_key, repair_fingerprint, eligible_count,
    corrected_count, ambiguous_count, newer_count, no_match_count, response
  );

  return response;
end;
$_$;


ALTER FUNCTION public.repair_pikes_order_batch_assignments_v1(p_batch_id uuid, p_dry_run boolean, p_idempotency_key text) OWNER TO postgres;

--
-- Name: repair_request_drive_evidence_v1(text[], boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.repair_request_drive_evidence_v1(p_request_ids text[], p_dry_run boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  candidate record;
  eligible_count integer := 0;
  repaired_count integer := 0;
  skipped_newer_count integer := 0;
  affected_count integer := 0;
  completed_at timestamptz;
  raw_mismatch boolean;
  repair_spec boolean;
  repair_caliper boolean;
  repair_match boolean;
  repair_pic_note boolean;
  repair_av_note boolean;
  repair_photo_link boolean;
  repair_photo_name boolean;
begin
  if not private.is_service_role_request() then
    raise exception using errcode = '42501', message = 'REQUEST_DRIVE_REPAIR_FORBIDDEN';
  end if;
  if cardinality(coalesce(p_request_ids, '{}'::text[])) < 1
     or cardinality(p_request_ids) > 100 then
    raise exception using errcode = '22023', message = 'REQUEST_DRIVE_REPAIR_SCOPE_INVALID';
  end if;

  for candidate in
    with latest_completion as (
      select distinct on (history.master_id)
        history.*,
        master.spec as master_spec,
        master.caliper as master_caliper,
        master.match as master_match,
        master.pic_note as master_pic_note,
        master.av_note as master_av_note,
        master.photo_link as master_photo_link,
        master.photo_name as master_photo_name,
        master.av_rule_last_cleared_at,
        master.av_rule_last_clear_reason,
        master.av_rule_bundle_updated_at,
        master.av_rule_av_note_updated_at,
        master.av_rule_spec_updated_at,
        master.av_rule_match_updated_at,
        master.av_rule_caliper_updated_at,
        master.av_rule_photo_updated_at
      from public.ph_request_history history
      join public.ph_master_inventory master on master.unique_id = history.master_id
      where lower(btrim(coalesce(history.req_status, ''))) in ('complete','completed','done')
      order by history.master_id, history.date_completed desc nulls last, history.updated_at desc nulls last
    )
    select completion.*
    from latest_completion completion
    where completion.unique_id = any(p_request_ids)
    order by completion.master_id
  loop
    completed_at := coalesce(candidate.date_completed, candidate.updated_at);
    raw_mismatch :=
      (nullif(btrim(candidate.req_spec), '') is not null and coalesce(btrim(candidate.req_spec), '') is distinct from coalesce(btrim(candidate.master_spec), ''))
      or (nullif(btrim(candidate.req_caliper), '') is not null and coalesce(btrim(candidate.req_caliper), '') is distinct from coalesce(btrim(candidate.master_caliper), ''))
      or (nullif(btrim(candidate.req_match), '') is not null and coalesce(btrim(candidate.req_match), '') is distinct from coalesce(btrim(candidate.master_match), ''))
      or (nullif(btrim(candidate.req_pic_note), '') is not null and coalesce(btrim(candidate.req_pic_note), '') is distinct from coalesce(btrim(candidate.master_pic_note), ''))
      or (nullif(btrim(candidate.av_note), '') is not null and coalesce(btrim(candidate.av_note), '') is distinct from coalesce(btrim(candidate.master_av_note), ''))
      or (nullif(btrim(candidate.req_photo_link), '') is not null and coalesce(btrim(candidate.req_photo_link), '') is distinct from coalesce(btrim(candidate.master_photo_link), ''))
      or (nullif(btrim(candidate.req_photo_name), '') is not null and coalesce(btrim(candidate.req_photo_name), '') is distinct from coalesce(btrim(candidate.master_photo_name), ''));

    if not raw_mismatch then
      continue;
    end if;
    -- An equal or later shared reset supersedes the old completion evidence.
    if candidate.av_rule_last_cleared_at is not null
       and candidate.av_rule_last_cleared_at >= completed_at then
      skipped_newer_count := skipped_newer_count + 1;
      continue;
    end if;
    if candidate.av_rule_bundle_updated_at is not null
       and candidate.av_rule_bundle_updated_at > completed_at then
      skipped_newer_count := skipped_newer_count + 1;
      continue;
    end if;

    repair_spec := nullif(btrim(candidate.req_spec), '') is not null
      and coalesce(btrim(candidate.req_spec), '') is distinct from coalesce(btrim(candidate.master_spec), '')
      and (candidate.av_rule_spec_updated_at is null or candidate.av_rule_spec_updated_at <= completed_at);
    repair_caliper := nullif(btrim(candidate.req_caliper), '') is not null
      and coalesce(btrim(candidate.req_caliper), '') is distinct from coalesce(btrim(candidate.master_caliper), '')
      and (candidate.av_rule_caliper_updated_at is null or candidate.av_rule_caliper_updated_at <= completed_at);
    repair_match := nullif(btrim(candidate.req_match), '') is not null
      and coalesce(btrim(candidate.req_match), '') is distinct from coalesce(btrim(candidate.master_match), '')
      and (candidate.av_rule_match_updated_at is null or candidate.av_rule_match_updated_at <= completed_at);
    repair_pic_note := nullif(btrim(candidate.req_pic_note), '') is not null
      and coalesce(btrim(candidate.req_pic_note), '') is distinct from coalesce(btrim(candidate.master_pic_note), '');
    repair_av_note := nullif(btrim(candidate.av_note), '') is not null
      and coalesce(btrim(candidate.av_note), '') is distinct from coalesce(btrim(candidate.master_av_note), '')
      and (candidate.av_rule_av_note_updated_at is null or candidate.av_rule_av_note_updated_at <= completed_at);
    repair_photo_link := nullif(btrim(candidate.req_photo_link), '') is not null
      and coalesce(btrim(candidate.req_photo_link), '') is distinct from coalesce(btrim(candidate.master_photo_link), '')
      and (candidate.av_rule_photo_updated_at is null or candidate.av_rule_photo_updated_at <= completed_at);
    repair_photo_name := nullif(btrim(candidate.req_photo_name), '') is not null
      and coalesce(btrim(candidate.req_photo_name), '') is distinct from coalesce(btrim(candidate.master_photo_name), '')
      and (candidate.av_rule_photo_updated_at is null or candidate.av_rule_photo_updated_at <= completed_at);

    if not (repair_spec or repair_caliper or repair_match or repair_pic_note or repair_av_note or repair_photo_link or repair_photo_name) then
      skipped_newer_count := skipped_newer_count + 1;
      continue;
    end if;
    eligible_count := eligible_count + 1;

    if not coalesce(p_dry_run, true) then
      update public.ph_master_inventory as master
      set spec = case when repair_spec then nullif(btrim(candidate.req_spec), '') else master.spec end,
          caliper = case when repair_caliper then nullif(btrim(candidate.req_caliper), '') else master.caliper end,
          match = case when repair_match then nullif(btrim(candidate.req_match), '') else master.match end,
          pic_note = case when repair_pic_note then nullif(btrim(candidate.req_pic_note), '') else master.pic_note end,
          av_note = case when repair_av_note then nullif(btrim(candidate.av_note), '') else master.av_note end,
          photo_link = case when repair_photo_link then nullif(btrim(candidate.req_photo_link), '') else master.photo_link end,
          photo_name = case when repair_photo_name then nullif(btrim(candidate.req_photo_name), '') else master.photo_name end,
          av_rule_bundle_updated_at = completed_at,
          av_rule_av_note_updated_at = case when repair_av_note then completed_at else master.av_rule_av_note_updated_at end,
          av_rule_spec_updated_at = case when repair_spec then completed_at else master.av_rule_spec_updated_at end,
          av_rule_match_updated_at = case when repair_match then completed_at else master.av_rule_match_updated_at end,
          av_rule_caliper_updated_at = case when repair_caliper then completed_at else master.av_rule_caliper_updated_at end,
          av_rule_photo_updated_at = case when repair_photo_link or repair_photo_name then completed_at else master.av_rule_photo_updated_at end,
          last_updated = now()
      where master.unique_id = candidate.master_id
        and master.av_rule_last_cleared_at is not distinct from candidate.av_rule_last_cleared_at
        and master.av_rule_last_clear_reason is not distinct from candidate.av_rule_last_clear_reason
        and master.av_rule_bundle_updated_at is not distinct from candidate.av_rule_bundle_updated_at
        and (not repair_spec or (master.spec is not distinct from candidate.master_spec and master.av_rule_spec_updated_at is not distinct from candidate.av_rule_spec_updated_at))
        and (not repair_caliper or (master.caliper is not distinct from candidate.master_caliper and master.av_rule_caliper_updated_at is not distinct from candidate.av_rule_caliper_updated_at))
        and (not repair_match or (master.match is not distinct from candidate.master_match and master.av_rule_match_updated_at is not distinct from candidate.av_rule_match_updated_at))
        and (not repair_pic_note or master.pic_note is not distinct from candidate.master_pic_note)
        and (not repair_av_note or (master.av_note is not distinct from candidate.master_av_note and master.av_rule_av_note_updated_at is not distinct from candidate.av_rule_av_note_updated_at))
        and (not (repair_photo_link or repair_photo_name) or (master.photo_link is not distinct from candidate.master_photo_link and master.photo_name is not distinct from candidate.master_photo_name and master.av_rule_photo_updated_at is not distinct from candidate.av_rule_photo_updated_at));
      get diagnostics affected_count = row_count;
      if affected_count = 1 then
        repaired_count := repaired_count + 1;
      else
        skipped_newer_count := skipped_newer_count + 1;
      end if;
    end if;
  end loop;

  return jsonb_build_object(
    'contract_version', 'request-drive-evidence-repair-v1',
    'dry_run', coalesce(p_dry_run, true),
    'eligible_count', eligible_count,
    'repaired_count', repaired_count,
    'skipped_newer_count', skipped_newer_count
  );
end
$$;


ALTER FUNCTION public.repair_request_drive_evidence_v1(p_request_ids text[], p_dry_run boolean) OWNER TO postgres;

--
-- Name: FUNCTION repair_request_drive_evidence_v1(p_request_ids text[], p_dry_run boolean); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.repair_request_drive_evidence_v1(p_request_ids text[], p_dry_run boolean) IS 'Service-only bounded repair. Never clears a master field from empty history and uses optimistic reset/timestamp/value guards against concurrent or newer writes.';


--
-- Name: report_app_health_event(text, text, text, text, integer, numeric, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.report_app_health_event(event_name text, area text, severity text, sanitized_code text DEFAULT NULL::text, duration_ms integer DEFAULT NULL::integer, sample_rate numeric DEFAULT 1, app_build text DEFAULT NULL::text, metadata jsonb DEFAULT '{}'::jsonb) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  profile public.profiles%rowtype;
  safe_metadata jsonb;
  event_id bigint;
begin
  profile := private.current_active_profile();
  if profile.id is null then
    raise exception using errcode = '42501', message = 'ACTIVE_PROFILE_REQUIRED';
  end if;
  if nullif(btrim(coalesce(event_name, '')), '') is null then
    raise exception using errcode = '22023', message = 'HEALTH_EVENT_NAME_REQUIRED';
  end if;

  safe_metadata := case when jsonb_typeof(coalesce(metadata, '{}'::jsonb)) = 'object'
    then coalesce(metadata, '{}'::jsonb)
      - array[
          'customer', 'customer_name', 'notes', 'note', 'photo', 'photos',
          'url', 'urls', 'endpoint', 'request', 'requests', 'payload',
          'commonname', 'display_name', 'email', 'name'
        ]::text[]
    else '{}'::jsonb end;
  if octet_length(safe_metadata::text) > 4096 then
    safe_metadata := jsonb_build_object('metadata_truncated', true);
  end if;

  insert into public.ph_app_health_events (
    profile_id, username, event_name, area, severity, sanitized_code,
    duration_ms, sample_rate, app_build, metadata
  ) values (
    profile.id, profile.username, left(event_name, 120), left(coalesce(area, 'app'), 80),
    case when lower(coalesce(severity, 'error')) in ('info', 'warning', 'error', 'critical')
      then lower(coalesce(severity, 'error')) else 'error' end,
    left(sanitized_code, 160), greatest(0, duration_ms),
    least(1, greatest(0, coalesce(sample_rate, 1))), left(app_build, 80), safe_metadata
  ) returning id into event_id;
  return event_id;
end;
$$;


ALTER FUNCTION public.report_app_health_event(event_name text, area text, severity text, sanitized_code text, duration_ms integer, sample_rate numeric, app_build text, metadata jsonb) OWNER TO postgres;

--
-- Name: request_codex_ops_escalation_v1(uuid, integer, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.request_codex_ops_escalation_v1(p_task_id uuid, p_expected_revision integer, p_reason text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  profile public.profiles%rowtype;
  task private.codex_ops_tasks%rowtype;
begin
  profile := private.require_codex_ops_dylan_v1();
  select * into task from private.codex_ops_tasks t where t.id = p_task_id and t.created_by = profile.id for update;
  if task.id is null then raise exception using errcode = 'P0002', message = 'CODEX_OPS_TASK_NOT_FOUND'; end if;
  if task.revision <> p_expected_revision then raise exception using errcode = '40001', message = 'CODEX_OPS_REVISION_CONFLICT'; end if;
  if task.status <> 'needs_escalation' then raise exception using errcode = '55000', message = 'CODEX_OPS_ESCALATION_NOT_AVAILABLE'; end if;
  insert into private.codex_ops_messages (task_id, actor_type, actor_username, body, client_idempotency_key)
  values (task.id, 'user', 'dylan_collyge', left(btrim(coalesce(p_reason, 'Request read-only Sol review.')), 12000), p_idempotency_key);
  update private.codex_ops_tasks set revision = revision + 1, status = 'queued', updated_at = now()
  where id = task.id returning * into task;
  insert into private.codex_ops_events (task_id, revision, event_type, sanitized_payload)
  values (task.id, task.revision, 'escalation.requested', jsonb_build_object('model', 'gpt-5.6-sol', 'mode', 'read-only'));
  return jsonb_build_object('id', task.id, 'status', task.status, 'revision', task.revision, 'action', 'sol_review');
end;
$$;


ALTER FUNCTION public.request_codex_ops_escalation_v1(p_task_id uuid, p_expected_revision integer, p_reason text, p_idempotency_key uuid) OWNER TO postgres;

--
-- Name: request_history_command_v1(uuid, text, jsonb, uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.request_history_command_v1(p_actor_id uuid, p_operation text, p_payload jsonb DEFAULT '{}'::jsonb, p_command_id uuid DEFAULT NULL::uuid, p_expected_revision bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor public.profiles;
  result jsonb;
  rep_scoped boolean;
  actor_key text;
  credit_allowed boolean := false;
  lim integer:=least(100,greatest(1,coalesce((p_payload->>'limit')::integer,40)));
  q text:=sales_private.key(p_payload->>'query');
  status text:=coalesce(p_payload->>'status','all');
  cursor_at timestamptz:=private.try_timestamptz(p_payload#>>'{cursor,at}');
  cursor_id text:=coalesce(p_payload#>>'{cursor,id}','');
begin
  actor:=sales_private.actor(p_actor_id);
  if p_operation='compatibility' then
    if not (public.navigation_module_allowed_v1(actor.id,'request-history')
      or public.navigation_module_allowed_v1(actor.id,'reports')
      or (public.navigation_module_allowed_v1(actor.id,'request') and private.navigation_legacy_allowed_v1(actor.id,'request')))
      then return jsonb_build_object('rows','[]'::jsonb,'nextCursor',null); end if;
  else
    perform sales_private.require_module(actor.id,'request-history');
  end if;
  if p_operation not in ('search','folders','detail','compatibility') or status not in ('completed','pending','all') then
    raise exception 'HISTORY_OPERATION_INVALID';
  end if;
  -- Equivalent to can_read_source for the already validated active actor.
  rep_scoped:=sales_private.is_rep(actor.role) or actor.username in ('ben_brown','chance_alldredge');
  actor_key:=sales_private.key(actor.username);
  if p_operation is distinct from 'folders' then
    credit_allowed:=public.navigation_module_allowed_v1(actor.id,'sales-credit');
  end if;

  with source as materialized (
    select coalesce(h.snapshot,'{}')||to_jsonb(h) row,h.assigned_rep_id rep
    from public.ph_request_history h
    union all
    select to_jsonb(a),sales_private.assigned_rep(to_jsonb(a)) from public.ph_active_request a
    where not exists(select 1 from public.ph_request_history h where h.unique_id=a.unique_id)
  ), normalized as (
    select row||jsonb_build_object(
      'customerKey',sales_private.customer_key(row),
      'customername',coalesce(nullif(row->>'customername',''),row->>'req_customer',row->>'request_customer','Unknown customer'),
      'consigneename',coalesce(nullif(row->>'consigneename',''),'Unknown consignee'),
      'assigned_rep_id',rep,
      'status',case when lower(row->>'req_status') in ('complete','completed') then 'completed' else 'pending' end
    ) row,
    coalesce(case when lower(row->>'req_status') in ('complete','completed')
      then private.try_timestamptz(row->>'date_completed') end,
      private.try_timestamptz(row->>'created_at'),'epoch'::timestamptz) sort_at
    from source
    where not rep_scoped or rep=actor.id or sales_private.key(row->>'request_created_by_username')=actor_key
  ), filtered as materialized (
    select row||jsonb_build_object('sort_at',sort_at) row,sort_at from normalized
    where (status='all' or row->>'status'=status)
      and (q='' or position(q in sales_private.key(concat_ws(' ',row->>'customername',row->>'consigneename',row->>'commonname',row->>'itemcode',row->>'request_folder')))>0)
      and (nullif(p_payload->>'customerKey','') is null or row->>'customerKey'=p_payload->>'customerKey')
      and (p_operation<>'detail' or row->>'unique_id'=p_payload->>'id')
  ), page as materialized (
    select * from filtered where cursor_at is null or (sort_at,row->>'unique_id')<(cursor_at,cursor_id)
    order by sort_at desc,row->>'unique_id' desc limit lim+1
  ), folders as (
    select row->>'customerKey' key,max(row->>'customername') customer,
      max(row->>'consigneename') consignee,count(*) count from filtered
    group by row->>'customerKey'
    having coalesce(p_payload#>>'{cursor,key}','')='' or row->>'customerKey'>p_payload#>>'{cursor,key}'
    order by row->>'customerKey' limit lim+1
  )
  select case when p_operation='folders' then
    jsonb_build_object('folders',coalesce((select jsonb_agg(jsonb_build_object('customerKey',key,
      'customername',customer,'consigneename',consignee,'count',count) order by key)
      from (select * from folders limit lim) f),'[]'::jsonb),
      'nextCursor',case when (select count(*) from folders)>lim
        then (select jsonb_build_object('key',key) from folders offset lim-1 limit 1) end)
  else
    jsonb_build_object('rows',coalesce((select jsonb_agg(r.row||jsonb_build_object(
      'canRequestCredit',coalesce(credit_allowed,false) and exists(
        select 1 from public.ph_credit_sources cs
        where cs.source_kind='request_history' and cs.source_id=r.row->>'unique_id'
          and (not rep_scoped or cs.assigned_rep_id=actor.id)
          and (cs.canonical_source_id is null or exists(
            select 1 from public.ph_credit_sources canonical where canonical.id=cs.canonical_source_id
              and canonical.canonical_source_id is null
              and (not rep_scoped or canonical.assigned_rep_id=actor.id)
          ))
      )) order by r.sort_at desc,r.row->>'unique_id' desc)
      from (select * from page order by sort_at desc,row->>'unique_id' desc limit lim) r),'[]'::jsonb),
      'nextCursor',case when (select count(*) from page)>lim
        then (select jsonb_build_object('at',sort_at,'id',row->>'unique_id')
          from page order by sort_at desc,row->>'unique_id' desc offset lim-1 limit 1) end)
  end into result;
  return result;
end $$;


ALTER FUNCTION public.request_history_command_v1(p_actor_id uuid, p_operation text, p_payload jsonb, p_command_id uuid, p_expected_revision bigint) OWNER TO postgres;

--
-- Name: FUNCTION request_history_command_v1(p_actor_id uuid, p_operation text, p_payload jsonb, p_command_id uuid, p_expected_revision bigint); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.request_history_command_v1(p_actor_id uuid, p_operation text, p_payload jsonb, p_command_id uuid, p_expected_revision bigint) IS 'Service-only rep/creator-scoped history. Full permitted search precedes paging; actor checks run once and credit projection runs only on returned rows.';


--
-- Name: requeue_request_delivery(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.requeue_request_delivery(delivery_event_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare updated_event public.ph_request_delivery_outbox;
begin
  if not private.can_manage_requests() then raise exception using errcode='42501',message='REQUEST_RECOVERY_FORBIDDEN'; end if;
  update public.ph_request_delivery_outbox set status='pending',next_attempt_at=now(),sanitized_error_code=null,
    lease_token=null,lease_owner=null,lease_expires_at=null
  where event_id=delivery_event_id and event_type not in ('hl_order_submission','hl_order_cancellation','bunch_note_submission')
    and (status in ('unknown','failed') or (status='pending' and next_attempt_at<=now())
      or (status='processing' and coalesce(lease_expires_at,last_attempt_at)<=now()))
  returning * into updated_event;
  if not found then raise exception using errcode='P0002',message='DELIVERY_EVENT_NOT_RECOVERABLE'; end if;
  return to_jsonb(updated_event)-'payload'-'channel_results';
end $$;


ALTER FUNCTION public.requeue_request_delivery(delivery_event_id uuid) OWNER TO postgres;

--
-- Name: resolve_location_work_line_v1(uuid, uuid, text, integer, text, integer, text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.resolve_location_work_line_v1(p_job_id uuid, p_line_id uuid, p_actor_username text, p_expected_revision integer, p_resolution_status text, p_actual_qty integer DEFAULT NULL::integer, p_not_completed_reason text DEFAULT NULL::text, p_variance_confirmed boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor public.profiles;
  job public.ph_location_work_jobs;
  line public.ph_location_work_lines;
  delivery public.ph_request_delivery_outbox;
  resolved_count integer;
  recipient_email text;
  event_payload jsonb;
  resolution_value text := lower(btrim(coalesce(p_resolution_status, '')));
begin
  actor := private.location_work_active_actor_v1(p_actor_username);
  select * into job from public.ph_location_work_jobs where id = p_job_id for update;
  if job.id is null then raise exception using errcode = '22023', message = 'location_work_job_not_found'; end if;
  if actor.username <> 'dylan_collyge' and not (actor.username = any(job.assigned_usernames)) then
    raise exception using errcode = '42501', message = 'location_work_complete_forbidden';
  end if;
  if job.revision <> p_expected_revision then
    raise exception using errcode = '40001', message = 'location_work_revision_conflict';
  end if;
  if job.status not in ('open', 'in_progress') then
    raise exception using errcode = '40001', message = 'location_work_status_conflict';
  end if;
  select * into line from public.ph_location_work_lines
    where id = p_line_id and job_id = job.id for update;
  if line.id is null then raise exception using errcode = '22023', message = 'location_work_line_not_found'; end if;
  if line.resolution_status <> 'pending' then
    raise exception using errcode = '40001', message = 'location_work_line_already_resolved';
  end if;
  if resolution_value = 'done' then
    if p_actual_qty is null or p_actual_qty < 0
       or (p_actual_qty > line.planned_qty and not coalesce(p_variance_confirmed, false)) then
      raise exception using errcode = '22023', message = 'location_work_actual_qty_invalid';
    end if;
    update public.ph_location_work_lines set resolution_status = 'done', actual_qty = p_actual_qty,
      variance_confirmed = coalesce(p_variance_confirmed, false), resolved_by_username = actor.username,
      resolved_at = now(), updated_at = now() where id = line.id returning * into line;
  elsif resolution_value = 'not_completed' then
    if length(btrim(coalesce(p_not_completed_reason, ''))) < 1
       or length(btrim(coalesce(p_not_completed_reason, ''))) > 2000 then
      raise exception using errcode = '22023', message = 'location_work_reason_required';
    end if;
    update public.ph_location_work_lines set resolution_status = 'not_completed', actual_qty = null,
      variance_confirmed = false, not_completed_reason = btrim(p_not_completed_reason),
      resolved_by_username = actor.username, resolved_at = now(), updated_at = now()
      where id = line.id returning * into line;
  else
    raise exception using errcode = '22023', message = 'location_work_resolution_invalid';
  end if;

  select count(*) into resolved_count from public.ph_location_work_lines l
    where l.job_id = job.id and l.resolution_status <> 'pending';
  update public.ph_location_work_jobs set
    resolved_line_count = resolved_count,
    status = case when resolved_count = line_count then 'complete' else 'in_progress' end,
    revision = revision + 1,
    completed_by_username = case when resolved_count = line_count then actor.username else completed_by_username end,
    completed_at = case when resolved_count = line_count then now() else completed_at end,
    updated_at = now()
  where id = job.id returning * into job;
  insert into public.ph_location_work_audit(job_id, line_id, event_type, actor_username, job_revision, metadata)
    values (job.id, line.id, 'line_' || resolution_value, actor.username, job.revision,
      jsonb_build_object('varianceConfirmed', line.variance_confirmed));

  if job.status = 'complete' and job.completion_event_id is null then
    recipient_email := lower(btrim(job.completion_recipient->>'email'));
    event_payload := private.location_work_event_payload_v1(job.id, 'completion', array[recipient_email]);
    insert into public.ph_request_delivery_outbox(
      event_key, event_type, request_id, request_folder, payload, status, next_attempt_at
    ) values (
      'location-work:' || job.id::text || ':completion:v1', 'location_work_completion',
      job.id::text, job.title, event_payload, 'pending', now()
    ) on conflict (event_key) do update set payload = excluded.payload, updated_at = now()
    returning * into delivery;
    insert into public.ph_location_work_delivery_events(job_id, delivery_kind, job_revision, outbox_event_id)
      values (job.id, 'completion', job.revision, delivery.event_id)
      on conflict (outbox_event_id) do nothing;
    update public.ph_location_work_jobs set completion_event_id = delivery.event_id, updated_at = now()
      where id = job.id returning * into job;
    insert into public.ph_location_work_audit(job_id, event_type, actor_username, job_revision, metadata)
      values (job.id, 'completed', actor.username, job.revision,
        jsonb_build_object('resolvedLineCount', job.resolved_line_count));
  end if;
  return jsonb_build_object('jobId', job.id, 'status', job.status, 'revision', job.revision,
    'lineId', line.id, 'lineStatus', line.resolution_status,
    'resolvedLineCount', job.resolved_line_count, 'lineCount', job.line_count,
    'completionEventId', job.completion_event_id);
end
$$;


ALTER FUNCTION public.resolve_location_work_line_v1(p_job_id uuid, p_line_id uuid, p_actor_username text, p_expected_revision integer, p_resolution_status text, p_actual_qty integer, p_not_completed_reason text, p_variance_confirmed boolean) OWNER TO postgres;

--
-- Name: FUNCTION resolve_location_work_line_v1(p_job_id uuid, p_line_id uuid, p_actor_username text, p_expected_revision integer, p_resolution_status text, p_actual_qty integer, p_not_completed_reason text, p_variance_confirmed boolean); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.resolve_location_work_line_v1(p_job_id uuid, p_line_id uuid, p_actor_username text, p_expected_revision integer, p_resolution_status text, p_actual_qty integer, p_not_completed_reason text, p_variance_confirmed boolean) IS 'Assigned-user optimistic line resolution. The final resolution queues one completion PDF to Dylan without changing inventory.';


--
-- Name: retry_drive_reclass_inquiry_v1(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.retry_drive_reclass_inquiry_v1(p_actor_username text, p_idempotency_token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_username text := lower(btrim(coalesce(p_actor_username, '')));
  token text := btrim(coalesce(p_idempotency_token, ''));
  event_row public.ph_request_delivery_outbox;
begin
  if actor_username = '' or length(token) < 12 or length(token) > 180 then
    raise exception using errcode = '22023', message = 'DRIVE_RECLASS_RETRY_INVALID';
  end if;
  select o.* into event_row
  from public.ph_request_delivery_outbox o
  where o.event_key = 'reclass-inquiry:' || left(encode(extensions.digest(token, 'sha256'), 'hex'), 40)
    and o.event_type = 'reclass_inquiry'
    and lower(btrim(coalesce(o.payload #>> '{reclassPayload,actor,username}', ''))) = actor_username
    and o.payload #>> '{reclassPayload,protectedDelivery,contractVersion}' = 'drive-reclass-protected-v1'
  limit 1
  for update;
  if event_row.event_id is null then
    return jsonb_build_object('ok', false, 'status', 'missing', 'message', 'This inquiry was not found.');
  end if;
  if event_row.status = 'delivered' or event_row.status in ('pending', 'processing') then
    return private.drive_reclass_delivery_result_v1(event_row);
  end if;
  if upper(coalesce(event_row.sanitized_error_code, '')) like 'RECLASS_CONFLICT%' then
    return private.drive_reclass_delivery_result_v1(event_row);
  end if;
  update public.ph_request_delivery_outbox o
  set status = 'pending', attempt_count = 0, next_attempt_at = now(),
      sanitized_error_code = null, lease_token = null, lease_owner = null,
      lease_expires_at = null, updated_at = now()
  where o.event_id = event_row.event_id
  returning * into event_row;
  return private.drive_reclass_delivery_result_v1(event_row);
end
$$;


ALTER FUNCTION public.retry_drive_reclass_inquiry_v1(p_actor_username text, p_idempotency_token text) OWNER TO postgres;

--
-- Name: retry_location_work_delivery_v1(uuid, text, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.retry_location_work_delivery_v1(p_job_id uuid, p_actor_username text, p_expected_revision integer, p_delivery_kind text) RETURNS public.ph_location_work_jobs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor public.profiles;
  job public.ph_location_work_jobs;
  event_id_value uuid;
  delivery_kind_value text := lower(btrim(coalesce(p_delivery_kind, '')));
begin
  actor := private.location_work_active_actor_v1(p_actor_username);
  if actor.username <> 'dylan_collyge' then
    raise exception using errcode = '42501', message = 'location_work_retry_forbidden';
  end if;
  select * into job from public.ph_location_work_jobs where id = p_job_id for update;
  if job.id is null then raise exception using errcode = '22023', message = 'location_work_job_not_found'; end if;
  if job.revision <> p_expected_revision then raise exception using errcode = '40001', message = 'location_work_revision_conflict'; end if;
  event_id_value := case when delivery_kind_value = 'assignment' then job.assignment_event_id
    when delivery_kind_value = 'completion' then job.completion_event_id else null end;
  if event_id_value is null or not exists (
    select 1 from public.ph_request_delivery_outbox d
      where d.event_id = event_id_value and d.status in ('failed', 'unknown')
  ) then raise exception using errcode = '40001', message = 'location_work_delivery_not_retryable'; end if;
  update public.ph_request_delivery_outbox set status = 'pending', next_attempt_at = now(),
    sanitized_error_code = null, lease_token = null, lease_owner = null,
    lease_expires_at = null, updated_at = now() where event_id = event_id_value;
  update public.ph_location_work_jobs set revision = revision + 1, updated_at = now()
    where id = job.id returning * into job;
  insert into public.ph_location_work_audit(job_id, event_type, actor_username, job_revision, metadata)
    values (job.id, 'delivery_retried', actor.username, job.revision,
      jsonb_build_object('deliveryKind', delivery_kind_value));
  return job;
end
$$;


ALTER FUNCTION public.retry_location_work_delivery_v1(p_job_id uuid, p_actor_username text, p_expected_revision integer, p_delivery_kind text) OWNER TO postgres;

--
-- Name: retry_shear_location_delivery_v1(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.retry_shear_location_delivery_v1(p_inquiry_id uuid, p_actor_username text, p_expected_revision integer) RETURNS public.ph_shear_location_inquiries
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor public.profiles;
  inquiry public.ph_shear_location_inquiries;
begin
  actor := private.shear_assert_active_actor_v1(p_actor_username);
  if actor.username <> 'dylan_collyge' then raise exception using errcode = '42501', message = 'shear_retry_forbidden'; end if;
  select * into inquiry from public.ph_shear_location_inquiries where id = p_inquiry_id for update;
  if inquiry.id is null then raise exception using errcode = '22023', message = 'shear_inquiry_not_found'; end if;
  if inquiry.revision <> p_expected_revision then raise exception using errcode = '40001', message = 'shear_revision_conflict'; end if;
  if not exists (select 1 from public.ph_request_delivery_outbox d
    where d.event_id = inquiry.delivery_event_id and d.status in ('failed', 'unknown')) then
    raise exception using errcode = '40001', message = 'shear_delivery_not_retryable';
  end if;
  update public.ph_request_delivery_outbox set status = 'pending', next_attempt_at = now(),
    sanitized_error_code = null, lease_token = null, lease_owner = null, lease_expires_at = null,
    updated_at = now()
  where event_id = inquiry.delivery_event_id;
  update public.ph_shear_location_inquiries set revision = revision + 1, updated_at = now()
  where id = inquiry.id returning * into inquiry;
  insert into public.ph_shear_location_events(inquiry_id, event_type, actor_username, revision)
  values (inquiry.id, 'delivery_retried', actor.username, inquiry.revision);
  return inquiry;
end
$$;


ALTER FUNCTION public.retry_shear_location_delivery_v1(p_inquiry_id uuid, p_actor_username text, p_expected_revision integer) OWNER TO postgres;

--
-- Name: run_request_integrity_maintenance(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.run_request_integrity_maintenance() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  assignment_result jsonb;
  expired_count integer;
  maintenance_status text;
begin
  assignment_result := public.reconcile_eval_itemcodes();
  expired_count := private.expire_shared_av_results();
  maintenance_status := coalesce(assignment_result->>'status', 'completed');

  return jsonb_strip_nulls(jsonb_build_object(
    'status', maintenance_status,
    'errorCode', case when maintenance_status = 'deferred' then 'MAINTENANCE_DEFERRED' end,
    'assignments', assignment_result,
    'expired_av_rows', expired_count,
    'health', jsonb_build_object(
      'status', 'delegated',
      'operation', 'get_hosted_health_snapshot'
    )
  ));
end;
$$;


ALTER FUNCTION public.run_request_integrity_maintenance() OWNER TO postgres;

--
-- Name: sales_credit_attachment_v1(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sales_credit_attachment_v1(p_actor_id uuid, p_operation text, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare actor public.profiles; src public.ph_credit_sources; attachment public.ph_credit_attachments; work_id uuid:=(p_payload->>'id')::uuid;
begin
  actor:=sales_private.actor(p_actor_id);
  if p_operation='download' then
    if public.navigation_module_allowed_v1(actor.id,'sales-credit') is distinct from true and public.navigation_module_allowed_v1(actor.id,'credit-request') is distinct from true then raise exception using errcode='42501',message='SALES_MODULE_FORBIDDEN'; end if;
  else perform sales_private.require_module(actor.id,'sales-credit'); end if;
  if work_id is null then raise exception 'CREDIT_ATTACHMENT_ID_REQUIRED'; end if;
  perform pg_advisory_xact_lock(hashtextextended(work_id::text,2));
  select * into attachment from public.ph_credit_attachments where id=work_id for update;
  if p_operation='reserve' then
    select * into src from public.ph_credit_sources where id=(p_payload->>'sourceId')::uuid;
    if src.id is null or not sales_private.can_read_source(actor.id,src.assigned_rep_id) then raise exception using errcode='42501',message='CREDIT_SOURCE_FORBIDDEN'; end if;
    if attachment.id is not null then
      if attachment.actor_id<>actor.id or attachment.source_id<>src.id or attachment.sha256 is distinct from p_payload->>'sha256' then raise exception 'CREDIT_ATTACHMENT_COMMAND_CONFLICT'; end if;
      return to_jsonb(attachment);
    end if;
    if p_payload->>'mime' not in ('image/jpeg','image/png','image/webp') or p_payload->>'extension' not in ('jpg','png','webp')
      or coalesce(p_payload->>'sha256','')!~'^[0-9a-f]{64}$' then raise exception 'CREDIT_ATTACHMENT_INVALID'; end if;
    insert into public.ph_credit_attachments(id,source_id,actor_id,object_path,mime,byte_count,sha256,state)
    values(work_id,src.id,actor.id,actor.id::text||'/'||work_id::text||'.'||(p_payload->>'extension'),p_payload->>'mime',(p_payload->>'size')::integer,p_payload->>'sha256','pending')
    returning * into attachment;
  elsif p_operation='finish' then
    if attachment.id is null or attachment.actor_id<>actor.id then raise exception using errcode='42501',message='CREDIT_ATTACHMENT_FORBIDDEN'; end if;
    if attachment.sha256 is distinct from p_payload->>'sha256' then raise exception 'CREDIT_ATTACHMENT_HASH_CONFLICT'; end if;
    if not exists(select 1 from storage.objects where bucket_id='sales-credit-evidence' and name=attachment.object_path) then raise exception 'CREDIT_ATTACHMENT_UPLOAD_INCOMPLETE'; end if;
    update public.ph_credit_attachments set state='ready' where id=work_id returning * into attachment;
  elsif p_operation='download' then
    if attachment.id is null or attachment.state<>'ready' then raise exception 'CREDIT_ATTACHMENT_NOT_FOUND'; end if;
    if attachment.actor_id<>actor.id and not exists(select 1 from public.ph_sales_credit_requests c where attachment.id=any(c.attachment_ids) and sales_private.can_read_line(actor.id,c)) then
      raise exception using errcode='42501',message='CREDIT_ATTACHMENT_FORBIDDEN';
    end if;
  else raise exception 'CREDIT_ATTACHMENT_OPERATION_INVALID'; end if;
  return to_jsonb(attachment);
end $_$;


ALTER FUNCTION public.sales_credit_attachment_v1(p_actor_id uuid, p_operation text, p_payload jsonb) OWNER TO postgres;

--
-- Name: sales_credit_command_v1(uuid, text, jsonb, uuid, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sales_credit_command_v1(p_actor_id uuid, p_operation text, p_payload jsonb DEFAULT '{}'::jsonb, p_command_id uuid DEFAULT NULL::uuid, p_expected_revision bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare actor public.profiles; reviewer boolean; result jsonb; src public.ph_credit_sources;
  kind text:=nullif(p_payload->>'sourceKind',''); q text:=sales_private.key(p_payload->>'query');
  lim integer:=least(100,greatest(1,coalesce((p_payload->>'limit')::integer,40)));
begin
  if p_operation not in ('folders','sources','source') then
    return sales_private.credit_command_base_v1(p_actor_id,p_operation,p_payload,p_command_id,p_expected_revision);
  end if;
  actor:=sales_private.actor(p_actor_id);
  perform sales_private.require_module(actor.id,'sales-credit');
  reviewer:=actor.username in ('dylan_collyge','jd_jones','megan_kelly');
  if kind is not null and kind not in ('docks','request_history') then raise exception 'CREDIT_SOURCE_KIND_INVALID'; end if;
  if p_operation='source' then
    if kind is null or nullif(p_payload->>'sourceUniqueId','') is null then raise exception 'CREDIT_SOURCE_ID_REQUIRED'; end if;
    select * into src from public.ph_credit_sources s where s.source_kind=kind and s.source_id=p_payload->>'sourceUniqueId'
      and sales_private.can_read_source(actor.id,s.assigned_rep_id);
    if src.id is null then raise exception using errcode='42501',message='CREDIT_SOURCE_FORBIDDEN'; end if;
    if src.canonical_source_id is not null then
      select * into src from public.ph_credit_sources s where s.id=src.canonical_source_id and s.canonical_source_id is null
        and sales_private.can_read_source(actor.id,s.assigned_rep_id);
      if src.id is null then raise exception using errcode='42501',message='CREDIT_SOURCE_FORBIDDEN'; end if;
    end if;
    return jsonb_build_object('source',sales_private.credit_source_json(src,actor.id,reviewer),'folder',jsonb_build_object(
      'customerKey',src.customer_key,'customername',coalesce(nullif(src.snapshot->>'customername',''),nullif(src.snapshot->>'req_customer',''),'Unknown customer'),
      'consigneename',coalesce(nullif(src.snapshot->>'consigneename',''),'Unknown consignee')));
  end if;
  if p_operation='folders' then
    with folders as (
      select customer_key,max(coalesce(nullif(snapshot->>'customername',''),nullif(snapshot->>'req_customer',''),nullif(snapshot->>'request_customer',''),'Unknown customer')) customer,
        max(coalesce(nullif(snapshot->>'consigneename',''),'Unknown consignee')) consignee,count(*) count
      from public.ph_credit_sources s where sales_private.can_read_source(actor.id,s.assigned_rep_id) and canonical_source_id is null
        and (kind is null or s.source_kind=kind)
        and (q='' or position(q in sales_private.key(concat_ws(' ',snapshot->>'customername',snapshot->>'req_customer',snapshot->>'consigneename',snapshot->>'itemcode',snapshot->>'commonname',snapshot->>'request_folder')))>0)
      group by customer_key having coalesce(p_payload#>>'{cursor,key}','')='' or customer_key>p_payload#>>'{cursor,key}' order by customer_key limit lim+1
    ) select jsonb_build_object('folders',coalesce((select jsonb_agg(jsonb_build_object('customerKey',customer_key,'customername',customer,'consigneename',consignee,'count',count) order by customer_key) from (select * from folders limit lim) f),'[]'),
      'nextCursor',case when (select count(*) from folders)>lim then (select jsonb_build_object('key',customer_key) from folders offset lim-1 limit 1) end) into result;
  else
    with visible as (
      select s.* from public.ph_credit_sources s where sales_private.can_read_source(actor.id,s.assigned_rep_id) and canonical_source_id is null
        and (kind is null or s.source_kind=kind)
        and (nullif(p_payload->>'customerKey','') is null or s.customer_key=p_payload->>'customerKey')
        and (q='' or position(q in sales_private.key(concat_ws(' ',snapshot->>'customername',snapshot->>'req_customer',snapshot->>'consigneename',snapshot->>'itemcode',snapshot->>'commonname',snapshot->>'request_folder')))>0)
        and (nullif(p_payload#>>'{cursor,id}','') is null or s.id>(p_payload#>>'{cursor,id}')::uuid) order by id limit lim+1
    ) select jsonb_build_object('rows',coalesce((select jsonb_agg(sales_private.credit_source_json(s::public.ph_credit_sources,actor.id,reviewer) order by s.id)
      from (select * from visible limit lim) s),'[]'::jsonb),
      'nextCursor',case when (select count(*) from visible)>lim then (select jsonb_build_object('id',id) from visible offset lim-1 limit 1) end) into result;
    if reviewer then result:=result||jsonb_build_object('requesters',coalesce((select jsonb_agg(jsonb_build_object('id',id,'username',username,'display_name',display_name) order by username) from public.profiles where disabled_at is null and not must_change_password),'[]'::jsonb)); end if;
  end if;
  return result;
end $$;


ALTER FUNCTION public.sales_credit_command_v1(p_actor_id uuid, p_operation text, p_payload jsonb, p_command_id uuid, p_expected_revision bigint) OWNER TO postgres;

