--
-- Name: save_eval_work_v1(uuid, text, integer, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.save_eval_work_v1(p_work_id uuid, p_actor_username text, p_expected_version integer, p_inquiry jsonb, p_evidence jsonb) RETURNS public.ph_eval_work
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor public.profiles;
  work public.ph_eval_work;
  current_rows jsonb;
  baseline_row jsonb;
  current_row jsonb;
  overlay jsonb;
  proposed_uid text;
begin
  actor := private.eval_work_assert_actor_v1(p_actor_username);
  select * into work from public.ph_eval_work where id = p_work_id for update;
  if work.id is null or lower(work.assignee_username) <> lower(actor.username) then
    raise exception using errcode = '42501', message = 'eval_work_edit_forbidden';
  end if;
  if work.status not in ('open', 'in_progress') then raise exception using errcode = '22023', message = 'eval_work_not_editable'; end if;
  if work.version <> p_expected_version then raise exception using errcode = '40001', message = 'eval_work_version_conflict'; end if;
  current_rows := private.eval_work_context_rows_v1(work.itemcode);
  for overlay in select value from jsonb_array_elements(coalesce(p_inquiry->'rowOverlays', '[]'::jsonb)) loop
    if jsonb_array_length(coalesce(overlay->'proposals', '[]'::jsonb)) = 0 then continue; end if;
    proposed_uid := trim(coalesce(overlay->>'unique_id', ''));
    select value into baseline_row from jsonb_array_elements(coalesce(work.context_rows, '[]'::jsonb)) where value->>'unique_id' = proposed_uid limit 1;
    select value into current_row from jsonb_array_elements(coalesce(current_rows, '[]'::jsonb)) where value->>'unique_id' = proposed_uid limit 1;
    if baseline_row is null or current_row is null
       or coalesce(baseline_row->>'itemcode', '') <> coalesce(current_row->>'itemcode', '')
       or coalesce(baseline_row->>'locationcode', '') <> coalesce(current_row->>'locationcode', '')
       or coalesce(baseline_row->>'lotcode', '') <> coalesce(current_row->>'lotcode', '')
       or coalesce(baseline_row->>'ptronhand', '') <> coalesce(current_row->>'ptronhand', '') then
      raise exception using errcode = '40001', message = 'eval_work_target_conflict';
    end if;
  end loop;
  perform private.validate_eval_work_inquiry_v1(coalesce(p_inquiry, work.inquiry_draft), work.itemcode, current_rows);
  update public.ph_eval_work set
    inquiry_draft = coalesce(p_inquiry, inquiry_draft),
    evidence_draft = coalesce(p_evidence, evidence_draft),
    context_rows = current_rows,
    inventory_signature = md5(current_rows::text),
    status = 'in_progress',
    started_at = coalesce(started_at, now()),
    version = version + 1,
    updated_at = now()
  where id = work.id returning * into work;
  insert into public.ph_eval_work_events(eval_work_id, event_type, actor_username, version, metadata)
  values (work.id, 'draft_saved', lower(actor.username), work.version, '{}'::jsonb);
  return work;
end
$$;


ALTER FUNCTION public.save_eval_work_v1(p_work_id uuid, p_actor_username text, p_expected_version integer, p_inquiry jsonb, p_evidence jsonb) OWNER TO postgres;

--
-- Name: save_eval_work_v2(uuid, text, integer, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.save_eval_work_v2(p_work_id uuid, p_actor_username text, p_expected_version integer, p_inquiry jsonb, p_evidence_by_origin jsonb) RETURNS public.ph_eval_work
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  work public.ph_eval_work;
  current_rows jsonb;
  settings jsonb;
begin
  select * into work from public.ph_eval_work where id = p_work_id;
  if coalesce(work.source_context->>'scopeContract', '') = 'itemcode-all-rows-v1' then
    current_rows := private.eval_work_assert_itemcode_membership_v1(p_work_id);
    settings := private.eval_work_settings_v1();
    if md5(settings::text) <> work.settings_signature then
      raise exception using errcode = '40001', message = 'eval_work_settings_conflict';
    end if;
    if jsonb_array_length(coalesce(p_inquiry->'rowOverlays', '[]'::jsonb)) <> work.origin_count
       or (select count(distinct value->>'unique_id') from jsonb_array_elements(coalesce(p_inquiry->'rowOverlays', '[]'::jsonb))) <> work.origin_count then
      raise exception using errcode = '40001', message = 'eval_work_itemcode_overlay_membership_conflict';
    end if;
  end if;
  return public.save_eval_work_v2_legacy_impl(
    p_work_id, p_actor_username, p_expected_version, p_inquiry, p_evidence_by_origin
  );
end
$$;


ALTER FUNCTION public.save_eval_work_v2(p_work_id uuid, p_actor_username text, p_expected_version integer, p_inquiry jsonb, p_evidence_by_origin jsonb) OWNER TO postgres;

--
-- Name: save_eval_work_v2_legacy_impl(uuid, text, integer, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.save_eval_work_v2_legacy_impl(p_work_id uuid, p_actor_username text, p_expected_version integer, p_inquiry jsonb, p_evidence_by_origin jsonb) RETURNS public.ph_eval_work
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor public.profiles;
  work public.ph_eval_work;
  origin_row public.ph_eval_work_origin_rows;
  current_origin public.ph_master_inventory;
  current_rows jsonb;
  origin_ids text[];
  evidence jsonb;
begin
  actor := private.eval_work_assert_actor_v1(p_actor_username);
  select * into work from public.ph_eval_work where id = p_work_id for update;
  if work.id is null or work.contract_version <> 'eval-work-v2-multi-origin'
     or lower(work.assignee_username) <> lower(actor.username) then
    raise exception using errcode = '42501', message = 'eval_work_edit_forbidden';
  end if;
  if work.status not in ('open', 'in_progress') then raise exception using errcode = '22023', message = 'eval_work_not_editable'; end if;
  if work.version <> p_expected_version then raise exception using errcode = '40001', message = 'eval_work_version_conflict'; end if;
  if jsonb_typeof(coalesce(p_evidence_by_origin, '{}'::jsonb)) <> 'object' then
    raise exception using errcode = '22023', message = 'eval_work_evidence_map_invalid';
  end if;
  select array_agg(origin_unique_id order by ordinal) into origin_ids
  from public.ph_eval_work_origin_rows where eval_work_id = work.id;
  current_rows := private.eval_work_context_rows_for_origins_v2(origin_ids);
  if jsonb_array_length(current_rows) <> work.origin_count then
    raise exception using errcode = '40001', message = 'eval_work_origin_identity_conflict';
  end if;
  for origin_row in select * from public.ph_eval_work_origin_rows where eval_work_id = work.id order by ordinal for update loop
    select * into current_origin from public.ph_master_inventory where unique_id = origin_row.origin_unique_id;
    if current_origin.unique_id is null
       or upper(trim(coalesce(current_origin.itemcode, ''))) <> upper(trim(origin_row.itemcode))
       or coalesce(current_origin.locationcode, '') <> origin_row.locationcode
       or coalesce(current_origin.lotcode, '') <> origin_row.lotcode
       or coalesce(to_jsonb(current_origin)->>'ptronhand', '') <> coalesce(origin_row.origin_snapshot->>'ptronhand', '') then
      raise exception using errcode = '40001', message = 'eval_work_origin_identity_conflict';
    end if;
    evidence := coalesce(p_evidence_by_origin->(origin_row.origin_unique_id), origin_row.evidence_draft, '{}'::jsonb);
    update public.ph_eval_work_origin_rows
      set evidence_draft = evidence, updated_at = now()
      where eval_work_id = work.id and origin_unique_id = origin_row.origin_unique_id;
  end loop;
  if exists (select 1 from jsonb_object_keys(p_evidence_by_origin) key where not (key = any(origin_ids))) then
    raise exception using errcode = '22023', message = 'eval_work_evidence_origin_invalid';
  end if;
  perform private.validate_eval_work_inquiry_v1(coalesce(p_inquiry, work.inquiry_draft), work.itemcode, current_rows);
  update public.ph_eval_work set inquiry_draft = coalesce(p_inquiry, inquiry_draft),
    evidence_draft = coalesce(p_evidence_by_origin, evidence_draft), context_rows = current_rows,
    inventory_signature = md5(current_rows::text), status = 'in_progress',
    started_at = coalesce(started_at, now()), version = version + 1, updated_at = now()
  where id = work.id returning * into work;
  insert into public.ph_eval_work_events(eval_work_id, event_type, actor_username, version, metadata)
  values (work.id, 'draft_saved', lower(actor.username), work.version,
    jsonb_build_object('originCount', work.origin_count));
  return work;
end
$$;


ALTER FUNCTION public.save_eval_work_v2_legacy_impl(p_work_id uuid, p_actor_username text, p_expected_version integer, p_inquiry jsonb, p_evidence_by_origin jsonb) OWNER TO postgres;

--
-- Name: save_limited_access_override_v1(integer, jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.save_limited_access_override_v1(p_expected_revision integer, p_changes jsonb, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor public.profiles;
  access_state private.app_limited_access_state;
  change_row jsonb;
  target_type_value text;
  target_key_value text;
  permission_key_value text;
  decision_value text;
  target_profile public.profiles;
  previous_value jsonb;
  next_value jsonb;
  applied_count integer := 0;
begin
  actor := private.current_active_profile();
  if actor.id is null or not private.is_kayla_limited_access_manager_v1() then
    raise exception using errcode = '42501', message = 'LIMITED_ACCESS_CONTROL_FORBIDDEN';
  end if;
  if char_length(btrim(coalesce(p_reason, ''))) not between 4 and 500 then
    raise exception using errcode = '22023', message = 'LIMITED_ACCESS_CONTROL_REASON_REQUIRED';
  end if;
  if jsonb_typeof(coalesce(p_changes, 'null'::jsonb)) <> 'array'
     or jsonb_array_length(p_changes) < 1
     or jsonb_array_length(p_changes) > 100 then
    raise exception using errcode = '22023', message = 'LIMITED_ACCESS_CONTROL_CHANGES_INVALID';
  end if;

  select * into access_state
  from private.app_limited_access_state
  where singleton
  for update;
  if access_state.revision <> p_expected_revision then
    raise exception using errcode = '40001', message = 'LIMITED_ACCESS_CONTROL_VERSION_CONFLICT';
  end if;

  for change_row in select value from jsonb_array_elements(p_changes) loop
    target_type_value := lower(btrim(coalesce(change_row->>'targetType', '')));
    target_key_value := lower(btrim(coalesce(change_row->>'targetKey', '')));
    permission_key_value := lower(btrim(coalesce(change_row->>'permissionKey', '')));
    decision_value := lower(btrim(coalesce(change_row->>'decision', '')));

    if target_type_value <> 'user' or decision_value not in ('inherit', 'allow', 'deny') then
      raise exception using errcode = '22023', message = 'LIMITED_ACCESS_CONTROL_CHANGE_INVALID';
    end if;
    if not private.is_kayla_managed_permission_v1(permission_key_value) then
      raise exception using errcode = '42501', message = 'LIMITED_ACCESS_CONTROL_PERMISSION_FORBIDDEN';
    end if;

    select p.* into target_profile
    from public.profiles p
    where lower(btrim(p.username)) = target_key_value
      and p.disabled_at is null
      and (p.locked_until is null or p.locked_until <= now())
    limit 1
    for update;
    if target_profile.id is null or not private.is_kayla_managed_role_v1(target_profile.role) then
      raise exception using errcode = '42501', message = 'LIMITED_ACCESS_CONTROL_TARGET_FORBIDDEN';
    end if;

    select jsonb_build_object('allowed', o.allowed)
      into previous_value
    from private.app_limited_live_overrides o
    where o.profile_id = target_profile.id
      and o.permission_key = permission_key_value;

    if decision_value = 'inherit' then
      delete from private.app_limited_live_overrides
      where profile_id = target_profile.id
        and permission_key = permission_key_value;
      next_value := null;
    else
      insert into private.app_limited_live_overrides
        (profile_id, permission_key, allowed, updated_by_username, updated_at)
      values
        (target_profile.id, permission_key_value, decision_value = 'allow', lower(btrim(actor.username)), now())
      on conflict (profile_id, permission_key) do update set
        allowed = excluded.allowed,
        updated_by_username = excluded.updated_by_username,
        updated_at = now();
      next_value := jsonb_build_object('allowed', decision_value = 'allow');
    end if;

    if previous_value is distinct from next_value then
      insert into private.app_limited_access_events
        (actor_username, target_username, target_role, permission_key,
         previous_value, next_value, reason)
      values
        (lower(btrim(actor.username)), target_key_value,
         private.normalized_profile_role(target_profile.role), permission_key_value,
         previous_value, next_value, btrim(p_reason));
      applied_count := applied_count + 1;
    end if;
  end loop;

  if applied_count > 0 then
    update private.app_limited_access_state
    set revision = revision + 1,
        updated_at = now()
    where singleton
    returning * into access_state;
  end if;

  return jsonb_build_object(
    'contractVersion', 'app-limited-access-v1',
    'revision', access_state.revision,
    'appliedCount', applied_count,
    'enforcementMode', 'limited-live'
  );
end
$$;


ALTER FUNCTION public.save_limited_access_override_v1(p_expected_revision integer, p_changes jsonb, p_reason text) OWNER TO postgres;

--
-- Name: FUNCTION save_limited_access_override_v1(p_expected_revision integer, p_changes jsonb, p_reason text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.save_limited_access_override_v1(p_expected_revision integer, p_changes jsonb, p_reason text) IS 'Applies audited live module overrides only when Kayla Knepp targets an active CSR, SALESREP, or SALES/MARKETING profile.';


--
-- Name: save_request_work(text, bigint, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.save_request_work(request_id text, expected_version bigint, patch jsonb, complete boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  existing public.ph_active_request%rowtype;
  profile public.profiles%rowtype;
  profile_email text;
  canonical jsonb;
  safe_patch jsonb;
  save_result jsonb;
  season_result jsonb;
  linked_itemcode text;
  resulting_version bigint;
  season_token text;
begin
  if not private.can_save_request_work() then
    raise exception using errcode = '42501', message = 'REQUEST_SAVE_FORBIDDEN';
  end if;
  if nullif(btrim(coalesce(request_id, '')), '') is null or expected_version is null then
    raise exception using errcode = '22023', message = 'REQUEST_ID_AND_VERSION_REQUIRED';
  end if;
  if patch is null or jsonb_typeof(patch) <> 'object' then
    raise exception using errcode = '22023', message = 'REQUEST_PATCH_INVALID';
  end if;

  select * into existing
  from public.ph_active_request
  where unique_id = request_id;
  if not found then
    raise exception using errcode = 'P0002', message = 'REQUEST_NOT_FOUND';
  end if;

  profile := private.current_active_profile();
  if profile.id is null then
    raise exception using errcode = '42501', message = 'REQUEST_PROFILE_REQUIRED';
  end if;
  if lower(btrim(coalesce(profile.username, ''))) in ('ben_brown', 'chance_alldredge') then
    if not private.can_work_request_identity(
      existing.request_created_by_username,
      existing.request_selected_rep_username,
      existing.requested_by
    ) then
      raise exception using errcode = '42501', message = 'REQUEST_ROW_FORBIDDEN';
    end if;
  end if;

  if lower(coalesce(existing.req_status, '')) in ('complete', 'completed')
     or nullif(btrim(coalesce(existing.date_completed, '')), '') is not null then
    canonical := coalesce(private.canonical_request_json(request_id), to_jsonb(existing));
    save_result := jsonb_build_object(
      'row', canonical,
      'row_version', existing.row_version,
      'delivery_state', coalesce((
        select outbox.status
        from public.ph_request_delivery_outbox outbox
        where outbox.request_id = existing.unique_id
          and outbox.event_type = 'request_completed'
        order by outbox.created_at desc
        limit 1
      ), 'already_completed'),
      'acknowledged', true
    );
  else
    if existing.row_version <> expected_version then
      raise exception using errcode = '40001', message = 'REQUEST_VERSION_CONFLICT',
        detail = jsonb_build_object('current_version', existing.row_version)::text;
    end if;

    safe_patch := patch - 'completed_by_username' - 'completed_by_display' - 'completed_by_email';
    if complete then
      select auth_user.email into profile_email
      from auth.users auth_user
      where auth_user.id = profile.id;
      safe_patch := safe_patch || jsonb_build_object(
        'completed_by_username', profile.username,
        'completed_by_display', coalesce(nullif(profile.display_name, ''), profile.username),
        'completed_by_email', coalesce(profile_email, '')
      );
    end if;

    save_result := public.save_request_work_v1(
      request_id, expected_version, safe_patch, complete
    );
  end if;

  if coalesce(complete, false) and existing.master_id is not null then
    select master.itemcode into linked_itemcode
    from public.ph_master_inventory master
    where master.unique_id = existing.master_id;
    if nullif(btrim(coalesce(linked_itemcode, '')), '') is not null then
      resulting_version := coalesce(
        nullif(save_result->>'row_version', '')::bigint,
        existing.row_version
      );
      season_token := 'request-season-' || encode(extensions.digest(
        request_id || '|' || coalesce(resulting_version, 0)::text,
        'sha256'
      ), 'hex');
      begin
        season_result := private.refresh_eligible_season_sales_itemcode_v1(
          linked_itemcode,
          left('request-complete:' || request_id || ':' || coalesce(resulting_version, 0)::text, 180),
          season_token
        );
      exception when others then
        season_result := jsonb_build_object(
          'ok', true,
          'status', 'maintenance_deferred',
          'code', 'MAINTENANCE_DEFERRED'
        );
      end;
      save_result := coalesce(save_result, '{}'::jsonb)
        || jsonb_build_object('season_sales_office', season_result);
    end if;
  end if;

  return save_result;
end
$$;


ALTER FUNCTION public.save_request_work(request_id text, expected_version bigint, patch jsonb, complete boolean) OWNER TO postgres;

--
-- Name: FUNCTION save_request_work(request_id text, expected_version bigint, patch jsonb, complete boolean); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.save_request_work(request_id text, expected_version bigint, patch jsonb, complete boolean) IS 'Atomic Request writer with authoritative completion identity, durable delivery, and non-failing scoped Season Sales Office reconciliation.';


--
-- Name: save_request_work_v1(text, bigint, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.save_request_work_v1(request_id text, expected_version bigint, patch jsonb, complete boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  existing public.ph_active_request%rowtype;
  saved public.ph_active_request%rowtype;
  canonical jsonb;
  completion_time text;
  delivery_status text := 'not_queued';
begin
  if not private.can_save_request_work() then
    raise exception using errcode = '42501', message = 'REQUEST_SAVE_FORBIDDEN';
  end if;
  if nullif(btrim(coalesce(request_id, '')), '') is null or expected_version is null then
    raise exception using errcode = '22023', message = 'REQUEST_ID_AND_VERSION_REQUIRED';
  end if;
  if patch is null or jsonb_typeof(patch) <> 'object' then
    raise exception using errcode = '22023', message = 'REQUEST_PATCH_INVALID';
  end if;

  select * into existing
  from public.ph_active_request
  where unique_id = request_id
  for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'REQUEST_NOT_FOUND';
  end if;
  if existing.row_version <> expected_version then
    raise exception using
      errcode = '40001',
      message = 'REQUEST_VERSION_CONFLICT',
      detail = jsonb_build_object('current_version', existing.row_version)::text;
  end if;

  completion_time := case
    when complete then coalesce(nullif(patch->>'date_completed', ''), now()::text)
    else existing.date_completed
  end;

  update public.ph_active_request r
  set req_match = case when patch ? 'req_match' then
        case
          when nullif(btrim(coalesce(patch->>'req_match', '')), '') is null then null
          when btrim(patch->>'req_match') ~ '^-?[0-9]+([.][0-9]+)?$'
            then btrim(patch->>'req_match')::numeric
          else r.req_match
        end
      else r.req_match end,
      req_spec = case when patch ? 'req_spec' then patch->>'req_spec' else r.req_spec end,
      req_caliper = case when patch ? 'req_caliper' then patch->>'req_caliper' else r.req_caliper end,
      req_pic_note = case when patch ? 'req_pic_note' then patch->>'req_pic_note' else r.req_pic_note end,
      req_sales_note = case when patch ? 'req_sales_note' then patch->>'req_sales_note' else r.req_sales_note end,
      req_comments = case when patch ? 'req_comments' then patch->>'req_comments' else r.req_comments end,
      av_note = case when patch ? 'av_note' then patch->>'av_note' else r.av_note end,
      req_reserve = case when patch ? 'req_reserve' then patch->>'req_reserve' else r.req_reserve end,
      req_photo_link = case when patch ? 'req_photo_link' then patch->>'req_photo_link' else r.req_photo_link end,
      req_photo_name = case when patch ? 'req_photo_name' then patch->>'req_photo_name' else r.req_photo_name end,
      req_photo_mode = case when patch ? 'req_photo_mode' then patch->>'req_photo_mode' else r.req_photo_mode end,
      req_rep_action = case when patch ? 'req_rep_action' then patch->>'req_rep_action' else r.req_rep_action end,
      request_note = case when patch ? 'request_note' then patch->>'request_note' else r.request_note end,
      completed_by_username = case when patch ? 'completed_by_username' then patch->>'completed_by_username' else r.completed_by_username end,
      completed_by_display = case when patch ? 'completed_by_display' then patch->>'completed_by_display' else r.completed_by_display end,
      completed_by_email = case when patch ? 'completed_by_email' then patch->>'completed_by_email' else r.completed_by_email end,
      req_status = case when complete then 'Complete'
        when patch ? 'req_status' then patch->>'req_status' else r.req_status end,
      date_completed = completion_time,
      req_archived = case when complete then false
        when patch ? 'req_archived' then coalesce((patch->>'req_archived')::boolean, false)
        else r.req_archived end,
      row_version = r.row_version + 1
  where r.unique_id = request_id
    and r.row_version = expected_version
  returning r.* into saved;

  if not found then
    raise exception using errcode = '40001', message = 'REQUEST_VERSION_CONFLICT';
  end if;

  -- Shared AV work is committed to Drive in the same transaction. The Drive
  -- trigger propagates these values to every other pending request for the row.
  if saved.master_id is not null then
    update public.ph_master_inventory m
    set match = case when patch ? 'req_match' then patch->>'req_match' else m.match end,
        loc_match_qty = case when patch ? 'loc_match_qty' then patch->>'loc_match_qty' else m.loc_match_qty end,
        spec = case when patch ? 'req_spec' then patch->>'req_spec' else m.spec end,
        caliper = case when patch ? 'req_caliper' then patch->>'req_caliper' else m.caliper end,
        pic_note = case when patch ? 'req_pic_note' then patch->>'req_pic_note' else m.pic_note end,
        av_note = case when patch ? 'av_note' then patch->>'av_note' else m.av_note end,
        photo_link = case when patch ? 'drive_photo_link' then patch->>'drive_photo_link' else m.photo_link end,
        photo_name = case when patch ? 'drive_photo_name' then patch->>'drive_photo_name' else m.photo_name end,
        av_rule_priority_snapshot = case
          when patch ? 'req_match' or patch ? 'req_spec' or patch ? 'req_caliper'
            or patch ? 'req_pic_note' or patch ? 'av_note'
          then m.priority else m.av_rule_priority_snapshot end,
        av_rule_holdstop_snapshot = case
          when patch ? 'req_match' or patch ? 'req_spec' or patch ? 'req_caliper'
            or patch ? 'req_pic_note' or patch ? 'av_note'
          then concat_ws('|', nullif(btrim(coalesce(m.holdstopcode, '')), ''),
                              nullif(btrim(coalesce(m.holdstopreason, '')), ''))
          else m.av_rule_holdstop_snapshot end,
        av_rule_match_updated_at = case when patch ? 'req_match' then now() else m.av_rule_match_updated_at end,
        av_rule_spec_updated_at = case when patch ? 'req_spec' then now() else m.av_rule_spec_updated_at end,
        av_rule_caliper_updated_at = case when patch ? 'req_caliper' then now() else m.av_rule_caliper_updated_at end,
        av_rule_av_note_updated_at = case when patch ? 'av_note' then now() else m.av_rule_av_note_updated_at end,
        av_rule_photo_updated_at = case
          when patch ? 'drive_photo_link' or patch ? 'drive_photo_name' then now()
          else m.av_rule_photo_updated_at end,
        av_rule_bundle_updated_at = case
          when patch ? 'req_match' or patch ? 'req_spec' or patch ? 'req_caliper'
            or patch ? 'req_pic_note' or patch ? 'av_note'
            or patch ? 'drive_photo_link' or patch ? 'drive_photo_name'
          then now() else m.av_rule_bundle_updated_at end
    where m.unique_id = saved.master_id;
  end if;

  if complete then
    perform private.upsert_request_history(request_id, 'completed', 'pending', false);
    insert into public.ph_request_delivery_outbox (
      event_key, event_type, request_id, request_folder, payload, status
    ) values (
      'request-completed:' || request_id || ':' || saved.row_version::text,
      'request_completed', request_id, saved.request_folder,
      jsonb_build_object('request_id', request_id, 'row_version', saved.row_version),
      'pending'
    ) on conflict (event_key) do nothing;
    delivery_status := 'pending';
  else
    perform private.upsert_request_history(request_id, 'updated', 'not_queued', false);
  end if;

  canonical := coalesce(private.canonical_request_json(request_id), to_jsonb(saved));
  return jsonb_build_object(
    'row', canonical,
    'row_version', coalesce((canonical->>'row_version')::bigint, saved.row_version),
    'delivery_state', delivery_status
  );
end;
$_$;


ALTER FUNCTION public.save_request_work_v1(request_id text, expected_version bigint, patch jsonb, complete boolean) OWNER TO postgres;

--
-- Name: FUNCTION save_request_work_v1(request_id text, expected_version bigint, patch jsonb, complete boolean); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.save_request_work_v1(request_id text, expected_version bigint, patch jsonb, complete boolean) IS 'Optimistic-concurrency Request save; atomically updates Drive AV fields, History, and delivery outbox.';


--
-- Name: save_season_sales_note_users_v1(text, text[], text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.save_season_sales_note_users_v1(p_actor_username text, p_usernames text[], p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor public.profiles := private.season_sales_assert_settings_manager_v1(p_actor_username);
  normalized_usernames text[];
  active_count integer := 0;
  request_hash text;
  prior_hash text;
  prior_response jsonb;
  response_value jsonb;
begin
  perform set_config('lock_timeout', '2000', true);
  perform set_config('statement_timeout', '10000', true);
  if length(btrim(coalesce(p_idempotency_key, ''))) not between 12 and 180 then
    raise exception using errcode = '22023', message = 'SEASON_SALES_TOKEN_INVALID';
  end if;

  select coalesce(array_agg(requested.username order by requested.username), '{}'::text[])
  into normalized_usernames
  from (
    select distinct lower(btrim(value)) as username
    from unnest(coalesce(p_usernames, '{}'::text[])) as requested_value(value)
    where btrim(coalesce(requested_value.value, '')) <> ''
  ) requested;
  if cardinality(normalized_usernames) > 100 then
    raise exception using errcode = '22023', message = 'SEASON_SALES_USER_LIMIT';
  end if;

  select count(*) into active_count
  from public.profiles profile
  where lower(btrim(profile.username)) = any(normalized_usernames)
    and profile.disabled_at is null
    and (profile.locked_until is null or profile.locked_until <= now())
    and not profile.must_change_password
    and exists (
      select 1
      from private.get_effective_app_permissions_v1(
        profile.id, private.resolve_app_access_policy_id_v1(false)
      ) permission
      where permission.permission_key = 'module.sales-office.view'
        and permission.allowed
    );
  if active_count <> cardinality(normalized_usernames) then
    raise exception using errcode = '22023', message = 'SEASON_SALES_USER_INVALID';
  end if;

  request_hash := encode(extensions.digest(coalesce(array_to_string(normalized_usernames, '|'), ''), 'sha256'), 'hex');
  perform pg_advisory_xact_lock(hashtextextended('season-sales-note-users-v1', 0));
  select saved.request_hash, saved.response into prior_hash, prior_response
  from private.season_sales_office_idempotency saved
  where saved.operation = 'save_users'
    and saved.actor_username = lower(btrim(actor.username))
    and saved.idempotency_key = btrim(p_idempotency_key);
  if prior_response is not null then
    if prior_hash is distinct from request_hash then
      raise exception using errcode = '22023', message = 'SEASON_SALES_TOKEN_CONFLICT';
    end if;
    return prior_response;
  end if;

  insert into public.ph_app_settings (key, value, updated_by, updated_at)
  values (
    'av_blanks_photo_bypass_users',
    jsonb_build_object(
      'users', to_jsonb(normalized_usernames),
      'updatedAt', now(),
      'updatedBy', lower(btrim(actor.username))
    ),
    lower(btrim(actor.username)),
    now()
  )
  on conflict (key) do update set
    value = excluded.value,
    updated_by = excluded.updated_by,
    updated_at = excluded.updated_at;

  response_value := jsonb_build_object(
    'ok', true,
    'status', 'saved',
    'users', to_jsonb(normalized_usernames),
    'updatedAt', now(),
    'updatedBy', lower(btrim(actor.username))
  );
  insert into public.ph_season_sales_note_user_events (
    actor_username, allowed_usernames, idempotency_key, metadata
  ) values (
    lower(btrim(actor.username)), normalized_usernames, btrim(p_idempotency_key),
    jsonb_build_object('count', cardinality(normalized_usernames))
  );
  insert into private.season_sales_office_idempotency (
    operation, actor_username, idempotency_key, request_hash, response
  ) values (
    'save_users', lower(btrim(actor.username)), btrim(p_idempotency_key),
    request_hash, response_value
  );
  return response_value;
end
$$;


ALTER FUNCTION public.save_season_sales_note_users_v1(p_actor_username text, p_usernames text[], p_idempotency_key text) OWNER TO postgres;

--
-- Name: save_season_sales_office_av_note_v1(text, text, integer, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.save_season_sales_office_av_note_v1(p_actor_username text, p_master_id text, p_expected_revision integer, p_av_note text, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'extensions'
    AS $$
declare
  actor public.profiles := private.season_sales_assert_actor_v1(p_actor_username);
  state_row public.ph_season_sales_office_state;
  winner public.ph_master_inventory;
  evidence jsonb;
  request_hash text;
  prior private.season_sales_office_idempotency;
  response_value jsonb;
begin
  perform pg_advisory_xact_lock(hashtextextended('season-sales-office-v1', 0));
  if length(btrim(coalesce(p_idempotency_key, ''))) < 12 then
    raise exception using errcode = '22023', message = 'SEASON_SALES_TOKEN_INVALID';
  end if;
  request_hash := encode(digest(concat_ws('|', p_master_id, p_expected_revision::text, coalesce(p_av_note, '')), 'sha256'), 'hex');
  select * into prior from private.season_sales_office_idempotency request
  where request.operation = 'save_av_note' and request.actor_username = lower(actor.username)
    and request.idempotency_key = btrim(p_idempotency_key);
  if prior.idempotency_key is not null then
    if prior.request_hash <> request_hash then
      raise exception using errcode = '22023', message = 'SEASON_SALES_TOKEN_CONFLICT';
    end if;
    return prior.response;
  end if;
  select * into state_row from public.ph_season_sales_office_state state
  where state.winner_unique_id = btrim(p_master_id) and state.status = 'open'
    and state.season_code = upper(btrim(coalesce(private.season_sales_settings_v1()->>'seasonCode', '')))
    and state.sales_year = private.season_sales_year_v1(private.season_sales_settings_v1()->>'salesYear')
  order by state.updated_at desc limit 1 for update;
  if state_row.id is null then raise exception using errcode = '40001', message = 'SEASON_SALES_NOT_OPEN'; end if;
  if state_row.revision <> p_expected_revision then raise exception using errcode = '40001', message = 'SEASON_SALES_STALE_REVISION'; end if;
  select * into winner from public.ph_master_inventory m where m.unique_id = state_row.winner_unique_id for update;
  if winner.unique_id is null then raise exception using errcode = '40001', message = 'SEASON_SALES_WINNER_CHANGED'; end if;
  update public.ph_master_inventory m set
    av_note = nullif(btrim(coalesce(p_av_note, '')), ''),
    av_rule_av_note_updated_at = now(), av_rule_bundle_updated_at = now(),
    av_rule_priority_snapshot = m.priority,
    av_rule_holdstop_snapshot = concat_ws('|', nullif(btrim(coalesce(m.holdstopcode, '')), ''), nullif(btrim(coalesce(m.holdstopreason, '')), '')),
    last_updated = now()
  where m.unique_id = winner.unique_id returning * into winner;
  evidence := private.season_sales_evidence_v1(to_jsonb(winner));
  update public.ph_season_sales_office_state state set
    retained_av_note = winner.av_note, retained_av_note_at = clock_timestamp(),
    revision = state.revision + 1, readiness_status = evidence->>'status',
    current_evidence_snapshot = evidence, source_fingerprint = evidence->>'fingerprint',
    updated_at = now()
  where state.id = state_row.id returning * into state_row;
  perform private.season_sales_mirror_winner_v1(winner, state_row);
  insert into public.ph_season_sales_office_events (state_id, event_type, actor_username, revision, metadata)
  values (state_row.id, 'av_note_saved', lower(actor.username), state_row.revision, '{}'::jsonb);
  response_value := jsonb_build_object('ok', true, 'status', 'saved', 'masterId', winner.unique_id,
    'revision', state_row.revision, 'readinessStatus', state_row.readiness_status,
    'workflowDetail', state_row.current_evidence_snapshot, 'avNote', coalesce(winner.av_note, ''));
  insert into private.season_sales_office_idempotency(operation, actor_username, idempotency_key, request_hash, response)
  values ('save_av_note', lower(actor.username), btrim(p_idempotency_key), request_hash, response_value);
  return response_value;
end
$$;


ALTER FUNCTION public.save_season_sales_office_av_note_v1(p_actor_username text, p_master_id text, p_expected_revision integer, p_av_note text, p_idempotency_key text) OWNER TO postgres;

--
-- Name: search_historical_inventory_common_names(text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.search_historical_inventory_common_names(search_text text, result_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare
  safe_search text := lower(btrim(coalesce(search_text, '')));
  safe_limit integer := least(greatest(coalesce(result_limit, 100), 1), 100);
  result_rows jsonb;
begin
  if not private.can_manage_eval_assignments() then
    raise exception using errcode = '42501', message = 'HISTORICAL_REPORT_FORBIDDEN';
  end if;

  select coalesce(jsonb_agg(to_jsonb(matches) order by matches.match_rank, matches.commonname), '[]'::jsonb)
  into result_rows
  from (
    select
      max(d.commonname) as commonname,
      count(distinct d.contsize_key)::integer as contsize_count,
      sum(d.historical_row_count)::bigint as historical_row_count,
      min(d.first_report_date) as first_report_date,
      max(d.last_report_date) as last_report_date,
      case
        when safe_search = '' then 0
        when d.commonname_key like safe_search || '%' then 0
        else 1
      end as match_rank
    from public.ph_historical_inventory_dimensions d
    where safe_search = '' or strpos(d.commonname_key, safe_search) > 0
    group by d.commonname_key
    order by match_rank, max(d.commonname)
    limit safe_limit
  ) matches;

  return result_rows;
end;
$$;


ALTER FUNCTION public.search_historical_inventory_common_names(search_text text, result_limit integer) OWNER TO postgres;

