-- Name: FUNCTION search_historical_inventory_common_names(search_text text, result_limit integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.search_historical_inventory_common_names(search_text text, result_limit integer) IS 'Dylan/Megan-only Common Name search for the Manager Historical Report.';


--
-- Name: send_onesignal_push(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.send_onesignal_push(target_user text, push_message text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  payload jsonb;
BEGIN
  payload := jsonb_build_object(
    'app_id', '15e7798a-29ff-427d-9648-8054b3ac03b4',
    'target_channel', 'push',
    'include_aliases', jsonb_build_object('external_id', jsonb_build_array(target_user)),
    'contents', jsonb_build_object('en', push_message)
  );

  PERFORM net.http_post(
      url:='https://api.onesignal.com/notifications',
      headers:=jsonb_build_object(
        'Content-Type', 'application/json', 
        'Authorization', 'Basic ' || (
          SELECT decrypted_secret
          FROM vault.decrypted_secrets
          WHERE name = 'onesignal_rich_api_key'
          LIMIT 1
        )
      ),
      body:=payload
  );
END;
$$;


ALTER FUNCTION public.send_onesignal_push(target_user text, push_message text) OWNER TO postgres;

--
-- Name: set_eval_item_low_stock_override_v1(text, integer, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_eval_item_low_stock_override_v1(p_itemcode text, p_override_qty integer, p_expected_revision bigint) RETURNS TABLE(itemcode_normalized text, qualifying_line_count integer, qualifying_day_count integer, source_file_count integer, mean_quantity numeric, p75_quantity numeric, suggested_qty integer, manual_override_qty integer, effective_qty integer, override_revision bigint, history_ready boolean, history_pending_files integer, history_total_files integer, history_from_date date, history_through_date date, calculated_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor public.profiles;
  item_key text := upper(btrim(coalesce(p_itemcode, '')));
  current_row private.ph_eval_item_low_stock_overrides%rowtype;
  current_revision bigint;
  next_revision bigint;
  fallback_qty integer;
begin
  actor := private.current_active_profile();
  if actor.id is null or lower(btrim(actor.username)) not in ('dylan_collyge', 'megan_kelly', 'jd_jones') then
    raise exception using errcode = '42501', message = 'LOW_STOCK_OVERRIDE_FORBIDDEN';
  end if;
  if item_key = '' or p_expected_revision is null
     or (p_override_qty is not null and p_override_qty not between 0 and 100000000) then
    raise exception using errcode = '22023', message = 'LOW_STOCK_OVERRIDE_INVALID';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(item_key, 904221));
  select * into current_row
  from private.ph_eval_item_low_stock_overrides o
  where o.itemcode_normalized = item_key
  for update;
  current_revision := coalesce(current_row.revision, 0);
  if current_revision <> p_expected_revision then
    raise exception using errcode = '40001', message = 'LOW_STOCK_OVERRIDE_CONFLICT';
  end if;

  if p_override_qty is not distinct from current_row.manual_override_qty
     and (current_row.itemcode_normalized is not null or p_override_qty is null) then
    null;
  else
    next_revision := current_revision + 1;
    insert into private.ph_eval_item_low_stock_overrides(
      itemcode_normalized, manual_override_qty, revision, updated_by, updated_at
    ) values (item_key, p_override_qty, next_revision, lower(btrim(actor.username)), now())
    on conflict on constraint ph_eval_item_low_stock_overrides_pkey do update
      set manual_override_qty = excluded.manual_override_qty,
          revision = excluded.revision,
          updated_by = excluded.updated_by,
          updated_at = excluded.updated_at;
    insert into private.ph_eval_item_low_stock_override_audit(
      itemcode_normalized, old_override_qty, new_override_qty, revision, changed_by
    ) values (
      item_key,
      case when current_row.itemcode_normalized is null then null else current_row.manual_override_qty end,
      p_override_qty,
      next_revision,
      lower(btrim(actor.username))
    );
  end if;

  select coalesce((select s.low_stock_max_slts from public.ph_eval_report_settings s where s.singleton limit 1), 150)
  into fallback_qty;
  return query
  select
    item_key,
    coalesce(s.qualifying_line_count, 0),
    coalesce(s.qualifying_day_count, 0),
    coalesce(s.source_file_count, 0),
    s.mean_quantity,
    s.p75_quantity,
    s.suggested_qty,
    o.manual_override_qty,
    coalesce(o.manual_override_qty, s.suggested_qty, fallback_qty),
    coalesce(o.revision, 0),
    coalesce(h.history_ready, false),
    coalesce(h.history_pending_files, 0),
    coalesce(h.history_total_files, 0),
    s.history_from_date,
    s.history_through_date,
    s.updated_at,
    greatest(s.updated_at, o.updated_at)
  from (select item_key as itemcode_normalized) item
  left join private.eval_item_low_stock_target_stats_v1 s
    on s.itemcode_normalized = item.itemcode_normalized
  left join private.ph_eval_item_low_stock_overrides o
    on o.itemcode_normalized = item.itemcode_normalized
  cross join (
    select
      state.active_run_id is not null and state.pending_run_id is null as history_ready,
      coalesce(jsonb_array_length(scan.expected_manifest), 0)::integer as history_total_files,
      coalesce((
        select count(*)::integer
        from private.ph_eval_item_low_stock_run_files rf
        left join private.ph_eval_item_low_stock_file_versions fv on fv.file_version_id = rf.file_version_id
        where rf.run_id = scan.run_id
          and (rf.file_version_id is null or fv.status <> 'finalized')
      ), 0) as history_pending_files
    from private.ph_eval_item_low_stock_import_state state
    left join private.ph_eval_item_low_stock_import_runs scan
      on scan.run_id = coalesce(state.pending_run_id, state.active_run_id)
    where state.singleton
  ) h;
end
$$;


ALTER FUNCTION public.set_eval_item_low_stock_override_v1(p_itemcode text, p_override_qty integer, p_expected_revision bigint) OWNER TO postgres;

--
-- Name: set_eval_itemcode_assignment(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_eval_itemcode_assignment(itemcode text, assignedto text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  resolved_genus text;
begin
  select min(x.genusname) into resolved_genus
  from (
    select max(mi.genusname) as genusname
    from public.ph_master_inventory mi
    where upper(btrim(coalesce(mi.itemcode, ''))) = upper(btrim(coalesce(itemcode, '')))
    group by lower(regexp_replace(btrim(coalesce(mi.genusname, '')), '[[:space:]]+', ' ', 'g'))
  ) x
  having count(*) = 1;

  if resolved_genus is null then
    raise exception using errcode = '22023', message = 'GENUSNAME_REQUIRED';
  end if;

  return public.set_eval_itemcode_assignment(itemcode, resolved_genus, assignedto);
end;
$$;


ALTER FUNCTION public.set_eval_itemcode_assignment(itemcode text, assignedto text) OWNER TO postgres;

--
-- Name: FUNCTION set_eval_itemcode_assignment(itemcode text, assignedto text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.set_eval_itemcode_assignment(itemcode text, assignedto text) IS 'Secured global ItemCode assignment function for dylan_collyge and megan_kelly.';


--
-- Name: set_eval_itemcode_assignment(text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_eval_itemcode_assignment(itemcode text, genusname text, assignedto text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  normalized_code text := upper(btrim(coalesce(itemcode, '')));
  resolved_genus text := nullif(btrim(coalesce(genusname, '')), '');
  normalized_genus text;
  normalized_key text;
  requested_assignee text := nullif(lower(btrim(coalesce(assignedto, ''))), '');
  canonical_assignee text;
  manager_username text;
  drive_row record;
  assignment public.ph_warehouse_assigned_items%rowtype;
begin
  if not private.can_manage_eval_assignments() then
    raise exception using errcode = '42501', message = 'EVAL_ASSIGNMENT_FORBIDDEN';
  end if;
  perform 1 from public.app_dataset_revisions where key='ph_master_inventory' for share;
  if not found or (select state from public.app_dataset_revisions where key='ph_master_inventory') is distinct from 'ready' then
    raise exception using errcode='55000',message='EVAL_ASSIGNMENT_SOURCE_NOT_READY';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('gnc-reconcile-eval-itemcodes-v2',0));
  if normalized_code = '' then
    raise exception using errcode = '22023', message = 'ITEMCODE_REQUIRED';
  end if;

  if requested_assignee = 'charey_robertson' then
    requested_assignee := 'charley_robertson';
  end if;

  if resolved_genus is null then
    select min(x.genusname) into resolved_genus
    from (
      select max(mi.genusname) as genusname
      from public.ph_master_inventory mi
      where upper(btrim(coalesce(mi.itemcode, ''))) = normalized_code
      group by lower(regexp_replace(btrim(coalesce(mi.genusname, '')), '[[:space:]]+', ' ', 'g'))
    ) x
    having count(*) = 1;
  end if;

  if resolved_genus is null then
    select min(a.genusname) into resolved_genus
    from public.ph_warehouse_assigned_items a
    where a.itemcode_normalized = normalized_code
    having count(distinct a.genusname_normalized) = 1;
  end if;

  if resolved_genus is null then
    raise exception using errcode = '22023', message = 'GENUSNAME_REQUIRED';
  end if;

  normalized_genus := lower(regexp_replace(btrim(resolved_genus), '[[:space:]]+', ' ', 'g'));
  normalized_key := private.normalize_eval_assignment_key(normalized_code, resolved_genus);
  if exists(select 1 from public.ph_warehouse_assigned_items where assignment_key=normalized_key and zone_override_active) then
    raise exception using errcode='55000',message='EVAL_ASSIGNMENT_ZONE_LOCKED';
  end if;
  manager_username := (private.current_active_profile()).username;

  if requested_assignee is not null then
    select u.username into canonical_assignee
    from public.ph_eval_assignment_users u
    where u.active
      and lower(btrim(u.username)) = requested_assignee
    limit 1;
    if canonical_assignee is null then
      raise exception using errcode = '22023', message = 'ASSIGNEE_NOT_IN_EVAL_ROSTER';
    end if;
  end if;

  select
    max(mi.genusname) as genusname,
    max(mi.commonname) as commonname,
    max(mi.contsize) as contsize,
    max(mi.locationcode) as locationcode
  into drive_row
  from public.ph_master_inventory mi
  where upper(btrim(coalesce(mi.itemcode, ''))) = normalized_code
    and lower(regexp_replace(btrim(coalesce(mi.genusname, '')), '[[:space:]]+', ' ', 'g')) = normalized_genus;

  resolved_genus := coalesce(nullif(btrim(drive_row.genusname), ''), resolved_genus);

  insert into public.ph_warehouse_assigned_items (
    unique_id, itemcode, itemcode_normalized, genusname, genusname_normalized,
    concat, assignment_key, assignedto, assigned_by, assigned_at,
    commonname, contsize, locationcode, first_seen_at, last_seen_at,
    present_in_drive, source, raw_row, updated_at, unassigned_notified_at
  ) values (
    'eval-itemcode-genus-' || md5(normalized_key),
    normalized_code,
    normalized_code,
    resolved_genus,
    normalized_genus,
    normalized_code || resolved_genus,
    normalized_key,
    canonical_assignee,
    manager_username,
    case when canonical_assignee is null then null else now() end,
    drive_row.commonname,
    drive_row.contsize,
    drive_row.locationcode,
    now(),
    now(),
    exists (
      select 1
      from public.ph_master_inventory mi
      where upper(btrim(coalesce(mi.itemcode, ''))) = normalized_code
        and lower(regexp_replace(btrim(coalesce(mi.genusname, '')), '[[:space:]]+', ' ', 'g')) = normalized_genus
    ),
    'supabase_assignment_manager',
    jsonb_build_object('authority', 'supabase', 'scope', 'itemcode_genus'),
    now(),
    case when canonical_assignee is null then null else now() end
  )
  on conflict (assignment_key) where assignment_key is not null
  do update set
    itemcode = excluded.itemcode,
    itemcode_normalized = excluded.itemcode_normalized,
    genusname = excluded.genusname,
    genusname_normalized = excluded.genusname_normalized,
    concat = excluded.concat,
    assignedto = excluded.assignedto,
    assigned_by = excluded.assigned_by,
    assigned_at = excluded.assigned_at,
    commonname = coalesce(excluded.commonname, public.ph_warehouse_assigned_items.commonname),
    contsize = coalesce(excluded.contsize, public.ph_warehouse_assigned_items.contsize),
    locationcode = coalesce(excluded.locationcode, public.ph_warehouse_assigned_items.locationcode),
    source = excluded.source,
    raw_row = excluded.raw_row,
    updated_at = now(),
    unassigned_notified_at = case
      when excluded.assignedto is null
           and nullif(btrim(coalesce(public.ph_warehouse_assigned_items.assignedto, '')), '') is not null
        then null
      when excluded.assignedto is not null then now()
      else public.ph_warehouse_assigned_items.unassigned_notified_at
    end
  returning * into assignment;

  if canonical_assignee is null and assignment.unassigned_notified_at is null then
    insert into public.ph_request_delivery_outbox (
      event_key, event_type, payload, status
    ) values (
      'eval-unassigned:' || md5(normalized_key),
      'eval_assignment_unassigned',
      jsonb_build_object(
        'itemcode', normalized_code,
        'genusname', resolved_genus,
        'assignment_key', normalized_key,
        'manager_usernames', jsonb_build_array('dylan_collyge', 'megan_kelly')
      ),
      'pending'
    )
    on conflict (event_key) do update set
      status = 'pending',
      next_attempt_at = now(),
      delivered_at = null,
      sanitized_error_code = null;

    update public.ph_warehouse_assigned_items
    set unassigned_notified_at = now(), updated_at = now()
    where id = assignment.id
    returning * into assignment;
  end if;

  return to_jsonb(assignment);
end;
$$;


ALTER FUNCTION public.set_eval_itemcode_assignment(itemcode text, genusname text, assignedto text) OWNER TO postgres;

