--
-- Name: stage_eval_item_low_stock_rows_v1(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.stage_eval_item_low_stock_rows_v1(p_file_version_id uuid, p_rows jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  version_status text;
  inserted_count integer;
  input_count integer;
begin
  select status into version_status
  from private.ph_eval_item_low_stock_file_versions
  where file_version_id = p_file_version_id
  for update;
  if version_status is null or version_status <> 'importing' then
    raise exception using errcode = '55000', message = 'LOW_STOCK_IMPORT_FILE_NOT_STAGING';
  end if;
  if p_rows is null or jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) > 1000 then
    raise exception using errcode = '22023', message = 'LOW_STOCK_IMPORT_ROWS_INVALID';
  end if;
  select count(*) into input_count from jsonb_array_elements(p_rows);
  if exists (
    select 1 from jsonb_to_recordset(p_rows) as x(
      group_key text, itemcode text, quantity_ordered numeric, dock text,
      source_row_number integer, source_sheet_name text
    )
    where nullif(btrim(group_key), '') is null
       or nullif(btrim(itemcode), '') is null
       or quantity_ordered is null or quantity_ordered <= 0
       or quantity_ordered::text in ('NaN', 'Infinity', '-Infinity')
       or nullif(btrim(itemcode), '') is null or upper(btrim(itemcode)) in ('NULL', 'NAN', 'UNDEFINED')
       or nullif(btrim(dock), '') is null
       or lower(btrim(dock)) in ('null', 'nan', 'undefined')
       or (regexp_replace(btrim(dock), ',', '', 'g') ~ '^[+-]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)$'
           and regexp_replace(btrim(dock), ',', '', 'g')::numeric = 0)
       or source_row_number is null or source_row_number <= 0
       or nullif(btrim(source_sheet_name), '') is null
  ) or (
    select count(*) from jsonb_to_recordset(p_rows) as x(
      group_key text, itemcode text, quantity_ordered numeric, dock text,
      source_row_number integer, source_sheet_name text
    )
  ) <> (
    select count(distinct source_row_number) from jsonb_to_recordset(p_rows) as x(
      group_key text, itemcode text, quantity_ordered numeric, dock text,
      source_row_number integer, source_sheet_name text
    )
  ) then
    raise exception using errcode = '22023', message = 'LOW_STOCK_IMPORT_ROWS_INVALID';
  end if;
  if exists (
    select 1
    from jsonb_to_recordset(p_rows) as x(
      group_key text, itemcode text, quantity_ordered numeric, dock text,
      source_row_number integer, source_sheet_name text
    )
    join private.ph_eval_item_low_stock_file_versions v on v.file_version_id = p_file_version_id
    where btrim(x.source_sheet_name) <> coalesce(v.source_sheet_name, '')
  ) then
    raise exception using errcode = '22023', message = 'LOW_STOCK_IMPORT_SHEET_MISMATCH';
  end if;

  insert into private.ph_eval_item_low_stock_order_rows(
    file_version_id, source_row_number, group_key, itemcode, quantity_ordered, dock, source_sheet_name
  )
  select p_file_version_id, x.source_row_number, btrim(x.group_key), btrim(x.itemcode),
    x.quantity_ordered, btrim(x.dock), btrim(x.source_sheet_name)
  from jsonb_to_recordset(p_rows) as x(
    group_key text, itemcode text, quantity_ordered numeric, dock text,
    source_row_number integer, source_sheet_name text
  )
  on conflict (file_version_id, source_row_number) do nothing;

  if exists (
    select 1
    from jsonb_to_recordset(p_rows) as x(
      group_key text, itemcode text, quantity_ordered numeric, dock text,
      source_row_number integer, source_sheet_name text
    )
    join private.ph_eval_item_low_stock_order_rows r
      on r.file_version_id = p_file_version_id and r.source_row_number = x.source_row_number
    where r.group_key <> btrim(x.group_key)
       or r.itemcode <> btrim(x.itemcode)
       or r.quantity_ordered <> x.quantity_ordered
       or r.dock <> btrim(x.dock)
       or r.source_sheet_name <> btrim(x.source_sheet_name)
  ) then
    raise exception using errcode = '22023', message = 'LOW_STOCK_IMPORT_ROW_CHANGED';
  end if;
  return input_count;
end
$_$;


ALTER FUNCTION public.stage_eval_item_low_stock_rows_v1(p_file_version_id uuid, p_rows jsonb) OWNER TO postgres;

--
-- Name: submit_eval_work_v1(uuid, text, integer, jsonb, jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.submit_eval_work_v1(p_work_id uuid, p_actor_username text, p_expected_version integer, p_inquiry jsonb, p_evidence jsonb, p_submission_token text) RETURNS public.ph_eval_work
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor public.profiles;
  work public.ph_eval_work;
  origin public.ph_master_inventory;
  current_rows jsonb;
  settings jsonb;
  photos jsonb;
  photo_links text;
  photo_names text;
  photo jsonb;
  photo_path text;
  spec_value text;
  match_value numeric;
  av_note_value text;
  ptr_value numeric;
  delivery public.ph_request_delivery_outbox;
  baseline_row jsonb;
  current_row jsonb;
  overlay jsonb;
  proposed_uid text;
begin
  actor := private.eval_work_assert_actor_v1(p_actor_username);
  select * into work from public.ph_eval_work where id = p_work_id for update;
  if work.id is null or lower(work.assignee_username) <> lower(actor.username) then
    raise exception using errcode = '42501', message = 'eval_work_submit_forbidden';
  end if;
  if work.status = 'submitted' and work.submission_token = trim(coalesce(p_submission_token, '')) then return work; end if;
  if length(trim(coalesce(p_submission_token, ''))) < 16 or length(trim(coalesce(p_submission_token, ''))) > 240 then raise exception using errcode = '22023', message = 'eval_work_submission_token_invalid'; end if;
  if work.status not in ('open', 'in_progress') then raise exception using errcode = '22023', message = 'eval_work_not_submittable'; end if;
  if work.version <> p_expected_version then raise exception using errcode = '40001', message = 'eval_work_version_conflict'; end if;
  select * into origin from public.ph_master_inventory where unique_id = work.origin_unique_id for update;
  if origin.unique_id is null or lower(trim(coalesce(origin.itemcode, ''))) <> lower(trim(work.itemcode))
     or coalesce(origin.locationcode, '') <> work.origin_locationcode or coalesce(origin.lotcode, '') <> work.origin_lotcode then
    raise exception using errcode = '40001', message = 'eval_work_origin_identity_conflict';
  end if;
  current_rows := private.eval_work_context_rows_v1(work.itemcode);
  settings := private.eval_work_settings_v1();
  if md5(settings::text) <> work.settings_signature then
    raise exception using errcode = '40001', message = 'eval_work_settings_conflict';
  end if;
  for overlay in select value from jsonb_array_elements(coalesce(p_inquiry->'rowOverlays', '[]'::jsonb)) loop
    if jsonb_array_length(coalesce(overlay->'proposals', '[]'::jsonb)) = 0 then continue; end if;
    proposed_uid := trim(coalesce(overlay->>'unique_id', ''));
    select value into baseline_row from jsonb_array_elements(coalesce(work.context_rows, '[]'::jsonb)) where value->>'unique_id' = proposed_uid limit 1;
    select value into current_row from jsonb_array_elements(coalesce(current_rows, '[]'::jsonb)) where value->>'unique_id' = proposed_uid limit 1;
    if baseline_row is null or current_row is null
       or coalesce(baseline_row->>'itemcode', '') <> coalesce(current_row->>'itemcode', '')
       or coalesce(baseline_row->>'locationcode', '') <> coalesce(current_row->>'locationcode', '')
       or coalesce(baseline_row->>'lotcode', '') <> coalesce(current_row->>'lotcode', '')
       or coalesce(baseline_row->>'ptronhand', '') <> coalesce(current_row->>'ptronhand', '') then
      raise exception using errcode = '40001', message = 'eval_work_target_conflict';
    end if;
  end loop;
  perform private.validate_eval_work_inquiry_v1(coalesce(p_inquiry, work.inquiry_draft), work.itemcode, current_rows);

  photos := coalesce(p_evidence->'photos', '[]'::jsonb);
  spec_value := trim(coalesce(p_evidence->>'spec', ''));
  av_note_value := trim(coalesce(p_evidence->>'avNote', ''));
  if jsonb_typeof(photos) <> 'array' or jsonb_array_length(photos) = 0 then raise exception using errcode = '22023', message = 'eval_work_photo_required'; end if;
  if spec_value = '' then raise exception using errcode = '22023', message = 'eval_work_spec_required'; end if;
  if av_note_value = '' then raise exception using errcode = '22023', message = 'eval_work_av_note_required'; end if;
  begin match_value := trim(coalesce(p_evidence->>'locMatchPercent', ''))::numeric;
  exception when others then raise exception using errcode = '22023', message = 'eval_work_loc_match_invalid'; end;
  if match_value < 0 or match_value > 100 then raise exception using errcode = '22023', message = 'eval_work_loc_match_invalid'; end if;
  for photo in select value from jsonb_array_elements(photos) loop
    photo_path := trim(coalesce(photo->>'filePath', photo->>'file_path', photo->>'path', ''));
    if left(photo_path, length('eval/' || work.id::text || '/')) <> 'eval/' || work.id::text || '/'
       or position('..' in photo_path) > 0 then
      raise exception using errcode = '22023', message = 'eval_work_photo_scope_invalid';
    end if;
  end loop;
  select string_agg(trim(value->>'url'), E'\n' order by ordinality), string_agg(trim(coalesce(value->>'name', 'eval-photo')), E'\n' order by ordinality)
    into photo_links, photo_names
  from jsonb_array_elements(photos) with ordinality
  where trim(coalesce(value->>'url', '')) <> '';
  if coalesce(photo_links, '') = '' then raise exception using errcode = '22023', message = 'eval_work_committed_photo_required'; end if;
  begin ptr_value := nullif(regexp_replace(coalesce(origin.ptravailable, ''), '[^0-9.-]', '', 'g'), '')::numeric; exception when others then ptr_value := null; end;

  update public.ph_master_inventory set
    spec = spec_value,
    match = trim(to_char(match_value, 'FM999990.##')),
    initial_ptr = case when trim(coalesce(initial_ptr, '')) <> '' or ptr_value is null then initial_ptr else trim(to_char(ptr_value, 'FM999999990.##')) end,
    loc_match_qty = case when ptr_value is null then loc_match_qty else round(ptr_value * match_value / 100)::text end,
    av_note = av_note_value,
    caliper = case when trim(coalesce(p_evidence->>'caliper', '')) = '' then caliper else trim(p_evidence->>'caliper') end,
    pic_note = case when trim(coalesce(p_evidence->>'pickNote', '')) = '' then pic_note else trim(p_evidence->>'pickNote') end,
    sales_note = case when trim(coalesce(p_evidence->>'comments', '')) = '' then sales_note else trim(p_evidence->>'comments') end,
    photo_link = photo_links,
    photo_name = photo_names,
    last_updated = now()
  where unique_id = origin.unique_id;

  update public.ph_eval_work set
    inquiry_draft = coalesce(p_inquiry, inquiry_draft), evidence_draft = p_evidence,
    submitted_inquiry = coalesce(p_inquiry, inquiry_draft), submitted_evidence = p_evidence,
    context_rows = current_rows, inventory_signature = md5(current_rows::text),
    status = 'submitted', submission_token = trim(p_submission_token), submitted_at = now(), version = version + 1, updated_at = now()
  where id = work.id returning * into work;
  insert into public.ph_eval_work_events(eval_work_id, event_type, actor_username, version, metadata)
  values (work.id, 'submitted', lower(actor.username), work.version,
    jsonb_build_object('photoCount', jsonb_array_length(photos), 'proposalCount', coalesce(jsonb_array_length(work.submitted_inquiry#>'{transaction,requestActions}'), 0)));
  insert into public.ph_request_delivery_outbox(event_key, event_type, request_id, payload, status, next_attempt_at)
  values (
    'eval-work:' || work.id::text || ':completion:v' || work.version::text,
    'eval_work_completion', work.id::text,
    jsonb_build_object(
      'contractVersion', 'eval-work-v1', 'deliveryKind', 'completion', 'evalWorkId', work.id,
      'assigneeUsername', work.assignee_username, 'assigneeDisplay', work.assignee_display,
      'creatorUsername', work.creator_username, 'creatorDisplay', work.creator_display,
      'completionRecipients', to_jsonb(work.completion_recipients), 'instructions', work.instructions,
      'itemcode', work.itemcode, 'commonname', work.commonname, 'contsize', work.contsize,
      'source', jsonb_build_object('unique_id', work.origin_unique_id, 'itemcode', work.itemcode, 'locationcode', work.origin_locationcode, 'lotcode', work.origin_lotcode, 'source_table', 'ph_master_inventory'),
      'inquiry', work.submitted_inquiry, 'evidence', work.submitted_evidence
    ), 'pending', now()
  ) on conflict (event_key) do update set updated_at = now()
  returning * into delivery;
  update public.ph_eval_work set completion_event_id = delivery.event_id where id = work.id returning * into work;
  return work;
end
$$;


ALTER FUNCTION public.submit_eval_work_v1(p_work_id uuid, p_actor_username text, p_expected_version integer, p_inquiry jsonb, p_evidence jsonb, p_submission_token text) OWNER TO postgres;

--
-- Name: submit_eval_work_v2(uuid, text, integer, jsonb, jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.submit_eval_work_v2(p_work_id uuid, p_actor_username text, p_expected_version integer, p_inquiry jsonb, p_evidence_by_origin jsonb, p_submission_token text) RETURNS public.ph_eval_work
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  work public.ph_eval_work;
  current_rows jsonb;
  submitted public.ph_eval_work;
  delivery public.ph_request_delivery_outbox;
  apply_parity boolean := false;
begin
  select * into work from public.ph_eval_work where id = p_work_id;
  if work.id is null then
    raise exception using errcode = '22023', message = 'eval_work_not_found';
  end if;

  if coalesce(work.source_context->>'scopeContract', '') = 'itemcode-all-rows-v1' then
    current_rows := private.eval_work_assert_itemcode_membership_v1(p_work_id);
    if jsonb_array_length(coalesce(p_inquiry->'rowOverlays', '[]'::jsonb)) <> work.origin_count
       or (select count(distinct value->>'unique_id') from jsonb_array_elements(coalesce(p_inquiry->'rowOverlays', '[]'::jsonb))) <> work.origin_count then
      raise exception using errcode = '40001', message = 'eval_work_itemcode_overlay_membership_conflict';
    end if;
    if jsonb_typeof(coalesce(p_evidence_by_origin, '{}'::jsonb)) <> 'object'
       or (select count(*) from jsonb_object_keys(coalesce(p_evidence_by_origin, '{}'::jsonb))) <> work.origin_count
       or exists (
         select 1
         from jsonb_each(coalesce(p_evidence_by_origin, '{}'::jsonb)) evidence
         where lower(trim(coalesce(evidence.value->>'picturesSpecsResolution', evidence.value->>'pictures_specs_resolution', ''))) <> 'done'
       ) then
      raise exception using errcode = '22023', message = 'eval_work_all_pictures_specs_mark_done_required';
    end if;
  end if;

  apply_parity := work.status in ('open', 'in_progress');
  submitted := public.submit_eval_work_v2_legacy_impl(
    p_work_id, p_actor_username, p_expected_version, p_inquiry, p_evidence_by_origin, p_submission_token
  );

  if apply_parity then
    perform private.eval_work_apply_request_drive_parity_v1(p_work_id, p_actor_username);
    select * into submitted from public.ph_eval_work where id = p_work_id;
  end if;

  if coalesce(submitted.source_context->>'scopeContract', '') = 'itemcode-all-rows-v1' then
    select * into delivery from public.ph_request_delivery_outbox where event_id = submitted.completion_event_id for update;
    update public.ph_request_delivery_outbox
      set payload = payload || jsonb_build_object(
        'scopeContract', 'itemcode-all-rows-v1',
        'membershipSignature', submitted.source_context->>'membershipSignature',
        'membershipCount', submitted.origin_count,
        'selectedUserFilters', coalesce(submitted.source_context#>'{report,selectedUserFilters}', '[]'::jsonb),
        'matchedAssignedToUsers', to_jsonb(submitted.assigned_to_users),
        'picturesSpecsContract', 'request-drive-parity-v1'
      ), updated_at = now()
      where event_id = submitted.completion_event_id;
  end if;
  return submitted;
end
$$;


ALTER FUNCTION public.submit_eval_work_v2(p_work_id uuid, p_actor_username text, p_expected_version integer, p_inquiry jsonb, p_evidence_by_origin jsonb, p_submission_token text) OWNER TO postgres;

--
-- Name: submit_eval_work_v2_legacy_impl(uuid, text, integer, jsonb, jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.submit_eval_work_v2_legacy_impl(p_work_id uuid, p_actor_username text, p_expected_version integer, p_inquiry jsonb, p_evidence_by_origin jsonb, p_submission_token text) RETURNS public.ph_eval_work
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor public.profiles;
  work public.ph_eval_work;
  origin_row public.ph_eval_work_origin_rows;
  origin public.ph_master_inventory;
  current_rows jsonb;
  settings jsonb;
  origin_ids text[];
  evidence jsonb;
  photos jsonb;
  photo jsonb;
  photo_path text;
  photo_links text;
  photo_names text;
  spec_value text;
  av_note_value text;
  match_value numeric;
  ptr_value numeric;
  delivery public.ph_request_delivery_outbox;
  result_origins jsonb;
begin
  actor := private.eval_work_assert_actor_v1(p_actor_username);
  select * into work from public.ph_eval_work where id = p_work_id for update;
  if work.id is null or work.contract_version <> 'eval-work-v2-multi-origin'
     or not (lower(actor.username) = any(coalesce(work.assignee_usernames, array[lower(work.assignee_username)]))) then
    raise exception using errcode = '42501', message = 'eval_work_submit_forbidden';
  end if;
  if work.status = 'submitted' and work.submission_token = trim(coalesce(p_submission_token, '')) then return work; end if;
  if length(trim(coalesce(p_submission_token, ''))) < 16 or length(trim(coalesce(p_submission_token, ''))) > 240 then
    raise exception using errcode = '22023', message = 'eval_work_submission_token_invalid';
  end if;
  if work.status not in ('open', 'in_progress') or work.version <> p_expected_version then
    raise exception using errcode = '40001', message = 'eval_work_version_conflict';
  end if;
  if jsonb_typeof(coalesce(p_evidence_by_origin, '{}'::jsonb)) <> 'object' then
    raise exception using errcode = '22023', message = 'eval_work_evidence_map_invalid';
  end if;
  settings := private.eval_work_settings_v1();
  if md5(settings::text) <> work.settings_signature then
    raise exception using errcode = '40001', message = 'eval_work_settings_conflict';
  end if;
  select array_agg(origin_unique_id order by ordinal) into origin_ids
  from public.ph_eval_work_origin_rows where eval_work_id = work.id;
  if cardinality(origin_ids) <> work.origin_count
     or (select count(*) from jsonb_object_keys(p_evidence_by_origin)) <> work.origin_count then
    raise exception using errcode = '22023', message = 'eval_work_all_origin_evidence_required';
  end if;
  current_rows := private.eval_work_context_rows_for_origins_v2(origin_ids);
  perform private.validate_eval_work_inquiry_v1(coalesce(p_inquiry, work.inquiry_draft), work.itemcode, current_rows);

  for origin_row in select * from public.ph_eval_work_origin_rows where eval_work_id = work.id order by ordinal for update loop
    select * into origin from public.ph_master_inventory where unique_id = origin_row.origin_unique_id for update;
    if origin.unique_id is null
       or upper(trim(coalesce(origin.itemcode, ''))) <> upper(trim(origin_row.itemcode))
       or coalesce(origin.locationcode, '') <> origin_row.locationcode
       or coalesce(origin.lotcode, '') <> origin_row.lotcode
       or coalesce(to_jsonb(origin)->>'ptronhand', '') <> coalesce(origin_row.origin_snapshot->>'ptronhand', '') then
      raise exception using errcode = '40001', message = 'eval_work_origin_identity_conflict';
    end if;
    evidence := p_evidence_by_origin->(origin_row.origin_unique_id);
    photos := coalesce(evidence->'photos', '[]'::jsonb);
    spec_value := trim(coalesce(evidence->>'spec', ''));
    av_note_value := trim(coalesce(evidence->>'avNote', evidence->>'av_note', ''));
    if jsonb_typeof(photos) <> 'array' or jsonb_array_length(photos) = 0 then raise exception using errcode = '22023', message = 'eval_work_photo_required'; end if;
    if spec_value = '' then raise exception using errcode = '22023', message = 'eval_work_spec_required'; end if;
    if av_note_value = '' then raise exception using errcode = '22023', message = 'eval_work_av_note_required'; end if;
    begin match_value := trim(coalesce(evidence->>'locMatchPercent', evidence->>'loc_match_percent', ''))::numeric;
    exception when others then raise exception using errcode = '22023', message = 'eval_work_loc_match_invalid'; end;
    if match_value < 0 or match_value > 100 then raise exception using errcode = '22023', message = 'eval_work_loc_match_invalid'; end if;
    for photo in select value from jsonb_array_elements(photos) loop
      photo_path := trim(coalesce(photo->>'filePath', photo->>'file_path', photo->>'path', ''));
      if left(photo_path, length('eval/' || work.id::text || '/' || origin_row.origin_unique_id || '/'))
           <> 'eval/' || work.id::text || '/' || origin_row.origin_unique_id || '/'
         or position('..' in photo_path) > 0 then
        raise exception using errcode = '22023', message = 'eval_work_photo_scope_invalid';
      end if;
    end loop;
    select string_agg(trim(value->>'url'), E'\n' order by ordinality),
           string_agg(trim(coalesce(value->>'name', 'eval-photo')), E'\n' order by ordinality)
      into photo_links, photo_names
    from jsonb_array_elements(photos) with ordinality
    where trim(coalesce(value->>'url', '')) <> '';
    if coalesce(photo_links, '') = '' then raise exception using errcode = '22023', message = 'eval_work_committed_photo_required'; end if;
    begin ptr_value := nullif(regexp_replace(coalesce(origin.ptravailable, ''), '[^0-9.-]', '', 'g'), '')::numeric; exception when others then ptr_value := null; end;
    update public.ph_master_inventory set
      spec = spec_value, match = trim(to_char(match_value, 'FM999990.##')),
      initial_ptr = case when trim(coalesce(initial_ptr, '')) <> '' or ptr_value is null then initial_ptr else trim(to_char(ptr_value, 'FM999999990.##')) end,
      loc_match_qty = case when ptr_value is null then loc_match_qty else round(ptr_value * match_value / 100)::text end,
      av_note = av_note_value,
      caliper = case when trim(coalesce(evidence->>'caliper', '')) = '' then caliper else trim(evidence->>'caliper') end,
      pic_note = case when trim(coalesce(evidence->>'pickNote', evidence->>'pick_note', '')) = '' then pic_note else trim(coalesce(evidence->>'pickNote', evidence->>'pick_note')) end,
      sales_note = case when trim(coalesce(evidence->>'comments', '')) = '' then sales_note else trim(evidence->>'comments') end,
      photo_link = photo_links, photo_name = photo_names, last_updated = now()
    where unique_id = origin.unique_id;
    update public.ph_eval_work_origin_rows set evidence_draft = evidence,
      submitted_evidence = evidence, updated_at = now()
    where eval_work_id = work.id and origin_unique_id = origin_row.origin_unique_id;
  end loop;

  update public.ph_eval_work set inquiry_draft = coalesce(p_inquiry, inquiry_draft),
    evidence_draft = p_evidence_by_origin, submitted_inquiry = coalesce(p_inquiry, inquiry_draft),
    submitted_evidence = p_evidence_by_origin, context_rows = current_rows,
    inventory_signature = md5(current_rows::text), status = 'submitted', submitted_by_username = lower(actor.username),
    submission_token = trim(p_submission_token), submitted_at = now(),
    version = version + 1, updated_at = now()
  where id = work.id returning * into work;
  insert into public.ph_eval_work_events(eval_work_id, event_type, actor_username, version, metadata)
  values (work.id, 'submitted', lower(actor.username), work.version,
    jsonb_build_object('originCount', work.origin_count, 'proposalCount',
      coalesce(jsonb_array_length(work.submitted_inquiry#>'{transaction,requestActions}'), 0)));
  select jsonb_agg((origin_snapshot || jsonb_build_object(
      'unique_id', origin_unique_id, 'itemcode', itemcode, 'locationcode', locationcode,
      'lotcode', lotcode, 'source', source, 'blockAlpha', block_alpha,
      'blockNumber', block_number, 'evidence', submitted_evidence)) order by ordinal)
    into result_origins
  from public.ph_eval_work_origin_rows where eval_work_id = work.id;
  insert into public.ph_request_delivery_outbox(event_key, event_type, request_id, payload, status, next_attempt_at)
  values (
    'eval-work:' || work.id::text || ':completion:v' || work.version::text,
    'eval_work_completion', work.id::text,
    jsonb_build_object(
      'contractVersion', 'eval-work-v2-multi-origin', 'deliveryKind', 'completion',
      'evalWorkId', work.id, 'assigneeUsername', work.assignee_username,
      'assigneeDisplay', work.assignee_display, 'creatorUsername', work.creator_username,
      'creatorDisplay', work.creator_display, 'completionRecipients', to_jsonb(work.completion_recipients),
      'lockedManagerRecipients', jsonb_build_array('dylan_collyge', 'megan_kelly'),
      'instructions', work.instructions, 'itemcode', work.itemcode,
      'commonname', work.commonname, 'contsize', work.contsize,
      'source', jsonb_build_object('unique_id', work.origin_unique_id, 'itemcode', work.itemcode,
        'locationcode', work.origin_locationcode, 'lotcode', work.origin_lotcode, 'source_table', 'ph_master_inventory'),
      'origins', result_origins, 'assignedToUsers', to_jsonb(work.assigned_to_users),
      'inquiry', work.submitted_inquiry, 'evidenceByOrigin', work.submitted_evidence
    ), 'pending', now()
  ) on conflict (event_key) do update set payload = excluded.payload, updated_at = now()
  returning * into delivery;
  update public.ph_eval_work set completion_event_id = delivery.event_id where id = work.id returning * into work;
  return work;
end
$$;


ALTER FUNCTION public.submit_eval_work_v2_legacy_impl(p_work_id uuid, p_actor_username text, p_expected_version integer, p_inquiry jsonb, p_evidence_by_origin jsonb, p_submission_token text) OWNER TO postgres;

--
-- Name: submit_manager_season_priority_v1(uuid, text, integer, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.submit_manager_season_priority_v1(p_actor_id uuid, p_source_unique_id text, p_expected_priority integer, p_scope_fingerprint text, p_idempotency_token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  actor public.profiles := private.manager_season_priority_actor_v1(p_actor_id);
  source_row public.ph_master_inventory;
  source_json jsonb;
  itemcode_value text;
  selected_lineage text;
  current_scope jsonb;
  current_scope_fingerprint text;
  before_state_hash text;
  after_state jsonb;
  after_state_hash text;
  overlays jsonb;
  request_fingerprint text;
  inventory_revision bigint;
  event_result jsonb;
  event_row public.ph_request_delivery_outbox;
  receipt private.manager_season_priority_receipts;
  active_receipt private.manager_season_priority_receipts;
  active_event public.ph_request_delivery_outbox;
  retried boolean := false;
  original_actor text;
  original_token text;
  bound_receipt private.manager_season_priority_receipts;
  bound_event public.ph_request_delivery_outbox;
  active_event_id uuid;
begin
  if p_expected_priority is null or p_expected_priority not between 2 and 4 then
    raise exception using errcode = '22023', message = 'SEASON_PRIORITY_EXPECTED_PRIORITY_INVALID';
  end if;
  if coalesce(p_scope_fingerprint, '') !~ '^[0-9a-f]{64}$' then
    raise exception using errcode = '22023', message = 'SEASON_PRIORITY_SCOPE_FINGERPRINT_INVALID';
  end if;
  if length(btrim(coalesce(p_idempotency_token, ''))) < 12
     or length(btrim(coalesce(p_idempotency_token, ''))) > 180 then
    raise exception using errcode = '22023', message = 'SEASON_PRIORITY_TOKEN_INVALID';
  end if;
  select r.* into bound_receipt
  from private.manager_season_priority_receipts r
  join public.ph_request_delivery_outbox o on o.event_id = r.event_id
  where o.event_key = 'reclass-inquiry:' || left(encode(extensions.digest(btrim(p_idempotency_token), 'sha256'), 'hex'), 40)
    and o.event_type = 'reclass_inquiry'
  limit 1;
  if bound_receipt.event_id is not null then
    select o.* into bound_event from public.ph_request_delivery_outbox o
    where o.event_id = bound_receipt.event_id;
    if bound_receipt.actor_id <> actor.id then
      raise exception using errcode = '42501', message = 'SEASON_PRIORITY_TOKEN_OWNERSHIP_CONFLICT';
    end if;
    if bound_receipt.source_unique_id is distinct from btrim(coalesce(p_source_unique_id, ''))
       or bound_receipt.expected_priority is distinct from p_expected_priority
       or bound_receipt.scope_fingerprint is distinct from p_scope_fingerprint then
      raise exception using errcode = '40001', message = 'SEASON_PRIORITY_TOKEN_CONFLICT';
    end if;
    return private.manager_season_priority_result_v1(bound_receipt, bound_event, true, false);
  end if;
  perform 1
  from public.app_dataset_revisions r
  where r.key in ('ph_master_inventory', 'ph_cav_import', 'ph_warehouse_assigned_items')
  order by r.key
  for share;
  if exists (
    select 1
    from unnest(array['ph_master_inventory', 'ph_cav_import', 'ph_warehouse_assigned_items']) required(key)
    left join public.app_dataset_revisions r on r.key = required.key
    where r.key is null or r.state <> 'ready'
  ) then
    raise exception using errcode = '40001', message = 'SEASON_PRIORITY_SOURCE_REFRESH_REQUIRED';
  end if;
  select r.revision into inventory_revision
  from public.app_dataset_revisions r where r.key = 'ph_master_inventory' for share;
  if inventory_revision is null then
    raise exception using errcode = '55000', message = 'SEASON_PRIORITY_SOURCE_REVISION_MISSING';
  end if;

  select m.* into source_row
  from public.ph_master_inventory m
  where btrim(coalesce(m.unique_id, '')) = btrim(coalesce(p_source_unique_id, ''))
  limit 1 for share;
  if source_row.unique_id is null then
    raise exception using errcode = '40001', message = 'SEASON_PRIORITY_SOURCE_MISSING';
  end if;
  source_json := to_jsonb(source_row);
  if not private.manager_season_priority_row_eligible_v1(source_json) then
    raise exception using errcode = '40001', message = 'SEASON_PRIORITY_SOURCE_NOT_ELIGIBLE';
  end if;
  if btrim(coalesce(source_json->>'priority', '')) <> p_expected_priority::text then
    raise exception using errcode = '40001', message = 'SEASON_PRIORITY_SOURCE_STALE';
  end if;
  itemcode_value := upper(btrim(coalesce(source_row.itemcode, '')));
  if itemcode_value = '' then
    raise exception using errcode = '22023', message = 'SEASON_PRIORITY_ITEMCODE_REQUIRED';
  end if;
  selected_lineage := private.manager_season_priority_lineage_v1(source_json);

  perform 1 from public.ph_master_inventory m
  where upper(btrim(coalesce(m.itemcode, ''))) = itemcode_value
  order by m.unique_id for share;
  current_scope := private.manager_season_priority_scope_v1(itemcode_value);
  current_scope_fingerprint := encode(extensions.digest(current_scope::text, 'sha256'), 'hex');
  if current_scope_fingerprint <> p_scope_fingerprint then
    raise exception using errcode = '40001', message = 'SEASON_PRIORITY_SCOPE_CHANGED';
  end if;
  if exists (
    select 1
    from public.ph_master_inventory m
    where upper(btrim(m.itemcode)) = itemcode_value
    group by private.manager_season_priority_lineage_v1(to_jsonb(m))
    having count(*) > 1
  ) then
    raise exception using errcode = '40001', message = 'SEASON_PRIORITY_LINEAGE_AMBIGUOUS';
  end if;
  before_state_hash := private.manager_season_priority_state_hash_v1(itemcode_value);

  with scope_rows as (
    select m.unique_id, to_jsonb(m) row_json,
      private.manager_season_priority_lineage_v1(to_jsonb(m)) lineage_hash,
      case when btrim(coalesce(m.priority, '')) ~ '^[1-4]$' then btrim(m.priority)::integer end old_priority
    from public.ph_master_inventory m
    where upper(btrim(coalesce(m.itemcode, ''))) = itemcode_value
  ), rotated as (
    select *, case
      when unique_id = source_row.unique_id then 1
      when old_priority between 1 and p_expected_priority - 1 then old_priority + 1
      else old_priority
    end new_priority
    from scope_rows
  )
  select
    coalesce(jsonb_agg(jsonb_build_object(
      'unique_id', unique_id,
      'expected', jsonb_build_object(
        'itemcode', coalesce(row_json->>'itemcode', ''),
        'lotcode', coalesce(row_json->>'lotcode', ''),
        'locationcode', coalesce(row_json->>'locationcode', ''),
        'ptronhand', coalesce(row_json->>'ptronhand', ''),
        'ptravailable', coalesce(row_json->>'ptravailable', ''),
        'priority', btrim(coalesce(row_json->>'priority', '')),
        'lineageHash', lineage_hash,
        'lineage', jsonb_build_object(
          'warehouse', coalesce(row_json->>'warehouseid', row_json->>'warehousei', ''),
          'itemcode', coalesce(row_json->>'itemcode', ''),
          'contsize', coalesce(row_json->>'contsize', ''),
          'locationcode', coalesce(row_json->>'locationcode', ''),
          'lotcode', coalesce(row_json->>'lotcode', ''),
          'source', coalesce(row_json->>'source', ''),
          'desigitem', coalesce(row_json->>'desigitem', ''),
          'desigcust', coalesce(row_json->>'desigcust', ''),
          'desigloc', coalesce(row_json->>'desigloc', '')
        )
      ),
      'proposals', case when new_priority is distinct from old_priority
        then jsonb_build_array(jsonb_build_object('action', 'priority_change', 'priority', new_priority))
        else '[]'::jsonb end
    ) order by lineage_hash, unique_id), '[]'::jsonb),
    coalesce(jsonb_agg(jsonb_build_object(
      'lineageHash', lineage_hash,
      'priority', case when new_priority is null then btrim(coalesce(row_json->>'priority', '')) else new_priority::text end
    ) order by lineage_hash,
      case when new_priority is null then btrim(coalesce(row_json->>'priority', '')) else new_priority::text end,
      unique_id), '[]'::jsonb)
  into overlays, after_state
  from rotated;

  after_state_hash := encode(extensions.digest(after_state::text, 'sha256'), 'hex');
  request_fingerprint := encode(extensions.digest(jsonb_build_object(
    'contractVersion', 'manager-season-priority-v1',
    'itemcode', itemcode_value,
    'selectedLineageHash', selected_lineage,
    'selectedPriority', p_expected_priority,
    'beforeStateHash', before_state_hash,
    'afterStateHash', after_state_hash
  )::text, 'sha256'), 'hex');

  perform pg_advisory_xact_lock(hashtextextended('manager-season-priority-item:' || itemcode_value, 0));
  perform pg_advisory_xact_lock(hashtextextended('manager-season-priority:' || request_fingerprint, 0));
  select r.event_id into active_event_id
  from private.manager_season_priority_receipts r
  join public.ph_request_delivery_outbox o on o.event_id = r.event_id
  where r.itemcode_normalized = itemcode_value and r.resolution is null
  limit 1 for update of r, o;
  if active_event_id is not null then
    select r.* into active_receipt from private.manager_season_priority_receipts r where r.event_id = active_event_id;
    select o.* into active_event from public.ph_request_delivery_outbox o where o.event_id = active_event_id;
    if active_event.status in ('failed', 'unknown')
       and upper(coalesce(active_event.sanitized_error_code, '')) like 'RECLASS_CONFLICT%' then
      update private.manager_season_priority_receipts r
      set resolution = 'stale', resolved_at = now(),
          resolved_inventory_revision = inventory_revision,
          resolution_snapshot_hash = before_state_hash
      where r.event_id = active_receipt.event_id and r.resolution is null
      returning * into active_receipt;
      return private.manager_season_priority_result_v1(active_receipt, active_event, true, false);
    end if;
    if active_receipt.request_fingerprint <> request_fingerprint then
      raise exception using errcode = '40001', message = 'SEASON_PRIORITY_ITEM_PENDING';
    end if;
    if active_event.status in ('failed', 'unknown') then
      original_actor := active_event.payload #>> '{reclassPayload,actor,username}';
      original_token := active_event.payload #>> '{reclassPayload,idempotencyToken}';
      perform public.retry_drive_reclass_inquiry_v1(original_actor, original_token);
      select * into active_event from public.ph_request_delivery_outbox where event_id = active_receipt.event_id;
      retried := true;
    end if;
    return private.manager_season_priority_result_v1(active_receipt, active_event, true, retried);
  end if;

  event_result := public.enqueue_drive_reclass_inquiry_v1(jsonb_build_object(
    'workflowPolicyVersion', 'reclass-action-workflow-v3-row-actions-20260826',
    'idempotencyToken', btrim(p_idempotency_token),
    'actorUsername', lower(btrim(actor.username)),
    'source', jsonb_build_object(
      'unique_id', source_row.unique_id,
      'itemcode', source_row.itemcode,
      'lotcode', source_json->>'lotcode',
      'locationcode', source_json->>'locationcode'
    ),
    'transaction', jsonb_build_object(
      'requestActions', jsonb_build_array('priority_change'),
      'holdStopProposals', '[]'::jsonb,
      'scope', jsonb_build_object(),
      'seasonPriority', jsonb_build_object(
        'contractVersion', 'manager-season-priority-v1',
        'mode', 'priority_one_rotation',
        'selectedLineageHash', selected_lineage,
        'selectedPriority', p_expected_priority,
        'scopeFingerprint', current_scope_fingerprint,
        'requestFingerprint', request_fingerprint,
        'beforeStateHash', before_state_hash,
        'afterStateHash', after_state_hash
      )
    ),
    'rowOverlays', overlays,
    'clientVersion', 'manager-season-priority-v1'
  ));

  select o.* into event_row
  from public.ph_request_delivery_outbox o
  where o.event_id = (event_result->>'jobId')::uuid
  for update;
  if event_row.event_id is null then
    raise exception using errcode = '55000', message = 'SEASON_PRIORITY_OUTBOX_MISSING';
  end if;
  if event_row.payload #>> '{reclassPayload,transaction,seasonPriority,requestFingerprint}' is distinct from request_fingerprint then
    raise exception using errcode = '40001', message = 'SEASON_PRIORITY_TOKEN_CONFLICT';
  end if;

  insert into private.manager_season_priority_receipts(
    event_id, request_fingerprint, itemcode_normalized, actor_id, source_unique_id,
    selected_lineage_hash, expected_priority, scope_fingerprint, before_state_hash,
    expected_after_hash, created_inventory_revision, last_checked_inventory_revision
  ) values (
    event_row.event_id, request_fingerprint, itemcode_value, actor.id, source_row.unique_id,
    selected_lineage, p_expected_priority, current_scope_fingerprint, before_state_hash,
    after_state_hash, inventory_revision, inventory_revision
  ) returning * into receipt;

  return private.manager_season_priority_result_v1(receipt, event_row, false, false);
end
$_$;


ALTER FUNCTION public.submit_manager_season_priority_v1(p_actor_id uuid, p_source_unique_id text, p_expected_priority integer, p_scope_fingerprint text, p_idempotency_token text) OWNER TO postgres;

--
-- Name: sync_v2_crop_roll_completed_drive_keys(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sync_v2_crop_roll_completed_drive_keys() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'private', 'vault', 'pg_temp'
    AS $$
declare
  old_completion_row_id text;
  new_completion_row_id text;
begin
  if tg_op in ('UPDATE', 'DELETE') then
    old_completion_row_id := coalesce(nullif(btrim(old.row_id), ''), 'no-row:' || md5(to_jsonb(old)::text));
    delete from public.ph_crop_roll_completed_drive_keys
    where completion_row_id = old_completion_row_id;
  end if;

  if tg_op in ('INSERT', 'UPDATE')
    and new.run_id = 'CR-LIVE-COMPLETIONS'
    and lower(coalesce(new.row_status, '')) = 'complete'
  then
    new_completion_row_id := coalesce(nullif(btrim(new.row_id), ''), 'no-row:' || md5(to_jsonb(new)::text));
    insert into public.ph_crop_roll_completed_drive_keys (
      completion_row_id, match_key, key_type, master_unique_id, itemcode, locationcode, lotcode, contsize, updated_at
    )
    select
      new_completion_row_id, k.match_key, k.key_type, k.master_unique_id, k.itemcode, k.locationcode, k.lotcode, k.contsize, now()
    from public.v2_crop_roll_completion_key_rows(to_jsonb(new)) k
    on conflict (completion_row_id, match_key) do update set
      key_type = excluded.key_type,
      master_unique_id = excluded.master_unique_id,
      itemcode = excluded.itemcode,
      locationcode = excluded.locationcode,
      lotcode = excluded.lotcode,
      contsize = excluded.contsize,
      updated_at = now();
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;


ALTER FUNCTION public.sync_v2_crop_roll_completed_drive_keys() OWNER TO postgres;

