--
-- Name: update_location_work_job_v1(uuid, text, integer, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_location_work_job_v1(p_job_id uuid, p_actor_username text, p_expected_revision integer, p_title text, p_general_instructions text) RETURNS public.ph_location_work_jobs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor public.profiles;
  job public.ph_location_work_jobs;
  delivery public.ph_request_delivery_outbox;
  recipient_emails text[];
  event_payload jsonb;
begin
  actor := private.location_work_active_actor_v1(p_actor_username);
  if actor.username <> 'dylan_collyge' then
    raise exception using errcode = '42501', message = 'location_work_edit_forbidden';
  end if;
  select * into job from public.ph_location_work_jobs where id = p_job_id for update;
  if job.id is null then raise exception using errcode = '22023', message = 'location_work_job_not_found'; end if;
  if job.revision <> p_expected_revision then raise exception using errcode = '40001', message = 'location_work_revision_conflict'; end if;
  if job.status <> 'open' or job.resolved_line_count <> 0 then
    raise exception using errcode = '40001', message = 'location_work_edit_after_start_forbidden';
  end if;
  if length(btrim(coalesce(p_title, ''))) < 1 or length(btrim(p_title)) > 240
     or length(btrim(coalesce(p_general_instructions, ''))) < 1
     or length(btrim(p_general_instructions)) > 8000 then
    raise exception using errcode = '22023', message = 'location_work_payload_invalid';
  end if;
  update public.ph_request_delivery_outbox set status = 'suppressed', updated_at = now()
    where event_id = job.assignment_event_id and status in ('pending', 'failed', 'unknown');
  update public.ph_location_work_jobs set title = btrim(p_title),
    general_instructions = btrim(p_general_instructions), revision = revision + 1, updated_at = now()
    where id = job.id returning * into job;
  select array_agg(a.email order by a.display_name, a.username) into recipient_emails
    from public.ph_location_work_assignments a where a.job_id = job.id;
  event_payload := private.location_work_event_payload_v1(job.id, 'assignment', coalesce(recipient_emails, '{}'::text[]));
  insert into public.ph_request_delivery_outbox(
    event_key, event_type, request_id, request_folder, payload, status, next_attempt_at
  ) values (
    'location-work:' || job.id::text || ':assignment:r' || job.revision::text,
    'location_work_assignment', job.id::text, job.title, event_payload, 'pending', now()
  ) returning * into delivery;
  insert into public.ph_location_work_delivery_events(job_id, delivery_kind, job_revision, outbox_event_id)
    values (job.id, 'assignment', job.revision, delivery.event_id);
  update public.ph_location_work_jobs set assignment_event_id = delivery.event_id, updated_at = now()
    where id = job.id returning * into job;
  insert into public.ph_location_work_audit(job_id, event_type, actor_username, job_revision)
    values (job.id, 'edited', actor.username, job.revision);
  return job;
end
$$;


ALTER FUNCTION public.update_location_work_job_v1(p_job_id uuid, p_actor_username text, p_expected_revision integer, p_title text, p_general_instructions text) OWNER TO postgres;

--
-- Name: upsert_my_push_subscription(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.upsert_my_push_subscription(subscription jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  profile public.profiles%rowtype;
  endpoint_value text;
  p256dh_value text;
  auth_value text;
  saved public.ph_push_subscriptions%rowtype;
begin
  profile := private.current_active_profile();
  if profile.id is null then
    raise exception using errcode = '42501', message = 'ACTIVE_PROFILE_REQUIRED';
  end if;
  if subscription is null or jsonb_typeof(subscription) <> 'object' then
    raise exception using errcode = '22023', message = 'PUSH_SUBSCRIPTION_INVALID';
  end if;
  endpoint_value := nullif(btrim(coalesce(subscription->>'endpoint', '')), '');
  p256dh_value := nullif(btrim(coalesce(subscription#>>'{keys,p256dh}', subscription->>'p256dh', '')), '');
  auth_value := nullif(btrim(coalesce(subscription#>>'{keys,auth}', subscription->>'auth', '')), '');
  if endpoint_value is null or p256dh_value is null or auth_value is null then
    raise exception using errcode = '22023', message = 'PUSH_SUBSCRIPTION_KEYS_REQUIRED';
  end if;

  insert into public.ph_push_subscriptions (
    profile_id, username, display_name, role, endpoint, p256dh, auth,
    device_label, user_agent, app_build, notifications_enabled,
    wants_new_request, wants_request_complete, subscription_json,
    last_seen, updated_at
  ) values (
    profile.id, profile.username, profile.display_name, profile.role,
    endpoint_value, p256dh_value, auth_value,
    left(coalesce(subscription->>'device_label', ''), 160),
    left(coalesce(subscription->>'user_agent', ''), 500),
    left(coalesce(subscription->>'app_build', ''), 80),
    coalesce((subscription->>'notifications_enabled')::boolean, true),
    coalesce((subscription->>'wants_new_request')::boolean, true),
    coalesce((subscription->>'wants_request_complete')::boolean, true),
    subscription, now(), now()
  )
  on conflict (endpoint) do update set
    profile_id = excluded.profile_id,
    username = excluded.username,
    display_name = excluded.display_name,
    role = excluded.role,
    p256dh = excluded.p256dh,
    auth = excluded.auth,
    device_label = excluded.device_label,
    user_agent = excluded.user_agent,
    app_build = excluded.app_build,
    notifications_enabled = excluded.notifications_enabled,
    wants_new_request = excluded.wants_new_request,
    wants_request_complete = excluded.wants_request_complete,
    subscription_json = excluded.subscription_json,
    last_seen = now(), updated_at = now()
  returning * into saved;

  return jsonb_build_object(
    'id', saved.id,
    'endpoint', saved.endpoint,
    'notifications_enabled', saved.notifications_enabled,
    'updated_at', saved.updated_at
  );
end;
$$;


ALTER FUNCTION public.upsert_my_push_subscription(subscription jsonb) OWNER TO postgres;

--
-- Name: FUNCTION upsert_my_push_subscription(subscription jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.upsert_my_push_subscription(subscription jsonb) IS 'Registers the authenticated caller push subscription without trusting client identity fields.';


