--
-- Name: v2_capture_hold_learning_event(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.v2_capture_hold_learning_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  event_date date;
  event_id text;
  reason text;
begin
  if upper(trim(coalesce(new.holdstopcode::text, ''))) <> 'H' then
    return new;
  end if;

  event_date := public.v2_get_hold_event_date(new.holdstopbegindate::text, new.filename::text, now());
  reason := nullif(trim(coalesce(new.holdstopreason::text, '')), '');
  event_id := 'hold_' || encode(digest(concat_ws('|',
    'ph_master_inventory',
    coalesce(new.unique_id::text, ''),
    coalesce(event_date::text, ''),
    lower(coalesce(reason, ''))
  ), 'sha256'), 'hex');

  insert into public.ph_hold_learning_events (
    unique_id,
    source_table,
    source_unique_id,
    import_file_name,
    hold_started_on,
    hold_detected_at,
    itemcode,
    commonname,
    genus,
    contsize,
    locationcode,
    lotcode,
    season,
    blockalpha,
    salesyear,
    holdstopcode,
    holdstopreason,
    holdstopbegindate_raw,
    hold_reason_category,
    weather_station_key
  )
  values (
    event_id,
    'ph_master_inventory',
    new.unique_id::text,
    new.filename::text,
    event_date,
    now(),
    new.itemcode::text,
    new.commonname::text,
    new.genusname::text,
    new.contsize::text,
    new.locationcode::text,
    new.lotcode::text,
    new.season::text,
    new.blockalpha::text,
    new.saleyear::text,
    new.holdstopcode::text,
    reason,
    new.holdstopbegindate::text,
    public.v2_classify_hold_reason(reason),
    'park_hill_ok'
  )
  on conflict (unique_id) do update set
    import_file_name = excluded.import_file_name,
    hold_detected_at = now(),
    itemcode = excluded.itemcode,
    commonname = excluded.commonname,
    genus = excluded.genus,
    contsize = excluded.contsize,
    locationcode = excluded.locationcode,
    lotcode = excluded.lotcode,
    season = excluded.season,
    blockalpha = excluded.blockalpha,
    salesyear = excluded.salesyear,
    holdstopcode = excluded.holdstopcode,
    holdstopreason = excluded.holdstopreason,
    holdstopbegindate_raw = excluded.holdstopbegindate_raw,
    hold_reason_category = excluded.hold_reason_category,
    updated_at = now();

  return new;
end;
$$;


ALTER FUNCTION public.v2_capture_hold_learning_event() OWNER TO postgres;

--
-- Name: v2_classify_hold_reason(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.v2_classify_hold_reason(p_reason text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select case
    when lower(coalesce(p_reason, '')) ~ '(aphid|mite|scale|thrip|snail|caterpillar|insect|bug|pest|borer|beetle)' then 'pest'
    when lower(coalesce(p_reason, '')) ~ '(fung|disease|leaf spot|phytophthora|rhizoctonia|botrytis|canker|mildew|rot|rust|anthracnose|blight|phomopsis|sclerotinia)' then 'fungal_disease'
    when lower(coalesce(p_reason, '')) ~ '(size|sizing|spec|height|too small|too short|too tall|caliper|under[ -]?size|undersized|not ready|not saleable|not ready to ship)' then 'size'
    when lower(coalesce(p_reason, '')) ~ '(leaf quality|leaf|foliar|chlorosis|yellow|necrosis|spotting|burn)' then 'leaf_quality'
    when lower(coalesce(p_reason, '')) ~ '(shear|sheared|trim|cutback|cut back|prune|pruned)' then 'sheared'
    when lower(coalesce(p_reason, '')) ~ '(freeze|frost|cold|heat|hail|weather|wind|drought|wet)' then 'weather_stress'
    when trim(coalesce(p_reason, '')) = '' then 'unknown'
    else 'other'
  end;
$$;


ALTER FUNCTION public.v2_classify_hold_reason(p_reason text) OWNER TO postgres;

--
-- Name: v2_crop_roll_completion_key_rows(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.v2_crop_roll_completion_key_rows(row_data jsonb) RETURNS TABLE(match_key text, key_type text, master_unique_id text, itemcode text, locationcode text, lotcode text, contsize text)
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'extensions', 'private', 'vault', 'pg_temp'
    AS $$
  with base as (
    select
      nullif(upper(btrim(coalesce(row_data->>'itemcode', row_data #>> '{metadata,crop_roll_form_values,itemcode}', row_data #>> '{metadata,original_values,itemcode}', ''))), '') as itemcode,
      nullif(upper(btrim(coalesce(row_data->>'locationcode', row_data #>> '{metadata,crop_roll_form_values,locationcode}', row_data #>> '{metadata,original_values,locationcode}', ''))), '') as locationcode,
      nullif(upper(btrim(coalesce(row_data->>'original_lotcode', row_data->>'target_lotcode', row_data #>> '{metadata,crop_roll_form_values,lotcode}', row_data #>> '{metadata,original_values,lotcode}', ''))), '') as lotcode,
      nullif(upper(btrim(coalesce(row_data->>'contsize', row_data #>> '{metadata,crop_roll_form_values,contsize}', row_data #>> '{metadata,original_values,contsize}', ''))), '') as contsize
  ),
  ids as (
    select distinct nullif(btrim(raw_id), '') as master_unique_id
    from unnest(public.get_v2_crop_roll_completion_master_ids(row_data)) as ids_raw(raw_id)
    where nullif(btrim(raw_id), '') is not null
  ),
  cards as (
    select itemcode, locationcode, lotcode, contsize
    from base
    where itemcode is not null
      and locationcode is not null
      and (lotcode is not null or contsize is not null)
  )
  select 'id:' || ids.master_unique_id, 'id', ids.master_unique_id, null::text, null::text, null::text, null::text
  from ids
  union
  select 'card:' || md5(concat_ws('|', cards.itemcode, cards.locationcode, coalesce(cards.lotcode, ''), coalesce(cards.contsize, ''))),
    'card', null::text, cards.itemcode, cards.locationcode, cards.lotcode, cards.contsize
  from cards
$$;


ALTER FUNCTION public.v2_crop_roll_completion_key_rows(row_data jsonb) OWNER TO postgres;

