--
-- Name: v2_get_hold_event_date(text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.v2_get_hold_event_date(p_holdstopbegindate text, p_filename text, p_fallback timestamp with time zone DEFAULT now()) RETURNS date
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'extensions', 'private', 'vault', 'pg_temp'
    AS $_$
declare
  v text := trim(coalesce(p_holdstopbegindate, ''));
  parsed_date date;
begin
  if v <> '' then
    begin
      if v ~ '^[0-9]+(\.[0-9]+)?$' then
        return date '1899-12-30' + floor(v::numeric)::int;
      end if;
      if v ~ '^[0-9]{4}[-/][0-9]{1,2}[-/][0-9]{1,2}' then
        return replace(left(v, 10), '/', '-')::date;
      end if;
      if v ~ '^[0-9]{1,2}[-/][0-9]{1,2}[-/][0-9]{4}' then
        return to_date(replace(left(v, 10), '-', '/'), 'MM/DD/YYYY');
      end if;
    exception when others then
      null;
    end;
  end if;

  parsed_date := public.v2_parse_hold_file_date(p_filename);
  if parsed_date is not null then
    return parsed_date;
  end if;

  return coalesce(p_fallback, now())::date;
end;
$_$;


ALTER FUNCTION public.v2_get_hold_event_date(p_holdstopbegindate text, p_filename text, p_fallback timestamp with time zone) OWNER TO postgres;

--
-- Name: v2_master_inventory_for_assigned_user(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.v2_master_inventory_for_assigned_user(p_username text) RETURNS SETOF public.ph_master_inventory
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
        select m.*
        from public.ph_master_inventory_user_assignments a
        join public.ph_master_inventory m on m.unique_id::text = a.master_unique_id
        where a.assignment_source = 'assignedto_final'
          and a.assignedto = coalesce(
            (select alias.assignedto from (values ('jorge', 'jorge_colunga')) as alias(raw_user_key, assignedto)
             where alias.raw_user_key = regexp_replace(lower(btrim(coalesce(p_username, ''))), '[^a-z0-9]+', '_', 'g') limit 1),
            regexp_replace(lower(btrim(coalesce(p_username, ''))), '[^a-z0-9]+', '_', 'g')
          )
      $$;


ALTER FUNCTION public.v2_master_inventory_for_assigned_user(p_username text) OWNER TO postgres;

--
-- Name: v2_parse_hold_file_date(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.v2_parse_hold_file_date(p_value text) RETURNS date
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'extensions', 'private', 'vault', 'pg_temp'
    AS $$
declare
  v text := coalesce(p_value, '');
  m text[];
begin
  m := regexp_match(v, '(20[0-9]{2})[-_\. ]?([01]?[0-9])[-_\. ]?([0-3]?[0-9])');
  if m is not null then
    begin
      return make_date(m[1]::int, m[2]::int, m[3]::int);
    exception when others then
      return null;
    end;
  end if;

  m := regexp_match(v, '([01]?[0-9])[-_\. ]([0-3]?[0-9])[-_\. ](20[0-9]{2})');
  if m is not null then
    begin
      return make_date(m[3]::int, m[1]::int, m[2]::int);
    exception when others then
      return null;
    end;
  end if;

  return null;
end;
$$;


ALTER FUNCTION public.v2_parse_hold_file_date(p_value text) OWNER TO postgres;

