--
-- Name: v2_refresh_hold_learning_from_drive_around_rows_range(date, date, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.v2_refresh_hold_learning_from_drive_around_rows_range(p_start_date date DEFAULT NULL::date, p_end_date date DEFAULT NULL::date, p_limit integer DEFAULT 200000) RETURNS TABLE(hold_events_upserted integer, release_cycles_upserted integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_snapshot_rows integer := 0;
  v_cycle_rows integer := 0;
begin
  select fast.snapshot_rows, fast.itemcode_cycles
  into v_snapshot_rows, v_cycle_rows
  from public.ph_refresh_hold_stop_itemcode_cycles_fast(p_start_date, p_end_date) fast;

  hold_events_upserted := coalesce(v_snapshot_rows, 0);
  release_cycles_upserted := coalesce(v_cycle_rows, 0);
  return next;
end;
$$;


