--
-- Name: v2_refresh_hold_learning_profiles(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.v2_refresh_hold_learning_profiles() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    SET statement_timeout TO '60s'
    AS $$
declare
  refreshed integer := 0;
begin
  drop table if exists pg_temp.hold_learning_profile_refresh_stage;

  create temporary table hold_learning_profile_refresh_stage
  on commit drop
  as
  with event_base as materialized (
    select
      lower(trim(coalesce(e.itemcode, ''))) as itemcode_key,
      lower(trim(coalesce(e.commonname, 'unknown'))) as common_key,
      lower(trim(coalesce(e.contsize, ''))) as contsize_key,
      coalesce(nullif(trim(e.hold_reason_category), ''), 'unknown') as reason_key,
      coalesce(nullif(trim(e.commonname), ''), 'Unknown') as commonname_display,
      nullif(trim(e.genus), '') as genus_display,
      nullif(trim(e.contsize), '') as contsize_display,
      e.hold_started_on,
      e.gdd_base_50_7d,
      e.gdd_base_50_14d,
      e.gdd_base_50_30d,
      e.gdd_base_50_season,
      e.chill_hours_30d,
      e.chill_hours_season,
      e.precipitation_in_30d,
      e.avg_temperature_f_30d
    from public.ph_hold_learning_events e
    where e.commonname is not null
      and e.hold_reason_category is not null
      and e.weather_features_refreshed_at is not null
  ),
  release_base as materialized (
    select
      lower(trim(coalesce(c.itemcode, ''))) as itemcode_key,
      lower(trim(coalesce(c.commonname, 'unknown'))) as common_key,
      lower(trim(coalesce(c.contsize, ''))) as contsize_key,
      coalesce(nullif(trim(c.hold_reason_category), ''), 'unknown') as reason_key,
      c.gdd_base_50_to_release,
      c.hold_days
    from public.ph_hold_release_cycles c
    where c.hold_released_on is not null
      and c.commonname is not null
      and c.hold_reason_category is not null
      and (c.gdd_base_50_to_release is not null or c.hold_days is not null)
  ),
  item_event_stats as (
    select
      itemcode_key,
      common_key,
      contsize_key,
      reason_key,
      max(commonname_display) as commonname_display,
      max(genus_display) as genus_display,
      max(contsize_display) as contsize_display,
      count(*)::integer as sample_count,
      min(hold_started_on) as first_hold_on,
      max(hold_started_on) as last_hold_on,
      round(avg(gdd_base_50_7d), 3) as avg_gdd_base_50_7d,
      round(avg(gdd_base_50_14d), 3) as avg_gdd_base_50_14d,
      round(avg(gdd_base_50_30d), 3) as avg_gdd_base_50_30d,
      round(avg(gdd_base_50_season), 3) as avg_gdd_base_50_season,
      round((percentile_cont(0.5) within group (order by gdd_base_50_30d))::numeric, 3) as median_gdd_base_50_30d,
      round(avg(chill_hours_30d), 3) as avg_chill_hours_30d,
      round(avg(chill_hours_season), 3) as avg_chill_hours_season,
      round(avg(precipitation_in_30d), 3) as avg_precipitation_in_30d,
      round(avg(avg_temperature_f_30d), 2) as avg_temperature_f_30d
    from event_base
    where itemcode_key <> ''
    group by itemcode_key, common_key, contsize_key, reason_key
  ),
  common_event_stats as (
    select
      common_key,
      contsize_key,
      reason_key,
      max(commonname_display) as commonname_display,
      max(genus_display) as genus_display,
      max(contsize_display) as contsize_display,
      count(*)::integer as sample_count,
      min(hold_started_on) as first_hold_on,
      max(hold_started_on) as last_hold_on,
      round(avg(gdd_base_50_7d), 3) as avg_gdd_base_50_7d,
      round(avg(gdd_base_50_14d), 3) as avg_gdd_base_50_14d,
      round(avg(gdd_base_50_30d), 3) as avg_gdd_base_50_30d,
      round(avg(gdd_base_50_season), 3) as avg_gdd_base_50_season,
      round((percentile_cont(0.5) within group (order by gdd_base_50_30d))::numeric, 3) as median_gdd_base_50_30d,
      round(avg(chill_hours_30d), 3) as avg_chill_hours_30d,
      round(avg(chill_hours_season), 3) as avg_chill_hours_season,
      round(avg(precipitation_in_30d), 3) as avg_precipitation_in_30d,
      round(avg(avg_temperature_f_30d), 2) as avg_temperature_f_30d
    from event_base
    group by common_key, contsize_key, reason_key
  ),
  item_release_stats as (
    select
      itemcode_key,
      common_key,
      contsize_key,
      reason_key,
      count(*)::integer as release_sample_count,
      round(avg(gdd_base_50_to_release), 3) as avg_gdd_base_50_to_release,
      round((percentile_cont(0.5) within group (order by gdd_base_50_to_release))::numeric, 3) as median_gdd_base_50_to_release,
      round(avg(hold_days), 2) as avg_days_to_release
    from release_base
    where itemcode_key <> ''
    group by itemcode_key, common_key, contsize_key, reason_key
  ),
  common_release_stats as (
    select
      common_key,
      contsize_key,
      reason_key,
      count(*)::integer as release_sample_count,
      round(avg(gdd_base_50_to_release), 3) as avg_gdd_base_50_to_release,
      round((percentile_cont(0.5) within group (order by gdd_base_50_to_release))::numeric, 3) as median_gdd_base_50_to_release,
      round(avg(hold_days), 2) as avg_days_to_release
    from release_base
    group by common_key, contsize_key, reason_key
  )
  select
    'hold_profile_item_' || encode(digest(concat_ws('|', e.itemcode_key, e.common_key, e.contsize_key, e.reason_key), 'sha256'), 'hex') as unique_id,
    nullif(e.itemcode_key, '') as itemcode,
    e.commonname_display as commonname,
    e.genus_display as genus,
    e.contsize_display as contsize,
    e.reason_key as hold_reason_category,
    e.sample_count,
    e.first_hold_on,
    e.last_hold_on,
    e.avg_gdd_base_50_7d,
    e.avg_gdd_base_50_14d,
    e.avg_gdd_base_50_30d,
    e.avg_gdd_base_50_season,
    e.median_gdd_base_50_30d,
    e.avg_chill_hours_30d,
    e.avg_chill_hours_season,
    e.avg_precipitation_in_30d,
    e.avg_temperature_f_30d,
    coalesce(r.release_sample_count, 0) as release_sample_count,
    r.avg_gdd_base_50_to_release,
    r.median_gdd_base_50_to_release,
    r.avg_days_to_release,
    now() as updated_at
  from item_event_stats e
  left join item_release_stats r
    on r.itemcode_key = e.itemcode_key
   and r.common_key = e.common_key
   and r.contsize_key = e.contsize_key
   and r.reason_key = e.reason_key
  union all
  select
    'hold_profile_' || encode(digest(concat_ws('|', e.common_key, e.contsize_key, e.reason_key), 'sha256'), 'hex') as unique_id,
    null::text as itemcode,
    e.commonname_display as commonname,
    e.genus_display as genus,
    e.contsize_display as contsize,
    e.reason_key as hold_reason_category,
    e.sample_count,
    e.first_hold_on,
    e.last_hold_on,
    e.avg_gdd_base_50_7d,
    e.avg_gdd_base_50_14d,
    e.avg_gdd_base_50_30d,
    e.avg_gdd_base_50_season,
    e.median_gdd_base_50_30d,
    e.avg_chill_hours_30d,
    e.avg_chill_hours_season,
    e.avg_precipitation_in_30d,
    e.avg_temperature_f_30d,
    coalesce(r.release_sample_count, 0) as release_sample_count,
    r.avg_gdd_base_50_to_release,
    r.median_gdd_base_50_to_release,
    r.avg_days_to_release,
    now() as updated_at
  from common_event_stats e
  left join common_release_stats r
    on r.common_key = e.common_key
   and r.contsize_key = e.contsize_key
   and r.reason_key = e.reason_key;

  alter table pg_temp.hold_learning_profile_refresh_stage
    add primary key (unique_id);

  insert into public.ph_hold_learning_profiles (
    unique_id, itemcode, commonname, genus, contsize, hold_reason_category,
    sample_count, first_hold_on, last_hold_on,
    avg_gdd_base_50_7d, avg_gdd_base_50_14d, avg_gdd_base_50_30d, avg_gdd_base_50_season,
    median_gdd_base_50_30d, avg_chill_hours_30d, avg_chill_hours_season,
    avg_precipitation_in_30d, avg_temperature_f_30d, release_sample_count,
    avg_gdd_base_50_to_release, median_gdd_base_50_to_release, avg_days_to_release, updated_at
  )
  select *
  from pg_temp.hold_learning_profile_refresh_stage
  on conflict (unique_id) do update set
    itemcode = excluded.itemcode,
    commonname = excluded.commonname,
    genus = excluded.genus,
    contsize = excluded.contsize,
    hold_reason_category = excluded.hold_reason_category,
    sample_count = excluded.sample_count,
    first_hold_on = excluded.first_hold_on,
    last_hold_on = excluded.last_hold_on,
    avg_gdd_base_50_7d = excluded.avg_gdd_base_50_7d,
    avg_gdd_base_50_14d = excluded.avg_gdd_base_50_14d,
    avg_gdd_base_50_30d = excluded.avg_gdd_base_50_30d,
    avg_gdd_base_50_season = excluded.avg_gdd_base_50_season,
    median_gdd_base_50_30d = excluded.median_gdd_base_50_30d,
    avg_chill_hours_30d = excluded.avg_chill_hours_30d,
    avg_chill_hours_season = excluded.avg_chill_hours_season,
    avg_precipitation_in_30d = excluded.avg_precipitation_in_30d,
    avg_temperature_f_30d = excluded.avg_temperature_f_30d,
    release_sample_count = excluded.release_sample_count,
    avg_gdd_base_50_to_release = excluded.avg_gdd_base_50_to_release,
    median_gdd_base_50_to_release = excluded.median_gdd_base_50_to_release,
    avg_days_to_release = excluded.avg_days_to_release,
    updated_at = now()
  where (
    ph_hold_learning_profiles.itemcode,
    ph_hold_learning_profiles.commonname,
    ph_hold_learning_profiles.genus,
    ph_hold_learning_profiles.contsize,
    ph_hold_learning_profiles.hold_reason_category,
    ph_hold_learning_profiles.sample_count,
    ph_hold_learning_profiles.first_hold_on,
    ph_hold_learning_profiles.last_hold_on,
    ph_hold_learning_profiles.avg_gdd_base_50_7d,
    ph_hold_learning_profiles.avg_gdd_base_50_14d,
    ph_hold_learning_profiles.avg_gdd_base_50_30d,
    ph_hold_learning_profiles.avg_gdd_base_50_season,
    ph_hold_learning_profiles.median_gdd_base_50_30d,
    ph_hold_learning_profiles.avg_chill_hours_30d,
    ph_hold_learning_profiles.avg_chill_hours_season,
    ph_hold_learning_profiles.avg_precipitation_in_30d,
    ph_hold_learning_profiles.avg_temperature_f_30d,
    ph_hold_learning_profiles.release_sample_count,
    ph_hold_learning_profiles.avg_gdd_base_50_to_release,
    ph_hold_learning_profiles.median_gdd_base_50_to_release,
    ph_hold_learning_profiles.avg_days_to_release
  ) is distinct from (
    excluded.itemcode,
    excluded.commonname,
    excluded.genus,
    excluded.contsize,
    excluded.hold_reason_category,
    excluded.sample_count,
    excluded.first_hold_on,
    excluded.last_hold_on,
    excluded.avg_gdd_base_50_7d,
    excluded.avg_gdd_base_50_14d,
    excluded.avg_gdd_base_50_30d,
    excluded.avg_gdd_base_50_season,
    excluded.median_gdd_base_50_30d,
    excluded.avg_chill_hours_30d,
    excluded.avg_chill_hours_season,
    excluded.avg_precipitation_in_30d,
    excluded.avg_temperature_f_30d,
    excluded.release_sample_count,
    excluded.avg_gdd_base_50_to_release,
    excluded.median_gdd_base_50_to_release,
    excluded.avg_days_to_release
  );

  delete from public.ph_hold_learning_profiles p
  where not exists (
    select 1
    from pg_temp.hold_learning_profile_refresh_stage s
    where s.unique_id = p.unique_id
  );

  select count(*)::integer into refreshed
  from pg_temp.hold_learning_profile_refresh_stage;

  return refreshed;
end;
$$;


ALTER FUNCTION public.v2_refresh_hold_learning_profiles() OWNER TO postgres;

--
-- Name: FUNCTION v2_refresh_hold_learning_profiles(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.v2_refresh_hold_learning_profiles() IS 'Set-based profile refresh that stages normalized aggregates and writes only changed rows.';


--
-- Name: v2_refresh_hold_learning_weather_features(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.v2_refresh_hold_learning_weather_features(p_limit integer DEFAULT 1000) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    SET statement_timeout TO '60s'
    AS $$
declare
  refreshed integer := 0;
begin
  with selected_events as materialized (
    select
      e.unique_id,
      e.weather_station_key,
      e.hold_started_on,
      ((e.hold_started_on + 1)::timestamp at time zone 'America/Chicago') as event_end,
      (make_date(extract(year from e.hold_started_on)::int, 1, 1)::timestamp at time zone 'America/Chicago') as season_start
    from public.ph_hold_learning_events e
    where e.hold_started_on is not null
    order by coalesce(e.weather_features_refreshed_at, '1900-01-01'::timestamptz), e.hold_started_on desc
    limit greatest(1, coalesce(p_limit, 1000))
  ),
  distinct_windows as materialized (
    select distinct weather_station_key, event_end, season_start
    from selected_events
  ),
  weather_rollups as materialized (
    select
      w.weather_station_key,
      w.event_end,
      w.season_start,
      coalesce(sum(h.gdd_base_50) filter (where h.observed_at >= w.event_end - interval '7 days'), 0) as gdd_7,
      coalesce(sum(h.gdd_base_50) filter (where h.observed_at >= w.event_end - interval '14 days'), 0) as gdd_14,
      coalesce(sum(h.gdd_base_50) filter (where h.observed_at >= w.event_end - interval '30 days'), 0) as gdd_30,
      coalesce(sum(h.gdd_base_50), 0) as gdd_season,
      coalesce(sum(h.chill_hours) filter (where h.observed_at >= w.event_end - interval '7 days'), 0) as chill_7,
      coalesce(sum(h.chill_hours) filter (where h.observed_at >= w.event_end - interval '14 days'), 0) as chill_14,
      coalesce(sum(h.chill_hours) filter (where h.observed_at >= w.event_end - interval '30 days'), 0) as chill_30,
      coalesce(sum(h.chill_hours), 0) as chill_season,
      coalesce(sum(h.precipitation_in) filter (where h.observed_at >= w.event_end - interval '7 days'), 0) as precip_7,
      coalesce(sum(h.precipitation_in) filter (where h.observed_at >= w.event_end - interval '14 days'), 0) as precip_14,
      coalesce(sum(h.precipitation_in) filter (where h.observed_at >= w.event_end - interval '30 days'), 0) as precip_30,
      avg(h.temperature_f) filter (where h.observed_at >= w.event_end - interval '7 days') as avg_temp_7,
      avg(h.temperature_f) filter (where h.observed_at >= w.event_end - interval '14 days') as avg_temp_14,
      avg(h.temperature_f) filter (where h.observed_at >= w.event_end - interval '30 days') as avg_temp_30
    from distinct_windows w
    left join public.ph_weather_hourly h
      on h.station_key = w.weather_station_key
     and h.observed_at >= w.season_start
     and h.observed_at < w.event_end
    group by w.weather_station_key, w.event_end, w.season_start
  ),
  updated as (
    update public.ph_hold_learning_events e
    set
      gdd_base_50_7d = round(r.gdd_7, 3),
      gdd_base_50_14d = round(r.gdd_14, 3),
      gdd_base_50_30d = round(r.gdd_30, 3),
      gdd_base_50_season = round(r.gdd_season, 3),
      chill_hours_7d = round(r.chill_7, 3),
      chill_hours_14d = round(r.chill_14, 3),
      chill_hours_30d = round(r.chill_30, 3),
      chill_hours_season = round(r.chill_season, 3),
      precipitation_in_7d = round(r.precip_7, 3),
      precipitation_in_14d = round(r.precip_14, 3),
      precipitation_in_30d = round(r.precip_30, 3),
      avg_temperature_f_7d = round(r.avg_temp_7, 2),
      avg_temperature_f_14d = round(r.avg_temp_14, 2),
      avg_temperature_f_30d = round(r.avg_temp_30, 2),
      weather_features_refreshed_at = now(),
      updated_at = now()
    from selected_events s
    join weather_rollups r
      on r.weather_station_key is not distinct from s.weather_station_key
     and r.event_end = s.event_end
     and r.season_start = s.season_start
    where e.unique_id = s.unique_id
    returning 1
  )
  select count(*)::integer into refreshed from updated;

  return refreshed;
end;
$$;


ALTER FUNCTION public.v2_refresh_hold_learning_weather_features(p_limit integer) OWNER TO postgres;

--
-- Name: FUNCTION v2_refresh_hold_learning_weather_features(p_limit integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.v2_refresh_hold_learning_weather_features(p_limit integer) IS 'Set-based weather rollup refresh that computes each station/date window once per batch.';


--
-- Name: v2_refresh_hold_stop_itemcode_episode_learning(date, date, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.v2_refresh_hold_stop_itemcode_episode_learning(p_start_date date DEFAULT NULL::date, p_end_date date DEFAULT NULL::date, p_weather_refresh_limit integer DEFAULT 5000) RETURNS TABLE(snapshot_rows integer, itemcode_cycles integer, hold_events_upserted integer, release_cycles_upserted integer, profiles_refreshed integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  safe_start date;
  safe_end date;
  snapshot_count integer := 0;
  cycle_count integer := 0;
  event_count integer := 0;
  release_count integer := 0;
  profile_count integer := 0;
begin
  select coalesce(p_start_date, min(coalesce(f.canonical_report_date, f.report_date))),
         coalesce(p_end_date, max(coalesce(f.canonical_report_date, f.report_date)))
    into safe_start, safe_end
  from public.ph_drive_around_report_files f
  where coalesce(f.canonical_report_date, f.report_date) is not null;

  if safe_start is null or safe_end is null then
    snapshot_rows := 0; itemcode_cycles := 0; hold_events_upserted := 0; release_cycles_upserted := 0; profiles_refreshed := 0;
    return next;
    return;
  end if;

  if safe_start > safe_end then
    raise exception 'Start date % must be on or before end date %.', safe_start, safe_end;
  end if;

  truncate table public.ph_hold_stop_itemcode_snapshots;
  truncate table public.ph_hold_stop_itemcode_cycles;

  create temp table tmp_ph_hold_stop_files on commit drop as
  select
    f.file_id,
    coalesce(f.canonical_report_date, f.report_date) as file_date,
    coalesce(nullif(trim(f.canonical_file_name), ''), f.file_name) as file_name,
    f.canonical_sequence,
    row_number() over (
      order by coalesce(f.canonical_report_date, f.report_date), coalesce(f.canonical_sequence, 999999), coalesce(nullif(trim(f.canonical_file_name), ''), f.file_name), f.file_id
    )::integer as file_rank
  from public.ph_drive_around_report_files f
  where coalesce(f.canonical_report_date, f.report_date) between safe_start and safe_end
    and coalesce(f.canonical_report_date, f.report_date) is not null;

  create index on tmp_ph_hold_stop_files (file_id);
  create index on tmp_ph_hold_stop_files (file_rank);

  insert into public.ph_hold_stop_itemcode_snapshots (
    unique_id, itemcode, file_id, file_name, file_date, canonical_sequence, file_rank,
    commonname, genus, contsize, total_row_count, h_row_count, s_row_count, blocked_row_count,
    blank_row_count, is_blocked, first_blocked_code, blocked_codes, observed_holdstopcodes,
    holdstopreason, holdstopreasons, hold_reason_category, hold_reason_categories, source_row_ids,
    snapshot, created_at, updated_at
  )
  with row_source as (
    select
      tf.file_id, tf.file_date, tf.file_name, tf.canonical_sequence, tf.file_rank,
      r.unique_id as source_row_id, r.row_number,
      upper(nullif(trim(coalesce(r.holdstopcode, '')), '')) as code,
      nullif(trim(r.holdstopreason), '') as reason,
      nullif(trim(r.itemcode), '') as itemcode,
      nullif(trim(r.commonname), '') as commonname,
      nullif(trim(r.genus), '') as genus,
      nullif(trim(r.contsize), '') as contsize,
      r.locationcode, r.lotcode
    from public.ph_drive_around_report_rows r
    join tmp_ph_hold_stop_files tf on tf.file_id = r.file_id
    where nullif(trim(r.itemcode), '') is not null
  ), grouped as (
    select
      rs.itemcode, rs.file_id, rs.file_name, rs.file_date, rs.canonical_sequence, rs.file_rank,
      (array_agg(rs.commonname order by rs.row_number) filter (where rs.commonname is not null))[1] as commonname,
      (array_agg(rs.genus order by rs.row_number) filter (where rs.genus is not null))[1] as genus,
      (array_agg(rs.contsize order by rs.row_number) filter (where rs.contsize is not null))[1] as contsize,
      count(*)::integer as total_row_count,
      count(*) filter (where rs.code = 'H')::integer as h_row_count,
      count(*) filter (where rs.code = 'S')::integer as s_row_count,
      count(*) filter (where rs.code in ('H', 'S'))::integer as blocked_row_count,
      count(*) filter (where rs.code is null or rs.code not in ('H', 'S'))::integer as blank_row_count,
      (count(*) filter (where rs.code in ('H', 'S')) > 0) as is_blocked,
      (array_agg(rs.code order by rs.row_number) filter (where rs.code in ('H', 'S')))[1] as first_blocked_code,
      coalesce(array_agg(distinct rs.code) filter (where rs.code in ('H', 'S')), '{}'::text[]) as blocked_codes,
      coalesce(array_agg(distinct rs.code) filter (where rs.code is not null), '{}'::text[]) as observed_holdstopcodes,
      (array_agg(rs.reason order by rs.row_number) filter (where rs.code in ('H', 'S') and rs.reason is not null))[1] as holdstopreason,
      coalesce(array_agg(distinct rs.reason) filter (where rs.code in ('H', 'S') and rs.reason is not null), '{}'::text[]) as holdstopreasons,
      coalesce(public.v2_classify_hold_reason((array_agg(rs.reason order by rs.row_number) filter (where rs.code in ('H', 'S') and rs.reason is not null))[1]), 'unknown') as hold_reason_category,
      coalesce(array_agg(distinct public.v2_classify_hold_reason(rs.reason)) filter (where rs.code in ('H', 'S')), '{}'::text[]) as hold_reason_categories,
      coalesce(array_agg(rs.source_row_id order by rs.row_number), '{}'::text[]) as source_row_ids,
      jsonb_build_object(
        'source', 'ph_drive_around_report_rows',
        'locations', coalesce(array_agg(distinct rs.locationcode) filter (where nullif(trim(coalesce(rs.locationcode, '')), '') is not null), '{}'::text[]),
        'lots', coalesce(array_agg(distinct rs.lotcode) filter (where nullif(trim(coalesce(rs.lotcode, '')), '') is not null), '{}'::text[])
      ) as snapshot
    from row_source rs
    group by rs.itemcode, rs.file_id, rs.file_name, rs.file_date, rs.canonical_sequence, rs.file_rank
  )
  select
    'hold_stop_itemcode_snapshot_' || encode(digest(concat_ws('|', g.itemcode, g.file_id), 'sha256'), 'hex'),
    g.itemcode, g.file_id, g.file_name, g.file_date, g.canonical_sequence, g.file_rank,
    g.commonname, g.genus, g.contsize, g.total_row_count, g.h_row_count, g.s_row_count,
    g.blocked_row_count, g.blank_row_count, g.is_blocked, g.first_blocked_code, g.blocked_codes,
    g.observed_holdstopcodes, g.holdstopreason, g.holdstopreasons, g.hold_reason_category,
    g.hold_reason_categories, g.source_row_ids, g.snapshot, now(), now()
  from grouped g;

  get diagnostics snapshot_count = row_count;

  create temp table tmp_ph_hold_stop_cycle_starts on commit drop as
  with ordered as (
    select s.*, lag(s.is_blocked) over (partition by s.itemcode order by s.file_rank) as previous_is_blocked
    from public.ph_hold_stop_itemcode_snapshots s
  )
  select o.*, row_number() over (partition by o.itemcode order by o.file_rank)::integer as episode_number
  from ordered o
  where o.is_blocked = true and coalesce(o.previous_is_blocked, false) = false;

  create index on tmp_ph_hold_stop_cycle_starts (itemcode, file_rank);

  insert into public.ph_hold_stop_itemcode_cycles (
    unique_id, itemcode, episode_number, blocked_code, episode_start_date, start_file_id,
    start_file_name, start_canonical_sequence, start_file_rank, episode_release_date, release_file_id,
    release_file_name, release_canonical_sequence, release_file_rank, days_blocked, snapshot_count,
    commonname, genus, contsize, holdstopreason, holdstopreasons, hold_reason_category,
    hold_reason_categories, blocked_codes, gdd_base_50_to_release, source_snapshot_ids,
    source_file_ids, source_file_names, snapshot, created_at, updated_at
  )
  select
    'hold_stop_itemcode_cycle_' || encode(digest(concat_ws('|', s.itemcode, s.episode_number::text, s.file_id), 'sha256'), 'hex'),
    s.itemcode,
    s.episode_number,
    coalesce(cycle_agg.first_blocked_code, s.first_blocked_code, 'H'),
    s.file_date,
    s.file_id,
    s.file_name,
    s.canonical_sequence,
    s.file_rank,
    rel.file_date,
    rel.file_id,
    rel.file_name,
    rel.canonical_sequence,
    rel.file_rank,
    case when rel.file_date is null then null else greatest((rel.file_date - s.file_date), 0) end,
    coalesce(cycle_agg.snapshot_count, 1),
    s.commonname,
    s.genus,
    s.contsize,
    cycle_agg.first_holdstopreason,
    coalesce(cycle_agg.holdstopreasons, '{}'::text[]),
    coalesce(public.v2_classify_hold_reason(cycle_agg.first_holdstopreason), cycle_agg.first_hold_reason_category, 'unknown'),
    coalesce(cycle_agg.hold_reason_categories, '{}'::text[]),
    coalesce(cycle_agg.blocked_codes, '{}'::text[]),
    case when rel.file_date is null then null else coalesce((
      select round(sum(coalesce(d.daily_gdd_base_50, greatest(((coalesce(d.temperature_high_f, 0) + coalesce(d.temperature_low_f, 0)) / 2) - 50, 0)))::numeric, 3)
      from public.ph_weather_daily d
      where d.station_key = 'park_hill_ok' and d.date >= s.file_date and d.date <= rel.file_date
    ), 0) end,
    coalesce(cycle_agg.source_snapshot_ids, '{}'::text[]),
    coalesce(cycle_agg.source_file_ids, '{}'::text[]),
    coalesce(cycle_agg.source_file_names, '{}'::text[]),
    jsonb_build_object('source','ph_hold_stop_itemcode_snapshots','start_snapshot_id',s.unique_id,'release_snapshot_id',rel.unique_id,'start_snapshot',s.snapshot,'release_snapshot',coalesce(rel.snapshot,'{}'::jsonb)),
    now(),
    now()
  from tmp_ph_hold_stop_cycle_starts s
  left join lateral (
    select r.* from public.ph_hold_stop_itemcode_snapshots r
    where r.itemcode = s.itemcode and r.file_rank > s.file_rank and r.is_blocked = false
    order by r.file_rank limit 1
  ) rel on true
  left join lateral (
    select
      count(*)::integer as snapshot_count,
      (array_agg(m.first_blocked_code order by m.file_rank) filter (where m.is_blocked and m.first_blocked_code is not null))[1] as first_blocked_code,
      (array_agg(m.holdstopreason order by m.file_rank) filter (where m.is_blocked and m.holdstopreason is not null))[1] as first_holdstopreason,
      (array_agg(m.hold_reason_category order by m.file_rank) filter (where m.is_blocked and m.hold_reason_category is not null))[1] as first_hold_reason_category,
      coalesce(array_agg(m.unique_id order by m.file_rank), '{}'::text[]) as source_snapshot_ids,
      coalesce(array_agg(m.file_id order by m.file_rank), '{}'::text[]) as source_file_ids,
      coalesce(array_agg(m.file_name order by m.file_rank), '{}'::text[]) as source_file_names,
      coalesce(array(select distinct code from public.ph_hold_stop_itemcode_snapshots bc cross join unnest(bc.blocked_codes) code where bc.itemcode = s.itemcode and bc.file_rank >= s.file_rank and (rel.file_rank is null or bc.file_rank < rel.file_rank) order by code), '{}'::text[]) as blocked_codes,
      coalesce(array(select distinct reason from public.ph_hold_stop_itemcode_snapshots br cross join unnest(br.holdstopreasons) reason where br.itemcode = s.itemcode and br.file_rank >= s.file_rank and (rel.file_rank is null or br.file_rank < rel.file_rank) order by reason), '{}'::text[]) as holdstopreasons,
      coalesce(array(select distinct category from public.ph_hold_stop_itemcode_snapshots cr cross join unnest(cr.hold_reason_categories) category where cr.itemcode = s.itemcode and cr.file_rank >= s.file_rank and (rel.file_rank is null or cr.file_rank < rel.file_rank) order by category), '{}'::text[]) as hold_reason_categories
    from public.ph_hold_stop_itemcode_snapshots m
    where m.itemcode = s.itemcode and m.file_rank >= s.file_rank and (rel.file_rank is null or m.file_rank < rel.file_rank)
  ) cycle_agg on true
  on conflict (unique_id) do update set
    blocked_code = excluded.blocked_code,
    episode_start_date = excluded.episode_start_date,
    start_file_id = excluded.start_file_id,
    start_file_name = excluded.start_file_name,
    start_canonical_sequence = excluded.start_canonical_sequence,
    start_file_rank = excluded.start_file_rank,
    episode_release_date = excluded.episode_release_date,
    release_file_id = excluded.release_file_id,
    release_file_name = excluded.release_file_name,
    release_canonical_sequence = excluded.release_canonical_sequence,
    release_file_rank = excluded.release_file_rank,
    days_blocked = excluded.days_blocked,
    snapshot_count = excluded.snapshot_count,
    commonname = excluded.commonname,
    genus = excluded.genus,
    contsize = excluded.contsize,
    holdstopreason = excluded.holdstopreason,
    holdstopreasons = excluded.holdstopreasons,
    hold_reason_category = excluded.hold_reason_category,
    hold_reason_categories = excluded.hold_reason_categories,
    blocked_codes = excluded.blocked_codes,
    gdd_base_50_to_release = excluded.gdd_base_50_to_release,
    source_snapshot_ids = excluded.source_snapshot_ids,
    source_file_ids = excluded.source_file_ids,
    source_file_names = excluded.source_file_names,
    snapshot = excluded.snapshot,
    updated_at = now();

  get diagnostics cycle_count = row_count;

  delete from public.ph_hold_learning_events where source_table in ('ph_drive_around_report_rows', 'ph_hold_stop_itemcode_cycles');

  insert into public.ph_hold_learning_events (
    unique_id, source_table, source_unique_id, import_file_name, hold_started_on, hold_detected_at,
    itemcode, commonname, genus, contsize, locationcode, lotcode, season, blockalpha, salesyear,
    holdstopcode, holdstopreason, holdstopbegindate_raw, hold_reason_category, weather_station_key,
    gdd_base_50_7d, gdd_base_50_14d, gdd_base_50_30d, gdd_base_50_season,
    chill_hours_7d, chill_hours_14d, chill_hours_30d, chill_hours_season,
    precipitation_in_7d, precipitation_in_14d, precipitation_in_30d,
    avg_temperature_f_7d, avg_temperature_f_14d, avg_temperature_f_30d,
    weather_features_refreshed_at, released_on, gdd_base_50_to_release, hold_days, created_at, updated_at
  )
  select
    'hold_event_itemcode_cycle_' || encode(digest(c.unique_id, 'sha256'), 'hex'),
    'ph_hold_stop_itemcode_cycles', c.unique_id, c.start_file_name, c.episode_start_date, now(),
    c.itemcode, c.commonname, c.genus, c.contsize, null::text, null::text, null::text, null::text, null::text,
    c.blocked_code, c.holdstopreason, null::text, coalesce(c.hold_reason_category, 'unknown'), 'park_hill_ok',
    weather.gdd_7, weather.gdd_14, weather.gdd_30, weather.gdd_season,
    null::numeric, null::numeric, null::numeric, null::numeric,
    weather.precip_7, weather.precip_14, weather.precip_30,
    weather.avg_temp_7, weather.avg_temp_14, weather.avg_temp_30,
    now(), c.episode_release_date, c.gdd_base_50_to_release, c.days_blocked, now(), now()
  from public.ph_hold_stop_itemcode_cycles c
  left join lateral (
    select
      coalesce(round((sum(coalesce(d.daily_gdd_base_50, greatest(((coalesce(d.temperature_high_f,0)+coalesce(d.temperature_low_f,0))/2)-50,0))) filter (where d.date >= c.episode_start_date - 6 and d.date <= c.episode_start_date))::numeric, 3), 0) as gdd_7,
      coalesce(round((sum(coalesce(d.daily_gdd_base_50, greatest(((coalesce(d.temperature_high_f,0)+coalesce(d.temperature_low_f,0))/2)-50,0))) filter (where d.date >= c.episode_start_date - 13 and d.date <= c.episode_start_date))::numeric, 3), 0) as gdd_14,
      coalesce(round((sum(coalesce(d.daily_gdd_base_50, greatest(((coalesce(d.temperature_high_f,0)+coalesce(d.temperature_low_f,0))/2)-50,0))) filter (where d.date >= c.episode_start_date - 29 and d.date <= c.episode_start_date))::numeric, 3), 0) as gdd_30,
      coalesce(round((sum(coalesce(d.daily_gdd_base_50, greatest(((coalesce(d.temperature_high_f,0)+coalesce(d.temperature_low_f,0))/2)-50,0))) filter (where d.date >= make_date(extract(year from c.episode_start_date)::integer,1,1) and d.date <= c.episode_start_date))::numeric, 3), 0) as gdd_season,
      coalesce(round((sum(coalesce(d.precipitation_in,0)) filter (where d.date >= c.episode_start_date - 6 and d.date <= c.episode_start_date))::numeric, 3), 0) as precip_7,
      coalesce(round((sum(coalesce(d.precipitation_in,0)) filter (where d.date >= c.episode_start_date - 13 and d.date <= c.episode_start_date))::numeric, 3), 0) as precip_14,
      coalesce(round((sum(coalesce(d.precipitation_in,0)) filter (where d.date >= c.episode_start_date - 29 and d.date <= c.episode_start_date))::numeric, 3), 0) as precip_30,
      round((avg(((d.temperature_high_f + d.temperature_low_f) / 2)) filter (where d.date >= c.episode_start_date - 6 and d.date <= c.episode_start_date))::numeric, 2) as avg_temp_7,
      round((avg(((d.temperature_high_f + d.temperature_low_f) / 2)) filter (where d.date >= c.episode_start_date - 13 and d.date <= c.episode_start_date))::numeric, 2) as avg_temp_14,
      round((avg(((d.temperature_high_f + d.temperature_low_f) / 2)) filter (where d.date >= c.episode_start_date - 29 and d.date <= c.episode_start_date))::numeric, 2) as avg_temp_30
    from public.ph_weather_daily d
    where d.station_key = 'park_hill_ok' and d.date >= make_date(extract(year from c.episode_start_date)::integer,1,1) and d.date <= c.episode_start_date
  ) weather on true;

  get diagnostics event_count = row_count;

  delete from public.ph_hold_release_cycles where cycle_source = 'ph_hold_stop_itemcode_cycles' or unique_id like 'hold_cycle_history_%' or unique_id like 'hold_cycle_itemcode_%';

  insert into public.ph_hold_release_cycles (
    unique_id, item_key, itemcode, commonname, genus, contsize, locationcode, lotcode, season,
    blockalpha, salesyear, holdstopcode, holdstopreason, hold_reason_category, hold_started_on,
    hold_released_on, hold_days, gdd_base_50_to_release, start_file_id, start_file_name,
    release_file_id, release_file_name, source_file_ids, source_file_names, episode_number,
    cycle_source, snapshot, created_at, updated_at
  )
  select
    'hold_cycle_itemcode_' || encode(digest(c.unique_id, 'sha256'), 'hex'),
    c.itemcode, c.itemcode, c.commonname, c.genus, c.contsize, null::text, null::text, null::text,
    null::text, null::text, c.blocked_code, c.holdstopreason, c.hold_reason_category,
    c.episode_start_date, c.episode_release_date, c.days_blocked, c.gdd_base_50_to_release,
    c.start_file_id, c.start_file_name, c.release_file_id, c.release_file_name,
    c.source_file_ids, c.source_file_names, c.episode_number, 'ph_hold_stop_itemcode_cycles',
    c.snapshot, now(), now()
  from public.ph_hold_stop_itemcode_cycles c
  where c.episode_release_date is not null;

  get diagnostics release_count = row_count;

  if to_regprocedure('public.v2_refresh_hold_learning_profiles()') is not null then
    delete from public.ph_hold_learning_profiles;
    profile_count := public.v2_refresh_hold_learning_profiles();
  end if;

  snapshot_rows := snapshot_count;
  itemcode_cycles := cycle_count;
  hold_events_upserted := event_count;
  release_cycles_upserted := release_count;
  profiles_refreshed := profile_count;
  return next;
end;
$$;


ALTER FUNCTION public.v2_refresh_hold_stop_itemcode_episode_learning(p_start_date date, p_end_date date, p_weather_refresh_limit integer) OWNER TO postgres;

