   FROM (( SELECT ar.id,
            ar.unique_id,
            ar.master_id,
                CASE
                    WHEN (mi.unique_id IS NULL) THEN ar.commonname
                    ELSE mi.commonname
                END AS commonname,
                CASE
                    WHEN (mi.unique_id IS NULL) THEN ar.contsize
                    ELSE mi.contsize
