--
-- Name: ph_crop_roll_open_rows; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.ph_crop_roll_open_rows WITH (security_invoker='true') AS
 SELECT d.unique_id,
    d.master_unique_id,
    d.source_table,
    d.crop_roll_view,
    d.warehouseid,
    d.plantgroupcode,
    d.itemcode,
    d.qualitycode,
    d.contsize,
    d.commonname,
    d.genus,
    d.genusname,
    d.botanicalname,
    d.lotcode,
    d.locationcode,
    d.source,
    d.desigitem,
    d.desigcust,
    d.desigloc,
    d.priority,
    d.ptravailable,
    d.ptronhand,
    d.ptrreviewed,
    d.s_lts,
    d.season_supply,
    d.saleyear,
    d.itemspec,
    d.locationnote,
    d.locationnotedate,
    d.locationptn1,
    d.fieldtagcolor,
    d.holdstopcode,
    d.holdstopreason,
    d.holdstopbegindate,
    d.season,
    d.blockalpha,
    d.blocknumber,
    d.app_tab_assignment,
    d.assignedto,
    d.date_completed,
    d.av_note,
    d.sales_note,
    d.salesnote,
    d.match,
    d.loc_match_qty,
    d.initial_ptr,
    d.spec,
    d.caliper,
    d.photo_link,
    d.photo_name,
    d.dock_photo_link,
    d.dock_photo_name,
    d.flyer_photo_link,
    d.flyer_photo_name,
    d.flyer_completed,
    d.flyer_av_note,
    d.flyer_match,
    d.flyer_loc_match_qty,
    d.flyer_spec,
    d.flyer_caliper,
    d.flyer_pick,
    d.flyer_initial_ptr,
    d.search_text,
    d.master_updated_at,
    d.created_at,
    d.updated_at
   FROM ((public.ph_crop_roll_drive_rows d
     LEFT JOIN public.ph_crop_roll_completed_drive_keys ci ON (((ci.key_type = 'id'::text) AND (ci.master_unique_id = d.master_unique_id))))
     LEFT JOIN public.ph_crop_roll_completed_drive_keys cc ON (((cc.key_type = 'card'::text) AND (cc.itemcode = upper(btrim(COALESCE(d.itemcode, ''::text)))) AND (cc.locationcode = upper(btrim(COALESCE(d.locationcode, ''::text)))) AND ((cc.lotcode IS NULL) OR (cc.lotcode = upper(btrim(COALESCE(d.lotcode, ''::text))))) AND ((cc.contsize IS NULL) OR (cc.contsize = upper(btrim(COALESCE(d.contsize, ''::text))))))))
  WHERE ((ci.completion_row_id IS NULL) AND (cc.completion_row_id IS NULL));


ALTER VIEW public.ph_crop_roll_open_rows OWNER TO postgres;

--
-- Name: ph_crop_roll_open_location_counts; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.ph_crop_roll_open_location_counts WITH (security_invoker='true') AS
 WITH location_counts AS (
         SELECT ph_crop_roll_open_rows.crop_roll_view,
            ph_crop_roll_open_rows.blockalpha,
            ph_crop_roll_open_rows.locationcode,
            count(*) AS row_count,
            count(DISTINCT ph_crop_roll_open_rows.itemcode) AS item_count,
            count(DISTINCT COALESCE(NULLIF(btrim(ph_crop_roll_open_rows.contsize), ''::text), 'Unknown'::text)) AS size_count,
            count(DISTINCT ph_crop_roll_open_rows.lotcode) AS lot_count,
            sum((NULLIF(regexp_replace(COALESCE(ph_crop_roll_open_rows.ptravailable, ''::text), '[^0-9.-]'::text, ''::text, 'g'::text), ''::text))::numeric) AS ptravailable_total
           FROM public.ph_crop_roll_open_rows
          GROUP BY ph_crop_roll_open_rows.crop_roll_view, ph_crop_roll_open_rows.blockalpha, ph_crop_roll_open_rows.locationcode
        ), size_counts AS (
         SELECT ph_crop_roll_open_rows.crop_roll_view,
            ph_crop_roll_open_rows.blockalpha,
            ph_crop_roll_open_rows.locationcode,
            COALESCE(NULLIF(btrim(ph_crop_roll_open_rows.contsize), ''::text), 'Unknown'::text) AS contsize,
            count(*) AS row_count
           FROM public.ph_crop_roll_open_rows
          GROUP BY ph_crop_roll_open_rows.crop_roll_view, ph_crop_roll_open_rows.blockalpha, ph_crop_roll_open_rows.locationcode, COALESCE(NULLIF(btrim(ph_crop_roll_open_rows.contsize), ''::text), 'Unknown'::text)
        )
 SELECT lc.crop_roll_view,
    lc.blockalpha,
    lc.locationcode,
    lc.row_count,
    lc.item_count,
    lc.size_count,
    lc.lot_count,
    lc.ptravailable_total,
    COALESCE(jsonb_object_agg(sc.contsize, sc.row_count ORDER BY sc.contsize) FILTER (WHERE (sc.contsize IS NOT NULL)), '{}'::jsonb) AS contsize_counts
   FROM (location_counts lc
     LEFT JOIN size_counts sc ON (((sc.crop_roll_view = lc.crop_roll_view) AND (sc.blockalpha = lc.blockalpha) AND (sc.locationcode = lc.locationcode))))
  GROUP BY lc.crop_roll_view, lc.blockalpha, lc.locationcode, lc.row_count, lc.item_count, lc.size_count, lc.lot_count, lc.ptravailable_total;


ALTER VIEW public.ph_crop_roll_open_location_counts OWNER TO postgres;

--
-- Name: ph_crop_roll_open_navigation_counts; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.ph_crop_roll_open_navigation_counts WITH (security_invoker='true') AS
 SELECT crop_roll_view,
    blockalpha,
    locationcode,
    COALESCE(NULLIF(btrim(contsize), ''::text), 'Unknown'::text) AS contsize,
    count(*) AS row_count,
    count(DISTINCT itemcode) AS item_count,
    count(DISTINCT lotcode) AS lot_count,
    sum((NULLIF(regexp_replace(COALESCE(ptravailable, ''::text), '[^0-9.-]'::text, ''::text, 'g'::text), ''::text))::numeric) AS ptravailable_total
   FROM public.ph_crop_roll_open_rows
  GROUP BY crop_roll_view, blockalpha, locationcode, COALESCE(NULLIF(btrim(contsize), ''::text), 'Unknown'::text);


ALTER VIEW public.ph_crop_roll_open_navigation_counts OWNER TO postgres;

--
-- Name: ph_crop_roll_rows; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ph_crop_roll_rows (
    row_id text NOT NULL,
    run_id text NOT NULL,
    master_unique_id text NOT NULL,
    group_key text NOT NULL,
    item_location_key text NOT NULL,
    itemcode text,
    commonname text,
    contsize text,
    genus text,
    blockalpha text,
    locationcode text,
    original_lotcode text,
    original_season text,
    original_priority text,
    original_locationnotedate text,
    original_locationnote text,
    original_locationptn1 text,
    original_holdstopcode text,
    original_holdstopreason text,
    assignedto text,
    row_status text DEFAULT 'open'::text NOT NULL,
    completed_by text,
    completed_at timestamp with time zone,
    target_lotcode text,
    target_season text,
    priority text,
