    resolution_status text DEFAULT 'pending'::text NOT NULL,
    actual_qty integer,
    variance_confirmed boolean DEFAULT false NOT NULL,
    not_completed_reason text,
    resolved_by_username text,
    resolved_at timestamp with time zone,
    ordinal integer NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ph_location_work_lines_action_type_check CHECK ((action_type = ANY (ARRAY['ta'::text, 'move'::text, 'grade'::text, 'save'::text]))),
    CONSTRAINT ph_location_work_lines_actual_qty_check CHECK (((actual_qty IS NULL) OR (actual_qty >= 0))),
    CONSTRAINT ph_location_work_lines_check CHECK (((planned_qty > 0) AND (planned_qty <= snapshotted_on_hand))),
    CONSTRAINT ph_location_work_lines_destination_check CHECK ((((action_type = 'move'::text) AND (NULLIF(btrim(destination_locationcode), ''::text) IS NOT NULL)) OR ((action_type = 'ta'::text) AND (NULLIF(btrim(destination_locationcode), ''::text) IS NULL)) OR (action_type = ANY (ARRAY['grade'::text, 'save'::text])))),
    CONSTRAINT ph_location_work_lines_destination_matching_rows_check CHECK ((destination_matching_rows >= 0)),
    CONSTRAINT ph_location_work_lines_destination_on_hand_check CHECK ((destination_on_hand >= (0)::numeric)),
    CONSTRAINT ph_location_work_lines_instructions_check CHECK ((length(instructions) <= 4000)),
    CONSTRAINT ph_location_work_lines_ordinal_check CHECK ((ordinal > 0)),
    CONSTRAINT ph_location_work_lines_resolution_check CHECK ((((resolution_status = 'pending'::text) AND (actual_qty IS NULL) AND (not_completed_reason IS NULL) AND (resolved_by_username IS NULL) AND (resolved_at IS NULL)) OR ((resolution_status = 'done'::text) AND (actual_qty IS NOT NULL) AND (not_completed_reason IS NULL) AND (resolved_by_username IS NOT NULL) AND (resolved_at IS NOT NULL)) OR ((resolution_status = 'not_completed'::text) AND (actual_qty IS NULL) AND ((length(btrim(not_completed_reason)) >= 1) AND (length(btrim(not_completed_reason)) <= 2000)) AND (resolved_by_username IS NOT NULL) AND (resolved_at IS NOT NULL)))),
    CONSTRAINT ph_location_work_lines_resolution_status_check CHECK ((resolution_status = ANY (ARRAY['pending'::text, 'done'::text, 'not_completed'::text]))),
    CONSTRAINT ph_location_work_lines_snapshotted_on_hand_check CHECK ((snapshotted_on_hand >= 0)),
    CONSTRAINT ph_location_work_lines_variance_check CHECK (((actual_qty IS NULL) OR (actual_qty <= planned_qty) OR variance_confirmed))
);


ALTER TABLE public.ph_location_work_lines OWNER TO postgres;

