--
-- Name: ph_pikes_order_batches; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ph_pikes_order_batches (
    batch_id uuid DEFAULT gen_random_uuid() NOT NULL,
    drive_file_id text NOT NULL,
    source_key text DEFAULT 'pikes'::text NOT NULL,
    file_name text NOT NULL,
    content_sha256 text NOT NULL,
    content_bytes bigint,
    source_sheet_name text,
    source_header_row integer,
    status text DEFAULT 'importing'::text NOT NULL,
    batch_date date,
    daily_sequence integer,
    display_name text,
    source_row_count integer DEFAULT 0 NOT NULL,
    distinct_item_count integer DEFAULT 0 NOT NULL,
    matched_item_count integer DEFAULT 0 NOT NULL,
    unmatched_item_count integer DEFAULT 0 NOT NULL,
    inventory_row_count integer DEFAULT 0 NOT NULL,
    last_error_code text,
    imported_at timestamp with time zone,
    archived_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ph_pikes_order_batches_content_bytes_check CHECK (((content_bytes IS NULL) OR (content_bytes >= 0))),
    CONSTRAINT ph_pikes_order_batches_content_sha256_check CHECK ((content_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT ph_pikes_order_batches_daily_sequence_check CHECK (((daily_sequence IS NULL) OR (daily_sequence >= 1))),
    CONSTRAINT ph_pikes_order_batches_distinct_item_count_check CHECK ((distinct_item_count >= 0)),
    CONSTRAINT ph_pikes_order_batches_inventory_row_count_check CHECK ((inventory_row_count >= 0)),
    CONSTRAINT ph_pikes_order_batches_matched_item_count_check CHECK ((matched_item_count >= 0)),
    CONSTRAINT ph_pikes_order_batches_source_header_row_check CHECK (((source_header_row IS NULL) OR (source_header_row >= 1))),
