--
-- Name: ph_request_delivery_status; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.ph_request_delivery_status WITH (security_invoker='true') AS
 SELECT DISTINCT ON (request_id, event_type) event_id,
    request_id,
    request_folder,
    event_type,
    status AS delivery_status,
    attempt_count AS delivery_attempt_count,
    next_attempt_at AS delivery_next_attempt_at,
    first_attempt_at AS delivery_first_attempt_at,
    last_attempt_at AS delivery_last_attempt_at,
    lease_expires_at AS delivery_lease_expires_at,
    sanitized_error_code AS delivery_error_code,
    email_delivered_at,
    push_delivered_at,
    delivered_at,
    delivery_mode,
    (EXTRACT(epoch FROM (now() - created_at)))::bigint AS delivery_age_seconds,
        CASE
            WHEN (status = ANY (ARRAY['pending'::text, 'processing'::text])) THEN 'sending'::text
            WHEN (status = 'failed'::text) THEN 'needs_attention'::text
            WHEN (status = 'delivered'::text) THEN 'delivered'::text
            ELSE status
        END AS delivery_display_state
   FROM public.ph_request_delivery_outbox o
  WHERE (request_id IS NOT NULL)
  ORDER BY request_id, event_type, created_at DESC, event_id DESC;


ALTER VIEW public.ph_request_delivery_status OWNER TO postgres;

