--

CREATE VIEW public.ph_request_queue_live_rows WITH (security_invoker='true') AS
 SELECT r.id,
    r.unique_id,
    r.master_id,
    r.commonname,
    r.contsize,
    r.locationcode,
    r.lotcode,
    r.itemcode,
    r.ptravailable,
    r.season_supply,
    r.priority,
    r.qualitycode,
    r.field_tag_color,
    r.plantgroupcode,
    r.requested_by,
    r.request_folder,
    r.req_customer,
    r.req_qty,
    r.desired_spec,
    r.desired_caliper,
    r.est_ship,
    r.req_reserve,
    r.req_photo_link,
    r.req_photo_name,
    r.req_archived,
    r.req_status,
    r.req_rep_action,
    r.created_at,
    r.req_match,
    r.req_spec,
    r.req_caliper,
    r.req_pic_note,
    r.req_sales_note,
    r.req_comments,
    r.av_note,
    r.date_completed,
    r.completed_by_username,
    r.completed_by_display,
    r.completed_by_email,
    r.req_photo_mode,
    r.move_batch_id,
    r.move_approval_stage,
    r.move_status,
    r.move_group_key,
    r.move_from_locationcode,
    r.move_to_locationcode,
    r.move_planned_qty,
    r.move_actual_qty,
    r.move_destination_needs_row,
    r.move_dylan_approved_at,
    r.move_jd_approved_at,
    r.move_completed_at,
    r.move_completed_by,
    r.request_note,
    r.request_created_by_username,
    r.request_created_by_display,
    r.request_created_by_email,
    r.request_selected_rep_username,
    r.request_selected_rep_display,
    r.request_selected_rep_email,
    r.app_tab_assignment,
    r.master_app_tab_assignment,
    r.request_source,
    r.client_batch_id,
    r.updated_at,
    r.row_version,
    r.drive_row_missing,
    r.drive_last_updated,
    r.drive_assignedto,
    r.drive_match,
    r.drive_loc_match_qty,
    r.drive_spec,
    r.drive_caliper,
    r.drive_pic_note,
    r.drive_av_note,
    r.drive_photo_link,
    r.drive_photo_name,
    r.av_rule_bundle_updated_at,
    r.av_rule_av_note_updated_at,
    r.av_rule_spec_updated_at,
    r.av_rule_match_updated_at,
    r.av_rule_caliper_updated_at,
    r.av_rule_photo_updated_at,
    r.av_rule_priority_snapshot,
    r.av_rule_holdstop_snapshot,
    r.av_rule_last_clear_reason,
    r.av_rule_last_cleared_at,
    s.event_id AS delivery_event_id,
    s.delivery_status,
    s.delivery_attempt_count,
    s.delivery_next_attempt_at,
    s.delivery_first_attempt_at,
    s.delivery_last_attempt_at,
    s.delivery_lease_expires_at,
    s.delivery_error_code,
    s.email_delivered_at AS delivery_email_delivered_at,
    s.push_delivered_at AS delivery_push_delivered_at,
    s.delivered_at AS delivery_delivered_at,
    s.delivery_mode,
    s.delivery_age_seconds,
    s.delivery_display_state
   FROM (public.ph_active_request_live_rows r
     LEFT JOIN public.ph_request_delivery_status s ON (((s.request_id = r.unique_id) AND (s.event_type = 'request_completed'::text))))
  WHERE ((NULLIF(btrim(COALESCE(r.date_completed, ''::text)), ''::text) IS NULL) OR (s.delivery_status = ANY (ARRAY['pending'::text, 'processing'::text, 'failed'::text])));


