--
-- Name: ph_view_av_hot_price; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.ph_view_av_hot_price WITH (security_invoker='true') AS
 WITH ranked_cav AS (
         SELECT c.unique_id,
            c.itemcode AS cav_itemcode,
            c.hot_price,
            c.filename AS cav_filename,
            c.last_updated AS cav_last_updated,
            upper(regexp_replace(c.itemcode, '[^A-Za-z0-9]'::text, ''::text, 'g'::text)) AS itemcode_key,
            row_number() OVER (PARTITION BY (upper(regexp_replace(c.itemcode, '[^A-Za-z0-9]'::text, ''::text, 'g'::text))) ORDER BY c.last_updated DESC NULLS LAST, c.filename DESC NULLS LAST, c.unique_id DESC) AS rn
           FROM public.ph_cav_import c
          WHERE ((COALESCE(TRIM(BOTH FROM c.hot_price), ''::text) <> ''::text) AND (upper(TRIM(BOTH FROM c.hot_price)) <> 'NULL'::text) AND (COALESCE(TRIM(BOTH FROM c.itemcode), ''::text) <> ''::text) AND (upper(TRIM(BOTH FROM c.itemcode)) <> 'NULL'::text))
        ), hot_cav AS (
         SELECT ranked_cav.cav_itemcode,
            ranked_cav.hot_price,
            ranked_cav.cav_filename,
            ranked_cav.cav_last_updated,
            ranked_cav.itemcode_key
           FROM ranked_cav
          WHERE (ranked_cav.rn = 1)
        )
 SELECT m.unique_id,
    m.itemcode,
    m.commonname,
    m.contsize,
    m.locationcode,
    m.lotcode,
    m.ptravailable,
    m.season_supply,
    m.priority,
    m.qualitycode,
    m.field_tag_color,
    m.s_lts,
    m.season,
    m.plantgroupcode,
    m.listprice,
    m.concat,
    m.last_updated,
    m.assignedto,
    m.date_completed,
    m.end_cap_folder,
    m.end_cap_qty,
    m.end_cap_level,
    m.match,
    m.spec,
    m.caliper,
    m.pic_note,
    m.sales_note,
    m.av_note,
    m.photo_link,
    m.photo_name,
    m.dock_spec,
    m.dock_caliper,
    m.dock_note,
    m.dock_photo_link,
    m.dock_photo_name,
    m.flyer_cat,
    m.flyer_title,
    m.flyer_inst,
    m.flyer_assigned,
    m.flyer_notes,
    m.flyer_photo_link,
    m.flyer_photo_name,
    m.flyer_completed,
    m.initial_ptr,
    m.loc_match_qty,
    m.warehousei,
    m.desigitem,
    m.desigcust,
    m.desigloc,
    m.ptronhand,
    m.ptrreviewed,
    m.holdstopcode,
    m.holdstopbegindate,
    m.holdstopreason,
    m.hsreasonbegin,
    m.season_oh,
    m.season_demand,
    m.oversellpercentage,
    m.itemspec,
    m.locationnote,
    m.locationnotedate,
    m.suspend,
    m.suspendto,
    m.specialpuller,
    m.pulltagnote1,
    m.pulltagnote2,
    m.fieldtagcolor,
    m.salesnote,
    m.inventorynote,
    m.locationptn1,
    m.locationptn2,
    m.prisetby,
    m.priupdated,
    m.bypassloc,
    m.largeptrqty,
    m.maxorderquantity,
    m.lochold,
    m.ext_ptronhand,
    m.varietycode,
    m.genusname,
    m.botanicalname,
    m.reversecommon,
    m.sortnamevariety,
    m.containersort,
    m.saleyear,
    m.blockalpha,
    m.blocknumber,
    m.bay,
    m.pullerresponsibility,
    m.grower,
    m.si_lts,
    m.a_lts,
    m.ai_lts,
    m.season_available,
    m.holdstopenddate,
    m.salesnote_1,
    m.fnsalesnote,
    m.warehousename,
    m.mcstatus,
    m.hz,
    m.intercopo,
    m.insurancegroup,
    m.brand,
    m.printedcontainercode,
    m.warehouseid,
    m.isreserve,
    m.salesrepid,
    m.salesrepname,
    m.nationalaccount,
    m.idgroup,
    m.customeridentityid,
    m.customername,
    m.consigneeidentityid,
    m.consigneename,
    m.consigneecity,
    m.consigneestate,
    m.consigneezip,
    m.tripnumber,
    m.stopnumber,
    m.zonecode,
    m.tagcode,
    m.transactionnumber,
    m.purchaseordernumber,
    m.extunitprice,
    m.ordertotal,
    m.requestdate,
    m.stagename,
