    m.customersku,
    m.formattedupc,
    m.descriptorcode,
    m.quantityordered,
    m.quantityshipped,
    m.unitprice,
    m.handlingchargeperitem,
    m.taggingchargeperitem,
    m.combinedprice,
    m.freightrateperitem,
    m.landed,
    m.retailprice,
    m.picknote,
    m.planstart,
    m.generalloadinstr,
    m.invoicedate,
    m.consigneeaddress_1,
    m.consigneeaddress_2,
    m.altshipcomment,
    m.shiptotelephone_1,
    m.okloadinstructions,
    m.txloadinstructions,
    m.ncloadinstructions,
    m.hlloadinstructions,
    m.dock,
    m.dock_num,
    m.equiv_unit,
