    m.salesnotebegindate,
    hot_cav.hot_price,
    hot_cav.cav_itemcode,
    hot_cav.cav_filename,
    hot_cav.cav_last_updated
   FROM (public.ph_master_inventory m
     JOIN hot_cav ON ((upper(regexp_replace(COALESCE(m.itemcode, ''::text), '[^A-Za-z0-9]'::text, ''::text, 'g'::text)) = hot_cav.itemcode_key)))
  WHERE (COALESCE(TRIM(BOTH FROM m.itemcode), ''::text) <> ''::text);


