--

CREATE VIEW public.ph_view_av_hot_price_keys WITH (security_invoker='true') AS
 WITH ranked_cav AS (
         SELECT c.unique_id,
            c.itemcode AS cav_itemcode,
            c.hot_price,
            c.filename AS cav_filename,
            c.last_updated AS cav_last_updated,
            upper(regexp_replace(c.itemcode, '[^A-Za-z0-9]'::text, ''::text, 'g'::text)) AS itemcode_key,
            row_number() OVER (PARTITION BY (upper(regexp_replace(c.itemcode, '[^A-Za-z0-9]'::text, ''::text, 'g'::text))) ORDER BY c.last_updated DESC NULLS LAST, c.filename DESC NULLS LAST, c.unique_id DESC) AS rn
           FROM public.ph_cav_import c
          WHERE ((COALESCE(TRIM(BOTH FROM c.hot_price), ''::text) <> ''::text) AND (upper(TRIM(BOTH FROM c.hot_price)) <> 'NULL'::text) AND (COALESCE(TRIM(BOTH FROM c.itemcode), ''::text) <> ''::text) AND (upper(TRIM(BOTH FROM c.itemcode)) <> 'NULL'::text))
        )
 SELECT itemcode_key,
    cav_itemcode,
    hot_price,
    cav_filename,
    cav_last_updated
   FROM ranked_cav
  WHERE (rn = 1);


ALTER VIEW public.ph_view_av_hot_price_keys OWNER TO postgres;

