CREATE VIEW public.ph_view_po_27f1_hl WITH (security_invoker='true') AS
 WITH latest AS (
         SELECT ph_27f1_hl_po.run_id
           FROM public.ph_27f1_hl_po
          ORDER BY ph_27f1_hl_po.imported_at DESC, ph_27f1_hl_po.id DESC
         LIMIT 1
        ), inventory AS (
         SELECT upper(btrim(m.itemcode)) AS itemcode,
            upper(btrim(m.contsize)) AS size,
            min(m.commonname) AS commonname,
            string_agg(DISTINCT m.locationcode, ', '::text ORDER BY m.locationcode) AS locationcode,
            string_agg(DISTINCT m.priority, ', '::text ORDER BY m.priority) AS priority,
            string_agg(DISTINCT (to_jsonb(m.*) ->> 'holdstopcode'::text), ', '::text) AS holdstopcode,
            string_agg(DISTINCT (to_jsonb(m.*) ->> 'holdstopreason'::text), ', '::text) AS holdstopreason,
            sum(
                CASE
                    WHEN (btrim((to_jsonb(m.*) ->> 'ptronhand'::text)) ~ '^-?[0-9]+([.][0-9]+)?$'::text) THEN ((to_jsonb(m.*) ->> 'ptronhand'::text))::numeric
                    ELSE NULL::numeric
                END) AS ptronhand
           FROM public.ph_master_inventory m
          WHERE (upper(btrim(m.lotcode)) = '27.F1'::text)
          GROUP BY (upper(btrim(m.itemcode))), (upper(btrim(m.contsize)))
