            s_1.stopnumber,
            s_1.zonecode,
            s_1.tagcode,
            s_1.transactionnumber,
            s_1.purchaseordernumber,
            s_1.extunitprice,
            s_1.ordertotal,
            s_1.requestdate,
            s_1.stagename,
            s_1.step,
