            s_1.formattedupc,
            s_1.printedcontainercode,
            s_1.lotcode,
            s_1.locationcode,
            s_1.descriptorcode,
            s_1.itemcode,
            s_1.plantgroupcode,
            s_1.sortnamevariety,
            s_1.containersort,
            s_1.qualitycode,
            s_1.commonname,
            s_1.quantityordered,
            s_1.quantityshipped,
            s_1.listprice,
            s_1.unitprice,
            s_1.handlingchargeperitem,
            s_1.taggingchargeperitem,
            s_1.combinedprice,
            s_1.freightrateperitem,
            s_1.landed,
            s_1.retailprice,
            s_1.holdstopcode,
            s_1.holdstopreason,
            s_1.salesnote,
            s_1.fnsalesnote,
            s_1.picknote,
            s_1.planstart,
            s_1.generalloadinstr,
            s_1.invoicedate,
            s_1.consigneeaddress_1,
            s_1.consigneeaddress_2,
            s_1.altshipcomment,
            s_1.shiptotelephone_1,
            s_1.okloadinstructions,
            s_1.txloadinstructions,
            s_1.ncloadinstructions,
            s_1.hlloadinstructions,
            s_1.dock,
            s_1.equiv_unit,
            s_1.equiv_uom,
            s_1.wingdingunits,
            s_1.dropweight,
            s_1.internalinvnote,
            s_1.hardinesszone,
            s_1.brand,
            s_1.tagdeptnote,
            s_1.ext_unit_merch_shipped,
            s_1.ext_eunit_shipped,
            s_1.avg_price_eunit_shipped,
            s_1.requestdateweek,
            s_1.carrier,
            s_1.suspend,
            s_1.suspend_to,
            s_1.qa_code,
            s_1.grower,
            s_1.priority,
            s_1.ptronhand,
            s_1.ptrreviewed,
            s_1.ptravailable,
            s_1.season_supply,
            s_1.s_lts,
            s_1.itemspec,
            s_1.season,
            s_1.mcstatus,
            s_1.hz,
            s_1.intercopo,
            s_1.insurancegroup,
            s_1.si_lts,
            s_1.a_lts,
            s_1.ai_lts,
            s_1.si_available,
            s_1.holdstopenddate,
            s_1.salesnote_1,
            s_1.spec,
            s_1.caliper,
            s_1.pic_note,
            s_1.sales_note,
            s_1.av_note,
            s_1.photo_link,
            s_1.photo_name,
            s_1.flyer_cat,
            s_1.flyer_title,
            s_1.flyer_inst,
            s_1.flyer_assigned,
            s_1.flyer_notes,
            s_1.flyer_photo_link,
            s_1.flyer_photo_name,
            s_1.flyer_completed,
            s_1.initial_ptr,
            s_1.loc_match_qty,
            s_1.end_cap_folder,
            s_1.end_cap_qty,
            s_1.end_cap_level,
            s_1.match,
            s_1.dock_num,
            s_1.source,
            s_1.desigitem,
            s_1.desigcust,
            s_1.desigloc,
            s_1.filename,
            row_number() OVER (PARTITION BY (upper(btrim(s_1.itemcode))), (upper(btrim(s_1.contsize))) ORDER BY s_1.unique_id) AS n
           FROM public.ph_soc_master s_1
          WHERE ((upper(btrim(s_1.lotcode)) = '27.F1'::text) AND (btrim(COALESCE(s_1.invoicedate, ''::text)) = ''::text))
        )
 SELECT p.id,
    p.run_id,
    p.row_index,
    p.item_code AS itemcode,
    COALESCE(i.commonname, p.common_name) AS commonname,
    p.size AS contsize,
    i.locationcode,
    i.priority,
    p.lot AS lotcode,
    i.holdstopcode,
    i.holdstopreason,
    p.po_ordered AS total_quantity_ordered,
    i.ptronhand,
    i.ptronhand AS total_ptronhand,
    p.lot_pend_rec,
    (to_jsonb(s.*) ->> 'salesrepid'::text) AS salesrepid,
    (to_jsonb(s.*) ->> 'salesrepname'::text) AS salesrepname,
    s.customername,
    s.consigneename,
    (to_jsonb(s.*) ->> 'consigneestate'::text) AS consigneestate,
    s.stopnumber,
        CASE
            WHEN (btrim(s.quantityordered) ~ '^-?[0-9]+([.][0-9]+)?$'::text) THEN (s.quantityordered)::numeric
            ELSE NULL::numeric
        END AS quantityordered,
    (to_jsonb(s.*) ->> 'requestdate'::text) AS requestdate,
    (to_jsonb(s.*) ->> 'stagename'::text) AS stagename,
    (to_jsonb(s.*) ->> 'step'::text) AS step,
    s.dock,
    p.po_remain,
    p.created_at,
    p.imported_at AS built_at
   FROM (((public.ph_27f1_hl_po p
     JOIN latest l USING (run_id))
     LEFT JOIN inventory i ON (((i.itemcode = upper(btrim(p.item_code))) AND (i.size = upper(btrim(p.size))))))
     LEFT JOIN soc s ON (((upper(btrim(s.itemcode)) = upper(btrim(p.item_code))) AND (upper(btrim(s.contsize)) = upper(btrim(p.size))) AND (s.n = 1))));


ALTER VIEW public.ph_view_po_27f1_hl OWNER TO postgres;

