--
-- Name: ph_view_season_notes; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.ph_view_season_notes WITH (security_invoker='true') AS
 SELECT unique_id
   FROM ( SELECT ph_master_inventory.unique_id,
            row_number() OVER (PARTITION BY ph_master_inventory.itemcode ORDER BY (NULLIF(regexp_replace(ph_master_inventory.priority, '[^0-9.]'::text, ''::text, 'g'::text), ''::text))::numeric, (NULLIF(regexp_replace(ph_master_inventory.ptravailable, '[^0-9.]'::text, ''::text, 'g'::text), ''::text))::numeric DESC) AS rn
           FROM public.ph_master_inventory
          WHERE ((ph_master_inventory.priority IS NOT NULL) AND (ph_master_inventory.priority <> ''::text) AND (upper(ph_master_inventory.priority) <> 'NULL'::text) AND ((NULLIF(regexp_replace(ph_master_inventory.ptravailable, '[^0-9.]'::text, ''::text, 'g'::text), ''::text))::numeric >= ((NULLIF(regexp_replace(ph_master_inventory.season_supply, '[^0-9.]'::text, ''::text, 'g'::text), ''::text))::numeric * 0.10)))) sub
  WHERE (rn = 1);


ALTER VIEW public.ph_view_season_notes OWNER TO postgres;

