DECLARE
  policy_row record;
  v_anon oid := 'anon'::regrole::oid;
  v_authenticated oid := 'authenticated'::regrole::oid;
BEGIN
  FOR policy_row IN
    SELECT p.polrelid::regclass AS relation_name, p.polname
    FROM pg_policy p
    JOIN pg_class c ON c.oid = p.polrelid
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public'
      AND c.relname = ANY (ARRAY[
        'ph_dock_issue_status',
        'ph_chat_members',
        'ph_chat_threads',
        'ph_master_inventory_user_assignments',
        'ph_dock_issue_allocations',
        'ph_crop_roll_completed_drive_keys'
      ])
      AND p.polpermissive
      AND p.polcmd IN ('r', '*')
      AND coalesce(pg_get_expr(p.polqual, p.polrelid), 'true') = 'true'
      AND p.polroles && ARRAY[0::oid, v_anon, v_authenticated]
  LOOP
    EXECUTE format(
      'DROP POLICY IF EXISTS %I ON %s',
