    'ph_dock_issue_status',
    'ph_chat_members',
    'ph_chat_threads',
    'ph_master_inventory_user_assignments',
    'ph_dock_issue_allocations',
    'ph_crop_roll_completed_drive_keys'
  ] LOOP
    SELECT string_agg(format('%I', c.column_name), ', ' ORDER BY c.ordinal_position)
    INTO v_columns
